def _purge_removed_demo_users():
    """Keep removed demo users out of existing local/serverless databases."""
    # Imported here, not read off the module: `task_assignees` is also the name
    # of a route handler defined further down, which rebinds the global once the
    # module finishes loading. This function ran at import time, before that
    # happened, so it never noticed — and would have failed on the association
    # table the moment anything called it again.
    from models import task_assignees as assignee_rows, task_watchers as watcher_rows
    names = set(REMOVED_DEMO_USERS)
    emails = set(REMOVED_DEMO_USERS.values())
    with Session(engine) as db:
        users = db.query(User).filter(or_(User.name.in_(names), User.email.in_(emails))).all()
        ids = [u.id for u in users]
        if not ids:
            return

        # Never the last way in. Deleting every administrator leaves a database
        # nobody can administer and no screen that can grant it back — so a demo
        # account that is still the only one is kept, and said so.
        #
        # Both rows count, the same two _cap reads. On a database that has just
        # been seeded this step runs before memberships exist at all, so asking
        # only about WorkspaceMember would find no administrators anywhere and
        # cheerfully delete the only one there was.
        admin_ids = ({m.user_id for m in db.query(WorkspaceMember)
                      .filter(WorkspaceMember.role == "admin").all()}
                     | {u.id for u in db.query(User).filter(User.role == "admin").all()})
        if admin_ids and admin_ids.issubset(set(ids)):
            keep = sorted(admin_ids)[0]
            ids = [i for i in ids if i != keep]
            kept = next((u.email for u in users if u.id == keep), keep)
            print(f"⚠️  keeping {kept}: the only administrator left", flush=True)
            if not ids:
                return

        # Rows that only exist to join a user to something: they go with them.
        db.execute(assignee_rows.delete().where(assignee_rows.c.user_id.in_(ids)))
        db.execute(watcher_rows.delete().where(watcher_rows.c.user_id.in_(ids)))
        db.query(BoardMember).filter(BoardMember.user_id.in_(ids)).delete(synchronize_session=False)
        db.query(WorkspaceMember).filter(WorkspaceMember.user_id.in_(ids)).delete(synchronize_session=False)
        db.query(EnvironmentMember).filter(EnvironmentMember.user_id.in_(ids)).delete(synchronize_session=False)
        db.query(BoardView).filter(BoardView.user_id.in_(ids)).delete(synchronize_session=False)
        db.query(LoginEvent).filter(LoginEvent.user_id.in_(ids)).delete(synchronize_session=False)
        db.query(Notification).filter(Notification.user_id.in_(ids)).delete(synchronize_session=False)

        db.query(Task).filter(Task.created_by.in_(ids)).update({Task.created_by: None}, synchronize_session=False)
        db.query(Comment).filter(Comment.user_id.in_(ids)).update({Comment.user_id: None}, synchronize_session=False)
        db.query(Permit).filter(Permit.assigned_to.in_(ids)).update({Permit.assigned_to: None}, synchronize_session=False)
        db.query(CitizenRequest).filter(CitizenRequest.assigned_to.in_(ids)).update({CitizenRequest.assigned_to: None}, synchronize_session=False)
        db.query(Project).filter(Project.manager_id.in_(ids)).update({Project.manager_id: None}, synchronize_session=False)
        db.query(ProjectStep).filter(ProjectStep.owner_id.in_(ids)).update({ProjectStep.owner_id: None}, synchronize_session=False)
        db.query(Approval).filter(Approval.approver_user_id.in_(ids)).update({Approval.approver_user_id: None}, synchronize_session=False)
        db.query(ChangeRequest).filter(ChangeRequest.requested_by.in_(ids)).update({ChangeRequest.requested_by: None}, synchronize_session=False)
        db.query(ChangeRequest).filter(ChangeRequest.approved_by.in_(ids)).update({ChangeRequest.approved_by: None}, synchronize_session=False)
        db.query(Document).filter(Document.uploaded_by.in_(ids)).update({Document.uploaded_by: None}, synchronize_session=False)
        db.query(AuditLog).filter(AuditLog.changed_by.in_(ids)).update({AuditLog.changed_by: None}, synchronize_session=False)
        # These four were never detached. It went unnoticed because SQLite does
        # not enforce foreign keys unless asked and the demo users listed above
        # happened to hold none of them — but on Postgres one dangling
        # reference makes the DELETE fail, _safe_startup logs it and carries on,
        # and the users quietly stay. Environment.created_by is the newest of
        # them and the likeliest to be held.
        db.query(Environment).filter(Environment.created_by.in_(ids)).update({Environment.created_by: None}, synchronize_session=False)
        db.query(Automation).filter(Automation.created_by.in_(ids)).update({Automation.created_by: None}, synchronize_session=False)
        db.query(Automation).filter(Automation.updated_by.in_(ids)).update({Automation.updated_by: None}, synchronize_session=False)
        db.query(AutomationRun).filter(AutomationRun.actor_id.in_(ids)).update({AutomationRun.actor_id: None}, synchronize_session=False)
        db.query(ItemLink).filter(ItemLink.created_by.in_(ids)).update({ItemLink.created_by: None}, synchronize_session=False)
        db.query(Board).filter(Board.deleted_by.in_(ids)).update({Board.deleted_by: None}, synchronize_session=False)
        db.query(Task).filter(Task.deleted_by.in_(ids)).update({Task.deleted_by: None}, synchronize_session=False)

        gone = [u.email for u in users if u.id in ids]
        db.query(User).filter(User.id.in_(ids)).delete(synchronize_session=False)
        db.commit()
        print(f"[seed] demo users removed: {', '.join(gone)}", flush=True)

def _safe_startup(fn):
    """Run a one-time startup/seed step; never let it crash the whole process.
    On a persistent prod DB these are mostly idempotent no-ops, so a failure
    against existing data must not take the server down — log and carry on."""
    try:
        fn()
    except Exception as _e:
        print(f"⚠️  startup step {getattr(fn,'__name__',fn)} failed: {_e}", flush=True)

_safe_startup(_purge_removed_demo_users)

def _seed_memberships():
    """One-time: give existing boards their members so nothing disappears.
    New boards start private to their creator (see create_board)."""
    with Session(engine) as db:
        users = db.query(User).all()
        # workspace/environment members
        if db.query(WorkspaceMember).count() == 0:
            for u in users:
                # only a true system admin (User.role == "admin") is a workspace/system
                # admin; a "manager" is NOT — they get access only to granted environments
                erole = "admin" if u.role == "admin" else ("viewer" if u.role == "viewer" else "member")
                db.add(WorkspaceMember(user_id=u.id, role=erole))
            db.commit()
        # board members
        if db.query(BoardMember).count() == 0:
            for b in db.query(Board).all():
                for u in users:
                    role = "viewer" if u.role == "viewer" else ("admin" if u.role in ("admin", "manager") else "editor")
                    db.add(BoardMember(board_id=b.id, user_id=u.id, role=role))
            db.commit()
_safe_startup(_seed_memberships)

# The municipality's environments (Monday-style workspaces, like 'עיריית הוד השרון').
# Seeded once; sysadmins manage them afterwards via /api/environments.
ENVIRONMENTS_SEED = [
    ("בינוי", "🏗️"), ("היסעים", "🚌"), ("חדשנות טכנולוגיה ומערכות מידע", "💡"),
    ("כספים", "💰"), ("מגזר ערבי דרוזי וצ'רקסי", "🕌"), ("מטה", "🏛️"),
    ("מינהל ואיכות", "📋"), ("משאבי אנוש", "👥"), ("משפטית", "⚖️"),
    ("סוכנות הביטוח", "🛡️"), ("פיקוח ובקרה", "🔎"), ("פיתוח תשתיות ואחזקה", "🛠️"),
    ('פמ"א', "🏭"), ("קשרי לקוחות", "🤝"), ("רגולציה וקשרי ממשל", "📜"),
    ("שיווק", "📣"), ('תבו"ר', "💵"),
]
_ENV_COLORS = ["#6366f1", "#0ea5e9", "#10b981", "#f59e0b", "#ef4444", "#8b5cf6", "#ec4899", "#14b8a6"]

# The primary workspace is matched BY NAME on every startup — renaming it in the
# UI without changing this would make the seeder create a second primary
# environment under the old name.
PRIMARY_ENV_NAME = "סביבה ראשית"
# What the default workspace used to be called. Renamed once, on the boot that
# first carries this list, and only while it still answers to the old name — it
# is an ordinary renameable workspace, so an admin who has given it a name of
# their own must not find it renamed back under them on the next deploy.
#
# "מערכות מידע" is in the list for a different reason than "בדיקה". It is not a
# name this workspace shipped with; it is a name the default workspace was given
# at some point, which left the one workspace EVERY user is in reading as a
# single department's — and a new user, who gets this workspace and no other,
# opened the app inside "מערכות מידע". The organisation's own department of that
# name has its own workspace and is untouched. The rename is therefore
# deliberate and deliberately overriding: name the default workspace that again
# and the next boot will name it back.
LEGACY_PRIMARY_NAMES = ("בדיקה", "מערכות מידע")

def _seed_environments():
    """What a database starts with, and what every boot keeps true.

    On a database with no environments at all — a new installation — this
    creates the primary workspace (PRIMARY_ENV_NAME) and the municipality's 17
    workspaces after it.

    On every boot, new or not, it keeps the two invariants that cannot be left
    to chance: exactly one workspace is the primary one, and a board belongs to
    a workspace. It creates nothing else, ever: a workspace an admin deleted or
    renamed is their decision, and a restart must not reverse it."""
    with Session(engine) as db:
        org = db.query(Organization).first()
        existing = {e.name: e for e in db.query(Environment).all()}
        # 1) primary workspace first. An existing primary wins over the name:
        # renaming it (it is an ordinary editable workspace) must not make this
        # seeder mint a second primary under the old name on the next boot.
        #
        # Repair first: more than one workspace flagged primary is never valid.
        # It is the residue of the older name-matching logic — renaming the
        # default workspace made the next boot mint another one under the old
        # name, each flagged primary. A primary workspace cannot be renamed away
        # from, moved out of or deleted, so every extra one is a workspace the
        # admin can no longer get rid of. Keep the one that actually holds the
        # boards (ties: the oldest) and demote the rest to ordinary workspaces.
        prims = db.query(Environment).filter(Environment.is_primary == True).order_by(Environment.id).all()
        if len(prims) > 1:
            counts = {e.id: db.query(Board).filter(Board.environment_id == e.id).count() for e in prims}
            keep = max(prims, key=lambda e: (counts[e.id], -e.id))
            for e in prims:
                if e.id != keep.id:
                    e.is_primary = False
            db.flush()
            print(f"↻ demoted {len(prims) - 1} extra default workspace(s); kept '{keep.name}'")
            prims = [keep]
        primary = (prims[0] if prims else None) or existing.get(PRIMARY_ENV_NAME)
        if not primary:
            primary = Environment(name=PRIMARY_ENV_NAME, icon="🏛️", color=_ENV_COLORS[0],
                                  position=0, is_primary=True, organization_id=org.id if org else None)
            db.add(primary); db.flush()
        elif not primary.is_primary:
            primary.is_primary = True
        if (primary.name or "").strip() in LEGACY_PRIMARY_NAMES:
            primary.name = PRIMARY_ENV_NAME
            print(f"↻ the default workspace is now '{PRIMARY_ENV_NAME}'")
        # 2) the municipality's own workspaces, after it — and ONLY on a
        # database that has none at all, which is a new installation and
        # nothing else.
        #
        # They used to be created BY NAME on every boot: any of the 17 missing
        # from the table was added back. That made two ordinary administrative
        # acts impossible, and both were done in QA and both were undone by the
        # next deploy:
        #
        #   * DELETING one. "חדשנות טכנולוגיה ומערכות מידע" was deleted on the
        #     18th and was back on the 19th, put there by a restart. Worse than
        #     merely back: deleting a workspace moves its boards to the default
        #     one and nothing moves them back, so what returned was an empty
        #     shell wearing the name of something somebody had finished with.
        #   * RENAMING one. The old name is then missing from the table, so the
        #     next boot minted a SECOND workspace under it, standing beside the
        #     renamed one.
        #
        # This is the same bug the default workspace already had, and the same
        # fix: the seeder says what a NEW database starts with, and holds no
        # opinion about a database that is in use. A workspace added to the list
        # after this reaches new installations only — on a live one, creating a
        # workspace is something an admin does in the app, and then it is theirs
        # to rename and to delete.
        if not existing:
            for pos, (name, icon) in enumerate(ENVIRONMENTS_SEED, start=1):
                db.add(Environment(name=name, icon=icon,
                                   color=_ENV_COLORS[pos % len(_ENV_COLORS)],
                                   position=pos, organization_id=org.id if org else None))
        # 3) legacy boards (no environment) belong to the primary workspace
        db.query(Board).filter(Board.environment_id == None).update({Board.environment_id: primary.id})
        # 4) the primary workspace is a workspace like any other: you are in it
        # because somebody put you in it. It used to mean "everyone", and that
        # rule was not a row — so turning it into one is a backfill, not a new
        # grant. Everybody already sitting on a board inside it gets the row
        # their access was resting on, and keeps every board they can open
        # today; what they lose is being offered for invitation on boards they
        # have nothing to do with.
        #
        # It is written to run on every boot without doing anything twice: a
        # board member here without a row can only be somebody this has not run
        # for yet, since an invitation to a board now requires the environment
        # membership first, and removing a member is refused while a board in
        # the environment still names them.
        have = {m.user_id for m in db.query(EnvironmentMember).filter(
            EnvironmentMember.environment_id == primary.id).all()}
        on_a_board = {uid for (uid,) in
                      db.query(BoardMember.user_id)
                        .join(Board, Board.id == BoardMember.board_id)
                        .filter(Board.environment_id == primary.id).all()}
        missing = sorted(uid for uid in on_a_board - have if uid is not None)
        for uid in missing:
            db.add(EnvironmentMember(environment_id=primary.id, user_id=uid, role="member"))
        if missing:
            print(f"↻ {len(missing)} member row(s) written for '{primary.name}' "
                  f"— it is now an ordinary workspace, by invitation")
        db.commit()
_safe_startup(_seed_environments)


AUTO_COLS = (("created_at", "מועד יצירה", "sys_created_at"),
             ("created_by", "יוצר הרשומה", "sys_created_by"))

def _backfill_auto_columns():
    """Give every board the two automatic columns — who created an item and when.

    New boards ship with them; boards that predate them did not have them at
    all, and the creator column on the oldest ones is a plain people column
    that only auto-filled for items created while it existed. Both are derived
    from the item itself, so adding them is enough — no values to write, and
    they are right for items that predate the column.

    Runs once per board (`auto_cols_v1`): an admin who then removes a column
    must not have it come back on the next restart.
    """
    with Session(engine) as db:
        added = 0
        for b in db.query(Board).all():
            s = dict(b.settings or {})
            cols = [dict(c) for c in (s.get("columns") or [])]
            changed = False
            # the legacy creator column is a people column that has to be written
            # on creation — the derived type reads the item's own creator instead
            for c in cols:
                if c.get("id") == "sys_created_by" and c.get("type") == "people":
                    c["type"] = "created_by"
                    changed = True
            if not s.get("auto_cols_v1"):
                have = {c.get("type") for c in cols}
                used = {c.get("id") for c in cols}
                for typ, title, sid in AUTO_COLS:
                    if typ in have:
                        continue
                    cid = sid if sid not in used else ("col_" + uuid.uuid4().hex[:8])
                    cols.append({"id": cid, "type": typ, "title": title, "options": None,
                                 "formula": None, "connect": None, "copy_mode": None, "perms": {}})
                    used.add(cid)
                    added += 1
                    changed = True
                s["auto_cols_v1"] = True
                changed = True
            if changed:
                s["columns"] = cols
                b.settings = s
        db.commit()
        if added:
            print(f"↻ added {added} automatic column(s) across boards", flush=True)
_safe_startup(_backfill_auto_columns)

# ── Configurable capability matrix (role → feature) ──────────────────
# 'admin' always has every capability (implicit, never stored). These roles are
# editable by a system admin from the SysAdmin → role-permissions panel.
CAPABILITIES = ["manage_system", "create_environment", "create_board",
                "view_automations", "export_automation_log",
                "hide_form_branding", "export_excel", "download_files",
                "print_board", "clean_screen"]
CAP_HE = {
    "manage_system": "ניהול מערכת",
    "create_environment": "יצירת סביבה חדשה",
    "create_board": "יצירת לוח חדש",
    # Two the automations matrix needs and a role alone cannot express: a board
    # EDITOR sees the rules only where the first is granted, and a board ADMIN
    # takes data out of the system only where the second is.
    "view_automations": "צפייה באוטומציות של לוח (לחבר לוח)",
    "export_automation_log": "ייצוא נתוני אוטומציות ושחזור גרסה",
    # Taking the product's name off a form somebody outside the organisation
    # will read. A board admin builds the form; whether it may go out
    # unbranded is the system's to say, which is what this table is for.
    "hide_form_branding": "הסרת מיתוג Missions מטופס",
    # Taking the data itself out of the system, in bulk and one file at a time.
    # Both are off for אורח and on for everybody else — see CAP_DEFAULT_ON.
    "export_excel": "ייצוא לוח לאקסל",
    "download_files": "הורדת קבצים מצורפים",
    # The two the server cannot enforce and says so. Printing happens inside
    # the browser and never asks us; a screenshot is the operating system
    # photographing its own screen, and no web page has ever been able to stop
    # one. What CAN be done is to make the copy traceable and the print refuse
    # itself, which is what these two switch on — see the Screen object in
    # frontend/index.html, where the whole reasoning is written out.
    "print_board": "הדפסת לוח ושמירה כ-PDF",
    "clean_screen": "מסך ללא סימן מים",
}

# What a (role, capability) row is born with, where it is not False.
#
# Every other capability in this table starts at False: it is a power granted,
# and until somebody grants it nobody had it. These two are the other kind —
# not a new power being handed out but an existing one being taken away from a
# single role. Seeded False for everybody, the first restart after this would
# have taken Excel and every attachment away from every member of every board,
# which is not what "block it for a guest" asked for.
CAP_DEFAULT_ON = {
    "export_excel": ["manager", "member", "viewer"],
    "download_files": ["manager", "member", "viewer"],
    "print_board": ["manager", "member", "viewer"],
    "clean_screen": ["manager", "member", "viewer"],
}
EDITABLE_ROLES = ["manager", "member", "viewer", "guest"]
ROLE_HE_BE = {"admin": "מנהל מערכת", "manager": "מנהל", "member": "חבר צוות",
              "viewer": "צפייה בלבד", "guest": "אורח"}

def _seed_role_permissions():
    """Ensure a row exists for every (editable role × capability). Defaults to
    False — only 'admin' (implicit) starts with access, matching prior behavior.
    CAP_DEFAULT_ON names the exceptions, and says there why they have to exist:
    a capability that describes something every role could already do cannot be
    born switched off without taking it away from everybody."""
    with Session(engine) as db:
        existing = {(r.role, r.capability) for r in db.query(RolePermission).all()}
        added = False
        for role in EDITABLE_ROLES:
            for cap in CAPABILITIES:
                if (role, cap) not in existing:
                    db.add(RolePermission(role=role, capability=cap,
                                          allowed=role in CAP_DEFAULT_ON.get(cap, ())))
                    added = True
        if added:
            db.commit()
_safe_startup(_seed_role_permissions)


def _repair_promoted_admins():
    """Give the workspace row to anyone the users screen already made an admin.

    Promotions written before _sync_ws_role existed set User.role and left the
    workspace row alone, so the account was let into ניהול מערכת and refused
    every action offered there. This puts the row where it was always meant to
    be. It only ever grants, and only where User.role already says "admin" —
    an administrator's own decision, recorded but not carried through. It never
    demotes: a workspace admin who is something else in the users screen may
    have been granted that row deliberately, and taking it away on a deploy is
    not a repair.
    """
    with Session(engine) as db:
        admins = db.query(User).filter(User.role == "admin").all()
        if not admins:
            return
        rows = {m.user_id: m for m in db.query(WorkspaceMember)
                .filter(WorkspaceMember.user_id.in_([u.id for u in admins])).all()}
        fixed = []
        for u in admins:
            m = rows.get(u.id)
            if m is None:
                db.add(WorkspaceMember(user_id=u.id, role="admin"))
                fixed.append(u.email)
            elif m.role != "admin":
                m.role = "admin"
                fixed.append(u.email)
        if fixed:
            db.commit()
            print(f"[auth] workspace admin row restored for: {', '.join(fixed)}", flush=True)
_safe_startup(_repair_promoted_admins)

def _role_perms(db):
    """Return {role: {capability: bool}} for the editable roles."""
    m = {role: {cap: False for cap in CAPABILITIES} for role in EDITABLE_ROLES}
    for r in db.query(RolePermission).all():
        if r.role in m and r.capability in CAPABILITIES:
            m[r.role][r.capability] = bool(r.allowed)
    return m

def _cap(db, uid, cap):
    """Whether the user (by User.role, with 'admin' always-on) has a capability."""
    if uid is None:
        return False
    if _ws_role(db, uid) == "admin":
        return True
    u = db.query(User).filter(User.id == uid).first()
    role = (u.role if u else None) or "guest"
    if role == "admin":
        return True
    row = (db.query(RolePermission)
           .filter(RolePermission.role == role, RolePermission.capability == cap).first())
    return bool(row and row.allowed)


def _ws_role_stored(db, uid, wanted):
    """What the workspace screen may actually store for `uid`.

    The screen offers מנהל / חבר / צופה and writes whichever was chosen. On a
    system administrator that wrote a row contradicting User.role, which is the
    authority — see _ws_role, which now reads past such a row rather than
    obeying it. The row is pinned here too so the members list does not go on
    showing "חבר" beside somebody the users screen calls מנהל מערכת: the two
    screens disagreeing is how this went unnoticed in the first place.

    Lowering a system administrator is done in the users screen, where it means
    what it says and _sync_ws_role carries it here.
    """
    u = db.query(User).filter(User.id == uid).first()
    if u is not None and u.role == "admin":
        return "admin"
    return wanted


def _ws_role_for(user_role):
    """The workspace-membership role a User.role implies.

    Two rows carry "is this person an admin": User.role, which the users screen
    edits, and WorkspaceMember.role, which most of the system actually reads.
    They are set together when an account is created — and were not when a role
    was changed afterwards, which is the whole of this.
    """
    return "admin" if user_role == "admin" else ("viewer" if user_role == "viewer" else "member")


def _sync_ws_role(db, user):
    """Make the workspace row say what the user's role says.

    Promoting someone to מנהל מערכת in the users screen wrote User.role and
    stopped there. `_cap` accepts User.role == "admin", so they were let into
    ניהול מערכת; everything reading the workspace row went on treating them as
    whatever they were before. In production that produced an account that
    could open the environments screen and act on nothing in it, while the same
    person in QA — created as an admin, both rows written together — had the
    lot. Both directions: a demotion has to take the workspace row with it, or
    it is not a demotion.
    """
    want = _ws_role_for(user.role)
    m = db.query(WorkspaceMember).filter(WorkspaceMember.user_id == user.id).first()
    if m:
        m.role = want
    else:
        db.add(WorkspaceMember(user_id=user.id, role=want))


def _can_admin_envs(db, uid):
    """Who may administer environments: see them all, delete one, hand out the
    manager role in one.

    Two different tests used to answer "is this person a system admin". The
    ניהול מערכת screen opens on the `manage_system` capability; the actions
    offered inside it asked instead for a WorkspaceMember row with role=admin.
    Someone holding one and not the other was let into the screen that lists
    every environment and refused every action on it — which is exactly what
    production looked like next to QA, where the same person also holds the row.

    It is now one question, and it is the capability, because that is what the
    screen itself is gated on: whoever may open it may act in it. `_cap`
    already treats a workspace admin as holding everything, so nobody who could
    do this before loses it.
    """
    return _cap(db, uid, "manage_system")

def get_db():
    with Session(engine) as session:
        yield session

# ── API Models ───────────────────────────────────────────────────────

class TaskOut(BaseModel):
    id: int; board_id: int; group_id: Optional[int]
    title: str; description: Optional[str]
    status: str; priority: str; position: int
    due_date: Optional[datetime]; start_date: Optional[datetime]
    estimated_hours: Optional[float]; actual_hours: Optional[float]
    location_lat: Optional[float]; location_lng: Optional[float]
    address: Optional[str]; gis_layer_id: Optional[str]
    custom_fields: dict; is_archived: bool
    created_by: Optional[int]
    created_at: datetime; updated_at: datetime
    assignees: list = []
    subtask_count: int = 0
    comment_count: int = 0

class BoardOut(BaseModel):
    id: int; name: str; description: Optional[str]
    board_type: str; icon: str; color: str
    is_archived: bool
    department_name: Optional[str] = ""
    groups: list = []
    tasks: list = []
    task_count: int = 0

class DashboardOut(BaseModel):
    total_tasks: int
    tasks_by_status: dict
    tasks_by_priority: dict
    overdue_tasks: int
    citizen_requests_open: int
    permits_pending: int
    recent_activity: list = []

# ── API Routes ───────────────────────────────────────────────────────

# The tag of the container image this process was built from, stamped by the
# release pipeline. A deploy that only checks for HTTP 200 proves that
# *something* is answering, which is exactly what a container that never
# restarted also does — so the release goes green while the old code keeps
# serving. Echoing the tag turns "is it up" into "is it the build I just
# pushed". Unauthenticated on purpose: this is also the App Service health
# check path, and the platform's probe carries no identity. A build number is
# not a secret.
IMAGE_TAG = os.environ.get("MISSIONS_IMAGE_TAG") or "dev"


@app.get("/api/status")
def status(request: Request):
    # The SPA shows the local user picker only in dev mode, so this has to be
    # the mode THIS request is actually authenticated under — dev is honoured
    # only when the app is served locally. It exposes no user data.
    return {"status": "ok", "app": "CODE-CAL MISSIONS", "version": "0.1.0",
            "image_tag": IMAGE_TAG,
            "auth_mode": effective_auth_mode(request)}

@app.get("/api/dashboard")
def dashboard(user_id: int = Depends(current_user_id)):
    with Session(engine) as db:
        visible = _visible_board_ids(db, user_id)
        tasks = db.query(Task).filter(
            Task.is_archived == False, Task.board_id.in_(visible)
        ).all() if visible else []
        # on a board where this person is assigned_only, only their own items
        # count — the same cut their board shows them (see _assigned_only_ids)
        _vis = {bid: _assigned_only_ids(db, bid, user_id)
                for bid in _assigned_only_boards(db, user_id) if bid in visible}
        if _vis:
            tasks = [t for t in tasks if t.board_id not in _vis or t.id in _vis[t.board_id]]
        total = len(tasks)
        by_status = {}
        by_priority = {}
        overdue = 0
        now = datetime.now(timezone.utc).replace(tzinfo=None)
        for t in tasks:
            s = t.status.value if hasattr(t.status, 'value') else t.status
            p = t.priority.value if hasattr(t.priority, 'value') else t.priority
            by_status[s] = by_status.get(s, 0) + 1
            by_priority[p] = by_priority.get(p, 0) + 1
            due = t.due_date
            if due and hasattr(due, 'tzinfo') and due.tzinfo:
                due = due.replace(tzinfo=None)
            if due and due < now and s not in ("done", "cancelled"):
                overdue += 1
        citizen_open = db.query(CitizenRequest).filter(
            CitizenRequest.status.in_(["new", "assigned", "in_progress"])
        ).count()
        permits_pending = db.query(Permit).filter(
            Permit.status.in_(["draft", "submitted", "in_review"])
        ).count()
        return {
            "total_tasks": total,
            "tasks_by_status": by_status,
            "tasks_by_priority": by_priority,
            "overdue_tasks": overdue,
            "citizen_requests_open": citizen_open,
            "permits_pending": permits_pending,
            "recent_activity": [],
        }

# Views a board can expose. "table" is always present and cannot be removed.
ALL_VIEWS = ["table", "kanban", "gantt", "dashboard", "ceo", "calendar", "map", "gis"]

def _board_views(b):
    """Enabled views for a board. New boards start with only the main table;
    older/seeded boards (no explicit setting) keep all views for compatibility."""
    s = b.settings or {}
    v = s.get("views")
    if not v:
        return list(ALL_VIEWS)
    # always keep table first and present
    out = ["table"] + [x for x in v if x in ALL_VIEWS and x != "table"]
    return out

# Per-board status vocabulary. Each entry is {key,label,color} where `key` is one
# of the underlying TaskStatus values. Keeping the enum key under the hood means
# the automations, the parent roll-up, the kanban and the charts keep working
# (they all key off task.status) while a board admin may rename/recolor/reorder the statuses
# and expose only the ones the board actually uses.
# The vocabulary a board starts with. Colours come from the status palette, and
# "טרם הוגדר" is not here: it is the state of an item nobody has set, carried as
# custom_fields.status_unset, so listing it would make "not chosen" a choice.
#
# `base` is the engine value the status behaves as — what the automations, the
# kanban and the charts read. Two entries may share one: תקוע and הקפאה are
# different words for an item that is not moving, and both park it in on_hold.
# An entry whose key is not itself an engine value must use the x_ prefix, or
# _norm_board_status drops it the first time an admin saves the list.
STATUS_DEFAULTS = [
    {"key": "done",        "label": "בוצע",   "color": "#1AC877"},
    {"key": "in_progress", "label": "בטיפול", "color": "#FBAA47"},
    {"key": "on_hold",     "label": "תקוע",   "color": "#DB2D4C"},
    {"key": "x_frozen",    "label": "הקפאה",  "color": "#FD5AC3", "base": "on_hold"},
    {"key": "cancelled",   "label": "בוטל",   "color": "#9BADBC"},
]
# What the ENGINE understands, which is the TaskStatus enum — not whatever the
# default vocabulary happens to offer. These were the same set until the
# defaults stopped covering every enum value; deriving this from the defaults
# would have made backlog, todo and review invalid keys overnight and dropped
# them from every board that had saved one.
_STATUS_KEYS = {s.value for s in TaskStatus}

def _valid_hex(c):
    c = str(c or "")
    if len(c) == 7 and c[0] == "#":
        try:
            int(c[1:], 16); return True
        except ValueError:
            return False
    return False

# A custom "status" column carries its own vocabulary — the board admin names and
# colours the labels of every such column separately (the built-in status column
# has its own, board-wide list above). Stored on the column as
def _number_col_cfg(raw):
    """How a number column is shown: a unit beside the figure, and whether the
    thousands are grouped. Or None, which is a plain number.

    Presentation only — the cell stores a number and goes on storing one, so
    sorting, formulas and the Excel export are untouched by anything set here,
    and the unit can be changed as often as anyone likes without rewriting a
    single cell. Stored as nothing when it says nothing, so a board that never
    opened the screen does not carry the defaults around.
    """
    if not isinstance(raw, dict):
        return None
    unit = str(raw.get("unit") or "").strip()[:6]
    thousands = bool(raw.get("thousands"))
    return {"unit": unit, "thousands": thousands} if (unit or thousands) else None


# options=[{label,color}]; an empty/absent list means "use the client defaults".
STATUS_COL_MAX = 30

def _status_col_options(raw):
    """Normalise a status column's own vocabulary, or None when unset.

    Each option carries a stable id. A cell stores that id, so renaming or
    recolouring the option is a change in one place that every cell already
    referencing it picks up — no rewriting of item data, and nothing to go
    stale if a rewrite were to fail halfway.
    """
    if not isinstance(raw, list):
        return None
    out, seen, ids = [], set(), set()
    for it in raw:
        if isinstance(it, str):
            it = {"label": it}
        if not isinstance(it, dict):
            continue
        label = (str(it.get("label") or "").strip())[:40]
        if not label or label in seen:
            continue
        seen.add(label)
        oid = str(it.get("id") or "").strip()
        if not oid or oid in ids:
            oid = "o_" + uuid.uuid4().hex[:8]
        ids.add(oid)
        out.append({"id": oid, "label": label,
                    "color": it.get("color") if _valid_hex(it.get("color")) else "#c4c4c4"})
        if len(out) >= STATUS_COL_MAX:
            break
    return out or None


# The vocabulary a status COLUMN falls back to when it has none of its own —
# the same five words in the same colours as STATUS_OPTS in index.html, which
# is where this list has lived alone until now.
#
# That it lived only in the browser is the whole of a bug worth writing down.
# A status column born from the board's "+" is given this vocabulary outright
# and stores it, so most columns have their own. A column that arrives without
# one — imported from a monday export whose status column was empty and whose
# file carried no column definitions, or made before columns were given a
# vocabulary at all — has `options` of None, and the two halves of the product
# then disagreed about what it offers. The grid falls back to this list in
# statusColOpts and lets anybody pick from it. The form's options are served
# by THIS process, which had no such list: a published form drew the question
# as an empty "—" and refused every answer with "הערך אינו אחת האפשרויות",
# while the form editor beside it — drawing from statusColOpts — showed the
# five words and looked perfectly well. A question nobody could answer, in a
# form that previewed correctly.
#
# `id` is None on purpose and is not an oversight: these options are not in
# the column, so there is nothing for a cell to point AT. A cell written
# against one carries the label and the colour, which is exactly what
# pickStatusCell writes in the browser for the same pick.
STATUS_COL_FALLBACK = (
    {"id": None, "label": "בוצע", "color": "#1AC877"},
    {"id": None, "label": "בטיפול", "color": "#FBAA47"},
    {"id": None, "label": "תקוע", "color": "#DB2D4C"},
    {"id": None, "label": "הקפאה", "color": "#FD5AC3"},
    {"id": None, "label": "בוטל", "color": "#9BADBC"},
)


def _status_col_vocab(col):
    """What a status column offers: its own list, or the default behind it.

    One function so that what a form offers and what a form accepts cannot
    drift apart — they are the two places that were already written twice.
    """
    return _status_col_options((col or {}).get("options")) or [
        dict(o) for o in STATUS_COL_FALLBACK]


# A board may define up to this many statuses. Only seven of them can be a
# TaskStatus value — the ones the engine keys off for automation conditions,
# kanban columns and charts. Any status beyond those seven is a board-defined label
# that *behaves as* one of the seven (its `base`): the item stores the base in
# task.status so all of that keeps working, and carries the chosen label and
# colour in custom_fields, which is what the grid renders.
BOARD_STATUS_MAX = 30

def _norm_board_status(it, seen):
    """One validated {key,label,color,base} entry, or None to skip it."""
    if not isinstance(it, dict):
        return None
    key = str(it.get("key") or "").strip()
    label = (str(it.get("label") or "").strip())[:40]
    if key in _STATUS_KEYS:                       # one of the seven built-ins
        base = key
    elif not key or key.startswith("x_"):          # a board-defined status
        # no key means "newly added" — the server mints it. An arbitrary
        # unknown key is still a client mistake and is dropped, as before.
        base = it.get("base") if it.get("base") in _STATUS_KEYS else "in_progress"
        key = key or ("x_" + uuid.uuid4().hex[:8])
    else:
        return None
    if not label:
        label = key
    if key in seen:
        return None
    seen.add(key)
    color = it.get("color") if _valid_hex(it.get("color")) else "#c4c4c4"
    return {"key": key, "label": label, "color": color, "base": base}

def _board_statuses(b):
    """The board's ordered status list (defaults when the admin hasn't customised)."""
    raw = (b.settings or {}).get("statuses")
    if not raw:
        return [dict(x, base=x.get("base", x["key"])) for x in STATUS_DEFAULTS]
    out, seen = [], set()
    for it in raw:
        e = _norm_board_status(it, seen)
        if e:
            out.append(e)
        if len(out) >= BOARD_STATUS_MAX:
            break
    return out or [dict(x, base=x.get("base", x["key"])) for x in STATUS_DEFAULTS]

# ── "יש בו שימוש" — a status items wear is not a status anyone may delete ──
# A status is a word the board agreed on, and every item wearing it points at
# that word. Dropping it out of the vocabulary while items still point at it
# leaves cells holding a value the board no longer offers: the grid goes on
# drawing the label it cached, the picker does not list it, the filter cannot
# ask for it, and no screen can say WHY the three disagree. So the removal is
# refused while anything still carries it. Moving those items to another
# status is a decision about the WORK — it belongs to the person making it,
# not to a deletion that makes it for them silently.
#
# Counted over the items the board SHOWS: the recycle bin is out of every
# query here already (_hide_deleted_tasks) and archived items are left out
# too, so the number in the refusal is a number the admin can go and look at.

def _status_usage_rows(db, board):
    """Every live item of the board — its sub-items among them — carrying only
    the two fields a status is read out of. Only those two are loaded: a board
    holds thousands of items and this question is asked every time the status
    editor opens."""
    if board is None:
        return []
    return (db.query(Task)
              .options(load_only(Task.status, Task.custom_fields))
              .filter(Task.board_id == board.id,
                      Task.is_archived == False)                     # noqa: E712
              .all())


def _board_status_usage(db, board, rows=None):
    """{status key: how many items wear it} for the board's own vocabulary.

    Read through _task_status_key and not off task.status, because the enum is
    the one thing that cannot tell תקוע from הקפאה — both are stored as
    on_hold, and counting the enum would guard one of the two and refuse the
    other for a use that was never its own.
    """
    out = {}
    for t in (_status_usage_rows(db, board) if rows is None else rows):
        if (t.custom_fields or {}).get("status_unset"):
            continue                    # "טרם הוגדר" is not one of the words
        k = str(_task_status_key(t))
        out[k] = out.get(k, 0) + 1
    return out


def _status_col_usage(db, board, col, rows=None):
    """{option id: how many items wear it} for one status COLUMN's vocabulary.

    `col` is the column as it stands BEFORE the save — a cell written by the
    grid holds the label rather than the id, and _status_cell_key can only
    turn it back into an id against the options that label still belongs to.
    """
    cid = str((col or {}).get("id") or "")
    out = {}
    if not cid:
        return out
    for t in (_status_usage_rows(db, board) if rows is None else rows):
        k = _status_cell_key(col, (t.custom_fields or {}).get(cid))
        if k:
            out[str(k)] = out.get(str(k), 0) + 1
    return out


# The refusal both gates raise. One shape for the board's own statuses and a
# column's, because the editor that removed either of them is the same screen
# and should not need two ways to read the same "no".
def _status_in_use_409(entries):
    raise HTTPException(409, {
        "message": "לא ניתן למחוק סטטוס שיש בו שימוש — העבר תחילה את הפריטים לסטטוס אחר",
        "statuses": entries})


# ── the same agreement, for a dropdown ("רשימה") column ──
# A dropdown option is a bare word — no id, no colour — and a cell holds the
# LIST of words ticked in it. So usage is counted by text, once per item even
# if a cell somehow carries a word twice: the number in a refusal is "how many
# items do I have to go and fix", not how many times the word was written.

def _dropdown_cell_words(v):
    """The option words one dropdown cell carries, whatever shape it was
    written in. The grid writes a list of strings; an older cell or an import
    may hold a lone string, and a list entry may be an {label} dict — read the
    same way filter_ast._cell reads them, so the count and the filter agree
    about what a cell says."""
    if v in (None, "", []):
        return []
    arr = v if isinstance(v, list) else [v]
    out = []
    for x in arr:
        x = x.get("label") if isinstance(x, dict) else x
        if x is None or str(x) == "":
            continue
        if str(x) not in out:
            out.append(str(x))
    return out


def _dropdown_col_usage(cid, rows):
    """{option word: how many items carry it} for one dropdown column, over
    the rows _status_usage_rows hands back — live, unarchived, sub-items
    included."""
    out = {}
    cid = str(cid or "")
    if not cid:
        return out
    for t in rows:
        for w in _dropdown_cell_words((t.custom_fields or {}).get(cid)):
            out[w] = out.get(w, 0) + 1
    return out


def _dropdown_inactive(options, raw):
    """The column's inactive options, cut down to words it actually offers —
    deduplicated, in the order they were sent.

    Matched against the options AS STORED and kept in their stored form. An
    imported column can hold a number as an option (3, not "3"), and the
    browser sends back whatever it rendered; keeping only `str` entries here
    meant such an option could never be retired — the request "succeeded" and
    the entry was silently dropped. A sent value names an option when it is
    equal to it or prints the same, and what is kept is the option itself, so
    the `o not in off` checks elsewhere (the form's offered list) compare like
    with like."""
    opts = list(options or [])
    out = []
    for x in (raw if isinstance(raw, list) else []):
        if x is None or isinstance(x, (dict, list)):
            continue
        hit = next((o for o in opts if o == x), None)
        if hit is None:
            hit = next((o for o in opts if str(o) == str(x)), None)
        if hit is not None and hit not in out:
            out.append(hit)
    return out


# ── Priority is a status column too ──────────────────────────────────────
# "עדיפות" is the same kind of thing as "סטטוס": one value out of a named,
# coloured vocabulary. So it gets the same treatment — a board admin renames,
# recolours, reorders, adds and removes its values, up to BOARD_PRIORITY_MAX,
# exactly as with the statuses above. Five of them can be a Priority enum value
# (what sorting and the charts key off); anything beyond behaves as one of those
# five (its `base`), with the chosen label and colour carried on the item.
PRIORITY_DEFAULTS = [
    {"key": "low", "label": "נמוכה", "color": "#579bfc"},
    {"key": "medium", "label": "בינונית", "color": "#5559df"},
    {"key": "high", "label": "גבוהה", "color": "#fdab3d"},
    {"key": "critical", "label": "קריטית", "color": "#e2445c"},
    {"key": "emergency", "label": "חירום", "color": "#bb3354"},
]
_PRIORITY_KEYS = {p["key"] for p in PRIORITY_DEFAULTS}
BOARD_PRIORITY_MAX = 30

def _norm_board_priority(it, seen):
    """One validated {key,label,color,base} priority, or None to skip it."""
    if not isinstance(it, dict):
        return None
    key = str(it.get("key") or "").strip()
    label = (str(it.get("label") or "").strip())[:40]
    if key in _PRIORITY_KEYS:                      # one of the five built-ins
        base = key
    elif not key or key.startswith("x_"):           # a board-defined priority
        base = it.get("base") if it.get("base") in _PRIORITY_KEYS else "medium"
        key = key or ("x_" + uuid.uuid4().hex[:8])
    else:
        return None
    if not label:
        label = key
    if key in seen:
        return None
    seen.add(key)
    color = it.get("color") if _valid_hex(it.get("color")) else "#c4c4c4"
    return {"key": key, "label": label, "color": color, "base": base}

def _board_priorities(b):
    """The board's ordered priority list (defaults when it hasn't customised)."""
    raw = (b.settings or {}).get("priorities")
    if not raw:
        return [dict(x, base=x["key"]) for x in PRIORITY_DEFAULTS]
    out, seen = [], set()
    for it in raw:
        e = _norm_board_priority(it, seen)
        if e:
            out.append(e)
        if len(out) >= BOARD_PRIORITY_MAX:
            break
    return out or [dict(x, base=x["key"]) for x in PRIORITY_DEFAULTS]

def _resolve_priority(board, value):
    """Map a chosen priority key to (engine value, the fields the item carries).

    A board-defined priority is not a Priority enum value, so it is stored as its
    `base` with the chosen label and colour on the item — the same arrangement as
    a board-defined status. Returns (None, None) for a key this board does not
    know, so the caller can leave the priority alone rather than crash on it.
    """
    key = str(value or "").strip()
    if not key:
        return None, None
    cleared = {"priority_key": None, "priority_label": None,
               "priority_color": None, "priority_unset": None}
    if key in _PRIORITY_KEYS:
        return key, cleared
    e = next((p for p in _board_priorities(board) if p["key"] == key), None) if board else None
    if not e:
        return None, None
    return e["base"], {"priority_key": e["key"], "priority_label": e["label"],
                       "priority_color": e["color"], "priority_unset": None}

BOARD_VISIBILITY = ("private", "public")

def _board_visibility(b):
    """'private' — only people invited to the board — or 'public' — anyone who
    belongs to the board's environment.

    Unset reads as private, which is exactly how every board behaved before this
    setting existed. Boards that predate it therefore keep their audience, and
    nothing becomes visible to anyone because of an upgrade.
    """
    v = ((b.settings or {}).get("visibility") if b else None)
    return v if v in BOARD_VISIBILITY else "private"

# ── the recycle bin's one rule ────────────────────────────────────────
# A deleted item is invisible to every query in the application, including the
# ones that load it through a relationship (board.tasks, task.subtasks).
#
# This is a single event hook rather than a filter added to each query on
# purpose: there are ~50 places that read Task, and the failure mode of missing
# one is a deleted item still showing on a board — silent, and exactly the bug
# the feature exists to prevent. One rule cannot be forgotten.
#
# The bin itself, restore and permanent delete opt out with
# .execution_options(include_deleted=True); they are the only code that should.
@event.listens_for(Session, "do_orm_execute")
def _hide_deleted_tasks(state):
    if state.is_select and not state.execution_options.get("include_deleted", False):
        state.statement = state.statement.options(
            with_loader_criteria(Task, lambda cls: cls.deleted_at.is_(None), include_aliases=True)
        )


def _board_role(db, board_id, user_id):
    """Board-scoped role (admin/editor/viewer) for a user, or None if no access."""
    if user_id is None:
        return None
    # System (workspace) admins are admins of every board, and this is asked
    # BEFORE the membership row rather than after it.
    #
    # Asked after, being invited to a board — an act that only ever adds — took
    # rights away: a system administrator holds admin on every board they were
    # never added to, and the moment somebody invited them to one as "חבר לוח"
    # the explicit row answered "editor" and the board became the single place
    # in the system they could not manage. That is how "מנהל מערכת לא יכול
    # למחוק אוטומציה" happened: _can_manage_automations reads this function,
    # saw "editor", and the delete came back 403 — on a board the same person
    # administers in every other respect.
    #
    # An explicit row still decides everything for everybody else, and still
    # decides the role of an admin's membership for anything that reads the row
    # itself (the members list shows what they were invited as). What it no
    # longer does is lower what being a system administrator already granted.
    if _ws_role(db, user_id) == "admin":
        return "admin"
    m = db.query(BoardMember).filter(BoardMember.board_id == board_id,
                                     BoardMember.user_id == user_id).first()
    if m:
        return m.role
    # A public board is readable by everyone in its environment, with no invite.
    # Deliberately 'viewer': being able to see a board is not permission to
    # change it, so contributing still requires being invited. An explicit
    # BoardMember row wins, above, so inviting someone to a public board as an
    # editor still upgrades them.
    b = db.query(Board).filter(Board.id == board_id).first()
    if (b is not None and b.deleted_at is None and _board_visibility(b) == "public"
            and _env_role(db, b.environment_id, user_id) is not None):
        return "viewer"
    return None

def _is_board_admin(db, board_id, user_id):
    return _board_role(db, board_id, user_id) == "admin"

def _account_blocked(db, user_id):
    """Is this a deactivated account?

    A blocked user stays in the directory — their name is on everything they
    ever did, and the history has to keep reading correctly — but they are not
    a colleague any more: nobody may invite them, tag them, mention them or
    name them in a rule. "Deactivated" is the end of participation, not a
    cosmetic flag on a user who still turns up in every picker.

    Only an explicit False blocks. The column was added to databases that
    already had users, so NULL means "nobody ever deactivated this one".
    """
    if user_id is None:
        return False
    return bool(db.query(User.id)
                  .filter(User.id == user_id, User.is_active.is_(False)).first())

def _can_be_assigned(db, board_id, user_id):
    """May this user be tagged on this board's items? Only people INVITED to it.

    Deliberately not `_board_role`, which a public board satisfies for everyone
    in the environment. Being able to read a board is not the same as being part
    of the work on it: on a busy public board, "everyone in the environment"
    would turn every people column and every @-menu into a directory of hundreds,
    and would let anyone put a colleague's name on an item they never agreed to
    own. Tagging follows the invitation, not the audience.

    Workspace admins stay taggable — they reach every board without an explicit
    invite, and excluding them would make it impossible to tag the very people
    who administer the system. A *blocked* workspace admin is not an exception
    to that: deactivation outranks every role.

    This is the one gate for naming a person — people columns, the assignee
    circles, @-mentions and the person field of an automation all come through
    here — so a deactivated account answered here is refused everywhere at once.
    """
    if user_id is None:
        return False
    if _account_blocked(db, user_id):
        return False
    m = db.query(BoardMember).filter(BoardMember.board_id == board_id,
                                     BoardMember.user_id == user_id).first()
    if m:
        return True
    return _ws_role(db, user_id) == "admin"

def _item_visible_to(db, task, user_id, board=None, cf=None, assignee_ids=None):
    """May `user_id` see this item — judged against the values it is ABOUT to
    hold, not only the ones it holds now?

    The tagging rule needs this and _item_perm cannot give it: when a single
    save both puts an assigned_only member into the perm column and into some
    other people column, the second is legitimate only because of the first,
    and the item as stored does not show the first yet. `cf` and
    `assignee_ids` are the after-state; left None, the item's own are read. A
    brand-new item that is not in the session yet works the same way.

    Same order of answers as _item_perm: an override first, then the role, and
    only assigned_only is ever closed by default."""
    if user_id is None or task is None:
        return False
    role = _board_role(db, task.board_id, user_id)
    if role is None:
        return False
    ov = (task.permissions or {}).get(str(user_id))
    if ov in ("view", "edit", "delete"):
        return True
    if ov == "none":
        return False
    if role != "assigned_only":
        return True
    if board is None:
        board = db.query(Board).filter(Board.id == task.board_id).first()
    col = _board_perm_col(board)
    if col == "assignees":
        ids = (set(assignee_ids) if assignee_ids is not None
               else {u.id for u in (task.assignees or [])})
        if user_id in ids:
            return True
    else:
        vals = (cf if cf is not None else (task.custom_fields or {})).get(col)
        if isinstance(vals, list) and user_id in vals:
            return True
    if task.parent_id:
        parent = db.query(Task).filter(Task.id == task.parent_id).first()
        return parent is not None and _assigned_in(parent, user_id, col)
    return False

def _not_taggable_reason(db, board_id, user_id, task=None):
    """Why this person may not be named on this board, in words — "" if they may.

    Two different refusals used to read as one: a deactivated member was told
    they were "not a member of the board", which they are, which sent whoever
    read it looking at the board's invitations for a problem that is on the
    user's account.

    With `task`, also: a member who cannot see THAT item — an assigned_only
    member who is not assigned to it, or anyone it is closed to by an
    override. Naming them on it would send a notification for an item they
    cannot open, the same reason a non-member is refused.
    """
    if _account_blocked(db, user_id):
        return "חשבונו מושבת"
    if not _can_be_assigned(db, board_id, user_id):
        return "אינו חבר בלוח"
    if task is not None and not _item_visible_to(db, task, user_id):
        return "אין לו גישה לפריט זה"
    return ""

def _may_name_on(db, task, user_id, col_id, board=None, cf=None):
    """May this member be written into people column `col_id` ("assignees" for
    the circles) of this item — the tagging rule's item half, for the writers
    that are not a person at a cell: automations, mappings, mirrors.

    Always into the board's perm column: that is how an assigned member is
    given an item. Into any other only if they can see the item, judged with
    `cf` as the cells will be. Board membership is the caller's own check
    (_can_be_assigned) and is not repeated here."""
    if board is None:
        board = db.query(Board).filter(Board.id == task.board_id).first()
    if col_id == _board_perm_col(board):
        return True
    return _item_visible_to(db, task, user_id, board, cf=cf)

def _filter_people_values(db, board_id, cf, before, task=None):
    """Drop non-members from people-column values in `cf` (in place).
    Only *newly added* ids are rejected: ids already stored on the item survive so
    that items tagged before this rule stay editable and can be cleaned up by
    hand, instead of a legacy value making the whole cell impossible to save.

    With `task` (the item being written, new or existing), a newly added id
    must also be somebody who can see the item — except in the board's perm
    column, because putting a person THERE is exactly how an assigned_only
    member is given the item. Visibility is judged on the item as it will be
    after this save (`before` merged with `cf`), so naming someone in the perm
    column and in another column at once is accepted."""
    board = db.query(Board).filter(Board.id == board_id).first()
    cols = {c["id"]: c for c in ((board.settings or {}).get("columns", []) if board else [])}
    perm_col = _board_perm_col(board) if task is not None else None
    after = {**(before or {}), **cf} if task is not None else None
    for key, val in list(cf.items()):
        if not isinstance(val, list):
            continue
        col = cols.get(key)
        if not col or col.get("type") != "people":
            continue
        kept = [c for c in (before or {}).get(key, []) if c in val]   # preserved, order-safe
        # An imported name with no account here is a string, not an id: a record
        # of who was on the item in monday. It is no one's assignment, so the
        # membership rule has nothing to say about it — and handing it to
        # _can_be_assigned would compare text to an integer column, which
        # Postgres refuses outright.
        cf[key] = [uid for uid in val
                   if not isinstance(uid, int) or uid in kept
                   or (_can_be_assigned(db, board_id, uid)
                       and (task is None or key == perm_col
                            or _item_visible_to(db, task, uid, board, cf=after)))]

# The two "assigned" roles rank with the viewer for everything decided at board
# level — creating items, groups, columns, views, moving, automations. What they
# may do beyond reading is decided item by item, in _item_perm, and must never
# leak upward into a board-wide grant. An unknown role ranks below everything
# (the .get(role, -1) at every reader), which is the safe direction.
_BROLE_ORDER = {"viewer": 0, "assigned_editor": 0, "assigned_only": 0,
                "editor": 1, "admin": 2}
def _require_board_edit(db, board_id, actor, need="editor", msg=None):
    """Enforce board-level write permission (closes IDOR on board mutations).
    The actor must be a board member whose role meets `need` (editor|admin).

    This used to return silently when `actor` was None, which meant dropping the
    parameter skipped the check entirely. Identity now comes from the transport,
    so None means unauthenticated and must be refused.

    `msg` names what was refused. The default reads "you may not change this
    board", which is true of a viewer but a lie to an editor asking for
    something only an admin may do — they change the board all day. A caller
    asking for more than editor should say what it is asking for."""
    if actor is None:
        raise HTTPException(401, "נדרשת התחברות")
    role = _board_role(db, board_id, actor)
    if role is None or _BROLE_ORDER.get(role, -1) < _BROLE_ORDER.get(need, 1):
        raise HTTPException(403, msg or "אין לך הרשאה לשנות לוח זה")

def _visible_board_ids(db, user_id):
    """Set of board IDs a user is allowed to see (membership-based).
    Mirrors /api/boards visibility so aggregate views (dashboard, CEO,
    insights) never leak boards the user was not invited to.
    An unauthenticated caller (user_id=None) sees nothing — this used to return
    every board, so omitting the parameter exposed the whole workspace."""
    live = db.query(Board).filter(Board.is_archived == False, Board.deleted_at == None).all()
    all_ids = {b.id for b in live}
    if user_id is None:
        return set()
    if _ws_role(db, user_id) == "admin":   # system admins see every board
        return all_ids
    member_ids = {m.board_id for m in db.query(BoardMember).filter(BoardMember.user_id == user_id).all()}
    # plus every public board in an environment this user belongs to — the
    # primary workspace included, which is why a board kept private there stays
    # private: visibility inside it is the board's own, like anywhere else
    env_ids = _user_env_ids(db, user_id)
    public_ids = {b.id for b in live
                  if b.environment_id in env_ids and _board_visibility(b) == "public"}
    return {i for i in all_ids if i in member_ids or i in public_ids}

def _primary_env_id(db):
    e = db.query(Environment).filter(Environment.is_primary == True).first()   # noqa: E712
    return e.id if e else None

def _user_env_ids(db, user_id):
    """The environments a user is in — the ones they were given, and no others.

    The primary workspace used to be the exception: everybody was in it with or
    without a row, because it was where the organisation met. But a board lives
    in an environment, and "who may be invited to this board" is read off the
    environment — so on the workspace almost every board lives in, that question
    answered "the entire user directory", which is the opposite of what an
    invitation is. Belonging to it is now a row somebody wrote, exactly like
    every other workspace.

    Nobody lost access to a board they could already open: the rows were
    backfilled once at startup for everyone already on a board there — see
    _seed_environments.

    This still says nothing about which BOARDS they see inside it. A board in
    the primary workspace is seen exactly as a board anywhere else is: public to
    the workspace, or by invitation — see _visible_board_ids."""
    if user_id is None:
        return set()
    return {m.environment_id for m in
            db.query(EnvironmentMember).filter(EnvironmentMember.user_id == user_id).all()}

def _ws_role(db, user_id):
    """The workspace role everything reads — and it answers for User.role first.

    Two rows carry "is this person an admin": User.role, which the users screen
    edits, and this one. _sync_ws_role makes the second follow the first when a
    role is CHANGED there; it cannot stop the workspace screen from writing a
    row that contradicts it afterwards, and that screen does exactly that.
    Inviting a מנהל מערכת to the workspace as "חבר" overwrote their row with
    "member", and since this function is what _board_role, _can_admin_envs and
    the automations gate all read, the administrator was left with User.role
    still saying admin — the users screen went on listing them as one — and no
    rights on a single board in the system. That is the second half of
    "מנהל מערכת לא יכול למחוק אוטומציה": the first was the board row winning
    over the system role, this is the workspace row doing the same.

    Answered here rather than only at the write sites because a database that
    already holds such a row would stay broken until someone noticed and
    re-saved the user. A system administrator is a workspace admin by
    definition — _ws_role_for has always said so — so the row is not consulted
    to find that out.
    """
    if user_id is None:
        return None
    u = db.query(User).filter(User.id == user_id).first()
    if u is not None and u.role == "admin":
        return "admin"
    m = db.query(WorkspaceMember).filter(WorkspaceMember.user_id == user_id).first()
    return m.role if m else None

# ── Multi-level permission model (סביבה → לוח → פריט → עמודה) ────────
def _board_caps(role):
    """Capabilities implied by a board role.

    The two assigned roles are "view" here on purpose — this is the BOARD-level
    answer, and at board level they are viewers. Their right to edit an item
    they are assigned to is granted per item by _item_perm, and their being
    unable to see the rest (assigned_only) is taken away there too."""
    return {
        "admin":  {"view", "edit", "delete", "manage"},
        "editor": {"view", "edit"},
        "viewer": {"view"},
        "assigned_editor": {"view"},
        "assigned_only": {"view"},
    }.get(role, set())

ASSIGNED_ROLES = ("assigned_editor", "assigned_only")

def _board_perm_col(board):
    """Which column says who an item is "assigned to", for the assigned roles.

    "assignees" — the built-in circles every board has — unless the board admin
    named one of the board's own people columns in settings.perm_column. A
    name that no longer points at a people column (the column was deleted, or
    retyped) falls back to the circles rather than to nothing: nothing would
    silently turn every assigned_only member's board empty, which reads as
    data loss to the person looking at it."""
    if board is None:
        return "assignees"
    pc = (board.settings or {}).get("perm_column")
    if not pc or pc == "assignees":
        return "assignees"
    for c in (board.settings or {}).get("columns", []) or []:
        if c.get("id") == pc:
            return pc if c.get("type") == "people" else "assignees"
    return "assignees"

def _assigned_in(task, user_id, col):
    """Is `user_id` named in this one item's perm column? (Not its parent's.)"""
    if task is None or user_id is None:
        return False
    if col == "assignees":
        return any(u.id == user_id for u in (task.assignees or []))
    vals = (task.custom_fields or {}).get(col)
    return isinstance(vals, list) and user_id in vals

def _is_assigned(task, user_id, col=None):
    """Assigned to this item — directly, or through its parent.

    A sub-item follows its parent: whoever owns the item owns the steps under
    it, and an assigned_only member who could open an item but not the
    sub-items it is made of would be looking at half of their own work. The
    perm column is read off the item's board unless the caller already has it.

    The parent is looked up through the session's identity map, so where it is
    already loaded it costs no query. A loop over a whole board should not
    come here at all — see _assign_scope."""
    if task is None or user_id is None:
        return False
    if col is None:
        try:
            col = _board_perm_col(task.board)
        except Exception:
            # Detached object: nothing to resolve the board with. Closed, not
            # a guess — guessing "assignees" on a board whose perm column is
            # another one would hand an item to whoever is in the circles.
            return False
    if _assigned_in(task, user_id, col):
        return True
    if task.parent_id:
        from sqlalchemy.orm import object_session
        sess = object_session(task)
        parent = sess.get(Task, task.parent_id) if sess is not None else None
        if parent is not None and _assigned_in(parent, user_id, col):
            return True
    return False

def _assign_scope(db, board, user_id, include_bin=False):
    """The ids of this board's items `user_id` is named on in its perm column —
    computed once, for a loop that is about to ask _item_perm of every item.

    Asked one item at a time, "is this person in the assignees" is a lazy load
    per row, and the board payload deliberately does not load the relationship
    (see _prefetch_items) — so an assigned member opening a board of fifteen
    thousand items paid fifteen thousand queries for the one question. Here it
    is one query: the join table for the built-in column, and for a custom
    people column only that one cell of each row, extracted in SQL — not the
    whole custom_fields JSON of every item on the board. A sub-item is covered
    by checking its parent_id against the same set (see _item_perm).

    Live, unarchived items only, which is what every board read shows;
    `include_bin` widens it to the recycle bin and the archive for the readers
    that show those too (the bin, the board log — see _assigned_only_ids).

    Kept on the session and reused, because one board read asks twice (the
    count, then the rows) and _serialize_task asks per row. It is therefore a
    snapshot: right for a read, not to be trusted across a write that
    changes who is assigned."""
    from models import task_assignees as assignee_rows
    if board is None or user_id is None:
        return frozenset()
    key = ("_assign_scope_bin" if include_bin else "_assign_scope", board.id, user_id)
    hit = db.info.get(key)
    if hit is not None:
        return hit
    col = _board_perm_col(board)
    if col == "assignees":
        q = (db.query(assignee_rows.c.task_id)
               .join(Task, Task.id == assignee_rows.c.task_id)
               .filter(Task.board_id == board.id, assignee_rows.c.user_id == user_id))
        if include_bin:
            q = q.execution_options(include_deleted=True)
        else:
            q = q.filter(Task.is_archived == False, Task.deleted_at.is_(None))   # noqa: E712
        scope = frozenset(r[0] for r in q.all())
    else:
        q = (db.query(Task.id, Task.custom_fields[col])
               .filter(Task.board_id == board.id))
        if include_bin:
            q = q.execution_options(include_deleted=True)
        else:
            q = q.filter(Task.is_archived == False, Task.deleted_at.is_(None))   # noqa: E712
        scope = frozenset(tid for tid, v in q.all()
                          if isinstance(v, list) and user_id in v)
    db.info[key] = scope
    return scope

def _item_perm(task, user_id, board_role, scope=None):
    """Effective permission on a specific item: none|view|edit|delete.
    A per-user item override wins over the board role.

    For the two assigned roles the board role alone does not answer: assigned
    to the item (or to its parent) means "edit"; not assigned means "view"
    for assigned_editor and "none" for assigned_only. Every other role never
    reaches that branch, so the hot loops over big boards pay nothing for it.
    `scope` is _assign_scope's answer for the item's board, for a caller
    looping over many items; without it the item is asked directly."""
    ov = (task.permissions or {}).get(str(user_id))
    if ov in ("none", "view", "edit", "delete"):
        return ov
    if board_role in ASSIGNED_ROLES:
        if scope is not None:
            mine = task.id in scope or (task.parent_id is not None
                                        and task.parent_id in scope)
        else:
            mine = _is_assigned(task, user_id)
        if mine:
            return "edit"
        return "view" if board_role == "assigned_editor" else "none"
    caps = _board_caps(board_role)
    return "delete" if "delete" in caps else ("edit" if "edit" in caps else ("view" if "view" in caps else "none"))

def _assigned_only_sql(db, board, user_id):
    """The SQL condition an assigned_only reader's item counts are cut by — the
    same set _item_perm lets them see, so a count and the list it heads agree.

    Assigned (the item or its parent is in the perm column) and not closed by
    an override, or opened by one. The built-in column is a subquery; a custom
    people column lives in JSON, whose SQL differs between SQLite and
    Postgres, so its ids are gathered in Python by _assign_scope instead."""
    from models import task_assignees as assignee_rows
    from sqlalchemy import select
    ov = Task.permissions[str(user_id)].as_string()
    if _board_perm_col(board) == "assignees":
        mine = select(assignee_rows.c.task_id).where(assignee_rows.c.user_id == user_id)
    else:
        mine = list(_assign_scope(db, board, user_id))
    assigned = or_(Task.id.in_(mine), Task.parent_id.in_(mine))
    return or_(ov.in_(("view", "edit", "delete")),
               and_(assigned, or_(ov.is_(None), ov != "none")))

def _assigned_only_ids(db, board_id, user_id):
    """For an assigned_only reader: the ids of this board's items they may see,
    bin included. For anybody else: None — no narrowing to apply here.

    Board-wide readers that never asked an item anything — the board log, the
    export's conversation and files sheets, the aggregates — were written when
    every board role could see every item short of an override. For this one
    role the default is closed, and a log line, a comment row or a count is
    an item's content as much as its row is. They filter by this set.

    One query over (id, parent, permissions) and one for the perm column,
    whatever the size of the board."""
    if user_id is None or _board_role(db, board_id, user_id) != "assigned_only":
        return None
    board = db.query(Board).filter(Board.id == board_id).first()
    scope = _assign_scope(db, board, user_id, include_bin=True)
    key = str(user_id)
    out = set()
    for tid, pid, perms in (db.query(Task.id, Task.parent_id, Task.permissions)
                              .execution_options(include_deleted=True)
                              .filter(Task.board_id == board_id).all()):
        ov = (perms or {}).get(key)
        if ov in ("view", "edit", "delete"):
            out.add(tid)
        elif ov != "none" and (tid in scope or (pid is not None and pid in scope)):
            out.add(tid)
    return out

def _assigned_only_boards(db, user_id):
    """The boards on which this person is assigned_only — one query, for the
    readers that span every board they can see and must not ask _board_role
    once per board to find the few where the answer matters. A system admin
    is admin everywhere (see _board_role), so their rows say nothing."""
    if user_id is None:
        return set()
    # the membership rows first: nearly everybody has none, and for them this
    # is the one query the function costs
    ids = {bid for (bid,) in db.query(BoardMember.board_id)
                               .filter(BoardMember.user_id == user_id,
                                       BoardMember.role == "assigned_only").all()}
    if ids and _ws_role(db, user_id) == "admin":
        return set()
    return ids

def _board_item_count(db, board_id, user_id):
    """How many rows this reader's board has — counted in the database, with
    not one item loaded.

    It has to agree to the item with the `total` that /items/query answers for
    an unfiltered query, because both numbers land on the same screen: the
    board says how many items it holds, and the paged fetch says how many it
    is paging through, and two counts that disagree read as a bug in whichever
    one the person happens to distrust. So this counts the same set that route
    counts — the board's top-level items, not archived and not in the bin —
    and then takes out the same ones it takes out.

    The permission pass is the only part that is not a plain COUNT, and it is
    much closer to one than it looks: every board role grants "view", and this
    is only ever reached by somebody who has a role on the board, so the
    default is never "none". An item is invisible here exactly when it carries
    a per-user override that says so, which is a key in its `permissions` JSON
    and something SQL can read — the same expression the link picker already
    uses to keep closed items out of its own total.

    `deleted_at` is spelled out rather than left to the global soft-delete
    criteria. That hook is applied to entity queries, and this is an aggregate
    over a column; relying on it here would be relying on the ORM to notice a
    mapper it was never handed.
    """
    q = (db.query(func.count(Task.id))
           .filter(Task.board_id == board_id, Task.parent_id.is_(None),
                   Task.is_archived == False, Task.deleted_at.is_(None)))   # noqa: E712
    if user_id is not None:
        # The one role whose default IS "none": an assigned_only member sees
        # only what they are assigned to, so the count is cut the same way
        # the list is — see _assigned_only_sql.
        if _board_role(db, board_id, user_id) == "assigned_only":
            board = db.query(Board).filter(Board.id == board_id).first()
            return q.filter(_assigned_only_sql(db, board, user_id)).scalar() or 0
        closed = Task.permissions[str(user_id)].as_string()
        # an item with no override at all extracts as NULL, and NULL != 'none'
        # is NULL rather than true — left as a bare inequality this counted
        # nothing on a board where nobody had an override, which is every board
        q = q.filter(or_(closed.is_(None), closed != "none"))
    return q.scalar() or 0

def _link_states(db, ids, user_id):
    """What each linked id is, from `user_id`'s point of view:

      "live"       — a normal item they may see
      "deleted"    — the item is in the recycle bin, and they may see it
      "deleted_board" — the item is fine, but its whole board is in the bin
      None         — not theirs to know about, or gone for good

    "deleted" is deliberately its own answer rather than folded into None. This
    system's deletion policy is a recycle bin: the item can come back, and the
    relationship row is kept so that it comes back with it. A cell that quietly
    dropped the link would give no hint that anything was pending, and the link
    would then reappear out of nowhere on a restore. It is marked instead.

    Purged items are None: there is nothing to restore and nothing to mark, and
    _drop_links_for_tasks has already removed the rows anyway.

    A board in the bin makes its items unavailable even though the items
    themselves were never deleted — the board comes back with them, so this is
    the same "marked, not dropped" answer, told apart only so the cell can say
    where the thing actually went.

    Cached on the session — one board role and one Task row per id per request,
    however many cells point at the same linked item.
    """
    ids = [i for i in (ids or []) if isinstance(i, int)]
    if not ids:
        return {}
    seen = db.info.setdefault(("_link_state", user_id), {})
    roles = db.info.setdefault(("_brole", user_id), {})
    boards = db.info.setdefault("_board_state", {})     # not user-specific
    unknown = [i for i in set(ids) if i not in seen]
    if unknown:
        # explicitly including binned items: the global soft-delete hook would
        # otherwise make them indistinguishable from ids that never existed
        found = {t.id: t for t in db.query(Task).filter(Task.id.in_(unknown))
                 .execution_options(include_deleted=True).all()}
        for i in unknown:
            t = found.get(i)
            if t is None:
                seen[i] = None
                continue
            if t.board_id not in boards:
                bd = db.query(Board).filter(Board.id == t.board_id).first()
                boards[t.board_id] = ("missing" if bd is None else
                                      "bin" if bd.deleted_at is not None else "live")
            if boards[t.board_id] == "missing":
                seen[i] = None            # nothing to restore, nothing to mark
                continue
            # Deliberately not `is_archived`: archiving is housekeeping, not a
            # permission, and treating it as one would relabel an archived item
            # as something the viewer may not see.
            state = ("deleted" if t.deleted_at is not None else
                     "deleted_board" if boards[t.board_id] == "bin" else "live")
            if user_id is None:            # internal caller, nobody to filter for
                seen[i] = state
                continue
            if t.board_id not in roles:
                roles[t.board_id] = _board_role(db, t.board_id, user_id)
            r = roles[t.board_id]
            seen[i] = state if (r is not None and _item_perm(t, user_id, r) != "none") else None
    return {i: seen.get(i) for i in ids}


def _require_task_view(db, task_id, actor):
    """The task, if `actor` may see it. 403/404 otherwise.

    A connect column hands out item ids by design, and an id was enough to read
    an item's conversation, its files and its whole history — including its
    title — on a board the caller was never invited to. Seeing a link is not
    permission to open what it points at, and that has to be enforced on every
    door into the item, not only on GET /api/tasks/{id}.
    """
    t = db.query(Task).filter(Task.id == task_id).first()
    if not t:
        raise HTTPException(404, "task not found")
    board = db.query(Board).filter(Board.id == t.board_id).first()
    if not board or board.deleted_at:
        raise HTTPException(404, "task not found")
    if actor is not None:
        role = _board_role(db, t.board_id, actor)
        if role is None:
            raise HTTPException(403, "אין לך גישה ללוח זה")
        if _item_perm(t, actor, role) == "none":
            raise HTTPException(403, "אין לך גישה לפריט זה")
    return t


def _require_item_edit(db, task, actor):
    """403 unless `actor` may change this item.

    For an assigned member that is the item's own answer — assigned to it, or
    given it by an override — because at board level they are viewers and
    _require_board_edit would refuse them their own work. For everybody else
    it is the board-level gate it always was, and then the item: an override
    closing an item to an editor closes it to every write, not only to the
    PATCH that already asked."""
    if actor is None:
        raise HTTPException(401, "נדרשת התחברות")
    role = _board_role(db, task.board_id, actor)
    if role not in ASSIGNED_ROLES:
        _require_board_edit(db, task.board_id, actor)
    if _item_perm(task, actor, role) not in ("edit", "delete"):
        raise HTTPException(403, "אין לך הרשאת עריכה לפריט זה")
    return role


def _visible_link_ids(db, ids, user_id):
    """Of these item ids, the ones `user_id` may see — live or waiting in the bin.

    A connect cell holds ids of items on OTHER boards, so the viewer's access to
    the board they are reading says nothing about their access to the other end.
    Everything the connect column shows, offers or resolves goes through here.

    `user_id=None` means an internal caller with no viewer to filter for (the
    serializer's own default), and is left alone.
    """
    if user_id is None:
        return list(ids or [])
    state = _link_states(db, ids, user_id)
    return [i for i in (ids or []) if isinstance(i, int) and state.get(i)]


def _hidden_link_ids(db, ids, user_id):
    """The complement of _visible_link_ids, in the original order."""
    vis = set(_visible_link_ids(db, ids, user_id))
    return [i for i in (ids or []) if isinstance(i, int) and i not in vis]


# ── system limits on linking ───────────────────────────────────────────────
# Both are guardrails, not product opinions: a board with dozens of connect
# columns is unreadable, and a cell holding thousands of links is a page that
# never finishes rendering. Env-driven so a deployment can move them.
def _max_connect_cols():
    try:
        return max(1, int(os.getenv("CITYOS_MAX_CONNECT_COLS", "10")))
    except ValueError:
        return 10


def _max_links_per_cell():
    try:
        return max(1, int(os.getenv("CITYOS_MAX_LINKS_PER_CELL", "100")))
    except ValueError:
        return 100


def _is_multi(col):
    """Does this connect column hold more than one item? Default yes, matching
    the picker, which treats anything but an explicit false as multiple."""
    return _connect_cfg(col).get("multiple") is not False


# What to tell someone whose link did not take. The rules do the refusing; this
# only explains it, so it runs on the write path where an extra query is free.
LINK_REJECT_HE = {
    "missing":           "הפריט שנבחר אינו קיים עוד",
    "deleted":           "הפריט שנבחר נמחק במהלך הפעולה",
    "board_unavailable": "לוח היעד אינו זמין — הוא נמצא בסל המחזור",
    "forbidden":         "אין לך עוד הרשאת צפייה בפריט שנבחר",
    "no_mirror":         "אין בלוח היעד עמודה שבה יוצג הקשר ההפוך",
    "limit":             "הגעת למספר הקישורים המרבי בתא זה",
    "rejected":          "לא ניתן היה לשמור את הקישור",
}


def _link_reject_reason(db, tid, user_id):
    """Why this id cannot be linked right now — for the message, not the rule."""
    t = (db.query(Task).filter(Task.id == tid)
         .execution_options(include_deleted=True).first())
    if t is None:
        return "missing"
    b = (db.query(Board).filter(Board.id == t.board_id)
         .execution_options(include_deleted=True).first())
    if b is None:
        return "missing"
    if b.deleted_at is not None:
        return "board_unavailable"
    if t.deleted_at is not None:
        return "deleted"
    if user_id is not None:
        role = _board_role(db, t.board_id, user_id)
        if role is None or _item_perm(t, user_id, role) == "none":
            return "forbidden"
    return "rejected"


def _merge_link_ids(db, submitted, current, user_id, multiple=True, report=None):
    """What a connect cell should hold after `user_id` saved `submitted`.

    Two rules, and they are the same rule from both ends. A user cannot ADD a
    link to an item they cannot see — otherwise the picker's restrictions could
    be walked around by posting an id, and the mirror would plant a row on a
    board they have no access to. And a user cannot REMOVE a link they cannot
    see: their cell was rendered without those ids, so submitting the list they
    can see must not read as "delete the rest".

    `multiple` is the column's own cardinality, and it is enforced here rather
    than only in the picker: the UI cleared the selection before saving, so the
    API never had to, and a single-link column would accept a list of any
    length from anything that was not the picker.
    """
    asked = [int(x) for x in (submitted or []) if isinstance(x, (int, str)) and str(x).lstrip("-").isdigit()]
    asked = list(dict.fromkeys(asked))        # the same item twice in one cell is one link
    # An item in the bin can be kept where the link already existed — that is
    # what makes a restore put the relationship back — but it cannot be linked
    # to for the first time. The picker never offers one; this is the API side
    # of the same rule.
    state = _link_states(db, asked, user_id) if user_id is not None else {}
    was = set(current or [])
    keep = [i for i in _visible_link_ids(db, asked, user_id)
            if user_id is None or state.get(i) == "live" or i in was]
    hidden = _hidden_link_ids(db, current or [], user_id)
    if not multiple:
        # A single-link column is the one place the "never delete what you
        # cannot see" rule has to give way: the cell holds one item, and
        # keeping an unseen one alongside a chosen one would hold two. Choosing
        # a value in a single-value cell IS a replacement, so the pick wins;
        # choosing nothing still leaves whatever was there untouched.
        out = keep[-1:] if keep else hidden[:1]
        if report is not None:
            got = set(out)
            for i in asked:
                if i not in got:
                    report.append({"item_id": i, "reason": _link_reject_reason(db, i, user_id)})
        return out
    # Capped rather than refused: hidden links are carried over regardless of
    # what was submitted, so a hard limit could leave a cell that is already
    # over it impossible to edit at all. The picker stops a person well before
    # this; this is the backstop for everything that is not the picker.
    out = (keep + [i for i in hidden if i not in keep])
    capped = out[:_max_links_per_cell()]
    if report is not None:
        got = set(capped)
        for i in asked:
            if i in got:
                continue
            report.append({"item_id": i,
                           "reason": "limit" if i in out else _link_reject_reason(db, i, user_id)})
    return capped


def _col_perm(col, user_id, board_role):
    """Effective permission on a column for a user: none|view|edit."""
    ov = (col.get("perms") or {}).get(str(user_id))
    if ov in ("none", "view", "edit"):
        return ov
    # The assigned roles edit cells on the items they are assigned to, so the
    # column must not refuse first: a column answering "view" here would have
    # update_task drop every cell they typed, silently, on their own item. The
    # item is what limits them (_item_perm), and a column override above still
    # narrows them like anyone else.
    if board_role in ASSIGNED_ROLES:
        return "edit"
    caps = _board_caps(board_role)
    return "edit" if "edit" in caps else ("view" if "view" in caps else "none")

def _filter_columns(b, user_id, role, known=None, fields=None):
    """(known, fields) — every filterable column on the board, and the subset
    this reader may ask about.

    One place, because two of them disagreeing is a leak rather than a bug: the
    query endpoint decides what a filter is allowed to run, and the view layer
    decides whether a SAVED filter may be opened at all. If the second were
    more generous than the first, a view would open and then answer nothing;
    if it were stricter, a cut somebody can run by hand would be refused as a
    tab. They are the same question and this is the one answer.
    """
    known = {} if known is None else known
    fields = {} if fields is None else fields
    # No col_hidden check here, deliberately: only HIDEABLE_BUILTIN_COLS can be
    # in that list, and none of them is a custom column. A custom column leaves
    # the board by leaving this very list, so it disappears from both sides on
    # its own. A guard for it would be a line that cannot run, which reads as a
    # case somebody handled and is worse than no line at all.
    for c in ((b.settings or {}).get("columns") or []):
        kind = filter_ast.KINDS.get(c.get("type"))
        if not kind:
            continue
        cid = str(c.get("id"))
        known[cid] = kind
        if user_id is None or _col_perm(c, user_id, role) != "none":
            fields[cid] = kind
    return known, fields


def _unseen_col_ids(b, user_id, role):
    """Column ids on this board that this reader may not see at all."""
    if user_id is None:
        return set()
    return {str(c.get("id")) for c in ((b.settings or {}).get("columns") or [])
            if _col_perm(c, user_id, role) == "none"}


@app.get("/api/boards")
def list_boards(user_id: int = Depends(current_user_id)):
    with Session(engine) as db:
        boards = db.query(Board).filter(Board.is_archived == False, Board.deleted_at == None).order_by(
            Board.position, Board.id).all()
        # system (workspace) admins see every board; everyone else only the boards
        # they were invited to (membership-based visibility)
        if user_id is not None and _ws_role(db, user_id) != "admin":
            visible = _visible_board_ids(db, user_id)   # membership + public boards
            boards = [b for b in boards if b.id in visible]
        result = []
        _ao_boards = _assigned_only_boards(db, user_id)
        for b in boards:
            # an assigned_only member's board holds their own items, and its
            # count in the sidebar says so — counted the way the board does
            task_count = (_board_item_count(db, b.id, user_id) if b.id in _ao_boards else
                          db.query(Task).filter(Task.board_id == b.id, Task.parent_id == None).count())
            dept_name = db.query(Department.name).filter(Department.id == b.department_id).scalar() or ""
            groups = db.query(Group).filter(Group.board_id == b.id).order_by(Group.position).all()
            result.append({
                "id": b.id, "name": b.name, "description": b.description,
                "board_type": b.board_type.value if hasattr(b.board_type, 'value') else b.board_type,
                "icon": b.icon, "color": b.color,
                "is_archived": b.is_archived,
                "department_name": dept_name,
                "environment_id": b.environment_id,
                "folder_id": b.folder_id,
                "position": b.position or 0,
                "task_count": task_count,
                "visibility": _board_visibility(b),
                "my_role": _board_role(db, b.id, user_id) if user_id is not None else None,
                "can_manage_env": _can_manage_env(db, b.environment_id, user_id) if user_id is not None else False,
                "groups": [{"id": g.id, "name": g.name, "position": g.position, "color": g.color, "task_status": g.task_status.value if hasattr(g.task_status, 'value') else g.task_status} for g in groups],
            })
        return result

# ── "מזהה פריט" (item id column) ─────────────────────────────────────
# A purely technical identifier: 11 digits, generated automatically, unique
# inside its board, with no prefix and no business meaning. It cannot be edited
# by hand. Sub-items are issued one by the same logic. Because the identifier is
# tied to the board it was minted for, an item that lands in another board (and
# later comes back) is issued a new one rather than keeping the old number.
ITEM_UID_MIN = 10_000_000_000     # smallest 11-digit number
ITEM_UID_MAX = 99_999_999_999

# The names the system puts on a row that nobody has named yet. "פריט חדש" is
# what the board's own "פריט חדש" button sends and what every route here falls
# back to; "Untitled" is what create_task has always used when a caller sends
# no title at all. Neither is a name a person chose, and anything that QUOTES
# an item's name to somebody has to be able to tell the difference — see
# _assigned_body, where «פריט חדש» read as a template that was never filled in.
NEW_ITEM_TITLE = "פריט חדש"
PLACEHOLDER_ITEM_TITLES = (NEW_ITEM_TITLE, "Untitled")

def _new_item_uid(db, board_id):
    for _ in range(60):
        cand = str(secrets.randbelow(ITEM_UID_MAX - ITEM_UID_MIN + 1) + ITEM_UID_MIN)
        taken = db.query(Task.id).filter(Task.board_id == board_id, Task.item_uid == cand).first()
        if not taken:
            return cand
    return str(secrets.randbelow(ITEM_UID_MAX - ITEM_UID_MIN + 1) + ITEM_UID_MIN)

def _board_name_from(typed, in_file, base):
    """Where an imported board's name came from.

    A board that arrives called "response1992g" is not named — it is named after
    whatever the browser happened to call the download, because the export did
    not carry the board's own name and the filename was the only thing left. The
    import is right to fall back to it; what it cannot do is leave that looking
    like the board's name. So the report says which of the three it was.
    """
    if (typed or "").strip():
        return "typed"
    if (in_file or "").strip():
        return "file"
    return "filename" if (base or "").strip() else "default"


def _mint_item_uids(n):
    """n identifiers, distinct from each other, minted without asking anything.

    For the rows of a board being created in this same transaction — there is
    nothing on it yet for them to collide with. A board that already holds items
    goes through _new_item_uid, which checks.
    """
    out, seen = [], set()
    while len(out) < n:
        c = str(secrets.randbelow(ITEM_UID_MAX - ITEM_UID_MIN + 1) + ITEM_UID_MIN)
        if c not in seen:
            seen.add(c)
            out.append(c)
    return out

def _ensure_item_uid(db, task):
    """Give the task an identifier if it has none, or a fresh one if the one it
    carries was minted for a different board. Returns the identifier."""
    if task.item_uid and task.item_uid_board == task.board_id:
        return task.item_uid
    task.item_uid = _new_item_uid(db, task.board_id)
    task.item_uid_board = task.board_id
    return task.item_uid

def _board_has_item_id_col(board):
    return any(c.get("type") == "item_id" for c in ((board.settings or {}).get("columns") or []))

def _backfill_item_uids(db, board_id):
    """Every item and sub-item on the board gets an identifier — used when the
    column is added to a board that already holds items."""
    # Having nothing to do is the normal case, and it was costing a full board
    # read to discover: every open of a board carrying the column loaded every
    # one of its items only to find each already had an identifier — 545ms on
    # the imported board of 21,187, every time, forever. Asking first whether
    # any row is still missing one is a single look-up. The condition mirrors
    # _ensure_item_uid's own, which is the point: no identifier at all, or one
    # minted while the item lived on a different board. The bin is excluded
    # because the loop below never sees binned rows either (the soft-delete
    # criteria), so a deleted item without an identifier would otherwise make
    # this answer "there is work" on every single open and never finish it.
    todo = (db.query(Task.id)
              .filter(Task.board_id == board_id, Task.deleted_at.is_(None),
                      or_(Task.item_uid.is_(None), Task.item_uid == "",
                          Task.item_uid_board.is_(None),
                          Task.item_uid_board != board_id))
              .limit(1).first())
    if not todo:
        return
    rows = db.query(Task).filter(Task.board_id == board_id).all()
    changed = False
    for t in rows:
        before = t.item_uid
        _ensure_item_uid(db, t)
        changed = changed or (t.item_uid != before)
    if changed:
        db.commit()

def _backfill_item_id_column():
    """Give every board the "מספר מזהה" column, not only the ones created since
    it became one of the defaults.

    A board created before it shipped simply does not have it, which is why the
    column shows up on QA — where boards are made all the time — and not on a
    production board that has been there for months. The identifier itself is
    not new to those items: it is minted the first time a board carrying the
    column is read (see the fetch below), so the column arrives already filled.

    Its own flag rather than a third entry in AUTO_COLS: every existing board
    already carries `auto_cols_v1`, so adding it there would reach new databases
    and skip every board this is for. Once per board, so an admin who removes
    the column does not find it back after the next restart.
    """
    with Session(engine) as db:
        added = 0
        for b in db.query(Board).all():
            s = dict(b.settings or {})
            if s.get("item_id_col_v1"):
                continue
            cols = [dict(c) for c in (s.get("columns") or [])]
            if not any(c.get("type") == "item_id" for c in cols):
                used = {c.get("id") for c in cols}
                cid = "sys_item_id" if "sys_item_id" not in used else ("col_" + uuid.uuid4().hex[:8])
                cols.append({"id": cid, "type": "item_id", "title": "מספר מזהה",
                             "options": None, "formula": None, "connect": None,
                             "copy_mode": None, "perms": {}})
                s["columns"] = cols
                added += 1
            s["item_id_col_v1"] = True
            b.settings = s
        db.commit()
        if added:
            print(f"↻ added the מספר מזהה column to {added} board(s)", flush=True)
_safe_startup(_backfill_item_id_column)


def _col_plan(db, columns, user_id, board_role):
    """The few columns that need work, worked out once for the whole board.

    Serializing an item walked every column three times: is it two-way, is it a
    connect, is it a mirror — and then again to find the ones this viewer may
    not see. None of those answers depends on the item, so on a board of 639
    items and 61 columns the same 39,000 questions were asked and answered per
    render. Here they are asked once and kept with the other per-request caches.
    """
    key = ("_col_plan", id(columns), user_id, board_role)
    plan = db.info.get(key)
    if plan is not None:
        return plan
    cols = columns or []
    plan = {
        "two_way": [c["id"] for c in cols if _is_two_way(c)],
        # EVERY connect column, two-way included: a two-way cell is filled from
        # the relationship rows above and then filtered here, in that order.
        # Excluding it from this list is how the first version of this leaked
        # links the viewer may not see — see tests/test_connect_revoked_access.py
        "connect": [c["id"] for c in cols if c.get("type") == "connect"],
        "mirror": [c for c in cols if c.get("type") == "mirror"],
        "hidden": ([c["id"] for c in cols if _col_perm(c, user_id, board_role) == "none"]
                   if user_id is not None else []),
    }
    db.info[key] = plan
    return plan


_PREFETCH_CHUNK = 400          # keep the IN (...) list inside every driver's limit


def _prefetch_items(db, tasks):
    """Answer, for a whole board at once, the four questions serializing an
    item used to ask one item at a time.

    _serialize_task needed an item's assignees, how many sub-items it has, how
    many comments, and the sub-items themselves. Each was its own query, so a
    board cost about ten statements per row — a board of four hundred items ran
    four thousand of them. In-process against SQLite that is invisible; against
    QA's Postgres every one is a network round trip, which is how opening a
    board came to take twenty seconds.

    Four grouped queries replace all of it. The answers go in the session's own
    info dict, the same place _prefetch_links keeps its cache, and
    _serialize_task reads them from there when they are present and falls back
    to its own query when they are not — so the write paths that serialize a
    single fresh item keep working untouched.

    Returns the sub-items it loaded, because the caller needs them for
    _prefetch_links and there is no reason to ask twice.
    """
    # `task_assignees` is an endpoint name in this module too, so the table is
    # imported under its own name here — same reason as in _purge_rows' caller
    from models import task_assignees as assignee_rows
    ids = [t.id for t in tasks]
    if not ids:
        return []
    info = db.info
    kids = info.setdefault("_kids_by", {})
    for tid in ids:
        kids.setdefault(tid, [])
    subs = []
    for part in [ids[i:i + _PREFETCH_CHUNK] for i in range(0, len(ids), _PREFETCH_CHUNK)]:
        for sub in (db.query(Task)
                      .filter(Task.parent_id.in_(part), Task.is_archived == False)   # noqa: E712
                      .order_by(Task.position, Task.id).all()):
            kids.setdefault(sub.parent_id, []).append(sub)
            subs.append(sub)
    # a sub-item is serialized too, so it needs the same three answers
    every = ids + [s.id for s in subs]
    ass = info.setdefault("_assignees_by", {})
    nsub = info.setdefault("_nsub_by", {})
    ncom = info.setdefault("_ncom_by", {})
    # when the thread was last written in — the other half of the same
    # group-by, because the board's chat bubble asks both questions at once:
    # whether there is a conversation, and whether anybody has said anything
    # in it lately (see chat_stale_days)
    lcom = info.setdefault("_lcom_by", {})
    for tid in every:
        ass.setdefault(tid, [])
        nsub.setdefault(tid, 0)
        ncom.setdefault(tid, 0)
        lcom.setdefault(tid, None)
    for part in [every[i:i + _PREFETCH_CHUNK] for i in range(0, len(every), _PREFETCH_CHUNK)]:
        for tid, uid, uname, uav in (db.query(assignee_rows.c.task_id, User.id,
                                              User.name, User.avatar_url)
                                       .join(User, User.id == assignee_rows.c.user_id)
                                       .filter(assignee_rows.c.task_id.in_(part))
                                       .order_by(assignee_rows.c.task_id,
                                                 assignee_rows.c.user_id).all()):
            ass[tid].append({"id": uid, "name": uname, "avatar_url": uav})
        # counts every child, archived ones included — which is what the badge
        # has always shown
        for pid, n in (db.query(Task.parent_id, func.count(Task.id))
                         .filter(Task.parent_id.in_(part))
                         .group_by(Task.parent_id).all()):
            nsub[pid] = n
        for tid, n, last in (db.query(Comment.task_id, func.count(Comment.id),
                                      func.max(Comment.created_at))
                               .filter(Comment.task_id.in_(part))
                               .group_by(Comment.task_id).all()):
            ncom[tid] = n
            lcom[tid] = last
    return subs


def _serialize_task(t, db, with_subs=True, user_id=None, board_role=None, columns=None):
    # a board read warms these for every row at once (_prefetch_items); a write
    # path serializing one fresh item has nothing warmed and asks for itself
    _pre = db.info
    _ass = _pre.get("_assignees_by")
    if _ass is not None and t.id in _ass:
        assignees = list(_ass[t.id])
    else:
        assignees = [{"id": u.id, "name": u.name, "avatar_url": u.avatar_url} for u in t.assignees] if t.assignees else []
    _ns = _pre.get("_nsub_by")
    subtask_count = (_ns[t.id] if _ns is not None and t.id in _ns
                     else db.query(Task).filter(Task.parent_id == t.id).count())
    _nc = _pre.get("_ncom_by")
    comment_count = (_nc[t.id] if _nc is not None and t.id in _nc
                     else db.query(Comment).filter(Comment.task_id == t.id).count())
    _lc = _pre.get("_lcom_by")
    last_comment_at = (_lc[t.id] if _lc is not None and t.id in _lc
                       else db.query(func.max(Comment.created_at))
                              .filter(Comment.task_id == t.id).scalar())
    _scope = (_pre.get(("_assign_scope", t.board_id, user_id))
              if board_role in ASSIGNED_ROLES else None)
    my_perm = _item_perm(t, user_id, board_role, _scope) if user_id is not None else "delete"
    cf = dict(t.custom_fields or {})
    # Which columns need anything doing to them is a property of the board and
    # the viewer, not of the item — so it is worked out once (_col_plan) rather
    # than by walking every column on every row. On a board of 639 items and 61
    # columns that walk ran 39,000 times to find, usually, nothing at all.
    plan = _col_plan(db, columns, user_id, board_role)
    # A two-way connect cell is not stored on the item — it is the shared
    # relationship rows, read from whichever side wrote them. That is what makes
    # a link created on the other board appear here without anything copying it.
    for cid in plan["two_way"]:
        cf[cid] = _linked_ids(db, t.id, cid)
    # A connect cell is the one place a board hands out ids from OTHER
    # boards. Show the viewer only the links they could have opened anyway;
    # the rest are not theirs to know about, and _merge_link_ids puts them
    # back when this same viewer saves the cell.
    for cid in plan["connect"]:
        if isinstance(cf.get(cid), list):
            cf[cid] = _visible_link_ids(db, cf[cid], user_id)
    # A mirror field holds no data of its own — it is read through the
    # connect column each time, so it follows the source item with nothing
    # to keep in step. Anything stored under its id is stale and ignored.
    for c in plan["mirror"]:
        cf[c["id"]] = _mirror_cells(db, t, c, user_id, columns or [])
    # A column's permission depends on the column and on the viewer's role —
    # never on the item. It used to ride on every item anyway, which on a board
    # of 687 items and 29 columns was 20,000 repetitions of the same map and
    # over half the response. The board now states it once (see get_board); what
    # stays per item is the consequence: a value the viewer may not see is not
    # in the item at all. Which columns those are is in the plan.
    for cid in plan["hidden"]:
        cf.pop(cid, None)
    d = {
        "id": t.id, "board_id": t.board_id, "group_id": t.group_id,
        "parent_id": t.parent_id,
        "item_uid": t.item_uid,          # "מזהה פריט" — automatic, read-only
        "title": t.title, "description": t.description,
        "status": t.status.value if hasattr(t.status, 'value') else t.status,
        "priority": t.priority.value if hasattr(t.priority, 'value') else t.priority,
        "position": t.position, "due_date": t.due_date,
        "start_date": t.start_date,
        "estimated_hours": t.estimated_hours, "actual_hours": t.actual_hours,
        "location_lat": t.location_lat, "location_lng": t.location_lng,
        "address": t.address,
        "custom_fields": cf,
        "permissions": t.permissions or {},
        "my_perm": my_perm,
        "is_archived": t.is_archived,
        "created_by": t.created_by,
        "created_at": t.created_at, "updated_at": t.updated_at,
        "assignees": assignees,
        "subtask_count": subtask_count,
        "comment_count": comment_count,
        # When the thread was last written in, or null when nobody ever has.
        # The board greys the chat bubble off this (see chat_stale_days); it is
        # not "when the item changed", which updated_at already says — an item
        # whose status somebody flipped has not been answered.
        "last_comment_at": last_comment_at,
    }
    # A cell whose words nobody could match to a record is not an empty cell:
    # the value is still there, on the conversion, waiting for somebody to say
    # what it meant. It is carried beside custom_fields rather than inside it
    # so the connect column goes on holding only item ids — a grid that found
    # a string in a list of links would render it as a broken chip. Absent
    # entirely when there is nothing pending, which is every item on every
    # board that is not mid-conversion.
    if plan["connect"]:
        _allowed = set(plan["connect"]) - set(plan["hidden"])
        _pending = {k: v for k, v in _link_pending_for(db, t).items() if k in _allowed}
        if _pending:
            d["link_pending"] = _pending
    if with_subs:
        _kids = _pre.get("_kids_by")
        subs = (_kids[t.id] if _kids is not None and t.id in _kids
                else db.query(Task).filter(Task.parent_id == t.id, Task.is_archived == False)
                        .order_by(Task.position, Task.id).all())
        subs = [s for s in subs if user_id is None or _item_perm(s, user_id, board_role, _scope) != "none"]
        d["subtasks"] = [_serialize_task(s, db, with_subs=False, user_id=user_id, board_role=board_role, columns=columns) for s in subs]
    return d

def _context_shell(parent, kids, db, user_id=None, board_role=None, columns=None):
    """A parent this reader may not see, holding sub-items they may.

    Everything readable about the parent is left out on purpose — the title
    above all, which is usually the whole of what a row discloses. What remains
    is an id to hang the children on and the two flags that say what this row
    is, so the screen can draw a neutral wrapper instead of a work item.

    The children are serialised normally: they are theirs to read, and nothing
    about them implies anything about the parent beyond its existence, which
    the sub-item's own parent_id already states.
    """
    return {
        "id": parent.id, "board_id": parent.board_id, "group_id": parent.group_id,
        "parent_id": None,
        "title": "", "description": None,
        "status": None, "priority": None,
        "due_date": None, "start_date": None,
        "assignees": [], "custom_fields": {}, "permissions": {},
        "my_perm": "none", "is_archived": False,
        "created_by": None, "created_at": None, "updated_at": None,
        "item_uid": None, "comment_count": 0, "last_comment_at": None,
        "subtask_count": len(kids),
        "subtasks": [_serialize_task(k, db, with_subs=False, user_id=user_id,
                                     board_role=board_role, columns=columns)
                     for k in kids],
        # not a row that failed the filter, and not a row with values withheld:
        # a row that is only here to hold the ones below it
        "context_only": True,
        "restricted": True,
    }


def _json_default(o):
    """What json.dumps cannot do by itself, done the way FastAPI would.

    Returning a plain dict hands it to FastAPI, which walks the whole structure
    with jsonable_encoder and then dumps it. On a board of 639 items and 61
    columns — 39,000 cells — that walk is ten times the cost of dumping the
    same thing directly. It is a fixed multiple of the payload, so it is worst
    exactly on the boards that are already slowest.

    Bypassing it only helps if nothing on the wire changes, which is the one
    thing that matters here: a date written "2026-10-14 09:00:00" instead of
    "2026-10-14T09:00:00" would be a quiet break in every cell that parses one.
    test_board_json_is_byte_identical compares the two, byte for byte.
    """
    if isinstance(o, (datetime, date)):
        return o.isoformat()
    if isinstance(o, Decimal):
        return float(o)
    if isinstance(o, Enum):
        return o.value
    if isinstance(o, (set, frozenset)):
        return list(o)
    if isinstance(o, bytes):
        return o.decode("utf-8", "replace")
    raise TypeError(f"not JSON-serializable: {type(o).__name__}")


def _json(payload):
    """A response built here rather than by FastAPI — see _json_default."""
    return Response(json.dumps(payload, ensure_ascii=False, default=_json_default),
                    media_type="application/json")


# ── saved views (תצוגות שמורות) ────────────────────────────────────────
# A named cut of a board, shown as a tab at the top of it. "באגים דחופים
# פתוחים" is three filters somebody sets every morning; a view is that cut,
# kept.
#
# The permission model is two words, and the asymmetry in it is deliberate:
#
#   private — only its owner sees it. Somebody's own way of reading a board is
#             not a statement about the board, so it takes only the right to
#             look at the board to make one.
#   public  — everyone who may open the board sees it. It is a tab ON the
#             board, which makes creating one an edit to the board, and it
#             takes the rights of one.
#
# Editing and deleting follow the same line: the owner always, and a board
# admin for a public view — somebody has to be able to take down a tab whose
# author has left.
def _is_sys_admin(db, user_id):
    """A system administrator, as opposed to an administrator of one board."""
    if not user_id:
        return False
    u = db.query(User).filter(User.id == user_id).first()
    return bool(u and u.role == "admin")


# ── where a filter runs, and how much comes back at a time ─────────────
# Below the threshold the browser filters what it already holds: the answer
# is instant, no request is made, and on a board of a few hundred rows that
# is simply better. Above it the question goes to the server, which is the
# only side that can answer for rows the browser was never handed.
#
# The number is configuration, not a constant with an opinion: a board of
# 1,000 rows on a laptop is not the same board on a five-year-old phone, and
# whoever runs the deployment is the one who knows which they have.
FILTER_CLIENT_MAX = max(0, int(os.environ.get("FILTER_CLIENT_MAX", "1000") or 1000))
# What happens when a view filters by a column its reader may not see.
#
#   skip  (default) — the rule is not applied for them. They see MORE rows
#                     than the view's author meant, and learn nothing about
#                     the column. This is the safe direction, and the reason
#                     is the opposite of the intuitive one: APPLYING the rule
#                     is the leak. "Budget > 1,000,000", run for somebody who
#                     cannot see budgets, hands them the answer as a row set —
#                     they read the figures off which rows survived. Dropping
#                     the rule hands them nothing.
#   block           — the view refuses to open for them at all. No inference
#                     of any kind, including from the view's name; the cost
#                     is that a shared view stops working across permission
#                     tiers, which for most boards is the worse trade.
#
# Configuration, because this is a security policy and the people who set it
# are the ones who know what is on their boards.
FILTER_COLUMN_POLICY = (os.environ.get("FILTER_COLUMN_POLICY") or "skip").strip().lower()
if FILTER_COLUMN_POLICY not in ("skip", "block"):
    FILTER_COLUMN_POLICY = "skip"
# One page. A board of tens of thousands of rows must never arrive in one
# response — not because the server cannot build it, but because the browser
# cannot draw it, and the request blocks everything behind it while it tries.
QUERY_PAGE = 50
QUERY_PAGE_MAX = 200

VIEW_VIS = ("private", "public")

# ── names and limits ────────────────────────────────────────────────────
# Technical ceilings, not product rules — hence the environment variables.
# They are here so a board cannot be made unusable, not to express anything
# about how many cuts a department ought to keep.
VIEW_NAME_MAX = max(1, int(os.environ.get("VIEW_NAME_MAX", "80") or 80))
# Active views per BOARD, the main table counted as one of them. Per board and
# not per person: the strip is shared now, so one person filling it fills
# everybody's, and a limit counted per owner would not be a limit on the strip.
VIEW_MAX = max(2, int(os.environ.get("VIEW_MAX_PER_BOARD", "100") or 100))
# The fixed main table. It has no row of its own — it is the board — but it
# occupies a name on the strip, and a saved view answering to the same name
# would make the strip ambiguous in the one place a reader cannot afford it.
# What a view is called when nobody named it. Adding a table view is one
# click — there is no type to choose and no question to answer — so the name
# cannot be a question either. It is numbered if it is taken, and renaming it
# afterwards is one item in the view's own menu.
#
# A board starts with NO view tabs. There was briefly a row per board called
# "טבלה ראשית", created automatically so that the board's fixed table had an
# id to be linked to — and it meant every board grew a tab nobody asked for.
# A tab is something somebody added; a board with none shows none. The `kind`
# column stays on the model for the day a fixed table needs a record again,
# and nothing writes "main" to it now.
NEW_VIEW_NAME = (os.environ.get("NEW_VIEW_NAME") or "טבלה").strip()
# How long a deleted view can still be brought back. After it, the row stays
# where it is — this is a window on RESTORING, not a promise to erase — but the
# board log stops offering it, because an offer that fails is worse than none.
VIEW_RESTORE_DAYS = max(1, int(os.environ.get("VIEW_RESTORE_DAYS", "30") or 30))


def _view_name_key(name):
    """What makes two view names "the same".

    Ends trimmed, then casefolded: "Budget" and "budget " are one name. Hebrew
    has no case, so casefold leaves it exactly as typed and the rule costs it
    nothing — it is there for the English a municipality's boards are full of.
    casefold rather than lower because it folds the pairs lower() misses.
    """
    return (name or "").strip().casefold()


def _check_view_name(db, board_id, name, exclude_id=None):
    """The trimmed name, or an HTTPException saying why there isn't one."""
    name = (name or "").strip()
    if not name:
        raise HTTPException(400, "לתצוגה צריך שם")
    if len(name) > VIEW_NAME_MAX:
        # refused rather than trimmed: a silently shortened name is not the one
        # somebody typed, and it can collide with a view that already exists
        raise HTTPException(400, f"שם תצוגה עד {VIEW_NAME_MAX} תווים")
    key = _view_name_key(name)
    q = (db.query(SavedView)
           .filter(SavedView.board_id == board_id, SavedView.deleted_at.is_(None)))
    if exclude_id is not None:
        q = q.filter(SavedView.id != exclude_id)
    if any(_view_name_key(v.name) == key for v in q.all()):
        raise HTTPException(400, "כבר יש תצוגה בשם הזה בלוח")
    return name


def _log_board(db, board_id, action, field=None, old=None, new=None, actor=None):
    """One line in the board's log for a change to the BOARD, not to an item.

    The log was built out of AuditLog rows whose entity is a task, because
    everything worth recording happened to an item. Deleting a column is not
    that: it happens to the board, it takes a column of data off every item at
    once, and until this existed it left no trace anywhere — the column was
    simply gone, and nobody could say by whom or when. "מחיקת עמודה בלוח צריכה
    להופיע בלוגים" is that hole.

    entity_id is the BOARD's id, so _board_activity_rows can find these rows
    without a table of its own, and _hard_delete_board takes them with it the
    way it takes the item rows — ids are reissued, and a row left behind would
    reattach to whatever board is created into that id next.

    These rows are never undoable: there is no old value to put back. The undo
    endpoint refuses anything that is not an entity_type="task" update, which
    is the gate rather than the hint.
    """
    row = AuditLog(entity_type="board", entity_id=board_id, action=action,
                   field_name=field, old_value=old, new_value=new,
                   changed_by=actor)
    db.add(row)
    # Flushed so the row has an id: the column bin points back at the exact
    # line its restore button belongs to, rather than matching on a title two
    # columns could share.
    db.flush()
    return row


COLUMN_BIN_MAX = 20


def _column_bin(board):
    return list((board.settings or {}).get("columns_bin") or [])


def _bin_a_column(db, board, col, log_id, actor, at=None):
    """Keep a deleted column's definition so the log line can put it back.

    Deleting a column removes it from settings["columns"] and nothing else —
    every item's value for it stays in custom_fields, keyed by the column id,
    and is never cleaned up. So the data survives a deletion already; what did
    not survive was the column itself: its type, its options, its width, where
    it sat. Without those there is nothing to restore the values INTO, which
    is why the log line could say a column was deleted and not offer to undo
    it.

    The definition goes here, carrying the id of the log row it belongs to, so
    the line can show its own button and a restore can be refused once the
    entry is gone. Capped at COLUMN_BIN_MAX, newest first: this lives inside
    the board's settings JSON, and a board whose columns churn should not grow
    an unbounded tail there. The values in the items are not capped and not
    touched — a column restored long after its entry fell off the end would
    still come back full, if its definition were still here to restore.
    """
    s = dict(board.settings or {})
    entry = {"col": col, "log_id": log_id, "at": at,
             "deleted_at": datetime.now(timezone.utc).replace(tzinfo=None).isoformat(),
             "deleted_by": actor}
    s["columns_bin"] = ([entry] + _column_bin(board))[:COLUMN_BIN_MAX]
    board.settings = s


def _group_name(db, gid):
    """A group's name for the log, or None for "ללא קבוצה".

    The log stores names rather than ids on purpose. A group can be deleted
    long after an item passed through it, and an id left in the history would
    then point at nothing — or, since ids are reissued, at some later group
    the item was never in. The name is what somebody reading the line a year
    from now is actually asking about.
    """
    if not gid:
        return None
    g = db.query(Group).filter(Group.id == gid).first()
    return g.name if g else None


def _log_group_move(db, task_id, from_gid, to_gid, actor=None):
    """"מעבר רשומה בין קבוצות" — one line on the item, where the move happened.

    A drag between groups changed group_id, fired its automation trigger and
    recorded nothing: the item's own history showed the status changes around
    it and said nothing about the move, so a board where the group IS the
    workflow had the one event that mattered missing from both logs. The
    status change two lines above this in move_task had been audited all
    along, which is the shape this follows.

    Group rows are read through _group_name, so a later rename or deletion
    cannot turn the line into a dangling id.
    """
    if from_gid == to_gid:
        return
    _audit(db, task_id, "update", "group",
           _group_name(db, from_gid), _group_name(db, to_gid), actor)


def _log_view(db, v, action, field=None, old=None, new=None, actor=None):
    """One line in the board's log for a change to a view.

    "לוג הלוח יתעד יצירה, עדכון משותף, שינוי שם, מחיקה, שחזור, נעילה והצמדה,
    עם מבצע וזמן ופרטי השינוי המורשים."

    Management events only. A temporary adjustment is explicitly NOT one —
    "התאמות זמניות אינן אירוע ניהול משותף" — and it could not be logged here
    anyway, because it never reaches the server. What distinguishes the two
    is exactly whether anybody else is affected.

    The details are deliberately small: what changed and from what to what,
    never the configuration itself. A cut can name a column somebody reading
    the log may not see, and a log is read by more people than a board.
    """
    db.add(AuditLog(entity_type="saved_view", entity_id=v.id, action=action,
                    field_name=field, old_value=old, new_value=new,
                    changed_by=actor))


def _commit_view(db, board_id, *, adding=True, log=None):
    """Commit a view write, with the two board-wide rules enforced for real.

    Both are read-then-write races on their own. Two people naming a view the
    same thing at the same moment both pass _check_view_name; two people
    creating the hundredth both pass _check_view_room. The checks stay — they
    are what produces a sentence somebody can act on — and this is what makes
    them true rather than usually true.

    The name is a partial unique index, so the database refuses the second
    write and the refusal is translated back into the same 400 the check would
    have given. The ceiling cannot be an index, so it is re-counted INSIDE the
    transaction and rolled back if the row that just landed put the board over.
    """
    try:
        if adding:
            # Inside the try, because this is where a duplicate name is
            # refused — a flush outside it raises past the translation and
            # the caller gets a 500 instead of the sentence.
            db.flush()
            live = (db.query(SavedView)
                      .filter(SavedView.board_id == board_id,
                              SavedView.deleted_at.is_(None)).count())
            if live > VIEW_MAX:
                db.rollback()
                raise HTTPException(400, f"יותר מדי תצוגות פעילות בלוח (מקסימום {VIEW_MAX})")
        # The log line is written only once the row it describes is real, and
        # in the same transaction as it: a log entry for a save that was
        # refused is worse than no entry at all.
        if log:
            log()
        db.commit()
    except IntegrityError:
        db.rollback()
        raise HTTPException(400, "כבר יש תצוגה בשם הזה בלוח")


def _check_view_room(db, board_id):
    """One more active view, main table included — or a refusal."""
    # The main table is one of these rows now, so it counts itself — the +1
    # that used to stand in for it would be counting it twice.
    live = (db.query(SavedView)
              .filter(SavedView.board_id == board_id,
                      SavedView.deleted_at.is_(None)).count())
    if live >= VIEW_MAX:
        raise HTTPException(400, f"יותר מדי תצוגות פעילות בלוח (מקסימום {VIEW_MAX})")


def _view_visible_to(v, user_id, role):
    """Who sees a view in the strip.

    This version has no private views: a saved table view is a tab on the
    board, and everyone who may open the board sees every one of them. What is
    still honoured is the rows written BEFORE that was decided — somebody's
    private cut is not republished to their colleagues by a deploy, so it stays
    theirs until they share it themselves. Nothing new is ever written private
    (see create_saved_view), so this clause empties out on its own.
    """
    return v.visibility == "public" or v.owner_id == user_id


def _may_write_locked(role):
    """נעילה: "רק בעל הלוח רשאי לשנות את הגדרותיה, לפתוח את נעילתה או למחוק אותה."

    So a lock does not freeze a view — it narrows who may touch it to the
    board's owner. Everyone else, the person who MADE the view included, may
    read it and copy it and may not write it: a cut a department works off is
    not a stray "שמור" away from being somebody else's cut, and whoever runs
    the board is the one who answers for what its tabs say.

    Locking is the owner's too, not only unlocking. A lock an editor could
    apply and then not undo would be a trap, and "רק בעל הלוח" reads the same
    at both ends of the switch. "בעל הלוח" is the board role and nothing else —
    see _may_edit_view on why this layer does not re-answer who an
    administrator is.
    """
    return role == "admin"


def _may_edit_view(v, user_id, role):
    """Who may rename or rewrite an UNLOCKED view. The lock is asked separately.

    The board's own roles answer it, not authorship: an editor may change any
    view on a board they edit, and a viewer may change none. A saved view is
    a tab on the board — part of how the board is set up — so the question is
    what somebody may do to this board, not who happened to press save first.

    `role` is the whole of the answer, deliberately. A system administrator
    reaches a board through _board_role like everybody else — it already
    returns "admin" for a workspace admin on every board — so there is nothing
    for this layer to add. An override of its own here would be a SECOND path
    to admin, reading a different row (User.role rather than the workspace
    membership _board_role goes through), and the two have drifted apart
    before: see _ws_role_for. Views are not the place to re-answer who an
    administrator is.

    Authorship counts for nothing here, and that is the rule rather than an
    omission: "היוצר משמש לתיעוד ואינו מכתיב הרשאות ניהול". owner_id says who
    made the view, which is worth recording and worth showing; it is not a
    claim on it. An earlier version let the author of a legacy private row
    keep it, which was the same mistake wearing a kinder face — the right
    answer for those rows is to share them, not to hand their author a
    permission the matrix does not give.
    """
    return role in ("admin", "editor")


def _view_blocked_for(b, v, user_id, role):
    """Does this saved cut ask about a column this reader may not see?

    If it does, the view is not opened for them and not copied by them. Not
    "run without that rule": a rule silently dropped from an "or" group shows
    the whole board, and a tab that answers a different question for different
    people is worse than one that opens for neither.

    Always blocking, whatever FILTER_COLUMN_POLICY says. That setting is about
    a filter somebody is building by hand, where the column picker never
    offered the column in the first place; this is a cut that was SAVED while
    somebody could see the column and is being opened by somebody who cannot.
    """
    if user_id is None:
        return False
    adv = (v.filters or {}).get("adv")
    if not adv:
        return False
    # The same two maps the query endpoint builds, from the same helper and
    # the same built-in base — see _filter_columns.
    base = {"title": "text", "status": "status", "priority": "status",
            "assignees": "people", "due": "date"}
    _known, fields = _filter_columns(b, user_id, role, dict(base), dict(base))
    try:
        _tree, gone = filter_ast.prune(filter_ast.parse(adv), fields)
    except filter_ast.BadFilter:
        return False          # a cut the server already refuses is its own error
    unseen = _unseen_col_ids(b, user_id, role)
    return any(str(f) in unseen for f in gone)


# What a saved configuration is made of, and nothing else.
#
# The spec gives this as a table of components: visible columns and their
# order, column widths, filters, sort. Everything else a person does to a
# board while looking at it — the search box, a collapsed group, the scroll
# position, which sub-items they opened — is theirs for as long as they are
# there and is not part of what anybody else opens.
#
# Written as what is KEPT rather than what is dropped, because the two fail in
# opposite directions. A list of things to strip lets anything new the client
# starts sending ride along into everybody's tab, silently, and the first
# anybody knows of it is a view that behaves differently for its author. A
# list of what is kept makes that a decision somebody has to make on purpose.
VIEW_CONFIG_KEYS = (
    "view",        # which base view the cut was taken of — table, for now
    "cols",        # visible columns, their order, their widths
    "adv",         # the condition tree
    "people", "status", "priority", "links",   # the toolbar's own filters
    "sort",
    # …and the column the board is ordered BY, which the spec's "sort" always
    # meant. It was missing, so a view could hold a filter and not the order it
    # was read in: sorting by a column changed the screen and changed nothing
    # the view could see, and the sorted board could not be kept.
    "colSort",
)


def _view_config(filters):
    """The shared part of what somebody is looking at.

    `q` is the one dropped by name in the spec — "טקסט חיפוש: לעולם אינו
    נשמר" — and it is also the clearest case of the rule above: a stored
    search is a tab that silently narrows the board for everybody who opens
    it, above a search box that looks empty.
    """
    if not isinstance(filters, dict):
        return filters
    return {k: v for k, v in filters.items() if k in VIEW_CONFIG_KEYS}


def _view_cut_allowed(b, filters, user_id, role):
    """Is this cut one the person saving it may ask for?

    The same validation duplicate does — "תנאי גישה והאימות זהים לאלה של
    שכפול" — and for the same reason: a filter naming a column somebody may
    not see is one they must not be able to run, and saving it as their own
    view would be exactly that with an extra step.
    """
    if user_id is None or not (filters or {}).get("adv"):
        return True
    base = {"title": "text", "status": "status", "priority": "status",
            "assignees": "people", "due": "date"}
    _known, fields = _filter_columns(b, user_id, role, dict(base), dict(base))
    try:
        _tree, gone = filter_ast.prune(filter_ast.parse(filters["adv"]), fields)
    except filter_ast.BadFilter:
        return True            # the parse error is reported on its own
    unseen = _unseen_col_ids(b, user_id, role)
    return not any(str(f) in unseen for f in gone)


def _view_needs_fix(b, v):
    """Does this cut ask about a column that no longer exists on the board?

    "אם עמודה נדרשת נמחקה, התצוגה תשוחזר במצב הדורש תיקון ולא תציג תוצאות
    חלקיות מטעות."

    The misleading part is specific, not vague. Dropping the dead rule and
    running the rest is identical to the author's intent inside an "and" group
    and its exact opposite inside an "or": a rule that is gone cannot make the
    group true, so one deleted column shows the WHOLE board — filter on, badge
    counting, nothing filtered. A reader has no way to tell that from a cut
    that genuinely matches everything.

    So the view says it needs fixing, and whoever can edit it decides what the
    rule should have been. Unlike a column somebody may not SEE, this is not a
    secret: the column is gone for everyone, so the state is reported to
    everyone and the name of the missing field may be shown.
    """
    f = v.filters or {}
    base = {"title": "text", "status": "status", "priority": "status",
            "assignees": "people", "due": "date"}
    known, _f = _filter_columns(b, None, None, dict(base), dict(base))
    missing = set()

    adv = f.get("adv")
    if adv:
        try:
            _tree, gone = filter_ast.prune(filter_ast.parse(adv), known)
            missing |= {str(x) for x in gone}
        except filter_ast.BadFilter:
            pass

    # A SORT naming a column that is gone is the same failure wearing different
    # clothes: the view opens, the rows come back in some order, and nothing on
    # the screen says the order it promised is not the order it gave. Falling
    # back to the board's own order silently is the "quietly wider results" of
    # the filter case — a wrong answer that looks like an answer.
    #
    # A plain DISPLAY column that was deleted is NOT here. Removing it from the
    # table is the whole of the right behaviour: nothing was promised about it
    # beyond being shown, and a view does not need fixing because a column it
    # used to show no longer exists.
    sort = str(f.get("sort") or "")
    if sort and sort not in ("due", "priority", "title") and sort not in known:
        missing.add(sort)
    return sorted(missing)


def _redact_view_cols(filters, unseen):
    """The view's table layout, minus the columns this reader may not see.

    "הגדרות שאינן ניתנות לצפייה לא יישלחו לדפדפן" — so a width, a position in
    the order or a place on the hidden list is removed before the view leaves
    the server. Each of those is a fact about a column, and the column itself
    is not this reader's to know about.
    """
    if not unseen or not isinstance(filters, dict):
        return filters
    cols = filters.get("cols")
    if not isinstance(cols, dict):
        return filters
    out = dict(cols)
    if isinstance(cols.get("order"), list):
        out["order"] = [c for c in cols["order"] if str(c) not in unseen]
    if isinstance(cols.get("hidden"), list):
        out["hidden"] = [c for c in cols["hidden"] if str(c) not in unseen]
    if isinstance(cols.get("widths"), dict):
        out["widths"] = {k: w for k, w in cols["widths"].items() if str(k) not in unseen}
    return dict(filters, cols=out)


def _redact_view_sort(filters, unseen):
    """…and the column the view is ORDERED by, for the same reason.

    The order rows come back in is a fact about the column that decides it —
    which budget is the largest is readable off a board sorted by budget,
    without one figure on screen. A view saved by somebody who can see the
    column opens for somebody who cannot, so the sort comes off on the way
    out and the board opens in its own order.
    """
    if not unseen or not isinstance(filters, dict):
        return filters
    cs = filters.get("colSort")
    if isinstance(cs, dict) and str(cs.get("key")) in unseen:
        return dict(filters, colSort=None)
    return filters


def _merge_view_cols(incoming, stored, unseen):
    """What to store when somebody who sees only part of the table saves it.

    They were sent a layout with the columns they may not see taken out of it,
    so what comes back has no opinion about those columns — and writing it as
    given would delete their width, their place in the order and their entry on
    the hidden list. The reader did not ask for that and could not have known
    they were doing it.

    So the stored settings for unseen columns are put back: the order keeps
    them where they were relative to the columns around them, and the two maps
    simply keep their entries.
    """
    if not unseen:
        return incoming
    if not isinstance(incoming, dict):
        return incoming
    inc = incoming.get("cols")
    old = (stored or {}).get("cols")
    if not isinstance(inc, dict) or not isinstance(old, dict):
        return incoming
    out = dict(inc)
    if isinstance(inc.get("order"), list) and isinstance(old.get("order"), list):
        # walk the stored order, keeping unseen ids pinned to the neighbour they
        # followed; everything else takes the incoming order
        kept = [c for c in inc["order"] if str(c) not in unseen]
        rebuilt, at = [], 0
        for c in old["order"]:
            if str(c) in unseen:
                rebuilt.append(c)
            elif at < len(kept):
                rebuilt.append(kept[at]); at += 1
        rebuilt += kept[at:]
        for c in kept:
            if c not in rebuilt:
                rebuilt.append(c)
        out["order"] = rebuilt
    if isinstance(inc.get("hidden"), list) and isinstance(old.get("hidden"), list):
        out["hidden"] = list(inc["hidden"]) + [c for c in old["hidden"] if str(c) in unseen]
    if isinstance(inc.get("widths"), dict) and isinstance(old.get("widths"), dict):
        w = dict(inc["widths"])
        for k, val in old["widths"].items():
            if str(k) in unseen:
                w[k] = val
        out["widths"] = w
    return dict(incoming, cols=out)


def _view_json(v, db=None, names=None):
    return {"id": v.id, "board_id": v.board_id, "name": v.name,
            "kind": v.kind or "saved",
            "config_version": v.config_version or 1,
            "schema_version": v.schema_version or 1,
            "visibility": v.visibility, "owner_id": v.owner_id,
            "owner_name": (names or {}).get(v.owner_id, ""),
            "filters": v.filters or {}, "position": v.position or 0,
            "locked": bool(v.locked), "pinned": bool(v.pinned),
            # When the shared configuration last changed. A reader holding
            # temporary adjustments compares this with what they opened and
            # says "התצורה המשותפת השתנתה" rather than silently discarding
            # what they were in the middle of.
            "updated_at": v.updated_at.isoformat() if v.updated_at else None}


def _view_order_for(db, board_id, user_id):
    """One person's arrangement of this board's strip — a list of view ids."""
    if user_id is None:
        return []
    row = (db.query(BoardViewPrefs)
             .filter(BoardViewPrefs.board_id == board_id,
                     BoardViewPrefs.user_id == user_id).first())
    return [int(i) for i in (row.order or [])] if row else []


def _arrange_views(rows, personal):
    """The order the strip is drawn in — two blocks, arranged by two people.

    Pinned views come first, in the order the BOARD puts them in. Both halves
    of that are the board owner's: which views are pinned, and how the pinned
    ones sit relative to each other. A reader's own arrangement does not reach
    into them — "סדר אישי לתצוגות שאינן מוצמדות" is exactly that boundary, and
    a pinned view that could be shuffled personally would make pinning mean
    nothing on the screen it was meant to control.

    Everything else follows, in the reader's own order. Views they have not
    arranged keep the board's order after the ones they have, which is where a
    view created since they last arranged their strip lands: at the end,
    disturbing nothing.
    """
    rank = {vid: i for i, vid in enumerate(personal)}
    def key(v):
        # The board's own table is always first. It is not pinned and cannot
        # be — pinning is a choice among the saved cuts, and this one is the
        # board. Ahead of the pinned block rather than inside it.
        if (v.kind or "saved") == "main":
            return (-1, 0, 0, v.id)
        if v.pinned:
            return (0, 0, v.position or 0, v.id)
        return (1, rank.get(v.id, len(rank)), v.position or 0, v.id)
    return sorted(rows, key=key)


def _board_role_or_403(db, board_id, user_id):
    b = db.query(Board).filter(Board.id == board_id).first()
    if not b or b.deleted_at:
        raise HTTPException(404, "board not found")
    role = _board_role(db, board_id, user_id)
    if user_id is not None and role is None:
        raise HTTPException(403, "אין לך גישה ללוח זה")
    return b, role


@app.get("/api/boards/{board_id}/views")
def list_saved_views(board_id: int, user_id: int = Depends(current_user_id)):
    with Session(engine) as db:
        _b, role = _board_role_or_403(db, board_id, user_id)
        rows = (db.query(SavedView)
                  .filter(SavedView.board_id == board_id,
                          SavedView.deleted_at.is_(None))      # the bin is its own endpoint
                  .order_by(SavedView.position, SavedView.id).all())
        # A form is a view of this board, so it is in this list — but it is
        # not a CUT of it, and everything below this line reads a cut. Its
        # rows are projected separately and rejoined in strip order.
        forms = {x.view_id: x for x in db.query(FormView).filter(
            FormView.view_id.in_([v.id for v in rows])).all()} if rows else {}
        # A dashboard is a view of this board in exactly the way a form is —
        # same strip, same name rule, same bin — and the strip needs the same
        # two things to draw its tab: that it IS one, and which one.
        dashes = {x.view_id: x for x in db.query(Dashboard).filter(
            Dashboard.view_id.in_([v.id for v in rows]),
            Dashboard.deleted_at.is_(None)).all()} if rows else {}
        rows = [v for v in rows if _view_visible_to(v, user_id, role)]
        rows = _arrange_views(rows, _view_order_for(db, board_id, user_id))
        names = {}
        if rows:
            ids = {v.owner_id for v in rows}
            names = {u.id: u.name for u in db.query(User).filter(User.id.in_(ids)).all()}
        unseen = _unseen_col_ids(_b, user_id, role)
        def one(v):
            vj = _view_json(v, db, names)
            if _is_dash_view(v):
                # Identity and nothing else. A dashboard holds no cut, so
                # `filters` is empty for the same reason a form's is — and
                # what it measures is answered by the dashboard endpoints,
                # which do their own permission work.
                dv = dashes.get(v.id)
                return dict(vj, filters={}, blocked=False, needs_fix=[],
                            dashboard_id=(dv.id if dv else None))
            if _is_form_view(v):
                # Identity and state, which is what a strip needs to draw a
                # tab and decide whether to offer the pencil. No filters —
                # there are none — and no token: that is a capability, and it
                # is handed out by the management endpoints to the people the
                # management endpoints let in.
                fv = forms.get(v.id)
                return dict(vj, filters={}, blocked=False, needs_fix=[],
                            form_id=(fv.id if fv else None),
                            form_status=(fv.status if fv else None),
                            form_access=(fv.access if fv else None))
            # A cut that asks about a column this reader may not see is not
            # opened by them — and its filters do not travel either. The
            # message is deliberately general: naming the column, or showing
            # the condition, is the disclosure the block exists to prevent.
            if _view_blocked_for(_b, v, user_id, role):
                return dict(vj, filters={}, blocked=True, needs_fix=[])
            # A column the cut names and the board no longer has. Reported to
            # everyone, unlike `blocked`: the column is gone for all of them.
            return dict(vj,
                        filters=_redact_view_sort(
                            _redact_view_cols(vj["filters"], unseen), unseen),
                        blocked=False, needs_fix=_view_needs_fix(_b, v))
        # Where a normal entry lands. Resolved here and not by the client,
        # because the two reasons it can be wrong are both the server's to
        # know: the view may have been deleted since, and it may hold a filter
        # this reader is not allowed to run. Either way the answer is null,
        # which the client reads as the main table.
        #
        # Pinning is deliberately not consulted. "הצמדה אינה קובעת תצוגת
        # ברירת מחדל" — a pin is about the ORDER of the strip, and a board
        # owner pinning a cut must not silently move everybody's landing place.
        prefs = (db.query(BoardViewPrefs)
                   .filter(BoardViewPrefs.board_id == board_id,
                           BoardViewPrefs.user_id == user_id).first()) if user_id else None
        last = prefs.last_view_id if prefs else None
        if last is not None and not any(
                v.id == last and not _view_blocked_for(_b, v, user_id, role) for v in rows):
            last = None
        return {"last_view_id": last,
                "views": [dict(one(v),
                               # may write to it — the rights, and the lock,
                               # which only the board's owner writes through
                               # The same question for a form as for a cut,
                               # and the same answer: _may_edit_view is the
                               # board's roles, which is exactly what
                               # FORM_MANAGE_ROLE asks for.
                               can_edit=(_may_edit_view(v, user_id, role)
                                         and (not v.locked
                                              or _may_write_locked(role))),
                               # may turn the lock itself: the board's owner
                               can_lock=_may_write_locked(role),
                               # may make a tab on this board — the same right
                               # creating one takes. Sent rather than derived,
                               # so the menu offers exactly what the server
                               # would accept and never draws a dead action.
                               can_duplicate=(role in ("admin", "editor")
                                              and not _is_form_view(v)
                                              and not _is_dash_view(v)),
                               # drawn as "yours" or "somebody's" — the strip
                               # offers a different thing to save in each case
                               is_owner=(v.owner_id == user_id))
                          for v in rows]}


@app.post("/api/boards/{board_id}/views")
def create_saved_view(board_id: int, data: dict, user_id: int = Depends(current_user_id)):
    with Session(engine) as db:
        _b, role = _board_role_or_403(db, board_id, user_id)
        # A name is optional on the way in. Omitted, the server picks a free
        # one — here rather than in the browser, because the uniqueness rule
        # lives here and a client guessing at it would guess differently.
        if (data.get("name") or "").strip():
            name = _check_view_name(db, board_id, data.get("name"))
        else:
            name = _free_name(db, board_id, NEW_VIEW_NAME, "")
        # No private views in this version: a saved table view IS a tab on the
        # board, so making one is an edit to the board and needs the rights of
        # one. The parameter is not read — a client asking for "private" gets a
        # shared view, because that is the only kind there is.
        vis = "public"
        if role not in ("admin", "editor"):
            raise HTTPException(403, "תצוגה שמורה היא טאב על הלוח — רק עורך או מנהל לוח יכול ליצור אחת")
        _check_view_room(db, board_id)
        # the cut is validated the way the query endpoint validates one: a view
        # holding a filter the server would refuse is a tab that cannot open
        filters = data.get("filters") if isinstance(data.get("filters"), dict) else {}
        try:
            filter_ast.parse(filters.get("adv"))
        except filter_ast.BadFilter as e:
            raise HTTPException(400, str(e))
        if not _view_cut_allowed(_b, filters, user_id, role):
            raise HTTPException(403, "התצוגה מסננת לפי עמודה שאינך מורשה לראות")
        filters = _view_config(filters)
        maxpos = (db.query(func.max(SavedView.position))
                    .filter(SavedView.board_id == board_id).scalar())
        v = SavedView(board_id=board_id, owner_id=user_id, name=name,
                      visibility=vis, filters=filters,
                      position=(maxpos + 1) if maxpos is not None else 0)
        db.add(v)
        _commit_view(db, board_id,
                     log=lambda: _log_view(db, v, "create", field="name",
                                           new=v.name, actor=user_id))
        db.refresh(v)
        return dict(_view_json(v), can_edit=True)


@app.patch("/api/views/{view_id}")
def update_saved_view(view_id: int, data: dict, user_id: int = Depends(current_user_id)):
    with Session(engine) as db:
        # Through _view_or_404, which also refuses a view that is in the bin.
        # Reading the row directly let a deleted view be saved over: the menu
        # was drawn while it was still there, and "מחיקה תיבדק שוב בזמן
        # הביצוע" is exactly about the gap between those two moments.
        v, role, may = _view_or_404(db, view_id, user_id)
        if _is_dash_view(v):
            raise HTTPException(400, "זוהי תצוגת דשבורד ולא חיתוך — "
                                     "השתמשו ב‎/api/dashboards")
        if _is_form_view(v):
            raise HTTPException(400, "זהו טופס ולא חיתוך — השתמשו ב‎/api/forms")
        if not may:
            raise HTTPException(403, "אפשר לערוך רק תצוגה שיצרת")
        # The lock, at both ends of the switch, is the board owner's alone.
        if data.get("locked") is not None and bool(data["locked"]) != bool(v.locked):
            if not _may_write_locked(role):
                raise HTTPException(403, "רק בעל הלוח יכול לנעול תצוגה או לבטל את נעילתה")
            v.locked = bool(data["locked"])
            _log_view(db, v, "lock" if v.locked else "unlock", field="locked",
                      old=str(not v.locked), new=str(v.locked), actor=user_id)
        # הצמדה — and the order the pinned ones sit in — says which cut matters
        # on this board. That is the board owner's statement to make.
        if data.get("pinned") is not None and bool(data["pinned"]) != bool(v.pinned):
            if not _may_write_locked(role):
                raise HTTPException(403, "רק בעל הלוח יכול להצמיד תצוגה")
            v.pinned = bool(data["pinned"])
            _log_view(db, v, "pin" if v.pinned else "unpin", field="pinned",
                      old=str(not v.pinned), new=str(v.pinned), actor=user_id)
        if data.get("position") is not None and not _may_write_locked(role):
            raise HTTPException(403, "רק בעל הלוח יכול לסדר תצוגות מוצמדות")
        # And while it is locked, so is everything the view says.
        rest = [k for k in ("name", "visibility", "filters", "position") if k in data]
        if rest and v.locked and not _may_write_locked(role):
            raise HTTPException(403, "התצוגה נעולה — רק בעל הלוח יכול לשנות אותה")
        if data.get("name") is not None:
            _was = v.name
            v.name = _check_view_name(db, v.board_id, data.get("name"), exclude_id=v.id)
            if v.name != _was:
                _log_view(db, v, "rename", field="name", old=_was, new=v.name, actor=user_id)
        if data.get("visibility") in VIEW_VIS:
            # publishing is the edit that needs the rights, not editing itself:
            # a private view becoming public puts a tab on everybody's board
            if data["visibility"] == "public" and v.visibility != "public" \
                    and role not in ("admin", "editor"):
                raise HTTPException(403, "רק עורך או מנהל לוח יכול לפרסם תצוגה")
            v.visibility = data["visibility"]
        if isinstance(data.get("filters"), dict):
            # ── the version the caller was looking at ────────────────────
            # "עדכון תצורה יכלול גרסה נוכחית ... אם בוצע בינתיים עדכון משותף,
            # השרת ידחה דריסה."
            #
            # Required, not optional, and that is the whole protection: a save
            # that arrives without a version is a save that cannot be checked,
            # and accepting it is exactly the silent overwrite this is here to
            # stop. "אין שמירה אוטומטית של גרסה מיושנת" — nor of an unstated
            # one, which is a stale version nobody bothered to name.
            #
            # 409, so the client can tell "you may not" from "you are behind":
            # the first is a refusal and the second is an invitation to look
            # again. The current version travels back with it, because the
            # next thing that client does is reload and retry.
            want = data.get("config_version")
            have = v.config_version or 1
            if want is None:
                raise HTTPException(400, "שמירת תצורה חייבת לכלול את גרסת התצורה הנוכחית")
            try:
                want = int(want)
            except (TypeError, ValueError):
                raise HTTPException(400, "גרסת תצורה לא תקינה")
            if want != have:
                raise HTTPException(409, {"error": "stale_config",
                                          "detail": "ההגדרות השתנו על ידי משתמש אחר",
                                          "config_version": have})
            try:
                filter_ast.parse(data["filters"].get("adv"))
            except filter_ast.BadFilter as e:
                raise HTTPException(400, str(e))
            b = db.query(Board).filter(Board.id == v.board_id).first()
            # Saving over a cut you may not open would overwrite the rule you
            # cannot see — the same disclosure from the other side.
            if _view_blocked_for(b, v, user_id, role):
                raise HTTPException(403, "התצוגה מסננת לפי עמודה שאינך מורשה לראות")
            if not _view_cut_allowed(b, data["filters"], user_id, role):
                raise HTTPException(403, "התצוגה מסננת לפי עמודה שאינך מורשה לראות")
            v.filters = _view_config(
                _merge_view_cols(data["filters"], v.filters,
                                 _unseen_col_ids(b, user_id, role)))
            # the configuration moved, so the version does — and only here
            v.config_version = (v.config_version or 1) + 1
            # "עדכון משותף" — the event, and the version it produced. Never
            # the cut itself: it can name a column the reader may not see.
            _log_view(db, v, "config", field="config_version",
                      old=str(v.config_version - 1), new=str(v.config_version),
                      actor=user_id)
        if isinstance(data.get("position"), int):
            v.position = data["position"]
        v.updated_at = datetime.now(timezone.utc)
        _commit_view(db, v.board_id, adding=False)
        db.refresh(v)
        # "משתמש ללא שינויים מקומיים יקבל את התצורה החדשה בלי לטעון מחדש את
        # הלוח." The doorbell, not the configuration: the client fetches the
        # strip and decides what to do with it, which is where it knows
        # whether this reader has temporary adjustments to protect.
        bus.publish("view.changed", board_id=v.board_id, actor_id=user_id, view_id=v.id)
        return dict(_view_json(v), can_edit=True)


def _within_restore_window(v):
    """Is this deleted view still inside the window it can be brought back in?

    The row is not erased when the window closes — nothing here deletes data on
    a timer — but the log stops offering the restore, because an offer that
    fails when pressed is worse than no offer at all.
    """
    if v.deleted_at is None:
        return True
    gone = v.deleted_at
    if gone.tzinfo is None:                 # SQLite hands back naive datetimes
        gone = gone.replace(tzinfo=timezone.utc)
    return (datetime.now(timezone.utc) - gone) <= timedelta(days=VIEW_RESTORE_DAYS)


def _is_form_view(v):
    """Is this view row a form? The one question the cut endpoints have to ask.

    A form shares the table with the saved cuts because it IS a view of the
    board — same strip, same name rule, same bin. It shares almost nothing
    else: writing a cut's `filters` onto one, or duplicating it as though the
    cut were the thing being copied, would quietly produce a form with no
    questions. So the cut endpoints refuse it and name where to go instead.
    """
    return (v.kind or "saved") == "form"


def _view_or_404(db, view_id, user_id, *, live=True):
    """The view, the board role, and whether this person may manage it."""
    q = db.query(SavedView).filter(SavedView.id == view_id)
    v = q.first()
    if not v or (live and v.deleted_at is not None):
        raise HTTPException(404, "view not found")
    _b, role = _board_role_or_403(db, v.board_id, user_id)
    return v, role, _may_edit_view(v, user_id, role)


@app.delete("/api/views/{view_id}")
def delete_saved_view(view_id: int, user_id: int = Depends(current_user_id)):
    """To the bin, not out of existence.

    A view is a tab other people work off. Deleting one by mistake is the kind
    of thing nobody notices until the morning somebody opens the board and
    their cut is gone — and a hard delete leaves nothing to put back. Same
    shape as a deleted board or item: deleted_at, and a restore beside it.

    Deleting a locked view is the board owner's too — the definition names
    deletion alongside changing and unlocking, and a lock that stopped edits
    but not deletion would protect nothing worth protecting.
    """
    with Session(engine) as db:
        v, role, may = _view_or_404(db, view_id, user_id)
        # "לא ניתן למחוק את הטבלה הראשית." It is the board's own table; there
        # is no board without one, so there is nothing here to delete.
        if (v.kind or "saved") == "main":
            raise HTTPException(400, "לא ניתן למחוק את הטבלה הראשית")
        if not may:
            raise HTTPException(403, "אפשר למחוק רק תצוגה שיצרת")
        if v.locked and not _may_write_locked(role):
            raise HTTPException(403, "התצוגה נעולה — רק בעל הלוח יכול למחוק אותה")
        v.deleted_at = datetime.now(timezone.utc)
        v.deleted_by = user_id
        # Into the board's log, because that is where the restore is offered
        # from — "בעל הלוח יוכל לשחזר דרך לוג הלוח". The view's name is the
        # whole of the record: it is what the person reading the log is looking
        # for, and the cut itself is still on the row if it comes back.
        _log_view(db, v, "delete", field="name", old=v.name, actor=user_id)
        db.commit()
        return {"status": "deleted", "id": v.id}


@app.get("/api/boards/{board_id}/views/trash")
def list_deleted_views(board_id: int, user_id: int = Depends(current_user_id)):
    """What can still be brought back, newest first."""
    with Session(engine) as db:
        _b, role = _board_role_or_403(db, board_id, user_id)
        rows = (db.query(SavedView)
                  .filter(SavedView.board_id == board_id,
                          SavedView.deleted_at.isnot(None))
                  .order_by(SavedView.deleted_at.desc(), SavedView.id.desc()).all())
        rows = [v for v in rows if _view_visible_to(v, user_id, role)
                and _within_restore_window(v)]
        names = {}
        if rows:
            ids = {v.owner_id for v in rows} | {v.deleted_by for v in rows if v.deleted_by}
            names = {u.id: u.name for u in db.query(User).filter(User.id.in_(ids)).all()}
        return {"views": [dict(_view_json(v, db, names),
                               deleted_at=v.deleted_at.isoformat() if v.deleted_at else None,
                               deleted_by_name=names.get(v.deleted_by, ""),
                               can_manage=_may_edit_view(v, user_id, role))
                          for v in rows]}


@app.post("/api/views/{view_id}/restore")
def restore_saved_view(view_id: int, user_id: int = Depends(current_user_id)):
    """Back onto the strip, with its cut and its name intact."""
    with Session(engine) as db:
        v, role, may = _view_or_404(db, view_id, user_id, live=False)
        if v.deleted_at is None:
            return dict(_view_json(v), can_edit=may)
        # Bringing a tab back puts it on everybody's board again, which is the
        # same act as creating one and then some — it may be a tab people had
        # already agreed to be rid of. The board owner's.
        if not _may_write_locked(role):
            raise HTTPException(403, "רק בעל הלוח יכול לשחזר תצוגה שנמחקה")
        if not _within_restore_window(v):
            raise HTTPException(400,
                                f"חלון השחזור הוא {VIEW_RESTORE_DAYS} יום ממועד המחיקה, והוא חלף")
        # Putting a tab back on the strip is subject to what the strip allows
        # NOW, not to what it allowed when the tab left it. The board may have
        # filled up since — that is a refusal, because there is nowhere to put
        # it — while a name taken since is not: "בשחזור עם שם תפוס תתווסף
        # סיומת ייחודית", so the view comes back under a name of its own
        # rather than not at all.
        _check_view_room(db, v.board_id)
        v.name = _free_name(db, v.board_id, v.name, " — משוחזרת", exclude_id=v.id)
        # "ההצמדה לא תשוחזר אוטומטית, כדי לא לשנות את סדר הניווט הקיים."
        # A pin puts the tab first for everybody; people have arranged
        # themselves around the strip as it is since. Coming back is the view's
        # to ask for, the front of the strip is not — the board owner can pin
        # it again in one click if that is still what they want.
        v.pinned = False
        v.deleted_at = None
        v.deleted_by = None
        v.updated_at = datetime.now(timezone.utc)
        _log_view(db, v, "restore", field="name", new=v.name, actor=user_id)
        # a restore puts a live row back, so it faces both rules again
        _commit_view(db, v.board_id)
        db.refresh(v)
        b = db.query(Board).filter(Board.id == v.board_id).first()
        return dict(_view_json(v),
                    can_edit=may and (not v.locked or _may_write_locked(role)),
                    can_manage=may,
                    # restored, and possibly into a board that has changed
                    # under it — see _view_needs_fix
                    needs_fix=_view_needs_fix(b, v))


@app.post("/api/views/{view_id}/duplicate")
def duplicate_saved_view(view_id: int, data: dict = None,
                         user_id: int = Depends(current_user_id)):
    """שכפול — the same cut under a new name, owned by whoever copied it.

    Not locked and not pinned, whatever the original was: a lock and a pin are
    statements about THAT tab, and a copy is a new tab that nobody has decided
    anything about yet.
    """
    with Session(engine) as db:
        v, role, _may = _view_or_404(db, view_id, user_id)
        if _is_dash_view(v):
            raise HTTPException(400, "זוהי תצוגת דשבורד ולא חיתוך — "
                                     "השתמשו ב‎/api/dashboards")
        if _is_form_view(v):
            raise HTTPException(400, "זהו טופס ולא חיתוך — השתמשו ב‎/api/forms")
        if role not in ("admin", "editor"):
            raise HTTPException(403, "תצוגה שמורה היא טאב על הלוח — רק עורך או מנהל לוח יכול ליצור אחת")
        b = db.query(Board).filter(Board.id == v.board_id).first()
        # Copying a cut you may not open would hand you the cut: the copy is
        # yours, and the rule naming the column you cannot see comes with it.
        if _view_blocked_for(b, v, user_id, role):
            raise HTTPException(403, "התצוגה מסננת לפי עמודה שאינך מורשה לראות")
        _check_view_room(db, v.board_id)
        # A name may arrive with the copy — the dialog offers the suggestion
        # below and lets it be changed before saving — and whichever one comes
        # is held to the same rule as any other name.
        name = _check_view_name(db, v.board_id,
                                ((data or {}).get("name") or "").strip() or _copy_name(db, v))
        maxpos = (db.query(func.max(SavedView.position))
                    .filter(SavedView.board_id == v.board_id).scalar())
        # The SAVED shared configuration, not whatever the copier is looking
        # at — that is what "שמירה כתצוגה חדשה" is for. Shared, unlocked,
        # unpinned, a new id, and nothing but the configuration: no items, and
        # no permission anybody did not already have.
        c = SavedView(board_id=v.board_id, owner_id=user_id, name=name,
                      visibility="public", filters=_view_config(dict(v.filters or {})),
                      position=(maxpos + 1) if maxpos is not None else 0)
        db.add(c)
        _commit_view(db, v.board_id,
                     log=lambda: _log_view(db, c, "create", field="name",
                                           old=v.name, new=c.name, actor=user_id))
        db.refresh(c)
        return dict(_view_json(c), can_edit=True, can_manage=True, is_owner=True)


def _free_name(db, board_id, name, suffix, exclude_id=None):
    """`name` if it is free, else the same with a distinguishing suffix.

    Used where a name MUST come out usable rather than refused: restoring a
    view, and suggesting one for a copy. Where somebody typed the name, it is
    refused instead — see _check_view_name — because silently renaming what a
    person wrote is its own small lie.
    """
    q = db.query(SavedView.name).filter(SavedView.board_id == board_id,
                                        SavedView.deleted_at.is_(None))
    if exclude_id is not None:
        q = q.filter(SavedView.id != exclude_id)
    taken = {_view_name_key(n) for (n,) in q.all()}

    def fit(tail):
        room = VIEW_NAME_MAX - len(tail)
        return ((name or "")[:room].strip() + tail) if room > 0 else tail.strip()

    if _view_name_key(name) not in taken and len(name or "") <= VIEW_NAME_MAX:
        return name
    n = 1
    while True:
        cand = fit(suffix if n == 1 else f"{suffix} {n}")
        if _view_name_key(cand) not in taken:
            return cand
        n += 1


def _copy_name(db, v):
    """A free name for a copy: "<שם> — עותק", then "עותק 2", and so on.

    Compared the way every other name on the strip is compared — trimmed and
    casefolded, with the main table's name among the taken ones — so the
    suggestion can never come back refused by the rule that produced it.

    Shortened to fit when the original is already near the ceiling. A
    suggestion is ours to trim; a name somebody typed is not.
    """
    taken = {_view_name_key(n) for (n,) in
             db.query(SavedView.name).filter(SavedView.board_id == v.board_id,
                                             SavedView.deleted_at.is_(None)).all()}

    def fit(suffix):
        room = VIEW_NAME_MAX - len(suffix)
        return ((v.name or "")[:room].strip() + suffix) if room > 0 else suffix.strip()

    n = 1
    while True:
        cand = fit(" — עותק" if n == 1 else f" — עותק {n}")
        if _view_name_key(cand) not in taken:
            return cand
        n += 1


@app.put("/api/boards/{board_id}/views/last")
def set_last_view(board_id: int, data: dict, user_id: int = Depends(current_user_id)):
    """Remember which view this person is on, so the next entry opens it.

    Anyone who may open the board may record it — it says nothing about the
    board, only about them — which is the same reason their order needs no
    rights either.

    `view_id` null means the main table. A view id that is not a live view of
    this board is stored as null rather than refused: the board changes under
    people, and the honest answer to "open the one I was on" when it is gone
    is the main table, not an error on the way in.
    """
    with Session(engine) as db:
        _b, role = _board_role_or_403(db, board_id, user_id)
        want = data.get("view_id")
        keep = None
        if want is not None:
            try:
                want = int(want)
            except (TypeError, ValueError):
                want = None
            if want is not None:
                v = (db.query(SavedView)
                       .filter(SavedView.id == want, SavedView.board_id == board_id,
                               SavedView.deleted_at.is_(None)).first())
                # not a view they could open is not a view they were on,
                # and a form is not a view anybody lands ON
                if (v is not None and not _is_form_view(v)
                        and not _view_blocked_for(_b, v, user_id, role)):
                    keep = v.id
        row = (db.query(BoardViewPrefs)
                 .filter(BoardViewPrefs.board_id == board_id,
                         BoardViewPrefs.user_id == user_id).first())
        if not row:
            row = BoardViewPrefs(board_id=board_id, user_id=user_id)
            db.add(row)
        row.last_view_id = keep
        row.updated_at = datetime.now(timezone.utc)
        db.commit()
        return {"last_view_id": keep}


@app.put("/api/boards/{board_id}/views/order")
def set_personal_view_order(board_id: int, data: dict,
                            user_id: int = Depends(current_user_id)):
    """סדר תצוגות אישי — this reader's arrangement, nobody else's.

    Anyone who may open the board may arrange their own strip; it changes
    nothing about the board, which is exactly why it needs no rights beyond
    looking. Ids of views that are not on this board are dropped rather than
    refused: a strip arranged and then re-arranged on a stale list must not
    fail, it must simply settle.
    """
    with Session(engine) as db:
        _b, role = _board_role_or_403(db, board_id, user_id)
        want = data.get("order")
        if not isinstance(want, list):
            raise HTTPException(400, "order must be a list of view ids")
        # Pinned views are not this reader's to order — see _arrange_views.
        # Dropped rather than refused, like a stale id: a strip dragged while
        # somebody else pinned a tab must settle, not fail.
        mine = {v.id for v in db.query(SavedView.id)
                                .filter(SavedView.board_id == board_id,
                                        SavedView.deleted_at.is_(None),
                                        SavedView.pinned.isnot(True)).all()}
        seen, clean = set(), []
        for i in want:
            try:
                i = int(i)
            except (TypeError, ValueError):
                continue
            if i in mine and i not in seen:
                seen.add(i)
                clean.append(i)
        row = (db.query(BoardViewPrefs)
                 .filter(BoardViewPrefs.board_id == board_id,
                         BoardViewPrefs.user_id == user_id).first())
        if not row:
            row = BoardViewPrefs(board_id=board_id, user_id=user_id)
            db.add(row)
        row.order = clean
        row.updated_at = datetime.now(timezone.utc)
        db.commit()
        return {"order": clean}


# ── תצוגת טופס (Form View) ─────────────────────────────────────────────
# A form is a view of a board, so the identity is a view: SavedView carries
# the board, the name on the strip, the position, the lock, the bin and the
# configuration version, and FormView carries what only a form has. The two
# are written together and neither is useful alone, which is why nothing here
# creates one without the other.
#
# Everything in this section is MANAGEMENT, and it is board-admin work.
# Filling a form in is the other mechanism — different audience, different
# gate, no board role at all ("הרשאות ניהול הטופס והרשאות מילויו הן מנגנונים
# נפרדים") — and it is not here yet.

# The column types the system computes for itself. A form has nothing to ask
# about one, and an answer stored against it is a value the grid ignores.
# Mirrors DERIVED_COLS in frontend/index.html — the same list, because the
# builder and the server have to offer the same questions.
FORM_DERIVED_TYPES = ("created_at", "created_by", "item_id", "formula", "mirror")
# The five fields every item has, whatever its board's columns are.
FORM_BUILTIN_FIELDS = ("title", "assignees", "status", "priority", "due_date")
FORM_FONT_SIZES = ("small", "medium", "large")
FORM_TEXT_ALIGNS = ("right", "center", "left")
# Emphasis on a block of the form's own words. Three, and no more: "אין
# להוסיף … CSS מותאם אישית" and a rich-text editor is that by another name.
FORM_TEXT_STYLES = ("normal", "bold", "italic")
# A heading's size, named by level rather than by pixels, so a form cannot
# hold a size the stylesheet has no rule for.
FORM_HEADING_LEVELS = (1, 2, 3)
NEW_FORM_NAME = (os.environ.get("NEW_FORM_NAME") or "טופס חדש").strip()
_HEX_RE = re.compile(r"^#[0-9a-fA-F]{6}$")


def _form_field_keys(b):
    """Every field of THIS board a question may bind to.

    The one place that decides, and the whole of "שאלה יכולה להתייחס רק לשדה
    מאותו לוח": a key that is not in this set is not a field of this board,
    whether it belongs to another board or to nothing at all. A column is not
    a row in this system — the board keeps its columns in `settings` — so
    there is no foreign key that could say this, and the check has to.
    """
    keys = set(FORM_BUILTIN_FIELDS)
    for c in ((b.settings or {}).get("columns") or []):
        if c.get("type") in FORM_DERIVED_TYPES:
            continue
        cid = c.get("id")
        if cid:
            keys.add(str(cid))
    return keys


def _form_one_of(value, allowed, what):
    v = str(value or "").strip()
    if v not in allowed:
        raise HTTPException(400, f"ערך לא תקין ל־{what}: {value}")
    return v


def _form_color(value, what):
    v = str(value or "").strip()
    if not _HEX_RE.match(v):
        raise HTTPException(400, f"{what} אינו צבע תקין (#rrggbb): {value}")
    return v


def _form_url(value):
    """A redirect the form may send somebody to, or nothing.

    Only http and https. A redirect target is a string an admin types and a
    stranger follows, and `javascript:` in that position is script running on
    whoever submitted the form — the same reason _safe_media_type refuses to
    echo back an active content type.
    """
    v = str(value or "").strip()
    if not v:
        return None
    if not v.lower().startswith(("http://", "https://")):
        raise HTTPException(400, "כתובת הפניה חייבת להתחיל ב־http:// או https://")
    if len(v) > 500:
        raise HTTPException(400, "כתובת ההפניה ארוכה מדי")
    return v


# ── מי רשאי מה ──
# "הרשאות הניהול נגזרות מהרשאות הלוח הקיימות", so they are not a second
# permission model: they are the board's own, read at the same two levels the
# board already reads them at.
#
#   editor — build the form. Same right that puts a saved cut on the strip
#            (create_saved_view), because that is what this is: a tab on a
#            board, made by somebody who works on that board.
#   admin  — publish it, and decide who may fill it in. Those two are the
#            board's exposure, not its content, and exposure is already the
#            admin's alone: visibility, column permissions, the timezone.
#            An editor who could publish could hand the board an address.
#
# A viewer is neither. Reading the management side IS reading the board's
# configuration — "משתמש שאינו מורשה אינו יכול לקרוא או לשנות את הגדרות
# הניהול" — so every door below asks, including the ones that only read.
FORM_MANAGE_ROLE = "editor"
FORM_EXPOSE_ROLE = "admin"
_FORM_REFUSALS = {
    "editor": "ניהול טופס דורש הרשאת עריכה בלוח",
    "admin": "רק מנהל הלוח יכול לפרסם טופס או לקבוע מי רשאי למלא אותו",
}


def _form_or_404(db, form_id, user_id, *, need=FORM_MANAGE_ROLE):
    """The form, its view, its board and the caller's role on it.

    Every management endpoint comes through here, which is what makes the
    rule hold for a direct request and not only for the screen: there is no
    path to a form that does not pass the board's own role check first.

    A form in the bin is a form that is not there, the same way a deleted view
    is: the row survives so a restore can bring the questions back, and every
    door into it is closed meanwhile.
    """
    f = db.query(FormView).filter(FormView.id == form_id).first()
    if not f:
        raise HTTPException(404, "form not found")
    v = db.query(SavedView).filter(SavedView.id == f.view_id).first()
    if not v or v.deleted_at is not None:
        raise HTTPException(404, "form not found")
    b, role = _board_role_or_403(db, f.board_id, user_id)
    _form_need(role, need)
    return f, v, b, role


def _form_need(role, need):
    if _BROLE_ORDER.get(role, -1) < _BROLE_ORDER.get(need, 1):
        raise HTTPException(403, _FORM_REFUSALS[need])


def _form_component_json(c, board=None):
    out = {"id": c.id, "kind": c.kind, "position": c.position}
    if c.kind == "question" and board is not None:
        # The field this question is bound to, as the board has it NOW. A
        # question outlives the column it was written against, and the
        # builder is the one person who can do something about that — so it
        # is reported to them, in words, rather than left to be noticed when
        # a respondent sees one question fewer than the form has.
        live = _form_col_type(board, c.field_key)
        if live is None:
            out["orphaned"] = True
            out["issue"] = "השדה נמחק מהלוח — השאלה אינה נשאלת"
        elif live in ("status", "dropdown"):
            col = _form_col(board, c.field_key)
            opts = (_status_col_options((col or {}).get("options")) if live == "status"
                    else (col or {}).get("options")) or []
            if not opts:
                out["issue"] = "לשדה אין אפשרויות בחירה — אי אפשר לענות על השאלה"
    if c.kind == "question":
        out.update(field_key=c.field_key, label=c.label or "",
                   description=c.description or "", placeholder=c.placeholder or "",
                   required=bool(c.required), visible=c.visible is not False,
                   settings=c.settings or {})
    else:
        # a block's own emphasis, and a heading's level — the only design a
        # single component carries
        out["content"] = c.content or ""
        out["settings"] = c.settings or {}
    return out


def _form_json(db, f, v, *, user_id=None, components=True):
    out = {
        "id": f.id, "view_id": v.id, "board_id": f.board_id,
        # "שם תצוגה" — the name on the strip, which is the view's and is
        # unique per board because the view's index says so.
        "name": v.name,
        "status": f.status, "access": f.access,
        # The public identifier. Returned to a manager, who is the only one
        # who ever sees this endpoint — a filler reaches the form BY the
        # token and is never told anything about the board behind it.
        "public_token": f.public_token,
        # The address itself, so the screen has nothing to assemble and
        # nothing to get wrong. None until the first publish.
        "public_url": (FORM_PUBLIC_PATH + f.public_token) if f.public_token else None,
        "target_group_id": f.target_group_id,
        "design": {
            "display_title": f.display_title or "",
            "display_description": f.display_description or "",
            "font_size": f.font_size or "medium",
            "text_align": f.text_align or "right",
            "theme_color": f.theme_color or "",
            "background_color": f.background_color or "",
            "text_color": f.text_color or "",
            "logo_token": f.logo_token, "cover_token": f.cover_token,
            "show_logo": f.show_logo is not False,
            "submit_label": f.submit_label or "",
            "show_branding": f.show_branding is not False,
        },
        # Whether this person may take the branding off, so the screen offers
        # exactly what the server would accept — the same rule the view strip
        # follows with can_edit.
        "can_hide_branding": _cap(db, user_id, "hide_form_branding"),
        "success": {
            "title": f.success_title or "",
            "message": f.success_message or "",
            "allow_another": bool(f.success_allow_another),
            "redirect_url": f.success_redirect_url,
        },
        "record_submitter": f.record_submitter is not False,
        "published_at": _iso(f.published_at), "published_by": f.published_by,
        # What a reader holds, so a save can say "this moved since". The
        # view's counter, because the name lives there and a form whose only
        # change was its name has still changed.
        "config_version": v.config_version or 1,
        "locked": bool(v.locked),
        "updated_at": _iso(f.updated_at),
    }
    if components:
        rows = (db.query(FormComponent)
                  .filter(FormComponent.form_id == f.id)
                  .order_by(FormComponent.position, FormComponent.id).all())
        board = db.query(Board).filter(Board.id == f.board_id).first()
        out["components"] = [_form_component_json(c, board) for c in rows]
        # …and the same facts once more, as the one question the publish
        # button needs answered: is there anything here that makes this form
        # unpublishable as it stands?
        out["blockers"] = [{"question_id": c["id"], "label": c.get("label", ""),
                            "message": c["issue"]}
                           for c in out["components"]
                           if c.get("orphaned") and c.get("required")
                           and c.get("visible") is not False]
    return out


def _form_components_in(db, f, b, items):
    """Validate a whole component list, then write it — never half of it.

    Whole, because a save refused in the middle leaves a form its author never
    asked for: six questions saved, the seventh rejected, and a published form
    now missing a field. Same rule the submission itself will follow.

    Replace rather than merge. The list IS the form's order — "רכיבי הטופס
    נשמרים בסדר עצמאי מסדר השדות בלוח" — so the index in what arrives is the
    position, and a component that is not in it is one the author removed.
    """
    if not isinstance(items, list):
        raise HTTPException(400, "components חייב להיות מערך")
    if len(items) > 200:
        raise HTTPException(400, "יותר מדי רכיבים בטופס (עד 200)")
    allowed = _form_field_keys(b)
    rows, seen = [], set()
    for i, raw in enumerate(items):
        rows.append(_form_component_in(f, allowed, raw, seen, position=i))
    return rows


def _form_component_in(f, allowed, raw, seen, *, position=0, onto=None):
    """One component, validated against the board and against the form.

    `seen` is the field keys already spoken for, so the duplicate rule works
    the same whether the list arrives whole or a question is added to one.
    `onto` updates an existing row instead of building a new one — a PATCH
    that names three fields must leave the other four as they were, which a
    rebuilt row would not.
    """
    if not isinstance(raw, dict):
        raise HTTPException(400, "כל רכיב חייב להיות אובייקט")
    c = onto or FormComponent(form_id=f.id, board_id=f.board_id, position=position)
    kind = (_form_one_of(raw.get("kind"), FORM_COMPONENT_KINDS, "kind")
            if (onto is None or "kind" in raw) else c.kind)
    c.kind = kind
    if kind == "question":
        key = str(raw.get("field_key") or (c.field_key if onto is not None else "") or "").strip()
        if not key:
            raise HTTPException(400, "שאלה חייבת להיות מקושרת לשדה")
        # The cross-board refusal. The message deliberately does not say which
        # board the field DOES belong to: whoever is asking either mistyped,
        # or is probing for the column list of a board they were not invited
        # to.
        if key not in allowed:
            raise HTTPException(
                400, f"השדה '{key}' אינו שדה של הלוח הזה — שאלה יכולה "
                     f"להתייחס רק לשדה מאותו לוח")
        if key in seen:
            raise HTTPException(400, f"השדה '{key}' מופיע יותר מפעם אחת בטופס")
        seen.add(key)
        required = bool(raw.get("required")) if ("required" in raw or onto is None) \
            else bool(c.required)
        visible = (raw.get("visible") is not False) if ("visible" in raw or onto is None) \
            else (c.visible is not False)
        # Hidden and required cannot both hold: the question is not asked, so
        # the answer cannot arrive, so the form cannot be submitted. A state
        # nothing can satisfy is refused at the save rather than resolved at
        # the display — today's builder resolves it, silently, by filtering to
        # the visible fields BEFORE checking required, and the requirement
        # simply evaporates.
        if required and not visible:
            raise HTTPException(
                400, f"שאלה מוסתרת אינה יכולה להיות חובה: "
                     f"'{raw.get('label') or c.label or key}'")
        c.field_key = key
        c.required = required
        c.visible = visible
        if "label" in raw or onto is None:
            c.label = str(raw.get("label") or "")[:200]
        if "description" in raw or onto is None:
            c.description = str(raw.get("description") or "")
        if "placeholder" in raw or onto is None:
            c.placeholder = str(raw.get("placeholder") or "")[:200]
        if "settings" in raw or onto is None:
            c.settings = _form_component_settings("question", raw.get("settings"))
        c.content = ""
    else:
        # A heading and a text are the form's own words, bound to nothing.
        # field_key goes back to NULL — which the table's CHECK insists on —
        # so a question turned into a heading releases the field it held.
        c.field_key = None
        c.required = False
        c.visible = True
        if "content" in raw or onto is None:
            c.content = str(raw.get("content") or "")
        if "settings" in raw or onto is None:
            c.settings = _form_component_settings(kind, raw.get("settings"))
    return c


def _form_component_settings(kind, raw):
    """The settings a component of THIS kind may carry, and nothing else.

    A whitelist per kind rather than a passed-through blob: the settings are
    read by the renderer — on the respondent's page as much as in the editor —
    and a key nothing validates is a key somebody can put anything in.

    A question's are its constraints (the date range the builder already
    stores). A heading's and a text's are emphasis, and a heading's size. That
    is the whole of the design a single block carries; everything else about
    how a form looks belongs to the form.
    """
    raw = raw if isinstance(raw, dict) else {}
    out = {}
    if kind == "question":
        for k in ("min", "max"):
            if raw.get(k) not in (None, ""):
                out[k] = str(raw[k])[:40]
        return out
    style = str(raw.get("style") or "normal")
    if style not in FORM_TEXT_STYLES:
        raise HTTPException(400, f"סגנון טקסט לא תקין: {raw.get('style')}")
    if style != "normal":
        out["style"] = style
    if kind == "heading":
        # `or 2` would swallow a 0, which is a level nothing has a size for
        lv = raw.get("level")
        try:
            level = 2 if lv in (None, "") else int(lv)
        except (TypeError, ValueError):
            raise HTTPException(400, "רמת כותרת לא תקינה")
        if level not in FORM_HEADING_LEVELS:
            raise HTTPException(400, f"רמת כותרת לא תקינה: {raw.get('level')}")
        out["level"] = level
    return out


def _form_seen_keys(db, form_id, *, exclude=None):
    """Fields this form already asks about — the duplicate rule's memory."""
    q = (db.query(FormComponent.field_key)
           .filter(FormComponent.form_id == form_id,
                   FormComponent.field_key.isnot(None)))
    if exclude is not None:
        q = q.filter(FormComponent.id != exclude)
    return {k for (k,) in q.all()}


def _form_repack(db, form_id):
    """0..n-1, in the order the rows are already in.

    Positions are the form's order and nothing reads the gaps, but a list that
    goes 0, 1, 3, 7 after two removals is one that nobody can reason about
    from the database — and an insert "at position 2" would mean two different
    things depending on which gaps happened to be there.
    """
    rows = (db.query(FormComponent)
              .filter(FormComponent.form_id == form_id)
              .order_by(FormComponent.position, FormComponent.id).all())
    for i, c in enumerate(rows):
        if c.position != i:
            c.position = i
    return rows


def _form_touched(db, f, v):
    """Every write to a form moves the same two things."""
    f.updated_at = datetime.now(timezone.utc)
    v.config_version = (v.config_version or 1) + 1
    v.updated_at = f.updated_at


@app.post("/api/boards/{board_id}/forms")
def create_form_view(board_id: int, data: dict = None,
                     user_id: int = Depends(current_user_id)):
    """A new form on this board — a view row and its settings, together.

    Starts as a DRAFT called "טופס חדש" — a draft because a form nobody has
    written yet is not one anybody should be able to reach, and named because
    an unnamed tab cannot be told from the next unnamed tab. The name is
    numbered if it is taken, the way a new table view is.
    """
    data = data or {}
    with Session(engine) as db:
        b, role = _board_role_or_403(db, board_id, user_id)
        _form_need(role, FORM_MANAGE_ROLE)
        if (data.get("name") or "").strip():
            name = _check_view_name(db, board_id, data.get("name"))
        else:
            name = _free_name(db, board_id, NEW_FORM_NAME, "")
        _check_view_room(db, board_id)
        maxpos = (db.query(func.max(SavedView.position))
                    .filter(SavedView.board_id == board_id).scalar())
        v = SavedView(board_id=board_id, owner_id=user_id, name=name,
                      kind="form", visibility="public",
                      # A form holds no cut. Empty rather than absent, so
                      # anything that reads `filters` on any view gets a dict.
                      filters={}, schema_version=1,
                      position=(maxpos + 1) if maxpos is not None else 0)
        db.add(v)
        db.flush()
        # The first group, as the plan has it: a form with no target creates
        # items with no group, which is legal and almost never meant. Still
        # changeable, and still re-checked at publish.
        first = (db.query(Group).filter(Group.board_id == board_id)
                   .order_by(Group.position, Group.id).first())
        f = FormView(view_id=v.id, board_id=board_id,
                     status="DRAFT", access="AUTHENTICATED",
                     # No address yet. A draft is not reachable, so there is
                     # nothing for a token to be the key to — it is minted at
                     # the first publish and never again.
                     public_token=None,
                     target_group_id=first.id if first else None,
                     display_title=name)
        db.add(f)
        _commit_view(db, board_id,
                     log=lambda: _log_view(db, v, "create", field="form",
                                           new=v.name, actor=user_id))
        db.refresh(f)
        db.refresh(v)
        return _form_json(db, f, v, user_id=user_id)


@app.get("/api/boards/{board_id}/forms")
def list_form_views(board_id: int, user_id: int = Depends(current_user_id)):
    """Every live form on this board. Managers see them; nobody else needs to.

    Two forms on one board is the ordinary case, not an edge one — the same
    board takes a short public request and a long internal intake, and
    "ההגדרות של טפסים שונים נשמרות בנפרד" is what lets the second exist
    without disturbing the first.
    """
    with Session(engine) as db:
        _b, role = _board_role_or_403(db, board_id, user_id)
        _form_need(role, FORM_MANAGE_ROLE)
        rows = (db.query(FormView, SavedView)
                  .join(SavedView, SavedView.id == FormView.view_id)
                  .filter(FormView.board_id == board_id,
                          SavedView.deleted_at.is_(None))
                  .order_by(SavedView.position, SavedView.id).all())
        return {"forms": [_form_json(db, f, v, user_id=user_id, components=False)
                          for f, v in rows]}


@app.get("/api/forms/{form_id}")
def get_form_view(form_id: int, user_id: int = Depends(current_user_id)):
    with Session(engine) as db:
        f, v, _b, role = _form_or_404(db, form_id, user_id)
        return _form_json(db, f, v, user_id=user_id)


@app.patch("/api/forms/{form_id}")
def update_form_view(form_id: int, data: dict, user_id: int = Depends(current_user_id)):
    """Save the form. Everything named in the body is written; the rest stands.

    `components`, when present, REPLACES the list — see _form_components_in
    for why it is not a merge.
    """
    with Session(engine) as db:
        f, v, b, role = _form_or_404(db, form_id, user_id)
        if v.locked and not _may_write_locked(role):
            raise HTTPException(403, "הטופס נעול — רק בעל הלוח יכול לשנות אותו")
        # the logo and the cover are shown to every stranger who opens the
        # form, so they may only be files the editor could already read
        _refuse_foreign_files(db, user_id, tokens=[str(data[k]).strip() for k in
                                                   ("logo_token", "cover_token") if data.get(k)])

        # ── שם תצוגה — the view's, under the view's rule ──
        if data.get("name") is not None:
            name = _check_view_name(db, f.board_id, data.get("name"), exclude_id=v.id)
            if name != v.name:
                _log_view(db, v, "rename", field="name", old=v.name, new=name, actor=user_id)
                v.name = name

        # ── מצב וגישה — the two closed sets the table also checks ──
        # Taking the product's name off a form is not a design preference —
        # it is an entitlement, and it is checked where it is spent. Turning
        # it back ON is nobody's to be stopped from.
        if "show_branding" in data and bool(data["show_branding"]) != bool(f.show_branding):
            if not data["show_branding"] and not _cap(db, user_id, "hide_form_branding"):
                raise HTTPException(403, "אין לך הרשאה להסיר את מיתוג Missions מטופס")
            f.show_branding = bool(data["show_branding"])
        if "access" in data:
            want_access = _form_one_of(data["access"], FORM_ACCESS_MODES, "access")
            if want_access != f.access:
                _form_need(role, FORM_EXPOSE_ROLE)
                f.access = want_access
        if "status" in data:
            want = _form_one_of(data["status"], FORM_STATUSES, "status")
            if want != f.status:
                # Publishing turns the token into a working address, and
                # withdrawing one takes it away from whoever is mid-answer.
                _form_need(role, FORM_EXPOSE_ROLE)
                if want == "PUBLISHED":
                    # A required question nobody can answer is a form nobody
                    # can send. Refused at the publish, which is the last
                    # moment it is still cheap: the alternative is a live
                    # form that fails every submission with "שדה חובה" for a
                    # question the respondent was never shown.
                    dead = [c for c in db.query(FormComponent).filter(
                                FormComponent.form_id == f.id,
                                FormComponent.kind == "question").all()
                            if c.required and c.visible is not False
                            and _form_col_type(b, c.field_key) is None]
                    if dead:
                        raise HTTPException(400, {
                            "message": "אי אפשר לפרסם: יש שאלות חובה ששדה הלוח שלהן נמחק",
                            "errors": [{"question_id": c.id, "label": c.label or "",
                                        "message": "השדה נמחק מהלוח"} for c in dead]})
                    # The public address, minted here and only here. A form
                    # that has been published before keeps the one it had:
                    # disabling it and publishing it again is the same form
                    # coming back, and a link somebody sent out last month
                    # has to be the link that works.
                    if not f.public_token:
                        f.public_token = uuid.uuid4().hex
                    # Where the record lands has to be answered before anybody
                    # can send one. Defaulted rather than refused — the plan's
                    # "ברירת מחדל לקבוצה הראשונה" — because a draft saved
                    # before the board had groups is not an error the author
                    # can act on.
                    if f.target_group_id is None:
                        first = (db.query(Group).filter(Group.board_id == f.board_id)
                                   .order_by(Group.position, Group.id).first())
                        if first is None:
                            raise HTTPException(400, "אי אפשר לפרסם טופס ללוח בלי קבוצות")
                        f.target_group_id = first.id
                    f.published_at = datetime.now(timezone.utc)
                    f.published_by = user_id
                was, f.status = f.status, want
                _log_view(db, v, "form_status", field="status",
                          old=was, new=want, actor=user_id)
        if "target_group_id" in data:
            gid = data["target_group_id"]
            if gid is None:
                f.target_group_id = None
            else:
                g = db.query(Group).filter(Group.id == int(gid),
                                           Group.board_id == f.board_id).first()
                if not g:
                    raise HTTPException(400, "הקבוצה אינה קבוצה של הלוח הזה")
                f.target_group_id = g.id

        # ── עיצוב ומסך הצלחה ──
        # One table, so a field added to the model is a line here and nothing
        # else. The kinds are the validation: a tuple is a closed set, and the
        # strings name the handful of shapes a setting can have.
        for key, kind in (("display_title", "text200"),
                          ("display_description", "text"),
                          ("font_family", "text60"),
                          ("font_size", FORM_FONT_SIZES),
                          ("text_align", FORM_TEXT_ALIGNS),
                          ("theme_color", "color"),
                          ("background_color", "color"),
                          ("text_color", "color"),
                          ("logo_token", "token"),
                          ("cover_token", "token"),
                          ("show_logo", "bool"),
                          ("success_title", "text200"),
                          ("success_message", "text"),
                          ("success_allow_another", "bool"),
                          ("success_redirect_url", "url"),
                          ("submit_label", "text40"),
                          ("record_submitter", "bool")):
            if key not in data:
                continue
            val = data[key]
            if isinstance(kind, tuple):
                val = _form_one_of(val, kind, key)
            elif kind == "color":
                val = _form_color(val, key)
            elif kind == "bool":
                val = bool(val)
            elif kind == "token":
                val = (str(val).strip() or None) if val is not None else None
            elif kind == "url":
                val = _form_url(val)
            else:
                cap = int(kind[4:]) if len(kind) > 4 else 0
                val = str(val or "")
                if cap and len(val) > cap:
                    raise HTTPException(400, f"{key} ארוך מדי (עד {cap} תווים)")
            setattr(f, key, val)

        # ── הרכיבים ──
        if "components" in data:
            rows = _form_components_in(db, f, b, data["components"])
            # Validated above, every one of them, before the first delete.
            (db.query(FormComponent)
               .filter(FormComponent.form_id == f.id)
               .delete(synchronize_session=False))
            for c in rows:
                db.add(c)

        f.updated_at = datetime.now(timezone.utc)
        # The shared configuration moved. A reader holding the old number can
        # be told so rather than discovering it by saving over somebody.
        v.config_version = (v.config_version or 1) + 1
        v.updated_at = f.updated_at
        try:
            db.commit()
        except IntegrityError:
            db.rollback()
            raise HTTPException(400, "שמירת הטופס נדחתה — שם תפוס או שדה כפול")
        db.refresh(f)
        db.refresh(v)
        return _form_json(db, f, v, user_id=user_id)


@app.delete("/api/forms/{form_id}")
def delete_form_view(form_id: int, user_id: int = Depends(current_user_id)):
    """To the bin, and the board is not touched.

    "מחיקת טופס אינה מוחקת שדות או רשומות בלוח" — and nothing here could: a
    form names columns and never owns them, and the items it created belong to
    the board the moment they exist. What goes is the tab, the same soft
    delete a saved cut gets, so a form deleted by mistake can come back with
    its questions rather than be rebuilt from memory.

    Items already submitted keep pointing at it. Task.form_view_id is where
    they came from, and that stays true after the form is gone.
    """
    with Session(engine) as db:
        f, v, _b, role = _form_or_404(db, form_id, user_id)
        if v.locked and not _may_write_locked(role):
            raise HTTPException(403, "הטופס נעול — רק בעל הלוח יכול למחוק אותו")
        v.deleted_at = datetime.now(timezone.utc)
        v.deleted_by = user_id
        _log_view(db, v, "delete", field="form", old=v.name, actor=user_id)
        db.commit()
        return {"status": "deleted", "id": f.id, "view_id": v.id}



# ── רכיבים, אחד אחד ───────────────────────────────────────────────────
# PATCH /api/forms/{id} with a `components` list replaces the lot, which is
# what a builder that keeps the whole form in memory wants. These four are
# for the builder that does not: add a question, change its wording, take one
# out, drag the list into a different order. Each is one row, so two people
# working on the same form do not overwrite each other's other edits.


@app.post("/api/forms/{form_id}/components")
def add_form_component(form_id: int, data: dict,
                       user_id: int = Depends(current_user_id)):
    """Append a component, or insert it at `position`."""
    with Session(engine) as db:
        f, v, b, role = _form_or_404(db, form_id, user_id)
        if v.locked and not _may_write_locked(role):
            raise HTTPException(403, "הטופס נעול — רק בעל הלוח יכול לשנות אותו")
        rows = _form_repack(db, f.id)
        if len(rows) >= 200:
            raise HTTPException(400, "יותר מדי רכיבים בטופס (עד 200)")
        c = _form_component_in(f, _form_field_keys(b), data,
                               _form_seen_keys(db, f.id), position=len(rows))
        at = data.get("position")
        if at is not None:
            try:
                at = max(0, min(int(at), len(rows)))
            except (TypeError, ValueError):
                at = len(rows)
            for other in rows[at:]:
                other.position += 1
            c.position = at
        db.add(c)
        _form_touched(db, f, v)
        try:
            db.commit()
        except IntegrityError:
            db.rollback()
            raise HTTPException(400, "השדה כבר מופיע בטופס")
        db.refresh(c)
        return _form_component_json(c)


# The ten kinds of question a form can ask, as board columns. Ordered the way
# the specification lists them, which is also roughly the order somebody
# reaches for them. Single Select is a `status` column — one value out of a
# coloured vocabulary — and Multi Select is a `dropdown`, which takes several;
# that difference is the board's, not the form's, so it is settled when the
# FIELD is made and never afterwards.
FORM_FIELD_TYPES = ("text", "long_text", "number", "status", "dropdown",
                    "checkbox", "date", "phone", "email", "files")
# The two that carry a vocabulary. Everything else ignores `options`.
FORM_OPTION_TYPES = ("status", "dropdown")


@app.post("/api/forms/{form_id}/fields")
def add_form_field(form_id: int, data: dict, user_id: int = Depends(current_user_id)):
    """Make a board column and the question that asks for it, in one write.

    The second route into a question: the first picks a field the board
    already has, this one makes the field as well. Two writes done in one
    transaction and not two requests, because "יצירת שדה ושאלה תטופל באופן
    עקבי גם במקרה של כשל" is a promise a client cannot keep — a browser that
    creates the column and then fails to create the question leaves a column
    nobody asked for, and one that tries the other order asks for a field
    that does not exist yet and is refused.

    Nothing is committed until both exist. A refusal — an unknown type, a
    duplicate name, a vocabulary with no options in it — leaves the board
    exactly as it was.

    Board ADMIN, not editor: adding a column changes the board for everybody
    who reads it, and that has been the admin's alone since columns existed
    (see the columns branch of update_board). Adding a question about a column
    that is already there stays an editor's job.
    """
    with Session(engine) as db:
        f, v, b, role = _form_or_404(db, form_id, user_id)
        if role != "admin":
            raise HTTPException(403, "רק מנהל הלוח יכול להוסיף שדה חדש ללוח")
        if v.locked and not _may_write_locked(role):
            raise HTTPException(403, "הטופס נעול — רק בעל הלוח יכול לשנות אותו")
        ctype = _form_one_of(data.get("type"), FORM_FIELD_TYPES, "type")
        title = str(data.get("title") or "").strip()[:60]
        if not title:
            raise HTTPException(400, "לשדה צריך שם")
        cols = list((b.settings or {}).get("columns") or [])
        # The board's own rule about two columns with one name. Checked here
        # rather than left to the grid, because a form that asks two questions
        # whose fields read the same is a form nobody can fill in correctly.
        if any((c.get("title") or "").strip() == title for c in cols):
            raise HTTPException(400, f"כבר יש בלוח עמודה בשם '{title}'")

        opts = None
        if ctype in FORM_OPTION_TYPES:
            raw = data.get("options")
            labels = [str(o).strip()[:40] for o in raw if str(o or "").strip()] \
                if isinstance(raw, list) else []
            # deduplicated, in the order they were typed
            seen = set()
            labels = [x for x in labels if not (x in seen or seen.add(x))]
            if not labels:
                raise HTTPException(400, "שדה בחירה צריך אפשרות אחת לפחות")
            # a status column's vocabulary goes through the same normaliser a
            # column edited by hand goes through, so each option gets the
            # stable id its cells will point at
            opts = (_status_col_options([{"label": x} for x in labels])
                    if ctype == "status" else labels)

        cid = "col_" + uuid.uuid4().hex[:8]
        col = {"id": cid, "type": ctype, "title": title, "options": opts,
               "formula": None, "connect": None, "mirror_of": None,
               "copy_mode": None, "number": None, "perms": {}}
        cols.append(col)
        settings = dict(b.settings or {})
        settings["columns"] = cols
        b.settings = settings
        db.flush()        # so _form_field_keys below sees the column that was just made

        # …and now the question, through exactly the same validation an
        # ordinary one goes through. If it refuses, the column goes with it:
        # nothing here has been committed.
        c = _form_component_in(
            f, _form_field_keys(b),
            {"kind": "question", "field_key": cid,
             "label": data.get("label") or title,
             "description": data.get("description") or "",
             "placeholder": data.get("placeholder") or "",
             "required": bool(data.get("required")),
             "visible": data.get("visible") is not False},
            _form_seen_keys(db, f.id),
            position=len(_form_repack(db, f.id)))
        db.add(c)
        _form_touched(db, f, v)
        _log_view(db, v, "form_field", field="column", new=title, actor=user_id)
        try:
            db.commit()
        except IntegrityError:
            db.rollback()
            raise HTTPException(400, "יצירת השדה נדחתה")
        db.refresh(c)
        return {"column": col, "component": _form_component_json(c)}


@app.patch("/api/forms/{form_id}/components/{component_id}")
def update_form_component(form_id: int, component_id: int, data: dict,
                          user_id: int = Depends(current_user_id)):
    """Change one component. Fields the body does not name are left alone."""
    with Session(engine) as db:
        f, v, b, role = _form_or_404(db, form_id, user_id)
        if v.locked and not _may_write_locked(role):
            raise HTTPException(403, "הטופס נעול — רק בעל הלוח יכול לשנות אותו")
        c = (db.query(FormComponent)
               .filter(FormComponent.id == component_id,
                       FormComponent.form_id == f.id).first())
        if not c:
            raise HTTPException(404, "component not found")
        # Its own field is not a duplicate of itself — a PATCH that changes
        # only the label must not trip the rule on the key it already holds.
        _form_component_in(f, _form_field_keys(b), data,
                           _form_seen_keys(db, f.id, exclude=c.id), onto=c)
        c.updated_at = datetime.now(timezone.utc)
        _form_touched(db, f, v)
        try:
            db.commit()
        except IntegrityError:
            db.rollback()
            raise HTTPException(400, "השדה כבר מופיע בטופס")
        db.refresh(c)
        return _form_component_json(c)


@app.delete("/api/forms/{form_id}/components/{component_id}")
def delete_form_component(form_id: int, component_id: int,
                          user_id: int = Depends(current_user_id)):
    """Take a component out. The board keeps its column either way.

    A hard delete, unlike the form itself: a question is a line in a list
    somebody is editing, not a tab other people work off, and an undo for it
    belongs in the builder rather than in a bin.
    """
    with Session(engine) as db:
        f, v, _b, role = _form_or_404(db, form_id, user_id)
        if v.locked and not _may_write_locked(role):
            raise HTTPException(403, "הטופס נעול — רק בעל הלוח יכול לשנות אותו")
        c = (db.query(FormComponent)
               .filter(FormComponent.id == component_id,
                       FormComponent.form_id == f.id).first())
        if not c:
            raise HTTPException(404, "component not found")
        db.delete(c)
        db.flush()
        _form_repack(db, f.id)
        _form_touched(db, f, v)
        db.commit()
        return {"status": "deleted", "id": component_id}


@app.put("/api/forms/{form_id}/components/order")
def set_form_component_order(form_id: int, data: dict,
                             user_id: int = Depends(current_user_id)):
    """The form's order, by id.

    Ids that are not this form's are dropped and components the list forgets
    keep their relative order after the ones it names — the same settling
    rule the personal view order follows, and for the same reason: a list
    dragged while somebody else added a question must settle, not fail.
    """
    with Session(engine) as db:
        f, v, _b, role = _form_or_404(db, form_id, user_id)
        if v.locked and not _may_write_locked(role):
            raise HTTPException(403, "הטופס נעול — רק בעל הלוח יכול לשנות אותו")
        want = data.get("order")
        if not isinstance(want, list):
            raise HTTPException(400, "order חייב להיות מערך של מזהי רכיבים")
        rows = _form_repack(db, f.id)
        by_id = {c.id: c for c in rows}
        ordered, seen = [], set()
        for i in want:
            try:
                i = int(i)
            except (TypeError, ValueError):
                continue
            if i in by_id and i not in seen:
                seen.add(i)
                ordered.append(by_id[i])
        ordered += [c for c in rows if c.id not in seen]
        for i, c in enumerate(ordered):
            c.position = i
        _form_touched(db, f, v)
        db.commit()
        return {"order": [c.id for c in ordered]}


# ── מה שהמשיב רואה ───────────────────────────────────────────────────
# "הפרד בין הנתונים שמוחזרים למנהל לבין הנתונים שיוחזרו למשיב בטופס" — and
# the separation is a different function rather than a flag on the same one,
# because a flag is something a caller can forget to pass.
#
# What does NOT travel: the board id, the view id, the column ids, the column
# titles, the board's members, the target group, who published it and when,
# the configuration version, and every hidden component. A respondent is told
# what to answer. Nothing in the answer tells them what they are answering
# into, which is the whole of "מילוי טופס אינו מעניק גישה ללוח".
#
# The unauthenticated route that will serve this is task 4 of the plan. The
# projection is here now because the rule about what crosses the line is
# worth having before there is a line to cross — and it is reachable today as
# the manager's own preview, which is the same bytes the respondent will get.

_FORM_BUILTIN_TYPES = {"title": "text", "assignees": "people",
                       "status": "status", "priority": "priority",
                       "due_date": "date"}


def _form_people_options(db, b, viewer_id):
    """Who this respondent may name on this board — and for a stranger, nobody.

    The rule has always been that a form must not hand out the board's member
    list: that is what "מילוי טופס אינו מעניק גישה ללוח" protects, and it is
    why this used to answer an empty list to everyone. But answering it to
    everyone meant an אחראים question had nothing to draw, so the field was
    dead on the page — clicking it did nothing, in the editor and on the
    published form alike.

    The line is drawn by who is READING rather than by the question: the
    options are the board's own taggable members, and they are offered only
    to somebody the board already knows — a member, or a workspace admin,
    exactly who _can_be_assigned accepts. Such a reader can see this list in
    the app anyway, so nothing crosses the line that was not already theirs.
    A stranger on a public link, and a signed-in user who is not on the
    board, still get nothing, and the page says so instead of drawing a
    control that cannot be used.

    Deactivated accounts are left out, the same as the board's own pickers do
    (see the `members` key of the board payload) — offering a name that
    _can_be_assigned would then refuse at submission is worse than not
    offering it.

    Called ONCE per request, by _form_public_json, and the result handed down
    to every question that needs it. It used to be called per question, which
    is four queries each — the gate is three on its own — so a form with three
    אחראים questions asked the database twelve times for one answer that
    cannot change inside a single response.
    """
    if not _can_be_assigned(db, b.id, viewer_id):
        return []
    return [{"value": u.id, "label": u.name}
            for u in (db.query(User)
                        .join(BoardMember, BoardMember.user_id == User.id)
                        .filter(BoardMember.board_id == b.id,
                                User.is_active.isnot(False))
                        .order_by(User.name).all())]


def _form_question_shape(db, b, key, people_options=None):
    """(type, options) — what a browser needs to draw this question.

    The type, because an input has to be an input OF something. The options,
    where a choice cannot be made without them.

    For a people question that depends on who is asking, and what arrives
    here is the ANSWER rather than the reader: _form_public_json works it out
    once for the whole form and passes it down. Taking a `viewer_id` instead
    meant re-deriving the same list for every אחראים question on the page.
    None is a reader who may name nobody — a stranger on a public link — and
    is the same empty list the caller would have got anyway. See
    _form_people_options for where that line is drawn.

    Whatever is answered here is a courtesy to the browser and never the
    rule: a submitted people value is checked again, one id at a time,
    against _can_be_assigned.
    """
    if key in _FORM_BUILTIN_TYPES:
        t = _FORM_BUILTIN_TYPES[key]
        if t == "people":
            return t, (people_options or [])
        if t == "status":
            return t, [{"value": x["key"], "label": x.get("label") or x["key"]}
                       for x in _board_statuses(b)]
        if t == "priority":
            return t, [{"value": x["key"], "label": x.get("label") or x["key"]}
                       for x in _board_priorities(b)]
        return t, []
    col = next((c for c in ((b.settings or {}).get("columns") or [])
                if str(c.get("id")) == str(key)), None)
    if not col:
        # The column was deleted out from under the question. Reported as its
        # own state rather than guessed at — see the plan, 9.2.
        return None, []
    t = col.get("type") or "text"
    if t == "status":
        # `o["id"] or o["label"]` rather than the id alone: a column with no
        # vocabulary of its own is answered by the default one, whose options
        # are not in the column and so have no id to point at. The browser's
        # own canvas has always keyed these the same way — see optionsFor in
        # index.html, `o.id||o.label`.
        return t, [{"value": o["id"] or o["label"], "label": o["label"]}
                   for o in _status_col_vocab(col)]
    if t == "dropdown":
        # An inactive option stays on the cells that already carry it and is
        # offered to nobody new — a stranger filling in a form included.
        off = set(col.get("inactive_options") or [])
        return t, [{"value": o, "label": o} for o in (col.get("options") or [])
                   if o not in off]
    if t == "people":
        return t, (people_options or [])
    return t, []


def _form_public_json(db, f, b, viewer_id=None):
    """The form as the person filling it in sees it, and nothing besides.

    `viewer_id` is who is reading — None for a stranger on a public link. It
    changes exactly one thing, the options of a people question, and it is
    passed rather than looked up because the two callers resolve identity
    differently: the public route through _public_form_or_refuse, the
    preview through the ordinary dependency.
    """
    rows = (db.query(FormComponent)
              .filter(FormComponent.form_id == f.id)
              .order_by(FormComponent.position, FormComponent.id).all())
    # Once, before the loop. Who may be named on this board is a fact about
    # the reader and the board, not about the question being drawn, so it
    # cannot differ between two אחראים questions in the same response — and
    # working it out inside the loop cost four queries per question for an
    # answer already known.
    people_options = _form_people_options(db, b, viewer_id)
    out = []
    for c in rows:
        if c.kind != "question":
            # `settings` travels with it: a heading's level and a block's
            # emphasis are how the form READS, and the page that draws it for
            # the respondent is the same renderer the editor uses. Leaving
            # them behind would make the published form a near-miss of the
            # one somebody designed.
            out.append({"id": c.id, "kind": c.kind, "content": c.content or "",
                        "settings": c.settings or {}})
            continue
        # A hidden question is not asked, so it is not sent. Hiding wins, and
        # it wins here rather than in the browser: a field withheld by the
        # page that drew it was never withheld at all.
        if c.visible is False:
            continue
        t, options = _form_question_shape(db, b, c.field_key, people_options)
        if t is None:
            continue           # the field is gone; the question goes with it
        q = {"id": c.id, "kind": "question", "type": t,
             "label": c.label or "", "description": c.description or "",
             "placeholder": c.placeholder or "", "required": bool(c.required),
             "settings": c.settings or {}}
        if options:
            q["options"] = options
        out.append(q)
    return {
        # The token, which the respondent already holds — it is how they got
        # here — and no other identifier. Not the form id: it is a number
        # beside other boards' numbers, and it is the key to the management
        # endpoints above.
        "token": f.public_token,
        "status": f.status,
        "access": f.access,
        # Everything the page needs to look like the form that was designed,
        # and nothing that says what is behind it. One renderer draws the
        # editor's canvas, the preview and the published page, so this is the
        # shape all three agree on.
        "design": {
            "display_title": f.display_title or "",
            "display_description": f.display_description or "",
            "font_size": f.font_size or "medium",
            "text_align": f.text_align or "right",
            "theme_color": f.theme_color or "",
            "background_color": f.background_color or "",
            "text_color": f.text_color or "",
            "logo_token": f.logo_token if f.show_logo is not False else None,
            "cover_token": f.cover_token,
            "submit_label": f.submit_label or "",
            "show_branding": f.show_branding is not False,
        },
        "success": {
            "title": f.success_title or "", "message": f.success_message or "",
            "allow_another": bool(f.success_allow_another),
            "redirect_url": f.success_redirect_url,
        },
        "components": out,
        # The file policy, so the page can say "too big" before a megabyte
        # has crossed the wire — and say it in the same numbers the server
        # will. It is told, not guessed: a second copy of these limits in a
        # public page would be wrong the first time either moved. Every one
        # of them is checked again on the way in; this is a courtesy.
        "uploads": {"max_mb": FORM_UPLOAD_MAX_BYTES // (1024 * 1024),
                    "per_question": FORM_UPLOAD_PER_QUESTION,
                    "total_mb": FORM_UPLOAD_TOTAL_BYTES // (1024 * 1024),
                    "types": sorted(FORM_UPLOAD_TYPES)},
    }


_FORM_LEGACY_LABELS = {"title": "שם הפריט", "assignees": "אחראים",
                       "status": "סטטוס", "priority": "עדיפות",
                       "due_date": "תאריך יעד"}


def _migrate_board_forms():
    """`board.settings["form"]` → a form view, once, on the way past.

    The old shape was one form per board kept as a key in the board's own
    settings: a list of {key, required, visible, min, max} and nothing else.
    Everything a question SAID — its label, its help — was read off the live
    column at display time, which is exactly the independence the
    specification asks for and the old shape could not express.

    So the label is copied FROM the column at the moment of the migration and
    stored. That is the one irreversible step here, and it is the right one:
    from this point on, renaming the column renames the column.

    PUBLISHED, because the old form was reachable by anyone who could open
    the board the moment the box was ticked — arriving as a draft would
    silently take a working form off the air. AUTHENTICATED for the same
    reason: it is the narrower of the two access modes, and the old form was
    never reachable without an account.

    Idempotent by construction: the key is removed as the rows are written,
    so a board that has been through this has nothing left to find.
    """
    with Session(engine) as db:
        try:
            boards = [b for b in db.query(Board).all()
                      if isinstance((b.settings or {}).get("form"), dict)]
        except Exception:                                  # noqa: BLE001
            return                                         # pre-migration database
        made = 0
        for b in boards:
            legacy = (b.settings or {}).get("form") or {}
            fields = legacy.get("fields")
            allowed = _form_field_keys(b)
            cols = {str(c.get("id")): c for c in ((b.settings or {}).get("columns") or [])}
            maxpos = (db.query(func.max(SavedView.position))
                        .filter(SavedView.board_id == b.id).scalar())
            v = SavedView(board_id=b.id, owner_id=None,
                          name=_free_name(db, b.id, NEW_FORM_NAME, ""),
                          kind="form", visibility="public", filters={},
                          position=(maxpos + 1) if maxpos is not None else 0)
            db.add(v)
            db.flush()
            first = (db.query(Group).filter(Group.board_id == b.id)
                       .order_by(Group.position, Group.id).first())
            f = FormView(view_id=v.id, board_id=b.id,
                         status="PUBLISHED", access="AUTHENTICATED",
                         public_token=uuid.uuid4().hex,
                         target_group_id=first.id if first else None,
                         display_title=b.name or "",
                         published_at=datetime.now(timezone.utc))
            db.add(f)
            db.flush()
            seen, pos = set(), 0
            for sf in (fields if isinstance(fields, list) else []):
                key = str((sf or {}).get("key") or "").strip()
                # A field the board no longer has is dropped rather than
                # carried across as a question nothing can answer.
                if key not in allowed or key in seen:
                    continue
                seen.add(key)
                visible = (sf.get("visible") is not False)
                col = cols.get(key)
                settings = {k: sf[k] for k in ("min", "max")
                            if sf.get(k) not in (None, "")}
                db.add(FormComponent(
                    form_id=f.id, board_id=b.id, kind="question", position=pos,
                    field_key=key,
                    label=(_FORM_LEGACY_LABELS.get(key)
                           or (col or {}).get("title") or key)[:200],
                    # Hidden and required together is a form nobody can send.
                    # The old builder let it be saved and then quietly dropped
                    # the requirement; here the visible half wins, out loud.
                    required=bool(sf.get("required")) and visible,
                    visible=visible, settings=settings))
                pos += 1
            st = dict(b.settings or {})
            st.pop("form", None)
            b.settings = st
            made += 1
        if made:
            db.commit()
            print(f"[forms] migrated {made} board form(s) out of board.settings",
                  flush=True)


_migrate_board_forms()


# ── הגשה ─────────────────────────────────────────────────────────────
# How many submissions one address will take from one caller, and over how
# long. The first unauthenticated write this system has, so it is also the
# first that can be repeated by somebody with nothing to lose: without a
# ceiling, one PUBLIC_LINK form is a way to put ten thousand rows on a board.
#
# In memory and per process, which is the honest description of what it is: a
# cost on the obvious abuse, not a distributed quota. The caller is hashed
# rather than stored — an address is personal data and keeping one is the
# organisation's decision (see _audit_ip_allowed), which this is not asking
# for.
# What a respondent may attach, and what of. An ALLOWLIST — "סוגים:
# allowlist, לא blocklist" — because the caller has no account and the list
# of things that are not dangerous is the shorter one to be right about.
FORM_UPLOAD_MAX_BYTES = int(os.getenv("FORM_UPLOAD_MAX_MB", "10")) * 1024 * 1024
FORM_UPLOAD_PER_QUESTION = int(os.getenv("FORM_UPLOAD_PER_QUESTION", "5"))
FORM_UPLOAD_TOTAL_BYTES = int(os.getenv("FORM_UPLOAD_TOTAL_MB", "25")) * 1024 * 1024
# How long a file uploaded for a form that was never sent is kept. Long
# enough that somebody can fill a long form in two sittings; short enough
# that an abandoned draft is not storage nobody will ever account for.
FORM_UPLOAD_TTL_HOURS = int(os.getenv("FORM_UPLOAD_TTL_HOURS", "24"))
FORM_UPLOAD_TYPES = {
    "image/png", "image/jpeg", "image/gif", "image/webp", "image/heic",
    "application/pdf", "text/plain", "text/csv",
    "application/msword",
    "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    "application/vnd.ms-excel",
    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
}
FORM_SUBMIT_MAX = int(os.getenv("FORM_SUBMIT_MAX", "20"))
FORM_SUBMIT_WINDOW = int(os.getenv("FORM_SUBMIT_WINDOW_SEC", "600"))
_form_hits = {}


def _form_rate_ok(token, request):
    if FORM_SUBMIT_MAX <= 0:
        return True
    import hashlib
    key = hashlib.sha256(
        # _rl_client, not _client_ip: the first X-Forwarded-For entry is the
        # caller's to write, and a limit keyed on it is a limit they reset at will
        f"{token}|{_rl_client(request)}".encode("utf-8")).hexdigest()[:32]
    now = time.time()
    hits = [t for t in _form_hits.get(key, []) if now - t < FORM_SUBMIT_WINDOW]
    if len(hits) >= FORM_SUBMIT_MAX:
        _form_hits[key] = hits
        return False
    hits.append(now)
    _form_hits[key] = hits
    # the table is bounded by callers, not by traffic: a key with nothing
    # left in its window is a key nobody is holding
    if len(_form_hits) > 5000:
        for k, v in list(_form_hits.items()):
            if not any(now - t < FORM_SUBMIT_WINDOW for t in v):
                _form_hits.pop(k, None)
    return True


# ── ולידציה של ערך, לפי הסוג שהעמודה מצהירה עליו ──────────────────
# The client is told the type so it can draw the right input. It is not
# believed about anything: the type checked here is the COLUMN's, read from
# the board, and the options are the column's own. A request that names a
# board, a field or a user is naming things it does not get to choose.
_FORM_EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s.]+(\.[^@\s.]+)+$")
# Digits, and the handful of characters people put between them. Not a
# country-by-country rule: this is a municipality's contact field, and
# refusing a number because of where the spaces are is worse than storing it.
_FORM_PHONE_RE = re.compile(r"^[0-9+()\-. ]{6,24}$")
FORM_TEXT_MAX = int(os.getenv("FORM_TEXT_MAX", "5000"))
FORM_LONG_TEXT_MAX = int(os.getenv("FORM_LONG_TEXT_MAX", "20000"))


def _form_empty(val):
    """Is there no answer here?

    `False` is an answer and `0` is an answer. `if not val` would call both of
    them missing, which is how a "no" on a checkbox and a zero in a number
    field quietly become blanks — so emptiness is spelled out instead of
    inferred from truthiness.
    """
    if val is None:
        return True
    if isinstance(val, str):
        return val.strip() == ""
    if isinstance(val, (list, tuple, dict)):
        return len(val) == 0
    return False            # False and 0 are values


def _form_bad(label, why):
    raise HTTPException(400, f"'{label}': {why}")


def _form_value(db, b, c, ctype, val, label):
    """One answer, checked against the field it is going to be written to.

    Returns the value to store. Raises 400 naming the question — never the
    column, the board or anything else behind it.
    """
    # ── text-shaped ──
    if ctype in ("text", "long_text", "title"):
        if not isinstance(val, (str, int, float)):
            _form_bad(label, "ערך טקסט לא תקין")
        v = str(val).strip()
        cap = FORM_LONG_TEXT_MAX if ctype == "long_text" else FORM_TEXT_MAX
        if len(v) > cap:
            _form_bad(label, f"הטקסט ארוך מדי (עד {cap} תווים)")
        return v
    if ctype == "email":
        v = str(val).strip()
        if not _FORM_EMAIL_RE.match(v) or len(v) > 254:
            _form_bad(label, "כתובת דוא\"ל לא תקינה")
        return v
    if ctype == "phone":
        v = str(val).strip()
        if not _FORM_PHONE_RE.match(v) or sum(ch.isdigit() for ch in v) < 6:
            _form_bad(label, "מספר טלפון לא תקין")
        return v

    # ── number ──
    if ctype in ("number", "rating"):
        if isinstance(val, bool):
            _form_bad(label, "נדרש מספר")
        try:
            n = float(val)
        except (TypeError, ValueError):
            _form_bad(label, "נדרש מספר")
        if n != n or n in (float("inf"), float("-inf")):
            _form_bad(label, "נדרש מספר")
        if ctype == "rating" and not (0 <= n <= 5):
            _form_bad(label, "דירוג בין 0 ל‎-5")
        return int(n) if float(n).is_integer() else n

    # ── boolean ──
    if ctype == "checkbox":
        if isinstance(val, bool):
            return val
        if str(val).lower() in ("true", "1", "yes", "on"):
            return True
        if str(val).lower() in ("false", "0", "no", "off", ""):
            return False
        _form_bad(label, "ערך כן/לא לא תקין")

    # ── date ──
    if ctype == "date":
        v = str(val).strip()
        try:
            day = datetime.fromisoformat(v.replace("Z", "+00:00"))
        except ValueError:
            _form_bad(label, "תאריך לא תקין")
        # the range the question itself carries, if it carries one
        st = c.settings or {}
        iso = day.date().isoformat()
        if st.get("min") and iso < str(st["min"]):
            _form_bad(label, f"התאריך מוקדם מ‎-{st['min']}")
        if st.get("max") and iso > str(st["max"]):
            _form_bad(label, f"התאריך מאוחר מ‎-{st['max']}")
        return iso

    # ── one of a list ──
    if ctype == "status":
        col = _form_col(b, c.field_key)
        if col is None:                        # the board's own status field
            keys = {x["key"] for x in _board_statuses(b)}
            if str(val) not in keys:
                _form_bad(label, "הערך אינו אחת האפשרויות")
            return str(val)
        # The same vocabulary the question was DRAWN from, default included —
        # a form that offers five words and then refuses all five is worse
        # than one that offers none.
        opts = _status_col_vocab(col)
        hit = next((o for o in opts
                    if (o["id"] is not None and str(o["id"]) == str(val))
                    or o["label"] == str(val)), None)
        if not hit:
            _form_bad(label, "הערך אינו אחת האפשרויות")
        # a status cell points at the option, so renaming it later carries
        # this answer with it — see the import, which learned the same thing
        return {"id": hit["id"], "label": hit["label"], "color": hit.get("color")}
    if ctype == "priority":
        keys = {x["key"] for x in _board_priorities(b)}
        if str(val) not in keys:
            _form_bad(label, "הערך אינו אחת האפשרויות")
        return str(val)

    # ── several of a list ──
    if ctype == "dropdown":
        col = _form_col(b, c.field_key)
        allowed = [str(o) for o in ((col or {}).get("options") or [])]
        # Refused separately from "does not exist": the form stopped offering
        # it, so an answer carrying it is a page opened before the option was
        # retired (or a hand-made request), and the respondent deserves to be
        # told which of the two it is.
        off = {str(o) for o in ((col or {}).get("inactive_options") or [])}
        vals = val if isinstance(val, list) else [val]
        out = []
        for v in vals:
            v = str(v)
            if v not in allowed:
                _form_bad(label, "אחת האפשרויות שנבחרו אינה קיימת")
            if v in off:
                _form_bad(label, "האפשרות שנבחרה אינה פעילה")
            if v not in out:
                out.append(v)
        return out

    # ── people ──
    # Only members of the board may be named on it — the same gate every
    # other door uses, and the reason a form never hands out the member list.
    if ctype in ("people", "assignees"):
        vals = val if isinstance(val, list) else [val]
        ids = []
        for v in vals:
            try:
                uid = int(v)
            except (TypeError, ValueError):
                _form_bad(label, "ערך אנשים לא תקין")
            if not _can_be_assigned(db, b.id, uid):
                _form_bad(label, "אחד האנשים שנבחרו אינו חבר בלוח")
            if uid not in ids:
                ids.append(uid)
        return ids

    # A column type a form has no way to collect. Reached only by a request
    # that made one up, since the projection never offered it.
    _form_bad(label, "סוג שדה שאינו נתמך בטופס")


def _form_col(b, key):
    return next((c for c in ((b.settings or {}).get("columns") or [])
                 if str(c.get("id")) == str(key)), None)


_FORM_BUILTIN_COL_TYPE = {"title": "title", "assignees": "assignees",
                          "status": "status", "priority": "priority",
                          "due_date": "date"}


def _form_thanks(f, replay=False):
    """What a respondent gets back: the screen the form was given, and
    nothing else. Not the item id — somebody who filled a form in has no
    business holding a reference to a row on a board they cannot see.

    A replay gets the same answer as the send it repeats. It IS that send:
    saying "already submitted" would be telling somebody their work did not
    land when it did.
    """
    return {"ok": True, "duplicate": bool(replay),
            "title": f.success_title or "",
            "message": f.success_message or "",
            "allow_another": bool(f.success_allow_another),
            "redirect_url": f.success_redirect_url}


def _form_col_type(b, key):
    """The type the FIELD declares — the board's word, never the client's."""
    if key in _FORM_BUILTIN_COL_TYPE:
        return _FORM_BUILTIN_COL_TYPE[key]
    return (_form_col(b, key) or {}).get("type")


def _form_column_uses(db, board_id, col_ids):
    """Which forms ask about these columns, and how badly they need them.

    A column is the board's, but a form's question is bound to one — so
    deleting a column is a change to every form that asks about it, and
    whoever is about to do it is entitled to know that before rather than
    after. Live forms only: a form in the bin asks nobody anything.
    """
    if not col_ids:
        return {}
    rows = (db.query(FormComponent, FormView, SavedView)
              .join(FormView, FormView.id == FormComponent.form_id)
              .join(SavedView, SavedView.id == FormView.view_id)
              .filter(FormComponent.board_id == board_id,
                      FormComponent.field_key.in_([str(c) for c in col_ids]),
                      SavedView.deleted_at.is_(None)).all())
    out = {}
    for c, f, v in rows:
        out.setdefault(str(c.field_key), []).append({
            "form_id": f.id, "name": v.name, "status": f.status,
            "label": c.label or "", "required": bool(c.required),
            "visible": c.visible is not False})
    return out


def _form_column_gone(db, board_id, col_ids, actor_id):
    """A column a form asked about is gone — leave the question, disable it.

    The decision taken when this was planned, and it is the one the saved
    views already take with a filter rule whose column was deleted: removing
    beats answering falsely. Deleting the question would throw away its
    wording, its help text and its place in the order, and leave the builder
    with no way to see what was lost. So the binding stays, and is DEAD:

      the respondent is never sent it      (_form_public_json)
      an answer to it is never read        (_form_validate)
      the builder sees it, flagged         (_form_json)
      a required one blocks publishing     (update_form_view)

    "ודא שלא נשאר מיפוי פעיל לשדה שאינו קיים" is those four together: the
    mapping is still written down, and there is no door at which it is live.
    """
    uses = _form_column_uses(db, board_id, col_ids)
    for key, forms in uses.items():
        for u in forms:
            fv = db.query(FormView).filter(FormView.id == u["form_id"]).first()
            v = db.query(SavedView).filter(SavedView.id == fv.view_id).first() if fv else None
            if v is not None:
                _log_view(db, v, "form_field_gone", field="column",
                          old=key, new=u["label"], actor=actor_id)
    return uses


# What a question's `settings` may still mean once its column is a different
# type. A date range on a text field is a rule nothing will ever apply, and
# leaving it is how a form grows settings that silently do nothing.
_FORM_SETTING_FOR_TYPE = {"date": ("min", "max")}


def _form_settings_resweep(db, board_id, changed):
    """Drop question settings a changed column can no longer carry."""
    if not changed:
        return 0
    rows = (db.query(FormComponent)
              .filter(FormComponent.board_id == board_id,
                      FormComponent.field_key.in_([str(c) for c in changed])).all())
    touched = 0
    for c in rows:
        keep = _FORM_SETTING_FOR_TYPE.get(changed[str(c.field_key)], ())
        now = {k: v for k, v in (c.settings or {}).items() if k in keep}
        if now != (c.settings or {}):
            c.settings = now
            touched += 1
    return touched


def _form_claim_files(db, f, val, label):
    """The upload tokens a respondent sent → the rows they are allowed to mean.

    Three things have to be true of every token, and the first is the one
    that matters: it was uploaded FOR THIS FORM. An attachment off a board
    carries no form id; an upload for a different form carries a different
    one; and a token already used by an earlier submission carries a claim.
    None of the three is a file this submission may point at, and changing an
    id in the request is exactly the attempt this refuses.

    Refused and not quietly dropped. A silent drop means somebody sends a
    form with a file on it and gets a record without one — and the only
    reading of a token that is not theirs is that something is wrong.

    Returns (cell, rows) — the value the board understands, and the rows to
    stamp once the record exists.
    """
    toks = [str(t) for t in (val if isinstance(val, list) else [val]) if t]
    if len(toks) > FORM_UPLOAD_PER_QUESTION:
        raise HTTPException(400, f"אפשר לצרף עד {FORM_UPLOAD_PER_QUESTION} קבצים "
                                 f"לשאלה '{label}'")
    cell, rows = [], []
    for t in toks:
        row = (db.query(UploadedFile)
                 .filter(UploadedFile.token == t,
                         UploadedFile.form_view_id == f.id,
                         UploadedFile.claimed_at.is_(None)).first())
        if not row:
            raise HTTPException(400, f"אחד הקבצים בשאלה '{label}' אינו זמין יותר — "
                                     f"העלו אותו שוב")
        rows.append(row)
        cell.append({"name": row.name, "url": f"/api/files/{row.token}",
                     "type": row.content_type})
    return cell, rows


def _form_idem_key(f, submission_id):
    """The key a replay of ONE send collides with, or None.

    `AutomationActionKey` is the system's existing once-only guard — a unique
    column, which is what makes it a rule rather than a read-then-write race —
    and a form submission is the same question it was built for: "did this
    exact attempt already happen?" Scoped to the form, so an id a client
    reuses across two forms is two different attempts.

    Optional on purpose. A caller that sends no id gets no protection, which
    is the honest description of what it asked for; the page always sends
    one.
    """
    sid = str(submission_id or "").strip()
    if not sid or len(sid) > 64:
        return None
    return f"form:{f.id}:{sid}"[:120]


def _form_errors_400(errors):
    """Every question that is wrong, keyed by the question — one answer.

    One at a time would mean a person fixing a form field by field, each time
    paying a round trip to be told about the next one. And keyed by id rather
    than spelled into a sentence, so the page can put each message beside the
    question it belongs to instead of printing a paragraph at the top.

    The message names the question's LABEL and nothing else. Never the
    column, never the board, never what the value was compared against —
    every one of those is something the asker is not entitled to learn by
    guessing at it.
    """
    raise HTTPException(400, {
        "message": "יש תשובות שצריך לתקן",
        "errors": errors,
    })


def _form_validate(db, f, b, answers, *, claim):
    """Check a whole submission and return what it would write.

    The one place that decides whether a submission is valid, used by the
    real thing and by the manager's dry run — so "test the validation without
    creating a record" is the SAME validation and not a second one that
    agrees with it today.

    `claim` is the only difference between the two callers: a dry run checks
    that the files are this form's and unclaimed, and does not take them.

    Returns (payload, cf, claimed). Raises 400 with every problem at once.
    """
    rows = (db.query(FormComponent)
              .filter(FormComponent.form_id == f.id, FormComponent.kind == "question")
              .order_by(FormComponent.position, FormComponent.id).all())
    allowed = _form_field_keys(b)

    # Every id in the request has to be a question OF THIS FORM. Not dropped
    # quietly: an id that is not here means the sender is holding a form that
    # has since changed, and telling them to reload is the only answer that
    # does not lose what they typed to a silence. The message says nothing
    # about what the id might have been.
    known = {str(c.id) for c in rows}
    if [k for k in answers if str(k) not in known]:
        raise HTTPException(400, "הטופס השתנה מאז שנפתח — רעננו את הדף ונסו שוב")

    errors, payload, cf, claimed = [], {}, {}, []

    def bad(c, msg):
        errors.append({"question_id": c.id, "label": c.label or "", "message": msg})

    for c in rows:
        # A hidden question is not asked, so an answer to it is not read —
        # whatever arrived under its id. The same rule the projection applies
        # on the way out, applied again on the way in, because the page that
        # drew the form is not the thing that enforces it.
        if c.visible is False:
            continue
        # A question whose column has since been deleted asks about nothing.
        if c.field_key not in allowed:
            continue
        label = c.label or c.field_key
        val = answers.get(str(c.id), answers.get(c.id))
        ctype = _form_col_type(b, c.field_key)
        if _form_empty(val):
            # A required checkbox means a box that has to be ticked — an
            # unticked one arrives as `false`, which is an answer and not a
            # blank, so it is refused by its own rule rather than by being
            # mistaken for nothing.
            if c.required:
                bad(c, "שדה חובה")
            continue
        try:
            if ctype == "files":
                cell, frows = _form_claim_files(db, f, val, label)
                if c.required and not cell:
                    bad(c, "שדה חובה")
                    continue
                cf[c.field_key] = cell
                claimed.extend(frows)
                continue
            value = _form_value(db, b, c, ctype, val, label)
        except HTTPException as exc:
            # Collected rather than thrown: the person filling the form is
            # owed every problem at once. Only a 400 — a 410 or a 429 from
            # underneath is about the form and not about this answer.
            if exc.status_code != 400:
                raise
            msg = exc.detail if isinstance(exc.detail, str) else "ערך לא תקין"
            # _form_value prefixes the label; the page puts it beside the
            # question, so the prefix would read it twice
            bad(c, msg.split("': ", 1)[-1] if msg.startswith("'") else msg)
            continue
        if c.required and ctype == "checkbox" and value is False:
            bad(c, "שדה חובה")
            continue
        if c.field_key == "title":
            payload["title"] = value[:500]
        elif c.field_key == "assignees":
            payload["assignee_ids"] = value
        elif c.field_key in ("status", "priority", "due_date"):
            payload[c.field_key] = value
        else:
            cf[c.field_key] = value
    if errors:
        _form_errors_400(errors)
    # The budget for the whole submission, not per file. Five files of ten
    # megabytes each is fifty megabytes on one record, which is nobody's
    # intention and everybody's disk.
    total = sum(r.size or 0 for r in claimed)
    if total > FORM_UPLOAD_TOTAL_BYTES:
        raise HTTPException(413, f"סך הקבצים בהגשה גדול מדי "
                                 f"(עד {FORM_UPLOAD_TOTAL_BYTES // (1024*1024)}MB)")
    return payload, cf, (claimed if claim else [])


def _form_submit(db, f, b, answers, user, request, submission_id=None):
    """One valid submission, one record. Never half of one.

    Everything is checked before anything is written — "הגשה תקינה יוצרת
    רשומה אחת, ללא רשומה חלקית" — and every failure comes back as one 400
    naming every question that is wrong, rather than one at a time.

    Answers are keyed by COMPONENT id. The respondent was never told a column
    id and does not need one; this is the only place that maps between them.
    """
    # A send that already happened. Checked before the work and claimed
    # inside the transaction below, so two requests racing each other end
    # with one record and one of them told it was the second.
    idem = _form_idem_key(f, submission_id)
    if idem and db.query(AutomationActionKey.id).filter(
            AutomationActionKey.key == idem).first():
        return _form_thanks(f, replay=True)
    if not _form_rate_ok(f.public_token, request):
        raise HTTPException(429, "נשלחו יותר מדי פניות מהכתובת הזאת. נסו שוב בעוד כמה דקות.")

    payload, cf, claimed = _form_validate(db, f, b, answers, claim=True)

    # A record has to be called something. A form that does not ask for the
    # item's name gets the form's own name — said here rather than left to
    # create_task's "Untitled", which is not a sentence anybody wants to read
    # on a board.
    title = payload.get("title") or (f.display_title or "").strip() \
        or (db.query(SavedView.name).filter(SavedView.id == f.view_id).scalar() or "פנייה")

    prio, prio_cf = _resolve_priority(b, payload.get("priority"))
    # "כאשר נדרש": an anonymous form records nobody, and a form that has been
    # told not to record the submitter records nobody either.
    actor = user.id if (user is not None and f.record_submitter is not False) else None

    task = Task(board_id=b.id, group_id=f.target_group_id, title=title,
                priority=prio or "medium", created_by=actor, form_view_id=f.id)
    if payload.get("due_date"):
        try:
            task.due_date = datetime.fromisoformat(
                str(payload["due_date"]).replace("Z", "+00:00"))
        except ValueError:
            pass
    if payload.get("status"):
        try:
            task.status = TaskStatus(payload["status"])
        except ValueError:
            pass

    # already checked against _can_be_assigned, one by one, with a refusal
    # rather than a silent drop — see _form_value
    ids = list(payload.get("assignee_ids") or [])
    if ids:
        task.assignees = db.query(User).filter(User.id.in_(ids)).all()
    _filter_people_values(db, b.id, cf, None, task)  # invited members only
    for col in ((b.settings or {}).get("columns") or []):
        if col.get("type") in ("mirror", "connect"):
            cf.pop(col["id"], None)     # not a cell a form writes
    if not payload.get("status"):
        cf.setdefault("status_unset", True)
    if not payload.get("priority"):
        cf.setdefault("priority_unset", True)
    elif prio_cf:
        for k, v in prio_cf.items():
            if v is not None:
                cf.setdefault(k, v)
    if cf:
        task.custom_fields = cf

    # include_deleted for the reason create_task gives: a number held by an
    # item in the bin is a number that can come back
    maxpos = (db.query(func.max(Task.position)).execution_options(include_deleted=True)
                .filter(Task.board_id == b.id, Task.parent_id == None,
                        Task.group_id == f.target_group_id).scalar())
    task.position = (maxpos + 1) if maxpos is not None else 0
    db.add(task)
    db.flush()
    _ensure_item_uid(db, task)
    # Who did this, when there is no account to name. The mechanism exists —
    # AuditLog.origin was built for an imported monday author — and its
    # presence is also what stops the row from offering an undo.
    db.add(AuditLog(entity_type="task", entity_id=task.id, action="create",
                    field_name="item", new_value=task.title, changed_by=actor,
                    origin={"source": "form", "form_view_id": f.id,
                            "authenticated": user is not None}))
    # Claimed now, in the transaction that creates the record — so a
    # submission that fails anywhere above leaves the files unclaimed and
    # re-sendable, and one that succeeds leaves them unusable by anybody else.
    now = datetime.now(timezone.utc)
    for row in claimed:
        row.claimed_at = now
    if idem:
        # In the same transaction as the record. The unique index is the
        # guard: two requests that got past the read above both try to write
        # it, one of them loses, and the loser's whole submission — record,
        # cells, file claims — goes with it.
        db.add(AutomationActionKey(key=idem, board_id=b.id,
                                   created_at=now.replace(tzinfo=None)))
    made = _event("item_created", "form")
    _run_automations(db, task, made, actor)
    tid = task.id
    try:
        db.commit()
    except IntegrityError:
        db.rollback()
        return _form_thanks(f, replay=True)
    bus.publish("task.created", board_id=b.id, task_id=tid, actor_id=actor)
    return _form_thanks(f)


# Where a published form lives. One constant, so the address the manager
# copies and the route that answers it cannot drift apart.
FORM_PUBLIC_PATH = "/forms/"


def _login_url(next_path):
    """Where to send somebody who has to sign in first, and come back here.

    Which door that is depends on how this deployment authenticates, and the
    server is the only one that knows: the form page is served to strangers
    and is told the address rather than working it out, so there is no second
    copy of the auth configuration living in a public page.

    The path is checked the same way entra._safe_next checks one — a `next`
    that is not a single-slash path on this site is an open redirect wearing
    our domain.
    """
    nxt = next_path if (next_path or "").startswith("/") \
        and not (next_path or "").startswith("//") else "/"
    mode = auth_mode()
    if mode == "entra":
        return "/auth/login?" + urllib.parse.urlencode({"next": nxt})
    if mode == "easyauth":
        # Azure's own sign-in, which the ingress terminates before anything
        # here runs. Its parameter name is not ours to choose.
        return "/.auth/login/aad?" + urllib.parse.urlencode({"post_login_redirect_uri": nxt})
    # dev: identity comes from a header the SPA's picker sets, and the picker
    # lives in the app — so the app is the door, and it is handed the same
    # `next` the other two get. Auth.login reads it and goes there once
    # somebody has been picked.
    return "/?" + urllib.parse.urlencode({"next": nxt})


def _public_form_or_refuse(db, token, request):
    """The form behind this token — or the refusal, in the right words.

    THE gate. Every public door goes through it, which is what makes the rule
    hold at submission time and not only when the page was opened: a
    respondent who had the form on screen when it was disabled gets here
    again when they press send, and is refused here again.

    The refusals are deliberately different from one another:

      404  no such token, or a form that has never been published. A draft
           has no public existence to report on, and saying "not yet" about
           one would confirm that a token somebody guessed is a real form.
      410  published once and not any more. Gone, and it was here — which is
           the honest thing to tell somebody holding a link that used to
           work, and the only case where saying so costs nothing.
      401  an AUTHENTICATED form reached without an identity.

    Returns (form, board, user) where user is None for a PUBLIC_LINK form
    nobody signed in for.
    """
    f = (db.query(FormView).filter(FormView.public_token == token).first()
         if token else None)
    if not f or not f.public_token:
        raise HTTPException(404, "הטופס לא נמצא")
    v = db.query(SavedView).filter(SavedView.id == f.view_id).first()
    b = db.query(Board).filter(Board.id == f.board_id).first()
    # A form whose view is in the bin, or whose board is, is as gone as a
    # closed one — and for the person holding the link it is the same event.
    if not v or v.deleted_at is not None or not b or b.deleted_at is not None:
        raise HTTPException(410, "הטופס נסגר ואינו מקבל פניות")
    if f.status == "DISABLED":
        raise HTTPException(410, "הטופס נסגר ואינו מקבל פניות")
    if f.status != "PUBLISHED":
        # back to a draft after having been published: it has an address and
        # nothing at that address
        raise HTTPException(404, "הטופס לא נמצא")

    user = None
    if f.access == "AUTHENTICATED":
        # By hand, because the middleware was told to let this path through.
        # resolve_user raises 401 with no identity and 403 for an account
        # this system does not know or has deactivated — both are the right
        # answer here, so neither is softened. What is ADDED to the 401 is
        # where to go: the page is a stranger's and has no way to know how
        # this deployment signs people in.
        try:
            user = resolve_user(db, request)
        except HTTPException as exc:
            if exc.status_code == 401:
                raise HTTPException(401, {
                    "message": "הטופס פתוח למשתמשים מחוברים בלבד",
                    "login_url": _login_url(FORM_PUBLIC_PATH + (token or ""))})
            raise
    elif f.access == "PUBLIC_LINK":
        # An identity is not required and is not refused either: somebody
        # signed in who opens a public link is still just somebody filling in
        # a form, and recording who they were is better than not.
        try:
            user = resolve_user(db, request)
        except HTTPException:
            user = None
    return f, b, user


@app.get("/api/public/forms/{token}/logo")
def public_form_logo(token: str, request: Request = None):
    """The form's own logo, for a page whose reader has no account.

    /api/files/{token} needs an identity, rightly — it serves every
    attachment on every board. This serves exactly one file, named by the
    form rather than by the caller, and only while the form is answering at
    all. There is nothing here to enumerate: the only thing a holder of the
    link can fetch is the picture already on the page they are looking at.
    """
    with Session(engine) as db:
        f, _b, _user = _public_form_or_refuse(db, token, request)
        if not f.logo_token or f.show_logo is False:
            raise HTTPException(404, "אין לוגו")
        row = (db.query(UploadedFile)
                 .filter(UploadedFile.token == f.logo_token).first())
        if not row:
            raise HTTPException(404, "אין לוגו")
        media_type, may_inline = _safe_media_type(row.content_type)
        if not may_inline or not media_type.startswith("image/"):
            # a logo is a picture. Anything else was not one when it was
            # uploaded and is certainly not one to serve inline here.
            raise HTTPException(404, "אין לוגו")
        # The only response under this prefix that is allowed to keep a cache
        # of its own: one picture, the same bytes for every reader of the
        # token, and it is on the page twice over. The middleware's blanket
        # `private, no-store` is a setdefault for exactly this.
        # It is still not unconditionally `public`. On an AUTHENTICATED form
        # getting this far took an identity — _public_form_or_refuse answers
        # 401 without one — so a shared copy would be a proxy handing the
        # logo to the stranger it had just refused. Members-only therefore
        # keeps the five minutes in the reader's own browser and gives up the
        # shared copy; a link anybody may open has nothing to give up.
        cache = ("public, max-age=300" if f.access == "PUBLIC_LINK"
                 else "private, max-age=300")
        return Response(content=row.data, media_type=media_type,
                        headers={"Content-Disposition": "inline",
                                 "X-Content-Type-Options": "nosniff",
                                 "Content-Security-Policy": "default-src 'none'; sandbox",
                                 "Cache-Control": cache})


@app.post("/api/public/forms/{token}/upload")
def public_form_upload(token: str, file: UploadFile = File(...), request: Request = None):
    """A file a respondent attached, held until they send the form.

    Deliberately narrow. The caller has no account, so the two things that
    normally bound an upload — who they are, and the board they are on — are
    both absent, and what is left has to do the work: the form must be open,
    the rate limit applies, the size is the system's own, and the type is an
    allowlist rather than a blocklist.

    What comes back is a token and the file's name. Not a URL: a respondent
    has no way to read the file back and no reason to.
    """
    with Session(engine) as db:
        f, _b, _user = _public_form_or_refuse(db, token, request)
        if not _form_rate_ok("up:" + (f.public_token or ""), request):
            raise HTTPException(429, "נשלחו יותר מדי קבצים מהכתובת הזאת. נסו שוב בעוד כמה דקות.")
        # A process that has been up for a month sweeps here rather than only
        # at boot. Bounded work: it touches the rows that are already past
        # the window and nothing else.
        try:
            _purge_unclaimed_form_uploads(db)
        except Exception:                              # noqa: BLE001
            pass
        content = file.file.read()
        if not content:
            raise HTTPException(400, "הקובץ ריק")
        if len(content) > FORM_UPLOAD_MAX_BYTES:
            raise HTTPException(413, f"הקובץ גדול מדי (עד {FORM_UPLOAD_MAX_BYTES // (1024*1024)}MB)")
        ctype = (file.content_type or "").split(";")[0].strip().lower()
        if ctype not in FORM_UPLOAD_TYPES:
            raise HTTPException(400, "סוג הקובץ אינו נתמך")
        tok = uuid.uuid4().hex
        # Stamped with the form it was uploaded FOR. This is the whole of
        # "אימות בצד השרת שהקובץ שהוגש שייך להקשר ההעלאה המותר": a submission
        # can only claim files carrying its own form's id, so a token lifted
        # off a board — or out of another form — names nothing it can use.
        db.add(UploadedFile(token=tok, name=_safe_filename(file.filename),
                            content_type=ctype, data=content, size=len(content),
                            form_view_id=f.id))
        db.commit()
        return {"token": tok, "name": _safe_filename(file.filename),
                "size": len(content), "type": ctype}


@app.get("/api/public/forms/{token}")
def public_form(token: str, request: Request = None):
    """The form, as the person filling it in is allowed to see it.

    Never the board id, the view id, the column ids, the group it lands in or
    who published it — see _form_public_json, which is the one place that
    decides what crosses this line.
    """
    with Session(engine) as db:
        f, b, user = _public_form_or_refuse(db, token, request)
        return _form_public_json(db, f, b, user.id if user else None)


@app.post("/api/public/forms/{token}/submit")
def public_form_submit(token: str, data: dict = None, request: Request = None):
    """A submission. The gate first, every time.

    The gate is re-run here rather than trusted from the GET, which is the
    whole of "בדיקת סטטוס וגישה מתבצעת גם בזמן ההגשה, ולא רק בפתיחת העמוד":
    between opening a form and sending it there is a person typing, and a
    form can be disabled, unpublished, deleted or switched to
    AUTHENTICATED inside that gap.
    """
    with Session(engine) as db:
        f, b, user = _public_form_or_refuse(db, token, request)
        data = data or {}
        answers = data.get("answers")
        if not isinstance(answers, dict):
            raise HTTPException(400, "חסרות תשובות")
        return _form_submit(db, f, b, answers, user, request,
                            submission_id=data.get("submission_id"))


@app.post("/api/forms/{form_id}/preview/submit")
def preview_form_submit(form_id: int, data: dict = None,
                        user_id: int = Depends(current_user_id)):
    """Fill the form in without filling anything in.

    The SAME validation the real thing runs — _form_validate, one function,
    so "test it in the preview" tests what will actually happen and not a
    second implementation that agrees with it today. The only difference is
    that nothing is written: no record, no cells, no file claims, no
    idempotency key.

    And it is a MANAGEMENT endpoint, not a public one. It is reached by the
    form's id and takes the rights of the editor who may open the builder —
    deliberately, because this is the one door that runs a submission's
    validation while the form is a draft, closed, or members-only. Hung off
    the public token it would be exactly the way around the gate that the
    gate exists to prevent.
    """
    with Session(engine) as db:
        f, _v, b, _role = _form_or_404(db, form_id, user_id)
        answers = (data or {}).get("answers")
        if not isinstance(answers, dict):
            raise HTTPException(400, "חסרות תשובות")
        # claim=False: the files are checked for being this form's and
        # unclaimed, and are left exactly as they were.
        _payload, _cf, _claimed = _form_validate(db, f, b, answers, claim=False)
        # Nothing was written, and nothing is about to be — the session is
        # read-only by construction here and is rolled back on the way out.
        db.rollback()
        return dict(_form_thanks(f), preview=True)


@app.get("/api/forms/{form_id}/preview")
def preview_form_view(form_id: int, user_id: int = Depends(current_user_id)):
    """The respondent's view of the form, for the person building it.

    Byte for byte what the public route will serve TO THIS SAME READER, so
    "תצוגה מקדימה" shows the form rather than an approximation of it — and so
    a leak is visible here, in a test, instead of on an endpoint with no
    identity behind it.

    That qualification is new and it is the whole of the sentence now: one
    thing in the body depends on who is asking, the options of an אחראים
    question, and the builder is a board member while the stranger on the
    link is not. So the preview shows a member's copy of the form, which is
    the copy its reader would get — not the stranger's. Everything else here
    is the same bytes for everybody, and _form_public_json is still the one
    place that decides either way.
    """
    with Session(engine) as db:
        f, _v, b, _role = _form_or_404(db, form_id, user_id)
        return _form_public_json(db, f, b, user_id)


def _cell_search_words(v):
    """Every word a cell holds, flattened — the raw reading, before the column
    says what kind of thing it is.

    A cell is a JSON value whose shape depends on the column: a string for
    text, a list of strings for a multi-select, {id,label,color} for a status
    written by a form or by the monday import, {from,to} for a timeline. All
    of them are things somebody typed into the board and can therefore expect
    to find again, so this is deliberately generous about shape and narrow
    about keys — an option's id and a colour are not words anybody searches
    for, and matching them would answer a search for "e2" with a third of the
    board.

    A bool is absent on purpose and not by oversight: "true" is the stored
    value of a ticked box and never the word anybody typed. What a checkbox
    DOES answer to is in _searchable_words, where the column says so.
    """
    if isinstance(v, bool) or v is None or v == "" or v == [] or v == {}:
        return []
    if isinstance(v, str):
        return [v]
    if isinstance(v, (int, float)):
        return [str(v)]
    if isinstance(v, list):
        out = []
        for x in v:
            out.extend(_cell_search_words(x))
        return out
    if isinstance(v, dict):
        return [x for x in (v.get("label"), v.get("text"), v.get("name"),
                            v.get("value"), v.get("address"), v.get("url"),
                            v.get("from"), v.get("to"))
                if isinstance(x, str) and x]
    return []


# A ticked box, in the word the board shows for it. Its own constant because
# the browser has to say the same word — see the frontend's TICK_WORD.
TICK_WORD = "מסומן"


def _searchable_words(ctype, v, names, vocab=None):
    """How one cell reads to somebody searching, given the kind of column it
    is — (substring words, whole words).

    Most cells read as what they store and come back in the first list, which
    is matched the way a search box is expected to match: anywhere inside.
    Four kinds do not read as what they store, and each one was a value
    sitting in plain sight on the board that the search box could not find:

      · PEOPLE stores user ids. Nobody searches "7"; they search "רות לוי".
        The ids are REPLACED by the names rather than added to them — an id
        left in the haystack is a row answering a search for a digit.
      · a DATE stores 2026-11-04 and the board shows 04/11/2026. Both are
        kept: the first is what somebody pastes out of a system, the second
        is what they read off the screen and retype.
      · a STATUS cell holds the option's LABEL when the grid wrote it and the
        option's stable id when a form or the monday import did. The label is
        the word; the id is resolved to it rather than matched raw.
      · a CHECKBOX has no content at all. It answers to the word the board
        shows for a tick — but as a WHOLE word, which is the second list and
        the only place in this search that is not a substring match. The
        reason is specific rather than fastidious: every other word in the
        haystack is something a person typed into one row, so over-matching it
        costs a few rows. "מסומן" is a word this system invents for every
        ticked row on the board, so matching it on "מס" — a prefix of מסמך,
        מספר, מסירה — would answer an ordinary search with half the board.
    """
    words = _cell_search_words(v)
    if ctype == "checkbox":
        return [], ([TICK_WORD] if (v is True or v == 1 or
                                    (isinstance(v, list) and len(v))) else [])
    if ctype in ("people", "created_by", "assignees"):
        out = []
        for w in words:
            try:
                out.append(names.get(int(w)) or "")
            except (TypeError, ValueError):
                out.append(w)          # a name already, from an older cell
        return [x for x in out if x], []
    if ctype in ("date", "timeline", "created_at", "due"):
        return words + [_fmt_day(str(w)[:10]) for w in words], []
    if vocab:
        return words + [vocab[w] for w in words if w in vocab], []
    return words, []


def _linked_title_hits(db, tasks, cols, needle, viewer):
    """Which of `tasks` are linked to an item whose title contains `needle`.

    An item is findable by what it is linked to and not only by its own words —
    the browser has always searched connect cells that way, off the titles it
    already holds in its link cache. Past the client threshold the browser
    holds no such thing and the server is the one answering, so without this
    the same search quietly stops working at exactly the board size where it
    matters.

    Three queries however large the board, rather than one per cell: the
    relationships in one, the titles that match in one more, and the viewer's
    access to the handful that matched in the last. Seeing a link is not
    permission to read what it points at, so the titles that matched are put
    through the same gate every other door into a linked item uses.
    """
    conn = [c for c in (cols or []) if c.get("type") == "connect"]
    if not conn or not tasks or not needle:
        return set()
    far_of = {}                                    # this board's item -> far ids
    one_way = [str(c.get("id")) for c in conn if not _is_two_way(c)]
    for t in tasks:
        cf = t.custom_fields or {}
        got = [i for cid in one_way for i in (cf.get(cid) or []) if isinstance(i, int)]
        if got:
            far_of.setdefault(t.id, set()).update(got)
    if any(_is_two_way(c) for c in conn):
        two = {str(c.get("id")) for c in conn if _is_two_way(c)}
        ids = [t.id for t in tasks]
        for part in [ids[i:i + _PREFETCH_CHUNK] for i in range(0, len(ids), _PREFETCH_CHUNK)]:
            for l in db.query(ItemLink).filter(or_(ItemLink.a_task_id.in_(part),
                                                   ItemLink.b_task_id.in_(part))).all():
                if l.a_col in two:
                    far_of.setdefault(l.a_task_id, set()).add(l.b_task_id)
                if l.b_col in two:
                    far_of.setdefault(l.b_task_id, set()).add(l.a_task_id)
    far = sorted({i for v in far_of.values() for i in v})
    if not far:
        return set()
    # LIKE's own wildcards, escaped: a search for "50%" is a search for the
    # characters, not for "anything after 50".
    pat = "%" + needle.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_") + "%"
    hit = set()
    for part in [far[i:i + _PREFETCH_CHUNK] for i in range(0, len(far), _PREFETCH_CHUNK)]:
        hit.update(r[0] for r in db.query(Task.id).filter(
            Task.id.in_(part), func.lower(Task.title).like(pat, escape="\\")).all())
    if not hit:
        return set()
    hit = set(_visible_link_ids(db, sorted(hit), viewer))
    return {tid for tid, v in far_of.items() if v & hit} if hit else set()


# ═══ דשבורדים ════════════════════════════════════════════════════════
# A dashboard is a set of measures read off boards. Everything below is the
# settings half — who may open one, what it points at, and the permission
# closure that decides whether a widget may be computed at all. Nothing here
# computes anything: "תוצאות מחושבות אינן מקור אמת", and the calculation is
# DASH-09's.
#
# ── the view kind, and why it is not "dashboard" ──
# `SavedView.kind` is a namespace of its own — main | saved | form — and
# `ALL_VIEWS` is a different one, which has held an entry called "dashboard"
# since long before this: the fixed, unconfigurable screen `/api/dashboard`
# feeds, which sums every board the reader can see and ignores the board it
# is a tab on. That screen is enabled on every board that never turned it
# off, so taking its name would change what those boards already show.
# "dash" is therefore the kind here, and the two namespaces go on meaning
# different things without sharing a word.
DASH_VIEW_KIND = "dash"
NEW_DASHBOARD_NAME = "דשבורד חדש"
# R02 — "דשבורד עצמאי: עד 10 לוחות" — and R10's ceiling on widgets. Enforced
# at the write, because a stored configuration past the limit is one the
# calculation would have to refuse later, in front of a reader who cannot fix
# it. The refusal says what to do about it; it never trims the request.
DASHBOARD_MAX_BOARDS = 10
DASHBOARD_MAX_WIDGETS = 20
# How deep the indirect-source walk goes. A mirror reads through a connect,
# and a formula can name a mirror, so the closure is genuinely recursive —
# and a configuration that points at itself must not be able to hang a
# request. Four is past anything a person builds and far short of a loop.
_DASH_SOURCE_DEPTH = 4


def _dash_for_view(db, view_id):
    """The dashboard hanging off this view row, if it is a dashboard tab."""
    return (db.query(Dashboard)
              .filter(Dashboard.view_id == view_id,
                      Dashboard.deleted_at.is_(None)).first())


def _is_dash_view(v):
    """Is this view row a dashboard? The question the cut endpoints must ask.

    A dashboard shares the table with the saved cuts because it IS a view of
    the board — same strip, same name rule, same bin — and shares nothing
    else. Writing a cut's `filters` onto one would produce a dashboard whose
    widgets answer to a condition tree nobody attached to them.
    """
    return (v.kind or "saved") == DASH_VIEW_KIND


def _dash_name(db, d, view=None):
    """What this dashboard is called.

    A board dashboard's name is its tab's, and is NOT copied here: two places
    holding one name is two places that can disagree about it, and the strip
    is the one people rename through.
    """
    if d.kind == "board":
        v = view or db.query(SavedView).filter(SavedView.id == d.view_id).first()
        return v.name if v else ""
    return d.name or ""


# ── מי רשאי לפתוח ולנהל ──────────────────────────────────────────────

def _dash_access(db, d, user_id):
    """This person's standing on this dashboard: "owner", "viewer" or None.

    R01, in one function:

      · עצמאי — the creator and the owners they named manage it. "ראשי"
        opens to anyone who may reach its workspace; "פרטי" opens to the
        people invited and to nobody else.
      · תצוגת לוח — "צפייה וניהול לפי הרשאות התצוגות הקיימות בלוח", so the
        board's own roles answer it and no new role is invented (DASH-03.2).
        A locked tab narrows writing to the board's owner, exactly as it does
        for a cut — the lock is a property of the tab, not of this feature.

    **None of this is permission to read data.** "בעלות או הזמנה אינן
    מעניקות הרשאות לנתוני מקור" — every figure and every drill-down row is
    gated again, per board, per column and per item, by _widget_blocked and
    by the ordinary item rules. This answers one question: may they open it.
    """
    if user_id is None or d is None:
        return None
    if d.kind == "board":
        v = db.query(SavedView).filter(SavedView.id == d.view_id).first()
        if v is None or v.deleted_at is not None:
            return None
        # The board itself, before its role. _board_role answers from the
        # membership row and does not look at the board — every caller checks
        # it separately, which is what get_board does before it asks — so a
        # board in the recycle bin would otherwise go on opening its dashboard
        # to everyone who was ever invited to it.
        b = db.query(Board).filter(Board.id == d.board_id).first()
        if b is None or b.deleted_at is not None:
            return None
        role = _board_role(db, d.board_id, user_id)
        if role is None:
            return None
        if _may_edit_view(v, user_id, role) and (not v.locked or _may_write_locked(role)):
            return "owner"
        return "viewer"
    # ── standalone ──
    if d.created_by is not None and d.created_by == user_id:
        return "owner"
    # A workspace administrator manages every dashboard, and is asked BEFORE
    # the membership row — the same ordering _board_role settled on, and for
    # the same reason: being invited to something as a viewer must not take
    # away what being an administrator already granted.
    if _ws_role(db, user_id) == "admin":
        return "owner"
    m = (db.query(DashboardMember)
           .filter(DashboardMember.dashboard_id == d.id,
                   DashboardMember.user_id == user_id).first())
    if m is not None and m.role == "owner":
        return "owner"
    if (d.visibility or "main") == "main":
        # "ראשי נגיש למורשי סביבת העבודה" — the environment's own membership,
        # which is what "מורשי סביבת העבודה" names. An explicit invitation
        # still counts, below, for somebody outside it.
        if _env_role(db, d.environment_id, user_id) is not None:
            return "viewer"
    return "viewer" if m is not None else None


def _dash_or_404(db, dash_id, user_id, *, manage=False):
    """The dashboard, if this person may reach it. 404 / 403 otherwise.

    404 before 403 on a dashboard nobody may see, deliberately: "there is no
    such dashboard" and "there is one and it is not yours" are different
    disclosures, and only the first is safe to give somebody guessing ids.
    A dashboard they may VIEW answers 403 to a write, because they already
    know it exists.
    """
    d = (db.query(Dashboard)
           .filter(Dashboard.id == dash_id, Dashboard.deleted_at.is_(None)).first())
    if d is None:
        raise HTTPException(404, "הדשבורד אינו קיים")
    access = _dash_access(db, d, user_id)
    if access is None:
        raise HTTPException(404, "הדשבורד אינו קיים")
    if manage and access != "owner":
        raise HTTPException(403, "רק מורשה עריכה יכול לשנות את הדשבורד")
    return d, access


# ── מקורות ───────────────────────────────────────────────────────────

def _dash_sources(raw, *, limit=DASHBOARD_MAX_BOARDS):
    """Normalise the source list: [{board_id, groups}, …], ids de-duplicated.

    `groups` is None — not the list of ids that happen to exist today — when
    every group is wanted. R02 says the choice includes "קבוצות עתידיות", and
    a list frozen at save time would quietly stop including them the first
    time somebody added one.
    """
    out, seen = [], set()
    for s in (raw or []):
        if not isinstance(s, dict):
            continue
        try:
            bid = int(s.get("board_id"))
        except (TypeError, ValueError):
            continue
        if bid in seen:
            continue
        seen.add(bid)
        g = s.get("groups")
        if g is None:
            groups = None
        else:
            groups = sorted({int(x) for x in g if str(x).lstrip("-").isdigit()})
        out.append({"board_id": bid, "groups": groups})
    if len(out) > limit:
        raise HTTPException(400, f"דשבורד עצמאי יכול לכלול עד {limit} לוחות")
    return out


def _widget_sources(d, w):
    """The boards this widget reads.

    A widget names a SUBSET of the dashboard's sources — "לכל ווידג׳ט
    תת־קבוצה מהם" (R02) — and an empty list means all of them, so adding a
    board to the dashboard does not require rewriting every widget. A board
    the widget names and the dashboard no longer has is dropped: the
    dashboard's list is the authority on what this dashboard may read.
    """
    base = {s["board_id"]: s for s in _dash_sources(d.sources, limit=10 ** 6)}
    own = _dash_sources(w.sources, limit=10 ** 6)
    if not own:
        return list(base.values())
    out = []
    for s in own:
        b = base.get(s["board_id"])
        if b is None:
            continue
        # The widget may narrow the groups; it may never widen past what the
        # dashboard allows, so "all groups" on the widget still means the
        # dashboard's choice for that board.
        out.append({"board_id": s["board_id"],
                    "groups": s["groups"] if s["groups"] is not None else b["groups"]})
    return out


_DASH_FORMULA_REF = re.compile(r"\{([^{}]*)\}")


def _dash_cols(db, board_id):
    """This board's columns, asked once per request.

    The closure walk reads the column list for every column it expands, and
    `_board_columns` goes to the database each time — so a dashboard of
    twenty widgets over ten boards asked the same handful of questions some
    hundreds of times per read. Cached on the session, the same place
    `_col_plan` and `_prefetch_links` keep theirs, and for the same reason:
    the answer cannot change inside one request.
    """
    cache = db.info.setdefault("_dash_cols", {})
    if board_id not in cache:
        cache[board_id] = _board_columns(db, board_id)
    return cache[board_id]


def _formula_refs(col, cols):
    """Which columns a formula column names, as ids.

    The formula text references a column by TITLE — "{שעות בפועל}" — because
    that is what somebody types. Resolving those titles to ids is all that
    happens here: this is the permission closure, not the calculator, and it
    must answer "what does this read" for a formula the server cannot yet
    evaluate at all (see DASH-01A in docs/DASHBOARDS_PLAN.md).

    A title that matches nothing is simply not returned. It makes the formula
    broken, which is a needs_fix and not a disclosure — and a broken formula
    reads no data, so it cannot be a way around a permission.
    """
    src = (col or {}).get("formula") or ""
    if not src:
        return set()
    by_title = {}
    for c in cols:
        t = (c.get("title") or "").strip()
        if t and c.get("id") != col.get("id"):
            by_title.setdefault(t, c["id"])
    return {by_title[m.strip()] for m in _DASH_FORMULA_REF.findall(src)
            if m.strip() in by_title}


def _widget_field_keys(d, w):
    """Every field key this widget's configuration names.

    Four places can name one, and all four have to be in the closure or a
    widget could read a column through a door nobody checked: the measures,
    the dashboard's filter, the widget's own filter, and a chart's dimension
    and split.
    """
    keys = set()
    for m in (w.metrics or []):
        if isinstance(m, dict) and m.get("field"):
            keys.add(str(m["field"]))
    for tree in (d.filters, w.filters):
        keys |= _filter_field_keys(tree)
    ch = w.chart or {}
    for k in ("dimension", "split"):
        if isinstance(ch, dict) and ch.get(k):
            keys.add(str(ch[k]))
    return keys


def _filter_field_keys(tree):
    """The field ids a condition tree asks about, at any depth."""
    out = set()

    def walk(n, depth=0):
        if not isinstance(n, dict) or depth > filter_ast.MAX_DEPTH:
            return
        if n.get("type") == "group" or "rules" in n:
            for kid in (n.get("rules") or []):
                walk(kid, depth + 1)
            return
        if n.get("field"):
            out.add(str(n["field"]))

    walk((tree or {}).get("adv") if isinstance(tree, dict) else None)
    return out


# Built-in fields need no mapping: every board has a title, a status, a
# priority, assignees and a due date, and they are gated by the board role
# rather than by a column permission.
_DASH_BUILTIN_FIELDS = {"title", "status", "priority", "assignees", "due"}


def _widget_required(db, d, w):
    """Every board and column this widget reads — directly and indirectly.

    This is the whole of DASH-04.1. A mirror holds no data of its own: it
    reads a field of a LINKED item, through a connect column, on another
    board. A formula reads other columns, which may themselves be mirrors. So
    "what does this widget read" is a closure and not a list, and computing a
    widget without walking it is how a reader is shown a total drawn from a
    board they were refused.

    **The contract this closure imposes on the calculation.** A mirror's
    reachable boards are taken from the connect column's DECLARED
    `board_ids`, not from the link rows that happen to exist — the two can
    differ, because narrowing a connect column's targets does not delete the
    links already made through it. That makes this list authoritative rather
    than descriptive: whatever computes a widget (DASH-09) must read records
    only from the boards named here, or it will read past the set that was
    checked. Reading the links instead would cost a query per widget per
    read and would still have to be bounded by something; the declaration is
    that something, and it is the same list the write path already enforces
    when a link is created.

    Returns (boards, cols, unmapped):
      boards   — board ids whose data is read
      cols     — (board_id, column_id) pairs whose values are read
      unmapped — field keys with no mapping on some source board, which makes
                 the configuration broken rather than forbidden
    """
    boards, cols, unmapped = set(), set(), set()
    srcs = _widget_sources(d, w)
    mapping = w.mapping or {}
    # A list widget shows columns directly rather than through a mapping, and
    # they are read exactly as a measure's are — so they are required sources
    # too. R01 makes no exception for a column somebody is only LOOKING at:
    # a list missing a column the viewer may not see is a partial answer, and
    # the rule is that the whole widget goes dark instead.
    if w is not None and w.type == "list":
        for bid, cid in _dash_list_columns(db, d, w):
            boards.add(bid)
            cols.add((bid, str(cid)))
    for s in srcs:
        bid = s["board_id"]
        boards.add(bid)
        m = mapping.get(str(bid)) or mapping.get(bid) or {}
        for key in _widget_field_keys(d, w):
            if key in _DASH_BUILTIN_FIELDS:
                continue
            cid = m.get(key)
            if not cid:
                unmapped.add(key)
                continue
            cols.add((bid, str(cid)))

    # ── the walk ──
    # Each round expands the columns found so far into the columns and boards
    # they read through. It stops when a round adds nothing, which is the
    # normal case after one or two, and at the depth cap, which only a
    # configuration pointing at itself can reach.
    seen = set()
    for _ in range(_DASH_SOURCE_DEPTH):
        fresh = cols - seen
        if not fresh:
            break
        seen |= fresh
        for bid, cid in fresh:
            bcols = _dash_cols(db, bid)
            col = next((c for c in bcols if str(c.get("id")) == cid), None)
            if col is None:
                continue
            ctype = col.get("type")
            if ctype == "formula":
                for ref in _formula_refs(col, bcols):
                    cols.add((bid, str(ref)))
            elif ctype == "mirror":
                cfg = _mirror_cfg(col)
                conn_id, field = cfg.get("connect"), cfg.get("field")
                if not conn_id or not field:
                    continue
                # The connect column is read to find the linked items at all,
                # so it is a required source in its own right.
                cols.add((bid, str(conn_id)))
                conn = next((c for c in bcols if str(c.get("id")) == str(conn_id)
                             and c.get("type") == "connect"), None)
                if conn is None:
                    continue
                for tb in (_connect_cfg(conn).get("board_ids") or []):
                    try:
                        tb = int(tb)
                    except (TypeError, ValueError):
                        continue
                    boards.add(tb)
                    # A builtin mirror field (title, status, …) is gated by
                    # the target board's role, which `boards` already carries.
                    if str(field) not in _MIRROR_BUILTINS:
                        cols.add((tb, str(field)))
    return boards, cols, unmapped


def _widget_state(db, d, w, user_id, *, visible=None):
    """"ok", "blocked" or "needs_fix" for this reader — never a number.

    R01: "אם לצופה חסרה הרשאה למקור נדרש, לרבות מקור מאחורי מראה או נוסחה,
    כל הווידג׳ט ייחסם." The whole widget, not the part they may see: a sum
    over four boards with one refused is not three-quarters of an answer, it
    is a wrong number that looks like a right one.

    "blocked" wins over "needs_fix". A configuration can be both broken and
    forbidden, and saying which would tell somebody something about a board
    they may not open.
    """
    vis = _visible_board_ids(db, user_id) if visible is None else visible
    boards, cols, unmapped = _widget_required(db, d, w)
    if not boards:
        return "needs_fix"
    if any(b not in vis for b in boards):
        return "blocked"
    roles = {b: _board_role(db, b, user_id) for b in boards}
    if any(r is None for r in roles.values()):
        return "blocked"
    missing = False
    for bid, cid in cols:
        col = next((c for c in _dash_cols(db, bid) if str(c.get("id")) == cid), None)
        if col is None:
            # The column was deleted. "מחיקת עמודה … אינם יוצרים מיפוי חלופי
            # ואינם מומרים לאפס" (R09) — it needs fixing, and it is not a
            # permission problem.
            missing = True
            continue
        if _col_perm(col, user_id, roles.get(bid)) == "none":
            return "blocked"
    return "needs_fix" if (missing or unmapped) else "ok"



# ── קבוצות מקור ──────────────────────────────────────────────────────

def _dash_check_groups(db, srcs):
    """Every group named belongs to the board that names it.

    R02 lets a source take "כל הקבוצות כברירת מחדל, כולל קבוצות עתידיות, או
    קבוצות מסוימות לפי מזהים". The first is a null and the second is a list,
    and the list is checked here because a group id from another board is a
    configuration that silently measures nothing — the records it names are
    never in the population, so the widget answers 0 and looks correct.

    An EMPTY list is refused rather than stored. "no groups" can only ever
    produce an empty population, and a widget that can never match is not a
    measure anybody meant to save.
    """
    for s in srcs:
        if s["groups"] is None:
            continue
        if not s["groups"]:
            raise HTTPException(400, "בחירת קבוצות ריקה — בחר קבוצות או בחר בכל הקבוצות")
        have = {g.id for g in db.query(Group).filter(Group.board_id == s["board_id"]).all()}
        stray = [g for g in s["groups"] if g not in have]
        if stray:
            raise HTTPException(400, "אחת הקבוצות שנבחרו אינה שייכת ללוח שנבחר")
    return srcs


# ── מיפוי עמודות ─────────────────────────────────────────────────────
# "המקורות המספריים המותרים הם מספר, נוסחה מספרית ומראה מספרית" — DASH-07.2.
_DASH_NUMERIC_TYPES = ("number", "formula", "mirror")
# The calculations that need one. A count needs no column at all: it counts
# records, and a record is not a value in a column.
_DASH_VALUE_CALCS = ("sum", "avg")


def _dash_col_unit(col):
    """The unit a column declares, or None when it declares none.

    Only a number column carries one (`_number_col_cfg`). A formula declares
    no unit — it is an expression, and what comes out of it is whatever the
    columns it reads were — and a mirror's unit belongs to the column it
    mirrors, on another board, which the cell does not currently carry
    (DASH-01B in docs/DASHBOARDS_PLAN.md). Both answer None here, which the
    comparison below reads as "nothing to disagree with" rather than as a
    unit of its own. Overstating what we know would block a legitimate save;
    this understates it, and the gap is written down.
    """
    if (col or {}).get("type") != "number":
        return None
    cfg = _number_col_cfg(col.get("number")) or {}
    return (cfg.get("unit") or "") or None


def _dash_propose_mapping(db, sources, reference, fields):
    """Suggest a column on every board for each field, by name and type.

    DASH-07.1 — "הצעת התאמת עמודות לפי שם וסוג מחייבת אישור או תיקון לפני
    שימוש." So this is a suggestion and NOTHING here is stored: the endpoint
    that calls it writes no mapping, and the mapping that is eventually saved
    is the one somebody sent back.

    Each proposal says WHY it was made, because "the titles match and so do
    the types" and "nothing matched, here is the only numeric column on that
    board" are different degrees of confidence and the person approving them
    deserves to be able to tell which is which.
    """
    ref_cols = {c["id"]: c for c in _dash_cols(db, reference)}
    out = {}
    for s in sources:
        bid = s["board_id"]
        if bid == reference:
            continue
        cols = _dash_cols(db, bid)
        per = {}
        for key, ref_id in (fields or {}).items():
            ref = ref_cols.get(str(ref_id))
            if ref is None:
                per[key] = {"column_id": None, "match": "no_reference", "candidates": []}
                continue
            title = (ref.get("title") or "").strip()
            same_type = [c for c in cols if c.get("type") == ref.get("type")]
            exact = next((c for c in same_type
                          if (c.get("title") or "").strip() == title), None)
            # Same name, same type — the only match this proposes with
            # confidence. Everything else is offered as a candidate and left
            # to a person.
            chosen, why = (exact, "name_and_type") if exact else (None, "none")
            per[key] = {
                "column_id": chosen["id"] if chosen else None,
                "title": chosen.get("title") if chosen else None,
                "unit": _dash_col_unit(chosen) if chosen else None,
                "match": why,
                "candidates": [{"column_id": c["id"], "title": c.get("title") or "",
                                "type": c.get("type"), "unit": _dash_col_unit(c)}
                               for c in same_type],
            }
        out[str(bid)] = per
    return out


def _dash_validate_mapping(db, sources, mapping, metrics):
    """Refuse a widget whose measures cannot be computed from its sources.

    DASH-07.3 — "מיפוי חסר או יחידות שאינן תואמות יחסמו שמירה, עם הודעה
    שמסבירה מה לתקן." Refused at the SAVE and not at the calculation,
    because the person who can fix it is the one saving it; discovered later,
    it is a broken widget in front of a reader who did not build it.

    Three things are checked, and each names what to do about it:
      · a measure with no column on some source board
      · a column that cannot hold a number, for a sum or an average
      · two boards answering one measure in different units

    "אין המרת מטבע אוטומטית" (R05) — mismatched units are refused, never
    converted. A sum of shekels and hours is not a number with a problem, it
    is not a number.
    """
    for m in (metrics or []):
        if not isinstance(m, dict):
            raise HTTPException(400, "הגדרת מדד לא תקינה")
        calc = m.get("calc") or "count"
        if calc not in ("count",) + _DASH_VALUE_CALCS:
            raise HTTPException(400, "פעולת חישוב לא נתמכת — ספירה, סכום או ממוצע")
        if calc not in _DASH_VALUE_CALCS:
            _dash_metric_format(m, m.get("title") or m.get("key") or "")
            # Counting records needs no column at all — a record is not a
            # value in one. "ספירת רשומות אינה מושפעת מריק בעמודה אלא אם
            # קיים מסנן שמחריג אותו": the way to count only the records that
            # have a value is a condition, not a mapping, so requiring one
            # here would refuse a configuration that is perfectly good.
            continue
        key = str(m.get("field") or "")
        if not key:
            raise HTTPException(400, "למדד חסר שדה מקור")
        if key in _DASH_BUILTIN_FIELDS:
            continue
        label = m.get("title") or key
        units = {}
        for s in sources:
            bid = s["board_id"]
            cid = (mapping.get(str(bid)) or {}).get(key)
            if not cid:
                raise HTTPException(
                    400, f'למדד "{label}" אין עמודה מתאימה באחד הלוחות — '
                         "אשר מיפוי לכל לוח מקור לפני השמירה")
            col = next((c for c in _dash_cols(db, bid) if str(c.get("id")) == str(cid)), None)
            if col is None:
                raise HTTPException(
                    400, f'למדד "{label}" ממופה עמודה שאינה קיימת עוד באחד הלוחות — '
                         "בחר עמודה אחרת")
            if calc in _DASH_VALUE_CALCS and col.get("type") not in _DASH_NUMERIC_TYPES:
                raise HTTPException(
                    400, f'למדד "{label}" נבחרה עמודה שאינה מספרית — '
                         "סכום וממוצע נתמכים במספר, בנוסחה מספרית ובמראה מספרית")
            u = _dash_col_unit(col)
            if u is not None:
                units[bid] = u
        _dash_metric_format(m, label)
        if len(set(units.values())) > 1:
            raise HTTPException(
                400, f'למדד "{label}" יחידות שונות בלוחות המקור — '
                     "אין המרה אוטומטית; בחר עמודות באותה יחידה")


# ── אוכלוסיית הרשומות ────────────────────────────────────────────────

def _dash_population(db, d, w, user_id):
    """Every record this widget measures, once each.

    R02 and DASH-08 in one pass, and every clause of them is a line here:

      · פריטים / תתי־פריטים / שניהם, with items the default.
      · "מזהה רשומה נספר פעם אחת גם אם מקושר מכמה מקומות" — `seen` is by id,
        so a record reachable twice is still one record.
      · "שני פריטים בשם זהה נספרים בנפרד" — nothing here looks at a title.
        Two items called the same thing are two items, and de-duplicating by
        name would quietly delete one of them from every total.
      · "מחוקים ובארכיון מוחרגים" — deleted records are already invisible to
        every query in this application (_hide_deleted_tasks), and archived
        ones are filtered here because that one is NOT automatic.
      · "פריט שהועבר נספר במיקומו הנוכחי בלבד" — a move rewrites `board_id`
        on the item and its sub-items, so there is one row in one place and
        nothing to de-duplicate across boards.
      · "אב וילדים הם רשומות עצמאיות, ללא ירושת ערכים" — rows come back as
        themselves. Nothing copies a parent's value onto a child or a child's
        onto a parent, which is what makes "both" a union of two populations
        rather than a double count of one.

    **The roll-up exclusion, and why there is no code for it.** R02 asks for
    a calculated roll-up of the same children appearing on the parent to be
    left out of the double count, "לפי מקור הערך, לא לפי דמיון במספרים".
    This system has no roll-up: nothing derives a parent's value from its
    children — not a column type, not `copy_mode`, and not a formula, which
    is evaluated per item and cannot reach a sub-item. So a value on a parent
    is always the parent's own and there is nothing to exclude. Detecting one
    by comparing numbers is what the rule forbids, and it is the only thing
    that could be written here today — so nothing is. If a roll-up is ever
    added, the exclusion keys off the value's SOURCE, at the place that
    produces it, and this comment is the note that it is owed.

    Item permissions are applied here and not afterwards: DASH-04.3 —
    "להחיל הרשאות פריט על אוכלוסיית הנתונים" — and a population filtered
    after it has been counted has already been counted wrong.
    """
    scope = (w.record_scope if w is not None else None) or "items"
    srcs = (_widget_sources(d, w) if w is not None
            else _dash_sources(d.sources, limit=10 ** 6))
    # ── one load per population, per request ──
    # Ten widgets on one dashboard usually read the same boards, and each was
    # loading the same ten thousand rows again: the profile put 60% of a
    # request in SQLAlchemy building those objects and decoding their JSON.
    # The population is a pure function of (source, scope) and the database
    # cannot change underneath one request, so it is loaded once and shared —
    # the same bargain `_col_plan` and `_prefetch_links` strike, in the same
    # place. Keyed by the sources themselves rather than by widget id,
    # because that is what makes two DIFFERENT widgets over the same boards
    # share the answer.
    key = ("_dash_pop", user_id, scope,
           tuple(sorted((x["board_id"], tuple(x["groups"] or ()))
                        for x in srcs)))
    hit = db.info.get(key)
    if hit is not None:
        return hit
    # Whether the assignees are read at all. They are a relationship, so
    # touching them per record is a query per record — and eager-loading them
    # for ten thousand rows that never ask is a query and a hydration nobody
    # needed. Three things want them: a chart grouped or split by person, and
    # any condition about them.
    ch = (w.chart or {}) if w is not None else {}
    need_people = (ch.get("dimension") == "person" or ch.get("split") == "person"
                   or "assignees" in _filter_field_keys(d.filters)
                   or (w is not None and "assignees" in _filter_field_keys(w.filters)))
    out, seen = [], set()
    for s in srcs:
        bid = s["board_id"]
        role = _board_role(db, bid, user_id)
        if role is None:
            continue
        # Only the columns the dashboard actually reads. The profile put most
        # of a request in SQLAlchemy building Task objects and decoding their
        # JSON, and `description` is a Text column nothing here looks at —
        # loading it for ten thousand rows is pure cost. `selectinload` on the
        # assignees is the other half: a person-grouped chart touches
        # `t.assignees` per record, which is one query each without it.
        q = (db.query(Task)
               .options(load_only(Task.id, Task.board_id, Task.group_id,
                                  Task.parent_id, Task.title, Task.status,
                                  Task.priority, Task.due_date, Task.created_at,
                                  Task.created_by, Task.custom_fields,
                                  Task.permissions, Task.is_archived,
                                  Task.item_uid),
                        *( [selectinload(Task.assignees)] if need_people else [] ))
               .filter(Task.board_id == bid,
                       Task.is_archived == False))                  # noqa: E712
        if scope == "items":
            q = q.filter(Task.parent_id.is_(None))
        elif scope == "subitems":
            q = q.filter(Task.parent_id.isnot(None))
        if s["groups"] is not None:
            q = q.filter(Task.group_id.in_(s["groups"]))
        # an assigned member's own items, asked once per board rather than
        # through a lazy assignees load per record (see _assign_scope)
        _sc = (_assign_scope(db, db.query(Board).filter(Board.id == bid).first(), user_id)
               if role in ASSIGNED_ROLES else None)
        for t in q.order_by(Task.id).all():
            if t.id in seen:
                continue
            if _item_perm(t, user_id, role, _sc) == "none":
                continue
            seen.add(t.id)
            out.append(t)
    db.info[key] = out
    return out




# ── פורמט ערך ויחידה ─────────────────────────────────────────────────
# DASH-15. All of it is presentation: "העיגול ישפיע על התצוגה בלבד" and
# "תווית היחידה לא תשנה את הערכים". So nothing here touches a stored cell or
# a computed total — the compute response carries the raw figure AND the
# instructions for showing it, and the two never collapse into one rounded
# number that nobody can get back out of.
WIDGET_FORMATS = ("number", "currency", "percent")
# "באחוזים יש להגדיר סולם מקור 0–1 או 0–100" — because 0.5 and 50 are the
# same half and a column holds one of them. Without being told which, a
# percent is a number with a sign stuck on the end of it.
PERCENT_SCALES = ("0-1", "0-100")
WIDGET_MAX_PRECISION = 4


def _dash_metric_format(m, label=""):
    """The resolved display settings for one measure, or a refusal."""
    fmt = str(m.get("format") or "number").lower()
    if fmt not in WIDGET_FORMATS:
        raise HTTPException(400, "פורמט ערך לא נתמך — מספר, מטבע או אחוז")
    p = m.get("precision", 0)
    if p is None:
        p = 0
    try:
        p = int(p)
    except (TypeError, ValueError):
        raise HTTPException(400, "דיוק לא תקין")
    if not 0 <= p <= WIDGET_MAX_PRECISION:
        raise HTTPException(400, f"דיוק חייב להיות בין 0 ל־{WIDGET_MAX_PRECISION} ספרות")
    scale = m.get("scale")
    if fmt == "percent":
        if scale not in PERCENT_SCALES:
            raise HTTPException(
                400, f'למדד "{label}" באחוזים יש להגדיר סולם מקור — 0–1 או 0–100')
    elif scale is not None and scale not in PERCENT_SCALES:
        raise HTTPException(400, "סולם מקור תקף לאחוזים בלבד")
    return {"format": fmt, "precision": p,
            "thousands": bool(m.get("thousands", True)),
            "scale": scale if fmt == "percent" else None}


# ── מיפוי לשדות שהמסנן נוגע בהם ──────────────────────────────────────

def _dash_filter_unmapped(sources, mapping, filters):
    """The first field a condition names that some source has no column for.

    R05 — "מסנן יוחל רק כשקיים מיפוי תקין לכל המקורות שעליהם הוא משפיע. אין
    סינון חלקי בשקט." DASH-16.1 makes it a save-time rule for a widget's own
    filter and DASH-17.1 for the dashboard's, which is why this is asked in
    both places rather than only at calculation time: a condition that cannot
    run is a configuration its author can fix, and discovering it later means
    discovering it in front of a reader who cannot.
    """
    for key in sorted(_filter_field_keys(filters)):
        if key in _DASH_BUILTIN_FIELDS:
            continue
        for s in sources:
            if not (mapping.get(str(s["board_id"])) or {}).get(key):
                return key
    return None


def _dash_check_filter_mapping(sources, mapping, widget_filters, dash_filters):
    """Both filters that will run over this widget, checked against it.

    The dashboard's is checked here as well as at its own save, because a
    widget added AFTER a dashboard filter was saved would otherwise slip past
    the rule — the dashboard was valid when it was stored and the widget is
    the thing that made it not.
    """
    gap = _dash_filter_unmapped(sources, mapping, widget_filters)
    if gap:
        raise HTTPException(
            400, f'לא ניתן לשמור מסנן על "{gap}" — השדה אינו ממופה בכל מקורות הווידג׳ט')
    gap = _dash_filter_unmapped(sources, mapping, dash_filters)
    if gap:
        raise HTTPException(
            400, f'מסנן הדשבורד מסנן לפי "{gap}", שאינו ממופה בווידג׳ט הזה — '
                 "מפה את השדה או הסר את התנאי")


def _dash_explicit_columns_on_calc_change(old_metrics, new_metrics, data):
    """Moving a measure from a count to a sum or an average needs a column.

    DASH-11.2 — "מעבר מספירה לחישוב יחייב בחירת עמודות מפורשת." A count needs
    no column, so a widget that was counting may be carrying a mapping from
    some earlier shape of itself, or none at all. Inheriting whatever is
    lying there would quietly pick the column for somebody — and the first
    they would know of it is a total.
    """
    was = {str(m.get("key") or ""): (m.get("calc") or "count").lower()
           for m in (old_metrics or []) if isinstance(m, dict)}
    for m in (new_metrics or []):
        if not isinstance(m, dict):
            continue
        key = str(m.get("key") or "")
        calc = (m.get("calc") or "count").lower()
        if calc in _DASH_VALUE_CALCS and was.get(key) == "count" and "mapping" not in data:
            raise HTTPException(
                400, "מעבר מספירה לסכום או לממוצע מחייב בחירת עמודות מפורשת — "
                     "שלח את המיפוי יחד עם החישוב")


# ── קריאת ערך מספרי מתא ──────────────────────────────────────────────
# Three sources are allowed for a sum or an average — "מספר, נוסחה שמחזירה
# מספר ומראה מספרית" (R03) — and each of them can fail in a way the other
# two cannot. What they share is the ANSWER's shape: a value, a blank, or a
# reason it is neither. Keeping those three apart is the whole of DASH-09.1:
# "פלט נוסחה שאינו מספרי או שיש בו שגיאה אינו ערך תקין לחישוב; אין להתייחס
# אליו כאל ריק בלי להתריע."

def _dash_raw_number(v):
    """A stored cell as a number — ("value", x) or ("empty", None).

    `v in (None, "", False)` would be a trap here: in Python 0 == False, so a
    cell holding zero would read as an empty cell. "אפס תקין תמיד משתתף"
    (R03), and this is the line that makes it true — the same care
    filter_ast._cell takes, for the same reason.
    """
    if v is None or isinstance(v, bool):
        return ("empty", None)
    if isinstance(v, str) and not v.strip():
        return ("empty", None)
    if isinstance(v, dict):
        v = v.get("value")
        if v is None:
            return ("empty", None)
    try:
        n = float(str(v).replace(",", "") if isinstance(v, str) else v)
    except (TypeError, ValueError):
        return ("error", "הערך אינו מספר")
    return ("value", n) if n == n and abs(n) != float("inf") else ("error", "הערך אינו מספר")


def _dash_mirror_numbers(db, task, col, viewer):
    """The mirrored column's values on each linked item the viewer may see.

    `_mirror_cells` answers the same question for the GRID and answers it as
    display text — a status with its colour, a date formatted, a number
    stringified. A total cannot be added up from that, so this walks the same
    links and reads the SOURCE cell instead. (The typed mirror contract,
    DASH-01B in docs/DASHBOARDS_PLAN.md.)

    The link resolution is deliberately identical, `_visible_link_ids`
    included — but note what that filtering means here and did not mean
    there. In the grid, dropping a link the viewer may not open is correct.
    In a total it would be a partial sum, which R01 forbids; the widget is
    therefore blocked before this is ever reached (`_widget_state`), and the
    filter below is the belt to that brace rather than the policy itself.
    """
    cfg = _mirror_cfg(col)
    src_id, field = cfg.get("connect"), cfg.get("field")
    if not src_id or not field:
        return ("error", "הגדרת המראה אינה שלמה")
    if str(field) in _MIRROR_BUILTINS:
        # title, status, priority, due, assignees — none of them is a
        # quantity. Said rather than quietly answered as blank.
        return ("error", "המראה אינו מצביע על עמודה מספרית")
    cols = _dash_cols(db, task.board_id)
    src = next((c for c in cols if c.get("id") == src_id
                and c.get("type") == "connect"), None)
    if src is None:
        return ("error", "עמודת הקישור שעליה נבנה המראה אינה קיימת")
    ids = (_linked_ids(db, task.id, src_id) if _is_two_way(src)
           else [i for i in ((task.custom_fields or {}).get(src_id) or [])
                 if isinstance(i, int)])
    ids = _visible_link_ids(db, ids, viewer)
    if not ids:
        return ("values", [])
    rows = {t.id: t for t in db.query(Task).filter(Task.id.in_(ids)).all()}
    out = []
    for i in ids:
        t = rows.get(i)
        if t is None:
            continue
        kind, val = _dash_raw_number((t.custom_fields or {}).get(str(field)))
        if kind == "error":
            return ("error", "אחד הערכים במראה אינו מספר")
        if kind == "value":
            out.append(val)
    return ("values", out)


def _dash_formula_number(db, task, col, cols, today):
    """A formula column, worked out here. See backend/formula.py."""
    by_title = {}
    for c in cols:
        t = (c.get("title") or "").strip()
        if t and c.get("id") != col.get("id"):
            by_title.setdefault(t, c)
    cf = task.custom_fields or {}

    def lookup(ref):
        c = by_title.get(str(ref).strip())
        if c is None:
            # Exactly what the browser's lookup does, and for the reason its
            # comment gives: answering 0 for a column that is not there would
            # show a confident number computed from something missing.
            raise formula.FormulaError("אין עמודה בשם " + str(ref))
        v = cf.get(c["id"])
        if c.get("type") == "checkbox":
            return 1 if v else 0
        if c.get("type") == "number":
            return None if v is None or v == "" else formula._fnum(v)
        if isinstance(v, dict):
            return formula._ftext(v.get("label") or v.get("text") or "")
        return v

    return formula.number_of(col.get("formula"), lookup, today=today)


def _dash_value(db, task, col, cols, viewer, *, mirror_agg="sum", today=None):
    """One record's contribution to one measure.

    ("value", float) · ("empty", None) · ("error", reason).

    A multi-valued mirror is reduced to ONE number for the item before the
    widget's own calculation ever sees it — R03: "במראה מרובת ערכים מגדירים
    סכום או ממוצע לכל פריט, ואז מבצעים את חישוב הווידג׳ט בין הפריטים.
    בממוצע החיצוני כל פריט בעל פלט תקין מקבל משקל אחד." That last sentence is
    why this returns one value and not a list: an item with nine linked
    records must not outvote an item with one.
    """
    ctype = (col or {}).get("type")
    if ctype == "number":
        return _dash_raw_number((task.custom_fields or {}).get(col["id"]))
    if ctype == "formula":
        return _dash_formula_number(db, task, col, cols, today)
    if ctype == "mirror":
        kind, got = _dash_mirror_numbers(db, task, col, viewer)
        if kind == "error":
            return ("error", got)
        if not got:
            # No linked records, or none of them holding a number. That is a
            # blank for this item — the empty policy decides what it is
            # worth, which is what "מדיניות הריק חלה על הפלט המסוכם של
            # הפריט" means.
            return ("empty", None)
        if mirror_agg == "avg":
            return ("value", sum(got) / len(got))
        return ("value", sum(got))
    return ("error", "העמודה אינה מקור מספרי")


# ── איחוד הערכים וחישובם ─────────────────────────────────────────────

def _dash_reduce(values, calc, empty_policy, n_records):
    """The measure itself, from values already gathered across every source.

    "כמה לוחות מחושבים מאיחוד הערכים, ללא ממוצע של ממוצעים וללא עיגול
    ביניים" (R03) — so this is handed ONE flat list from every board at once
    and never a per-board subtotal. An average of averages weights a board of
    three records the same as a board of three hundred, which is a different
    number and a wrong one.

    Returns (state, result, n_values).
    """
    present = [v for k, v in values if k == "value"]
    blanks = sum(1 for k, _ in values if k == "empty")
    if calc == "count":
        # "ספירת רשומות אינה מושפעת מריק בעמודה אלא אם קיים מסנן שמחריג אותו"
        # — a count counts records, and a record with a blank cell is still a
        # record. The filter is the only thing that removes one.
        return ("ok", float(n_records), n_records)
    if empty_policy == "zero":
        present = present + [0.0] * blanks
    if calc == "sum":
        # No values at all is zero and NOT "no data": "סכום ללא ערכים
        # מספריים: 0 עם אין ערכים מספריים לחישוב" (R04). The caller says so
        # in words; the number is still 0.
        return ("ok", float(sum(present)), len(present))
    if calc == "avg":
        if not present:
            # "ממוצע ללא ערכים בהתעלמות מריקים: אין נתונים", and with no
            # records at all there is no denominator either way.
            return ("no_data", None, 0)
        return ("ok", sum(present) / len(present), len(present))
    return ("error", None, 0)


# ── הסינון המשותף ────────────────────────────────────────────────────
# DASH-10. One filter mechanism, applied the same way to the measure and to
# the records behind it — "להחיל כל תנאי סינון באותה דרך על המדד ועל רשומות
# הפירוט". Nothing here re-implements the operators: `filter_ast` already
# holds the field kinds, the operators, the AND/OR logic and the inclusive
# range bounds R05 asks for, and it is the same engine a board filter and an
# automation condition run through. What a dashboard adds is that a field is
# answered by a DIFFERENT column on every board, so the tree is rewritten
# per board before it is evaluated.


class _DashUnmapped(Exception):
    """A condition names a field this board has no column for."""

    def __init__(self, field):
        super().__init__(field)
        self.field = field


def _dash_tree_for_board(tree, board_map):
    """The condition tree with every field replaced by this board's column.

    Raises `_DashUnmapped` rather than dropping the rule. R05 — "מסנן יוחל רק
    כשקיים מיפוי תקין לכל המקורות שעליהם הוא משפיע. אין סינון חלקי בשקט."
    Dropping it is the silent half of that: inside an OR group a missing rule
    and a false one are opposites, and the forgiving reading quietly returns
    the whole board.
    """
    if not isinstance(tree, dict):
        return None
    if tree.get("type") == "group" or "rules" in tree:
        return {"type": "group", "operator": tree.get("operator", "and"),
                "rules": [_dash_tree_for_board(k, board_map)
                          for k in (tree.get("rules") or [])]}
    field = str(tree.get("field") or "")
    if field in _DASH_BUILTIN_FIELDS:
        return dict(tree)
    cid = (board_map or {}).get(field)
    if not cid:
        raise _DashUnmapped(field)
    return dict(tree, field=str(cid))


def _dash_filter_fields(db, board_id, tree):
    """What each field in this (already rewritten) tree may be asked about."""
    b = db.query(Board).filter(Board.id == board_id).first()
    fields = {"title": "text", "status": "status", "priority": "status",
              "assignees": "people", "due": "date"}
    for c in _dash_cols(db, board_id):
        kind = filter_ast.KINDS.get(c.get("type"))
        if kind:
            fields[str(c.get("id"))] = kind
    return fields


def _dash_filter_item(db, board, task):
    """One record in the shape `filter_ast` reads.

    The same shape `_filter_item` builds for a board filter and an automation
    condition — on purpose. A question about a cell must answer the same way
    wherever it is asked, or the board's filter and the dashboard's will
    disagree about the same record.
    """
    return {"id": task.id, "title": task.title,
            "status": _task_status_key(task), "priority": _task_priority_key(task),
            "due_date": task.due_date.isoformat() if task.due_date else None,
            "assignees": [{"id": u.id} for u in list(task.assignees or [])],
            "custom_fields": {**(task.custom_fields or {}),
                              **_derived_cells(board, task)}}


def _dash_clock(db):
    """The organisation's day and offset — not the server's, not the reader's.

    R05 and R07 both say "אזור הזמן הארגוני". The board filter resolves dates
    against the CLIENT's clock, deliberately and for a good reason of its own
    ("Dates belong to the person looking"), but a dashboard cannot: two
    readers in two zones would see two different totals for one saved
    configuration, and a measure is a statement about the organisation.
    """
    tz = _board_tz(db, None)
    now = datetime.now(tz)
    return now.date(), int(now.utcoffset().total_seconds() // 60)


def _dash_matching(db, d, w, user_id, temp=None):
    """The records this widget measures, after every layer of filtering.

    DASH-10.2 — "לחשב אוכלוסיית רשומות אחת לפי כל שכבות הסינון וההרשאות,
    בלי תלות בעמוד התוצאות שנטען." This is that one population, and it is
    what BOTH the measure and the drill-down are built from: the drill-down
    pages this list, it does not re-derive it. A list computed twice is two
    lists the moment the two derivations differ by a line.

    Returns (records, blocked_field) — a field name instead of records when a
    condition could not be applied to one of the sources.
    """
    today, offset = _dash_clock(db)
    mapping = w.mapping or {} if w is not None else {}
    # Three layers, intersected: what the dashboard saved, what the widget
    # saved, and what this visitor is trying out. The third is never stored —
    # R05, "צופה מסנן זמנית לאורך הביקור בלבד, ללא השפעה על אחרים" — and it
    # is applied here rather than anywhere else precisely so that it cannot
    # take a different path from the saved two and see a different set.
    trees = [t for t in ((d.filters or {}).get("adv"),
                         ((w.filters or {}) if w is not None else {}).get("adv"),
                         (temp or {}).get("adv")) if t]
    out = []
    boards = {}
    for t in _dash_population(db, d, w, user_id):
        if t.board_id not in boards:
            boards[t.board_id] = db.query(Board).filter(Board.id == t.board_id).first()
        board = boards[t.board_id]
        if not trees:
            out.append(t)
            continue
        bmap = mapping.get(str(t.board_id)) or {}
        item = _dash_filter_item(db, board, t)
        keep = True
        for raw in trees:
            try:
                tree = _dash_tree_for_board(raw, bmap)
            except _DashUnmapped as e:
                return ([], e.field)
            try:
                parsed = filter_ast.parse(tree)
            except filter_ast.BadFilter:
                return ([], "__bad__")
            fields = _dash_filter_fields(db, t.board_id, tree)
            # A rule naming a column this board does not have is the same
            # refusal as an unmapped field, not a rule to skip.
            pruned, gone = filter_ast.prune(parsed, fields)
            if gone:
                return ([], gone[0])
            if not filter_ast.match(item, pruned, fields, today.isoformat(),
                                    offset, user_id):
                keep = False
                break
        if keep:
            out.append(t)
    return (out, None)


# ── המדד ─────────────────────────────────────────────────────────────

def _dash_metric(db, d, w, metric, records, user_id):
    """One measure over an already-settled population.

    Returns the dict the compute response carries per measure. The population
    is passed IN rather than derived here, so the measure and the drill-down
    cannot disagree about which records they are about.
    """
    calc = (metric.get("calc") or "count").lower()
    key = str(metric.get("field") or "")
    policy = (metric.get("empty_policy") or "ignore").lower()
    mirror_agg = (metric.get("mirror_agg") or "sum").lower()
    unit = metric.get("unit") or None
    today, _off = _dash_clock(db)
    values, errors, first_error = [], 0, None
    if calc != "count" and key and key not in _DASH_BUILTIN_FIELDS:
        mapping = w.mapping or {}
        for t in records:
            cid = (mapping.get(str(t.board_id)) or {}).get(key)
            if not cid:
                errors += 1
                first_error = first_error or "חסר מיפוי עמודה באחד הלוחות"
                continue
            col = next((c for c in _dash_cols(db, t.board_id)
                        if str(c.get("id")) == str(cid)), None)
            if col is None:
                errors += 1
                first_error = first_error or "עמודה שממופה למדד אינה קיימת עוד"
                continue
            kind, got = _dash_value(db, t, col, _dash_cols(db, t.board_id), user_id,
                                    mirror_agg=mirror_agg, today=today)
            if kind == "error":
                errors += 1
                first_error = first_error or got
            else:
                values.append((kind, got))
            # The unit travels from the column rather than from the request:
            # the figure's unit is a property of what was added up.
            if unit is None:
                unit = _dash_col_unit(col)
    state, result, n_values = _dash_reduce(values, calc, policy, len(records))
    # DASH-15, and the reason it rides along with the number instead of being
    # applied to it: "העיגול ישפיע על התצוגה בלבד". The raw figure is what
    # was computed and what a reader gets on touch and focus; this is how to
    # show it. Collapsing the two would throw away the full value.
    fmt = _dash_metric_format(metric, metric.get("title") or "")
    if errors:
        # "אין להתייחס אליו כאל ריק בלי להתריע" (DASH-09.1) and "כשל שרת,
        # שגיאת חישוב או מקור חסום אינם מוצגים כ־0" (R04). A record whose
        # value could not be worked out is neither blank nor zero, so the
        # measure is not presented as a total at all — it is presented as a
        # configuration that needs fixing, with the count of what failed.
        # Deliberately `needs_fix` and not `error`: nothing went wrong on the
        # server, something is wrong in the settings, and DASH-20.2 wants
        # those told apart so the link to fix it goes only to whoever may.
        return {"key": metric.get("key") or key or "metric",
                "title": metric.get("title") or "",
                "calc": calc, "state": "needs_fix", "result": None,
                "unit": unit, "empty_policy": policy,
                "records": len(records), "values": n_values,
                "failed": errors, "reason": first_error, **fmt}
    return {"key": metric.get("key") or key or "metric",
            "title": metric.get("title") or "",
            "calc": calc, "state": state, "result": result,
            "unit": unit, "empty_policy": policy,
            "records": len(records), "values": n_values,
            **fmt,
            # "סכום ללא ערכים מספריים: 0 עם אין ערכים מספריים לחישוב" — the
            # figure is a true zero and the sentence beside it is why.
            "note": ("אין ערכים מספריים לחישוב"
                     if calc == "sum" and n_values == 0 and len(records) else None)}


# ── מה יוצא החוצה ────────────────────────────────────────────────────

def _widget_json(db, d, w, user_id, *, visible=None):
    """One widget, as much of it as this reader is allowed to know.

    A blocked widget keeps its identity and loses its configuration — the
    same shape `_view_blocked_for` settled on for a cut filtering by a column
    the reader may not see, and for the same reason: naming the source, the
    column or the condition is the disclosure the block exists to prevent.

    What stays is the title and the type. The title is the author's own
    label, not a fact about a board — it is how a reader knows a widget is
    there to ask for access to — and the precedent keeps the view's name for
    exactly that. What does NOT stay is anything a quantity could be inferred
    from: no sources, no mapping, no filters, no measures, no chart.

    No result travels either way. Computation is DASH-09's, and a widget's
    settings are not the place a number would live even once it exists.
    """
    state = _widget_state(db, d, w, user_id, visible=visible)
    base = {"id": w.id, "type": w.type, "title": w.title or "",
            "position": w.position or 0, "state": state}
    if state == "blocked":
        return dict(base, description="")
    return dict(base,
                description=w.description or "",
                sources=_dash_sources(w.sources, limit=10 ** 6),
                mapping=w.mapping or {},
                record_scope=w.record_scope or "items",
                filters=w.filters or {},
                metrics=w.metrics or [],
                chart=w.chart or {},
                display=w.display or {},
                created_by=w.created_by, updated_by=w.updated_by,
                created_at=w.created_at, updated_at=w.updated_at)


def _dash_json(db, d, user_id, access=None, *, with_widgets=True):
    """One dashboard for one reader.

    `sources` is filtered to the boards this reader may open — DASH-05.2 asks
    the header to show "המקורות המותרים", and the allowed ones are what that
    means. A board they cannot open is not named: the dashboard's own
    audience and the boards' audiences are separate questions, and being
    invited here answers neither of them about a board.
    """
    access = access or _dash_access(db, d, user_id)
    view = (db.query(SavedView).filter(SavedView.id == d.view_id).first()
            if d.kind == "board" else None)
    vis = _visible_board_ids(db, user_id)
    allowed = [s for s in _dash_sources(d.sources, limit=10 ** 6)
               if s["board_id"] in vis]
    out = {
        "id": d.id, "kind": d.kind,
        "name": _dash_name(db, d, view),
        "board_id": d.board_id, "view_id": d.view_id,
        "environment_id": d.environment_id,
        "position": d.position or 0,
        "visibility": d.visibility or "main",
        "sources": allowed,
        # How many were withheld, without saying which. A reader whose
        # totals are short deserves to know that the dashboard reaches
        # further than they do; naming the boards would be the disclosure.
        "sources_hidden": max(0, len(_dash_sources(d.sources, limit=10 ** 6)) - len(allowed)),
        "filters": d.filters or {},
        "layout": d.layout or {},
        "config_version": d.config_version or 1,
        "schema_version": d.schema_version or 1,
        "can_edit": access == "owner",
        "created_by": d.created_by, "updated_by": d.updated_by,
        "created_at": d.created_at, "updated_at": d.updated_at,
    }
    if with_widgets:
        ws = (db.query(DashboardWidget)
                .filter(DashboardWidget.dashboard_id == d.id)
                .order_by(DashboardWidget.position, DashboardWidget.id).all())
        out["widgets"] = [_widget_json(db, d, w, user_id, visible=vis) for w in ws]
        # Which boards a change would make these figures stale — the ones the
        # widgets name AND the ones they reach through a mirror. DASH-21.1
        # asks for a refresh on "שינוי במקורות עקיפים של נוסחה ומראה", and
        # the browser cannot work out what those are: the closure that knows
        # is here. Only for widgets this reader is not blocked from, so the
        # list never names a board they could not already see.
        watch = set()
        for w in ws:
            if _widget_state(db, d, w, user_id, visible=vis) == "blocked":
                continue
            boards, _cols, _unmapped = _widget_required(db, d, w)
            watch |= {b for b in boards if b in vis}
        out["watch_boards"] = sorted(watch)
    return out


def _dash_member_json(db, d):
    rows = (db.query(DashboardMember, User)
              .join(User, User.id == DashboardMember.user_id)
              .filter(DashboardMember.dashboard_id == d.id)
              .order_by(DashboardMember.role, User.name).all())
    out = []
    if d.created_by is not None:
        u = db.query(User).filter(User.id == d.created_by).first()
        if u is not None:
            # The creator is an owner by definition and carries no row, so
            # the list says so rather than leaving the dashboard looking
            # like it belongs to whoever was invited afterwards.
            out.append({"id": u.id, "name": u.name, "avatar_url": u.avatar_url,
                        "role": "owner", "is_creator": True})
    for m, u in rows:
        if u.id == d.created_by:
            continue
        out.append({"id": u.id, "name": u.name, "avatar_url": u.avatar_url,
                    "role": m.role, "is_creator": False})
    return out


def _log_dash(db, d, action, field=None, old=None, new=None, actor=None):
    """One line in the log for a change to a dashboard.

    The same shape `_log_view` writes, and the same restraint: what changed
    and from what to what, never the configuration itself. A dashboard's
    sources and filters name boards and columns, and a log is read by more
    people than any one dashboard.
    """
    db.add(AuditLog(entity_type="dashboard", entity_id=d.id, action=action,
                    field_name=field, old_value=old, new_value=new,
                    changed_by=actor))


def _dash_bump(db, d, user_id):
    """The configuration moved, so the version does — and only here.

    One counter for the dashboard AND its widgets. A widget rewrite and a
    settings rewrite are both "this dashboard changed" to the person holding
    the old one, and two counters would let each land on top of the other
    while both claimed to be current.
    """
    d.config_version = (d.config_version or 1) + 1
    d.updated_by = user_id
    d.updated_at = datetime.now(timezone.utc)
    return d.config_version


def _dash_check_version(data, d):
    """Refuse a save that is not based on what is stored.

    R09: "שמירה מאומתת בשרת ומוגנת בגרסה; התנגשות מציגה 'התצוגה עודכנה על ידי
    משתמש אחר' ללא דריסה שקטה."

    A save arriving without a version is a save that cannot be checked, and
    accepting it is the silent overwrite this exists to stop — so an absent
    version is refused as firmly as a stale one. 409 and not 403, because the
    two are different answers: one is "you may not", the other is "you are
    behind", and the current version travels back so the client can reload
    and retry rather than guess.
    """
    have = d.config_version or 1
    want = data.get("config_version")
    if want is None:
        raise HTTPException(400, "שמירת דשבורד חייבת לכלול את גרסת התצורה הנוכחית")
    try:
        want = int(want)
    except (TypeError, ValueError):
        raise HTTPException(400, "גרסת תצורה לא תקינה")
    if want != have:
        raise HTTPException(409, {"error": "stale_config",
                                  "detail": "הדשבורד עודכן על ידי משתמש אחר",
                                  "config_version": have})
    return have


def _dash_check_sources(db, srcs, user_id):
    """"עורך דשבורד רשאי לחבר לוח שיש לו בו הרשאת צפייה."

    Checked at the write and not only at the read, so a dashboard cannot be
    built pointing at a board its author never had — which would otherwise be
    a way to find out whether a board id exists by watching what the server
    accepts.
    """
    vis = _visible_board_ids(db, user_id)
    bad = [s["board_id"] for s in srcs if s["board_id"] not in vis]
    if bad:
        raise HTTPException(403, "אפשר לחבר רק לוחות שיש לך בהם הרשאת צפייה")
    return srcs


def _dash_validate_filters(raw):
    """A filter stored here is a filter `filter_ast` can read."""
    if raw in (None, {}):
        return {}
    if not isinstance(raw, dict):
        raise HTTPException(400, "מסנן לא תקין")
    try:
        filter_ast.parse(raw.get("adv"))
    except filter_ast.BadFilter as e:
        raise HTTPException(400, str(e))
    return raw


# ── דשבורד עצמאי בסביבת עבודה ────────────────────────────────────────

@app.post("/api/dashboards")
def create_dashboard(data: dict = None, user_id: int = Depends(current_user_id)):
    """A new standalone dashboard in a workspace.

    "יצירה למי שמורשה ליצור לוחות" (R01) — the same capability, asked the
    same way, rather than a permission of its own. A dashboard is a way of
    reading boards, and somebody trusted to make one of those is trusted to
    make a view across them.
    """
    data = data or {}
    with Session(engine) as db:
        if not _cap(db, user_id, "create_board"):
            raise HTTPException(403, "אין לך הרשאה ליצור דשבורד")
        try:
            env_id = int(data.get("environment_id"))
        except (TypeError, ValueError):
            raise HTTPException(400, "נדרשת סביבת עבודה")
        env = db.query(Environment).filter(Environment.id == env_id).first()
        if env is None:
            raise HTTPException(404, "סביבת העבודה אינה קיימת")
        if _env_role(db, env_id, user_id) is None:
            raise HTTPException(403, "אין לך גישה לסביבת העבודה הזו")
        name = (data.get("name") or "").strip() or NEW_DASHBOARD_NAME
        if len(name) > 80:
            raise HTTPException(400, "שם הדשבורד ארוך מדי")
        vis = data.get("visibility") or "main"
        if vis not in DASHBOARD_VISIBILITY:
            raise HTTPException(400, "סוג דשבורד לא תקין")
        srcs = _dash_check_groups(
            db, _dash_check_sources(db, _dash_sources(data.get("sources")), user_id))
        pos = (db.query(func.max(Dashboard.position))
                 .filter(Dashboard.environment_id == env_id,
                         Dashboard.deleted_at.is_(None)).scalar())
        d = Dashboard(kind="standalone", environment_id=env_id, name=name,
                      visibility=vis, created_by=user_id, updated_by=user_id,
                      sources=srcs, filters={}, layout={},
                      position=(pos + 1) if pos is not None else 0)
        db.add(d)
        db.flush()
        _log_dash(db, d, "create", field="name", new=name, actor=user_id)
        db.commit()
        db.refresh(d)
        return _json(_dash_json(db, d, user_id, "owner"))


@app.get("/api/dashboards")
def list_dashboards(environment_id: int = None,
                    user_id: int = Depends(current_user_id)):
    """The standalone dashboards this person may open.

    Filtered by _dash_access one row at a time rather than by a clever query:
    "ראשי" and "פרטי" answer to different tables, and a join that got one of
    them subtly wrong would list a private dashboard to the workspace.
    """
    with Session(engine) as db:
        q = (db.query(Dashboard)
               .filter(Dashboard.kind == "standalone",
                       Dashboard.deleted_at.is_(None)))
        if environment_id is not None:
            q = q.filter(Dashboard.environment_id == environment_id)
        rows = q.order_by(Dashboard.position, Dashboard.id).all()
        out = []
        for d in rows:
            access = _dash_access(db, d, user_id)
            if access is None:
                continue
            out.append(_dash_json(db, d, user_id, access, with_widgets=False))
        return _json({"dashboards": out})


@app.get("/api/dashboards/{dash_id}")
def get_dashboard(dash_id: int, user_id: int = Depends(current_user_id)):
    with Session(engine) as db:
        d, access = _dash_or_404(db, dash_id, user_id)
        return _json(_dash_json(db, d, user_id, access))


@app.patch("/api/dashboards/{dash_id}")
def update_dashboard(dash_id: int, data: dict,
                     user_id: int = Depends(current_user_id)):
    """Rename it, change its audience, its sources, its filter or its layout.

    Every one of these is a change to what other people see, so every one of
    them is version-checked and bumps the version. "תצוגה מקדימה אינה שמירה"
    (R09) — a preview never reaches here at all.
    """
    with Session(engine) as db:
        d, _access = _dash_or_404(db, dash_id, user_id, manage=True)
        _dash_check_version(data, d)
        if "name" in data:
            name = (data.get("name") or "").strip()
            if not name:
                raise HTTPException(400, "נדרש שם לדשבורד")
            if len(name) > 80:
                raise HTTPException(400, "שם הדשבורד ארוך מדי")
            if d.kind == "board":
                # The name of a board dashboard IS its tab's, and it stays
                # there — two places holding one name is two places that can
                # disagree about it. What this endpoint does is give the tab
                # ONE door to be renamed through: the view endpoint refuses a
                # dashboard outright (it is not a cut), and before this it
                # refused the name as well, so a dashboard tab could not be
                # renamed at all. The board's own uniqueness rule is applied
                # here, by the board's own checker.
                v = db.query(SavedView).filter(SavedView.id == d.view_id).first()
                if v is None:
                    raise HTTPException(404, "התצוגה אינה קיימת")
                if name != v.name:
                    checked = _check_view_name(db, d.board_id, name, exclude_id=v.id)
                    _log_view(db, v, "rename", field="name", old=v.name,
                              new=checked, actor=user_id)
                    v.name = checked
                    v.updated_at = datetime.now(timezone.utc)
            elif name != d.name:
                _log_dash(db, d, "rename", field="name", old=d.name, new=name,
                          actor=user_id)
                d.name = name
        if "visibility" in data:
            if d.kind == "board":
                raise HTTPException(400, "קהל הצפייה של תצוגת דשבורד נקבע בלוח")
            vis = data.get("visibility")
            if vis not in DASHBOARD_VISIBILITY:
                raise HTTPException(400, "סוג דשבורד לא תקין")
            if vis != d.visibility:
                _log_dash(db, d, "visibility", field="visibility",
                          old=d.visibility, new=vis, actor=user_id)
                d.visibility = vis
        if "sources" in data:
            limit = DASHBOARD_MAX_BOARDS if d.kind == "standalone" else 1
            srcs = _dash_check_groups(
                db, _dash_check_sources(db, _dash_sources(data.get("sources"),
                                                          limit=limit), user_id))
            if d.kind == "board":
                # "בתצוגת לוח, הלוח המארח יהיה המקור היחיד והקבוע" — DASH-06.1.
                # Refused rather than silently corrected: a caller asking for
                # another board is asking for something this view cannot be.
                if [s["board_id"] for s in srcs] not in ([], [d.board_id]):
                    raise HTTPException(400, "תצוגת דשבורד מציגה את הלוח המארח בלבד")
                if not srcs:
                    srcs = [{"board_id": d.board_id, "groups": None}]
            d.sources = srcs
        if "filters" in data:
            want = _dash_validate_filters(data.get("filters"))
            # DASH-17.1 — "להחיל מסנן משותף רק כשהשדה ממופה בכל המקורות
            # שעליהם הוא משפיע. אין להפעיל סינון חלקי בלי ליידע את המשתמש."
            # Refusing IS the informing: the alternative is a dashboard-wide
            # condition that runs on four widgets and silently does nothing
            # on the fifth, which reads as five answers to one question.
            for _w in (db.query(DashboardWidget)
                         .filter(DashboardWidget.dashboard_id == d.id).all()):
                gap = _dash_filter_unmapped(_widget_sources(d, _w),
                                            _w.mapping or {}, want)
                if gap:
                    raise HTTPException(
                        400, f'לא ניתן לסנן לפי "{gap}" — השדה אינו ממופה '
                             f'בווידג׳ט "{_w.title or _w.id}"')
            d.filters = want
        if "layout" in data:
            lay = data.get("layout")
            if lay is not None and not isinstance(lay, dict):
                raise HTTPException(400, "פריסה לא תקינה")
            d.layout = lay or {}
        if isinstance(data.get("position"), int) and d.kind == "standalone":
            d.position = data["position"]
        ver = _dash_bump(db, d, user_id)
        _log_dash(db, d, "config", field="config_version",
                  old=str(ver - 1), new=str(ver), actor=user_id)
        db.commit()
        db.refresh(d)
        return _json(_dash_json(db, d, user_id, "owner"))


@app.delete("/api/dashboards/{dash_id}")
def delete_dashboard(dash_id: int, user_id: int = Depends(current_user_id)):
    """Into the bin, and nothing else goes with it.

    "מחיקה … תסיר את הגדרות הדשבורד בלבד" (DASH-05.3). Nothing here owns a
    board, a column or an item — a dashboard only ever pointed at them — so
    there is nothing for this to cascade into. Soft, like every other
    deletion in this system, so an accident is recoverable.
    """
    with Session(engine) as db:
        d, _access = _dash_or_404(db, dash_id, user_id, manage=True)
        if d.kind == "board":
            raise HTTPException(400, "תצוגת דשבורד נמחקת דרך רצועת התצוגות של הלוח")
        d.deleted_at = datetime.now(timezone.utc)
        d.deleted_by = user_id
        _log_dash(db, d, "delete", field="name", old=d.name, actor=user_id)
        db.commit()
        return {"status": "deleted"}


# ── קהל הצפייה ───────────────────────────────────────────────────────

@app.get("/api/dashboards/{dash_id}/members")
def list_dashboard_members(dash_id: int, user_id: int = Depends(current_user_id)):
    with Session(engine) as db:
        d, _access = _dash_or_404(db, dash_id, user_id)
        if d.kind == "board":
            raise HTTPException(400, "קהל הצפייה של תצוגת דשבורד הוא חברי הלוח")
        return {"members": _dash_member_json(db, d)}


@app.post("/api/dashboards/{dash_id}/members")
def add_dashboard_member(dash_id: int, data: dict,
                         user_id: int = Depends(current_user_id)):
    """Name another owner, or invite somebody to read it.

    R01 again, and it bears repeating at the one endpoint that could be
    mistaken for granting access to data: "בעלות או הזמנה אינן מעניקות
    הרשאות לנתוני מקור". This row lets somebody open the dashboard. What
    they then see in it is decided, board by board and column by column, by
    _widget_state — and a widget whose sources they lack stays blocked no
    matter who invited them here.
    """
    with Session(engine) as db:
        d, _access = _dash_or_404(db, dash_id, user_id, manage=True)
        if d.kind == "board":
            raise HTTPException(400, "קהל הצפייה של תצוגת דשבורד נקבע בלוח")
        try:
            uid = int(data.get("user_id"))
        except (TypeError, ValueError):
            raise HTTPException(400, "נדרש מזהה משתמש")
        role = data.get("role") or "viewer"
        if role not in DASHBOARD_MEMBER_ROLES:
            raise HTTPException(400, "תפקיד לא תקין")
        u = db.query(User).filter(User.id == uid).first()
        if u is None:
            raise HTTPException(404, "המשתמש אינו קיים")
        if _account_blocked(db, uid):
            raise HTTPException(400, "לא ניתן לצרף חשבון מושבת")
        if uid == d.created_by:
            raise HTTPException(400, "יוצר הדשבורד הוא בעלים מלכתחילה")
        m = (db.query(DashboardMember)
               .filter(DashboardMember.dashboard_id == d.id,
                       DashboardMember.user_id == uid).first())
        if m is None:
            db.add(DashboardMember(dashboard_id=d.id, user_id=uid, role=role))
        else:
            m.role = role
        _log_dash(db, d, "member", field="role", new=f"{uid}:{role}", actor=user_id)
        db.commit()
        return {"members": _dash_member_json(db, d)}


@app.delete("/api/dashboards/{dash_id}/members/{member_id}")
def remove_dashboard_member(dash_id: int, member_id: int,
                            user_id: int = Depends(current_user_id)):
    with Session(engine) as db:
        d, _access = _dash_or_404(db, dash_id, user_id, manage=True)
        if member_id == d.created_by:
            raise HTTPException(400, "לא ניתן להסיר את יוצר הדשבורד")
        (db.query(DashboardMember)
           .filter(DashboardMember.dashboard_id == d.id,
                   DashboardMember.user_id == member_id)
           .delete(synchronize_session=False))
        _log_dash(db, d, "member", field="role", old=str(member_id), actor=user_id)
        db.commit()
        return {"members": _dash_member_json(db, d)}


# ── תצוגת דשבורד בתוך לוח ────────────────────────────────────────────

@app.post("/api/boards/{board_id}/dashboards")
def create_board_dashboard(board_id: int, data: dict = None,
                           user_id: int = Depends(current_user_id)):
    """A dashboard tab on this board — a view row and its settings, together.

    The same two-row shape a form uses: the tab is a `SavedView`, so the
    name, the strip position, the lock and the bin are the board's existing
    machinery, and this row holds only what a dashboard has and a cut does
    not. The host board is the one source and it is written here at creation,
    never afterwards (DASH-06.1).
    """
    data = data or {}
    with Session(engine) as db:
        _b, role = _board_role_or_403(db, board_id, user_id)
        if role not in ("admin", "editor"):
            raise HTTPException(403, "תצוגה בלוח היא טאב על הלוח — רק עורך או מנהל לוח יכול ליצור אחת")
        if (data.get("name") or "").strip():
            name = _check_view_name(db, board_id, data.get("name"))
        else:
            name = _free_name(db, board_id, NEW_DASHBOARD_NAME, "")
        _check_view_room(db, board_id)
        maxpos = (db.query(func.max(SavedView.position))
                    .filter(SavedView.board_id == board_id).scalar())
        v = SavedView(board_id=board_id, owner_id=user_id, name=name,
                      kind=DASH_VIEW_KIND, visibility="public",
                      # A dashboard holds no cut. Empty rather than absent, so
                      # anything reading `filters` on any view gets a dict.
                      filters={}, schema_version=1,
                      position=(maxpos + 1) if maxpos is not None else 0)
        db.add(v)
        db.flush()
        d = Dashboard(kind="board", view_id=v.id, board_id=board_id,
                      created_by=user_id, updated_by=user_id,
                      sources=[{"board_id": board_id, "groups": None}],
                      filters={}, layout={})
        db.add(d)
        _commit_view(db, board_id,
                     log=lambda: _log_view(db, v, "create", field="dashboard",
                                           new=v.name, actor=user_id))
        db.refresh(d)
        return _json(_dash_json(db, d, user_id, "owner"))


@app.get("/api/boards/{board_id}/dashboards")
def list_board_dashboards(board_id: int, user_id: int = Depends(current_user_id)):
    """Every live dashboard tab on this board, for anyone who may open it."""
    with Session(engine) as db:
        _b, _role = _board_role_or_403(db, board_id, user_id)
        rows = (db.query(Dashboard, SavedView)
                  .join(SavedView, SavedView.id == Dashboard.view_id)
                  .filter(Dashboard.board_id == board_id,
                          Dashboard.kind == "board",
                          Dashboard.deleted_at.is_(None),
                          SavedView.deleted_at.is_(None))
                  .order_by(SavedView.position, SavedView.id).all())
        out = []
        for d, _v in rows:
            access = _dash_access(db, d, user_id)
            if access is None:
                continue
            out.append(_dash_json(db, d, user_id, access, with_widgets=False))
        return _json({"dashboards": out})


# ── ווידג׳טים ────────────────────────────────────────────────────────

def _widget_payload(db, d, data, user_id, w=None):
    """Read a widget's settings off a request, refusing what cannot be stored.

    Validation and not correction: a widget saved with a source its author
    may not open, or with a filter `filter_ast` cannot parse, is a widget
    that would have to be refused at calculation time instead — in front of
    a reader who did not write it and cannot fix it.
    """
    wtype = data.get("type") or (w.type if w else "numbers")
    if wtype not in WIDGET_TYPES:
        raise HTTPException(400, "סוג ווידג׳ט לא תקין")
    title = (data.get("title") if "title" in data else (w.title if w else "")) or ""
    title = str(title).strip()
    if not title:
        raise HTTPException(400, "נדרשת כותרת לווידג׳ט")      # DASH-11.1
    if len(title) > 120:
        raise HTTPException(400, "כותרת הווידג׳ט ארוכה מדי")
    scope = data.get("record_scope") or (w.record_scope if w else "items")
    if scope not in WIDGET_SCOPES:
        raise HTTPException(400, "אוכלוסיית רשומות לא תקינה")
    out = {"type": wtype, "title": title, "record_scope": scope,
           "description": str(data.get("description")
                              if "description" in data
                              else (w.description if w else "") or "")[:2000]}
    if "sources" in data or w is None:
        srcs = _dash_sources(data.get("sources"), limit=DASHBOARD_MAX_BOARDS)
        allowed = {s["board_id"] for s in _dash_sources(d.sources, limit=10 ** 6)}
        stray = [s["board_id"] for s in srcs if s["board_id"] not in allowed]
        if stray:
            raise HTTPException(400, "ווידג׳ט יכול להשתמש רק בלוחות של הדשבורד")
        _dash_check_groups(db, _dash_check_sources(db, srcs, user_id))
        out["sources"] = srcs
    if "filters" in data or w is None:
        out["filters"] = _dash_validate_filters(data.get("filters"))
    for key, default in (("mapping", {}), ("metrics", []), ("chart", {}),
                         ("display", {})):
        if key in data or w is None:
            val = data.get(key, default)
            if val is None:
                val = default
            if not isinstance(val, type(default)):
                raise HTTPException(400, f"ערך לא תקין בשדה {key}")
            out[key] = val
    # ── DASH-07.3, against what the widget will BE ──
    # A patch carries only what changed, so validating the payload alone
    # would pass a mapping that is wrong once merged — change the measures
    # today and the columns they need tomorrow, and neither save is refused
    # while the widget between them cannot be computed. The effective state
    # is what has to answer for itself, so it is assembled first.
    eff_sources = out.get("sources", _dash_sources(w.sources, limit=10 ** 6) if w else [])
    if not eff_sources:
        eff_sources = _dash_sources(d.sources, limit=10 ** 6)
    eff_mapping = out.get("mapping", (w.mapping if w else {}) or {})
    eff_metrics = out.get("metrics", (w.metrics if w else []) or [])
    eff_filters = out.get("filters", (w.filters if w else {}) or {})
    _dash_explicit_columns_on_calc_change(w.metrics if w else [], eff_metrics, data)
    # A list measures nothing, so it carries no metrics and none are checked.
    # Demanding one would be demanding a mapping for a column it never maps.
    if out["type"] != "list":
        _dash_validate_mapping(db, eff_sources, eff_mapping, eff_metrics)
    else:
        _dash_validate_list(db, eff_sources, out.get("display",
                                                     (w.display if w else {}) or {}))
    _dash_check_filter_mapping(eff_sources, eff_mapping, eff_filters, d.filters or {})
    _dash_validate_chart(out["type"],
                         out.get("chart", (w.chart if w else {}) or {}), eff_metrics,
                         db=db, sources=eff_sources, mapping=eff_mapping)
    return out


def _dash_reorder(db, d, w, want):
    """Put this widget at `want` and re-pack the rest around it.

    Writing the position and leaving the others alone is how two widgets come
    to claim one slot — and the list reads back ordered by position, so the
    tie is then broken by id and the saved order is quietly not the saved
    order. The board learned this the hard way with groups (see
    `move_items_bulk`, which renumbers each group it touches exactly once);
    this is the same rule for the same reason.

    It matters more here than it looks: the reading order IS the mobile
    column (R08, DASH-19.3), so a tie is not a cosmetic wobble on the desktop
    grid — it is a phone showing a different order from the one somebody
    saved.
    """
    rest = [x for x in (db.query(DashboardWidget)
                          .filter(DashboardWidget.dashboard_id == d.id)
                          .order_by(DashboardWidget.position, DashboardWidget.id).all())
            if x.id != w.id]
    want = max(0, min(len(rest), int(want)))
    rest.insert(want, w)
    for i, x in enumerate(rest):
        x.position = i


@app.post("/api/dashboards/{dash_id}/widgets")
def create_widget(dash_id: int, data: dict,
                  user_id: int = Depends(current_user_id)):
    with Session(engine) as db:
        d, _access = _dash_or_404(db, dash_id, user_id, manage=True)
        _dash_check_version(data, d)
        n = (db.query(DashboardWidget)
               .filter(DashboardWidget.dashboard_id == d.id).count())
        # R10, enforced at the write and in the direct request both — a
        # ceiling only the screen keeps is not a ceiling (DASH-12.3).
        if n >= DASHBOARD_MAX_WIDGETS:
            raise HTTPException(400,
                                f"יש כבר {DASHBOARD_MAX_WIDGETS} ווידג׳טים בדשבורד — "
                                "הסר אחד או פצל לדשבורד נוסף")
        fields = _widget_payload(db, d, data, user_id)
        pos = (db.query(func.max(DashboardWidget.position))
                 .filter(DashboardWidget.dashboard_id == d.id).scalar())
        w = DashboardWidget(dashboard_id=d.id, created_by=user_id,
                            updated_by=user_id,
                            position=(pos + 1) if pos is not None else 0,
                            **fields)
        db.add(w)
        db.flush()
        ver = _dash_bump(db, d, user_id)
        _log_dash(db, d, "widget", field="create", new=str(w.id), actor=user_id)
        db.commit()
        db.refresh(w); db.refresh(d)
        return _json({"widget": _widget_json(db, d, w, user_id),
                      "config_version": ver})


@app.patch("/api/dashboards/{dash_id}/widgets/{widget_id}")
def update_widget(dash_id: int, widget_id: int, data: dict,
                  user_id: int = Depends(current_user_id)):
    with Session(engine) as db:
        d, _access = _dash_or_404(db, dash_id, user_id, manage=True)
        _dash_check_version(data, d)
        w = (db.query(DashboardWidget)
               .filter(DashboardWidget.id == widget_id,
                       DashboardWidget.dashboard_id == d.id).first())
        if w is None:
            raise HTTPException(404, "הווידג׳ט אינו קיים")
        for k, v in _widget_payload(db, d, data, user_id, w).items():
            setattr(w, k, v)
        if isinstance(data.get("position"), int):
            _dash_reorder(db, d, w, data["position"])
        w.updated_by = user_id
        w.updated_at = datetime.now(timezone.utc)
        ver = _dash_bump(db, d, user_id)
        _log_dash(db, d, "widget", field="update", new=str(w.id), actor=user_id)
        db.commit()
        db.refresh(w); db.refresh(d)
        return _json({"widget": _widget_json(db, d, w, user_id),
                      "config_version": ver})


@app.delete("/api/dashboards/{dash_id}/widgets/{widget_id}")
def delete_widget(dash_id: int, widget_id: int, config_version: int = None,
                  user_id: int = Depends(current_user_id)):
    """Remove one measure. "מחיקת ווידג׳ט לא תשנה נתוני לוחות" — DASH-12.2."""
    with Session(engine) as db:
        d, _access = _dash_or_404(db, dash_id, user_id, manage=True)
        _dash_check_version({"config_version": config_version}, d)
        w = (db.query(DashboardWidget)
               .filter(DashboardWidget.id == widget_id,
                       DashboardWidget.dashboard_id == d.id).first())
        if w is None:
            raise HTTPException(404, "הווידג׳ט אינו קיים")
        db.delete(w)
        # The grid remembers geometry by widget id, and a key pointing at a
        # widget that no longer exists is a hole the layout would carry for
        # ever. Removed here because this is the one place that knows.
        lay = dict(d.layout or {})
        lay.pop(str(widget_id), None)
        d.layout = lay
        ver = _dash_bump(db, d, user_id)
        _log_dash(db, d, "widget", field="delete", old=str(widget_id), actor=user_id)
        db.commit()
        return {"status": "deleted", "config_version": ver}



def _dash_validate_list(db, sources, display):
    """Refuse a list whose columns cannot be shown.

    The two things it can get wrong are a column that is not on the board it
    is claimed for, and one of a type a list has no honest way to draw — a
    connect cell is a set of ids from other boards and a mirror reads through
    it, and both have a disclosure story (see _visible_link_ids) that a row
    of text cannot tell. They are one click away, on the item itself.
    """
    if not isinstance(display, dict):
        raise HTTPException(400, "הגדרת רשימה לא תקינה")
    allowed = {s["board_id"] for s in sources}
    picked = display.get("columns") or {}
    if not isinstance(picked, dict):
        raise HTTPException(400, "בחירת עמודות לא תקינה")
    total = 0
    for bid_s, ids in picked.items():
        try:
            bid = int(bid_s)
        except (TypeError, ValueError):
            raise HTTPException(400, "בחירת עמודות לא תקינה")
        if bid not in allowed:
            raise HTTPException(400, "אפשר להציג עמודות מלוחות המקור של הווידג\u05f3ט בלבד")
        have = {str(c.get("id")): c for c in _dash_cols(db, bid)}
        for cid in (ids or []):
            col = have.get(str(cid))
            if col is None:
                raise HTTPException(400, "אחת העמודות שנבחרו אינה קיימת בלוח")
            if col.get("type") not in LIST_COLUMN_TYPES:
                raise HTTPException(
                    400, f'לא ניתן להציג ברשימה עמודה מסוג "{col.get("title") or cid}" — '
                         "עמודת קישור או מראה נפתחת מתוך הפריט עצמו")
            total += 1
    if total > 8:
        raise HTTPException(400, "אפשר להציג עד 8 עמודות ברשימה")


# Which built-in field each built-in dimension and split actually reads, and
# what to call it in a refusal.
#
# A board may take any of the four built-in columns off itself (`col_hidden`,
# and HIDEABLE_BUILTIN_COLS is the list) — a monday import switches all four
# off, so most imported boards show no סטטוס, no אחראים and no תאריך יעד at
# all. Grouping a chart by one of those is then grouping by a field the board
# does not have: every record carries the default status, nobody is assigned
# and no due date is set, so the chart comes out as a single bar or as one
# "ללא ערך" column, and the reader is left with a distribution of something
# that is not on their board.
#
# The board's own filter has refused a hidden built-in since
# `query_board_items` learned to prune one — "a board whose admin had used
# מחק עמודה on סטטוס went on answering filters about it while the browser
# drew no such column". A chart is that same question asked a different way,
# so it gets the same answer rather than a bar nobody can explain.
_DIM_BUILTIN_FIELD = {"status": ("status", "סטטוס"),
                      "person": ("assignees", "אחראים"),
                      "date": ("due", "תאריך יעד")}


def _dash_builtin_off(db, sources, field, mapping=None):
    """The first source board that has taken this built-in column off itself.

    The date dimension is the one exception: it reads the item's due date
    only while nothing better is named, so a board that maps `__date__` to a
    date column of its own is answering with a column it does have.
    """
    for sc in (sources or []):
        bid = sc["board_id"]
        if field == "due" and ((mapping or {}).get(str(bid)) or {}).get("__date__"):
            continue
        b = db.query(Board).filter(Board.id == bid).first()
        if b is None:
            continue
        if field in {str(k) for k in ((b.settings or {}).get("col_hidden") or [])}:
            return b
    return None


def _dash_check_builtin_dim(db, sources, key, mapping, what):
    """Refuse a built-in dimension or split the source boards do not show."""
    if db is None or key not in _DIM_BUILTIN_FIELD:
        return
    field, he = _DIM_BUILTIN_FIELD[key]
    off = _dash_builtin_off(db, sources, field, mapping)
    if off is not None:
        raise HTTPException(
            400, f'לא ניתן {what} לפי {he} — הלוח "{off.name}" אינו מציג את העמודה הזו. '
                 "בחרי עמודה של הלוח.")


def _dash_dim_ok(db, sources, dim, mapping):
    """A dimension is one of the four kinds, or a column that can be one.

    Returns the kind it behaves as, or raises. A text column is refused by
    name: R06 names four kinds rather than saying "any column" precisely
    because a chart grouped by free text is a chart with one bar per record.
    """
    if not dim or dim in CHART_DIMS:
        return dim
    seen = None
    for sc in sources:
        col = _dash_dim_column(db, sc["board_id"], dim, mapping)
        if col is None:
            raise HTTPException(400, "העמודה שנבחרה לקיבוץ אינה קיימת בלוח המקור")
        if col.get("type") not in CHART_DIM_COLUMN_TYPES:
            raise HTTPException(
                400, f'לא ניתן לקבץ לפי "{col.get("title") or dim}" — '
                     "קיבוץ אפשרי לפי סטטוס, רשימה נפתחת, אדם, תאריך או סימון")
        seen = col.get("type")
    return "date" if seen in ("date", "created_at") else seen


def _dash_validate_chart(w_type, chart, metrics, db=None, sources=None, mapping=None):
    """Refuse a chart configuration that cannot be drawn from what it names.

    Each type has a rule of its own and each one is a save-time refusal,
    because the alternative is a chart that is accepted and then cannot be
    computed — in front of a reader who did not configure it (DASH-26.3,
    DASH-27.1).
    """
    if w_type != "chart":
        return
    c = dict(chart or {})
    ctype = c.get("type") or "vbar"
    if ctype not in CHART_TYPES:
        raise HTTPException(400, "סוג תרשים לא נתמך")
    dim = c.get("dimension")
    dim_kind = dim
    if not dim:
        # DASH-11.2 — "מקור, מיפוי, חישוב או יחידה שאינם תקינים יחסמו שמירה."
        # A chart IS its distribution: without one there is nothing to draw,
        # and the widget could only ever say "נדרש תיקון" to somebody who did
        # not configure it.
        raise HTTPException(400, "לתרשים יש לבחור התפלגות — לפי מה לקבץ את הנתונים")
    if dim not in CHART_DIMS:
        if db is None:
            raise HTTPException(400, "קיבוץ אפשרי לפי קבוצה, סטטוס, אדם או תאריך בלבד")
        dim_kind = _dash_dim_ok(db, sources or [], dim, mapping or {})
    else:
        _dash_check_builtin_dim(db, sources or [], dim, mapping or {}, "לקבץ")
    split = c.get("split")
    if split:
        if ctype in ("pie", "donut"):
            # R06 — "עוגה ודונאט משתמשות במדד אחד וללא פיצול נוסף."
            raise HTTPException(400, "עוגה ודונאט אינן תומכות בפיצול לסדרות")
        if split not in CHART_SPLITS:
            raise HTTPException(400, "פיצול אפשרי לפי קבוצה, סטטוס, אדם או לוח מקור")
        _dash_check_builtin_dim(db, sources or [], split, mapping or {}, "לפצל")
        if split == dim or split == dim_kind:
            # "לוח מקור אינו ממד קיבוץ נוסף", and no more is the dimension
            # itself: splitting by what you grouped by yields one series per
            # category and a chart that says nothing.
            raise HTTPException(400, "לא ניתן לפצל לפי אותו שדה שלפיו מקבצים")
    if c.get("period") and c["period"] not in CHART_PERIODS:
        raise HTTPException(400, "תקופה לא נתמכת")

    calcs = {(m.get("calc") or "count").lower() for m in (metrics or []) if isinstance(m, dict)}
    if ctype == "line" and dim is not None and dim_kind != "date":
        # DASH-27.1 — "הוא יחייב ממד תאריך; בחירה בממד אחר תחסום שמירה."
        raise HTTPException(400, "תרשים קו מחייב קיבוץ לפי תאריך")
    if ctype == "stacked" and "avg" in calcs:
        # DASH-26.1 — "הן יתמכו בספירה ובסכום בלבד, ללא ממוצע." Stacking
        # averages adds up numbers whose total means nothing.
        raise HTTPException(400, "עמודות מוערמות תומכות בספירה ובסכום בלבד, ללא ממוצע — "
                                 "שנה את החישוב או בחר סוג תרשים אחר")
    if ctype in ("pie", "donut") and len([m for m in (metrics or [])]) > 1:
        raise HTTPException(400, "עוגה ודונאט מציגות מדד יחיד")
    if len(metrics or []) > 1:
        # R06 — "כמה מדדים מותרים באותה יחידה ובציר משותף בלבד", and
        # DASH-26.2 says it again for a stack: "אין לשלב כמות וסכום כספי
        # באותה ערימה." Two measures on one axis with two units is two
        # different quantities drawn as if they were comparable.
        units = {(m.get("unit") or "") for m in metrics if isinstance(m, dict)}
        if len(units) > 1:
            raise HTTPException(400, "כמה מדדים מותרים באותה יחידה ובציר משותף בלבד")
        if ctype == "stacked" and len(calcs) > 1:
            raise HTTPException(400, "אין לערום מדדים בחישובים שונים באותה ערימה")


@app.post("/api/dashboards/{dash_id}/widgets/{widget_id}/chart")
def compute_chart(dash_id: int, widget_id: int, data: dict = None,
                  user_id: int = Depends(current_user_id)):
    """The chart\'s categories and series, for this reader, now."""
    data = data or {}
    with Session(engine) as db:
        d, _access = _dash_or_404(db, dash_id, user_id)
        w = (db.query(DashboardWidget)
               .filter(DashboardWidget.id == widget_id,
                       DashboardWidget.dashboard_id == d.id).first())
        if w is None:
            raise HTTPException(404, "הווידג\u05f3ט אינו קיים")
        temp = _dash_validate_filters(data.get("temp_filter"))
        return _json(_dash_chart(db, d, w, user_id, temp))


@app.post("/api/dashboards/{dash_id}/widgets/{widget_id}/chart-preview")
def preview_chart(dash_id: int, widget_id: int = 0, data: dict = None,
                  user_id: int = Depends(current_user_id)):
    """A chart worked out from a draft, stored nowhere — DASH-11.2 for charts."""
    data = data or {}
    with Session(engine) as db:
        d, _access = _dash_or_404(db, dash_id, user_id, manage=True)
        fields = _widget_payload(db, d, data, user_id)
        draft = DashboardWidget(dashboard_id=d.id, position=0, **fields)
        draft.id = None
        temp = _dash_validate_filters(data.get("temp_filter"))
        out = _dash_chart(db, d, draft, user_id, temp)
        out["widget_id"] = None
        out["preview"] = True
        return _json(out)


@app.post("/api/dashboards/{dash_id}/widgets/preview")
def preview_widget(dash_id: int, data: dict,
                   user_id: int = Depends(current_user_id)):
    """Work out what a widget WOULD say, without making it one.

    DASH-11.2 — "להציג תצוגה מקדימה לפני שמירה" — and R09's first sentence
    about saving: "תצוגה מקדימה אינה שמירה."

    So this is deliberately not a save that gets rolled back. Nothing is
    added to the session, no version moves, and no `config_version` is even
    required on the way in: a preview has nothing to conflict with, and
    demanding one would make the draft behave like the thing it exists to
    come before.

    Everything else IS the real path. The same validation refuses the same
    configurations with the same sentences, and the same permission closure
    blocks the same sources — a preview that was more permissive than the
    save would be a way to compute over a board through a widget that could
    never exist.
    """
    with Session(engine) as db:
        # A preview is an authoring action, so it asks for the rights of one.
        d, _access = _dash_or_404(db, dash_id, user_id, manage=True)
        fields = _widget_payload(db, d, data, user_id)
        # Transient on purpose: built, used, and never added to the session.
        draft = DashboardWidget(dashboard_id=d.id, position=0, **fields)
        draft.id = None
        temp = _dash_validate_filters(data.get("temp_filter"))
        # Dispatched on the kind, like every other path that computes a
        # widget — a preview that answered as a different kind would be
        # showing something the save cannot produce.
        out = (_dash_list(db, d, draft, user_id, temp) if draft.type == "list"
               else _dash_compute(db, d, draft, user_id, temp))
        # It has no identity, and saying it had one would invite a client to
        # send it back as though it did.
        out["widget_id"] = None
        out["preview"] = True
        return _json(out)


@app.post("/api/dashboards/{dash_id}/widgets/{widget_id}/duplicate")
def duplicate_widget(dash_id: int, widget_id: int, data: dict = None,
                     user_id: int = Depends(current_user_id)):
    """A copy of this measure, beside it.

    DASH-12.1 — "שכפול יעתיק את הגדרות המקורות, החישוב, המסננים והעיצוב
    וייצור מזהה חדש. שינוי בעותק לא ישנה את המקור." The JSON columns are
    copied by value rather than assigned across, because two rows pointing at
    one dict is exactly how a change to the copy reaches the original.

    DASH-12.3 — the ceiling is enforced here too. A limit that a duplicate
    could step over is not a limit.
    """
    data = data or {}
    with Session(engine) as db:
        d, _access = _dash_or_404(db, dash_id, user_id, manage=True)
        _dash_check_version(data, d)
        w = (db.query(DashboardWidget)
               .filter(DashboardWidget.id == widget_id,
                       DashboardWidget.dashboard_id == d.id).first())
        if w is None:
            raise HTTPException(404, "הווידג׳ט אינו קיים")
        n = (db.query(DashboardWidget)
               .filter(DashboardWidget.dashboard_id == d.id).count())
        if n >= DASHBOARD_MAX_WIDGETS:
            raise HTTPException(400,
                                f"יש כבר {DASHBOARD_MAX_WIDGETS} ווידג׳טים בדשבורד — "
                                "הסר אחד לפני שכפול")
        title = (data.get("title") or "").strip() or f"{w.title} (עותק)"
        pos = (db.query(func.max(DashboardWidget.position))
                 .filter(DashboardWidget.dashboard_id == d.id).scalar())
        copy = DashboardWidget(
            dashboard_id=d.id, type=w.type, title=title[:120],
            description=w.description,
            position=(pos + 1) if pos is not None else 0,
            # by value — see the docstring
            sources=list(w.sources or []), mapping=dict(w.mapping or {}),
            record_scope=w.record_scope, filters=dict(w.filters or {}),
            metrics=[dict(m) for m in (w.metrics or []) if isinstance(m, dict)],
            chart=dict(w.chart or {}),
            created_by=user_id, updated_by=user_id)
        db.add(copy)
        db.flush()
        ver = _dash_bump(db, d, user_id)
        _log_dash(db, d, "widget", field="duplicate",
                  old=str(w.id), new=str(copy.id), actor=user_id)
        db.commit()
        db.refresh(copy); db.refresh(d)
        return _json({"widget": _widget_json(db, d, copy, user_id),
                      "config_version": ver})


@app.post("/api/dashboards/{dash_id}/duplicate")
def duplicate_dashboard(dash_id: int, data: dict = None,
                        user_id: int = Depends(current_user_id)):
    """A copy of this dashboard, with new ids and no borrowed permissions.

    DASH-05.3 — "שכפול ייצור מזהים חדשים בלי להקנות הרשאות למקורות."

    Three things a copy deliberately does NOT inherit:

      · **The audience.** Invitees are not copied. Sharing is a deliberate
        act, and a duplicate that arrived pre-shared would hand a private
        dashboard's readership to whoever pressed copy.
      · **The creator.** Whoever makes the copy owns it; the original's
        owner has nothing to do with a dashboard they have not seen.
      · **Access to the sources.** Checked rather than assumed: a copy may
        only name boards the person copying can already open.

    The sources are refused and not quietly dropped. A copy missing a board
    computes different numbers from the original while looking like it — and
    "there is a board in here you cannot open" is a sentence somebody can
    act on, where a silently smaller total is not.
    """
    data = data or {}
    with Session(engine) as db:
        d, _access = _dash_or_404(db, dash_id, user_id)
        if d.kind == "board":
            raise HTTPException(400, "תצוגת דשבורד משוכפלת דרך רצועת התצוגות של הלוח")
        if not _cap(db, user_id, "create_board"):
            raise HTTPException(403, "אין לך הרשאה ליצור דשבורד")
        srcs = _dash_sources(d.sources, limit=10 ** 6)
        _dash_check_sources(db, srcs, user_id)
        name = (data.get("name") or "").strip() or f"{_dash_name(db, d)} (עותק)"
        if len(name) > 80:
            name = name[:80]
        env_id = d.environment_id
        if _env_role(db, env_id, user_id) is None:
            raise HTTPException(403, "אין לך גישה לסביבת העבודה הזו")
        pos = (db.query(func.max(Dashboard.position))
                 .filter(Dashboard.environment_id == env_id,
                         Dashboard.deleted_at.is_(None)).scalar())
        copy = Dashboard(kind="standalone", environment_id=env_id, name=name,
                         # A copy of a private dashboard starts private. The
                         # safer of the two is the one to inherit: widening
                         # an audience must be a decision somebody took.
                         visibility=d.visibility or "main",
                         created_by=user_id, updated_by=user_id,
                         sources=srcs, filters=d.filters or {},
                         position=(pos + 1) if pos is not None else 0,
                         layout={})
        db.add(copy)
        db.flush()
        # The grid is keyed by widget id, so it cannot be copied as it
        # stands — every key would point at a widget belonging to the
        # original. It is rebuilt as the new widgets are made.
        old_layout = d.layout or {}
        layout = {}
        for w in (db.query(DashboardWidget)
                    .filter(DashboardWidget.dashboard_id == d.id)
                    .order_by(DashboardWidget.position, DashboardWidget.id).all()):
            nw = DashboardWidget(
                dashboard_id=copy.id, type=w.type, title=w.title,
                description=w.description, position=w.position,
                sources=w.sources, mapping=w.mapping,
                record_scope=w.record_scope, filters=w.filters,
                metrics=w.metrics, chart=w.chart,
                created_by=user_id, updated_by=user_id)
            db.add(nw)
            db.flush()
            geom = old_layout.get(str(w.id))
            if geom is not None:
                layout[str(nw.id)] = geom
        copy.layout = layout
        _log_dash(db, copy, "duplicate", field="name",
                  old=_dash_name(db, d), new=name, actor=user_id)
        db.commit()
        db.refresh(copy)
        return _json(_dash_json(db, copy, user_id, "owner"))


@app.get("/api/dashboards/{dash_id}/sources/{board_id}/impact")
def source_removal_impact(dash_id: int, board_id: int,
                          user_id: int = Depends(current_user_id)):
    """What removing this board from the dashboard would do to its widgets.

    DASH-06.3 — "לפני הסרת לוח, להציג אילו ווידג׳טים יושפעו ולבקש אישור. אם
    נותר מקור תקין, ניתן להמשיך לפי התצורה. מקור חסר או הגדרה שנשברה ידרשו
    תיקון."

    Counted on the server and not from what the client is holding, for the
    same reason `column_impact` is: the configuration a reader has has
    already been filtered to what they may see, so counting there would
    understate a destructive action in front of exactly the person about to
    take it.

    Each widget comes back as one of two answers — it carries on with the
    sources it has left, or it is left with none and needs its settings
    fixed. The caller decides; this says nothing about whether to proceed.
    """
    with Session(engine) as db:
        d, _access = _dash_or_404(db, dash_id, user_id, manage=True)
        if d.kind == "board":
            raise HTTPException(400, "תצוגת דשבורד מציגה את הלוח המארח בלבד")
        have = {s["board_id"] for s in _dash_sources(d.sources, limit=10 ** 6)}
        if board_id not in have:
            raise HTTPException(404, "הלוח אינו מקור של הדשבורד הזה")
        remaining = have - {board_id}
        affected, orphaned = [], 0
        for w in (db.query(DashboardWidget)
                    .filter(DashboardWidget.dashboard_id == d.id)
                    .order_by(DashboardWidget.position, DashboardWidget.id).all()):
            own = {s["board_id"] for s in _dash_sources(w.sources, limit=10 ** 6)}
            # An empty list means "every source the dashboard has", so such a
            # widget is affected only when nothing is left at all.
            after = (own - {board_id}) if own else remaining
            if own and board_id not in own:
                continue
            verdict = "ok" if after else "needs_fix"
            if verdict == "needs_fix":
                orphaned += 1
            affected.append({"id": w.id, "title": w.title or "",
                             "verdict": verdict,
                             "sources_left": len(after)})
        return {"board_id": board_id,
                "board_name": (db.query(Board.name)
                                 .filter(Board.id == board_id).scalar() or ""),
                "widgets": affected, "orphaned": orphaned,
                "sources_left": len(remaining)}


@app.post("/api/dashboards/{dash_id}/mapping-proposal")
def propose_mapping(dash_id: int, data: dict,
                    user_id: int = Depends(current_user_id)):
    """Suggest how the other boards answer the measures the reference board does.

    DASH-07.1 — "הצעת התאמת עמודות לפי שם וסוג מחייבת אישור או תיקון לפני
    שימוש." **Nothing is stored by this endpoint.** It reads boards and
    answers; the mapping that is eventually kept is the one somebody sends
    back to the widget, having looked at this and agreed with it or changed
    it. A proposal that wrote itself in would be exactly the automatic
    column substitution R09 forbids.
    """
    with Session(engine) as db:
        d, _access = _dash_or_404(db, dash_id, user_id, manage=True)
        try:
            reference = int(data.get("reference_board_id"))
        except (TypeError, ValueError):
            raise HTTPException(400, "נדרש לוח ייחוס")
        srcs = _dash_sources(data.get("sources") or d.sources, limit=10 ** 6)
        allowed = {s["board_id"] for s in _dash_sources(d.sources, limit=10 ** 6)}
        if reference not in allowed or any(s["board_id"] not in allowed for s in srcs):
            raise HTTPException(400, "אפשר למפות רק בין לוחות הדשבורד")
        _dash_check_sources(db, srcs + [{"board_id": reference, "groups": None}], user_id)
        fields = data.get("fields")
        if not isinstance(fields, dict) or not fields:
            raise HTTPException(400, "נדרשים שדות למיפוי")
        return {"reference_board_id": reference,
                "proposals": _dash_propose_mapping(db, srcs, reference, fields)}


def _dash_conditions(d, w, temp):
    """How many conditions are actually running — DASH-17.3.

    Reported rather than left to the client to add up: the compact filter
    button shows this number, and three places counting one thing is three
    places that can disagree about it.
    """
    n = 0
    for f in ((d.filters or {}), ((w.filters or {}) if w is not None else {}), (temp or {})):
        try:
            n += filter_ast.count(filter_ast.parse((f or {}).get("adv")))
        except filter_ast.BadFilter:
            pass
    return n



# ── תרשימים: קיבוץ, סדרות וזמן ───────────────────────────────────────
# DASH-22, and the two rules it is built out of.
#
# R06 decides what a chart may be grouped by and how its series are formed;
# R07 decides what a period is and how a gap in one is told from a blank.
# Everything below is one of those two sentences made executable, and the
# comments say which — because the rules are not obvious and the wrong
# reading produces a chart that looks right.
#
# "קיבוץ לפי קבוצה, סטטוס, אדם ותאריך בלבד" — four, and no more. A chart
# grouped by a free-text column is a chart with one bar per item.
CHART_DIMS = ("group", "status", "person", "date")
# …and so may a COLUMN of the board, which is the same four kinds wearing a
# column's name: a board can have several status columns, and "חלוקה לפי
# סטטוסים" is as likely to mean one of those as the built-in one. R06 bars a
# free-text dimension and this keeps that bar — a chart grouped by a text
# column is a chart with one bar per record, which is the whole reason the
# rule names four kinds instead of saying "any column".
CHART_DIM_COLUMN_TYPES = ("status", "dropdown", "people", "date", "created_at",
                          "checkbox", "created_by")
# "בעמודות, במוערם ובקו ניתן לפצל לפי שדה קטגוריאלי נתמך אחד נוסף או להציג
# לוחות מקור כסדרות; לוח מקור אינו ממד קיבוץ נוסף" — so `board` is a legal
# SPLIT and never a legal dimension, which is why the two tuples differ.
CHART_SPLITS = ("group", "status", "person", "board")
CHART_TYPES = ("vbar", "hbar", "pie", "donut", "stacked", "line")
CHART_PERIODS = ("day", "week", "month", "quarter", "year")
# R10. The series cap counts every combination that reaches the legend —
# "כולל סדרות שנוצרו ממדדים מרובים" — so two metrics split three ways is six.
CHART_MAX_CATEGORIES = 50
CHART_MAX_SERIES = 10
# The category a record with no value for the dimension falls into. "ממד ריק
# מוצג בקטגוריית ללא ערך כברירת מחדל וניתן להסתירו" — and R06 is explicit
# that this is a DIFFERENT setting from the numeric empty policy of R03.
NO_VALUE_KEY = "__none__"
NO_VALUE_LABEL = "ללא ערך"


def _chart_cfg(w):
    """A chart's settings, with every default spelled out.

    Read through one function so a chart saved before a setting existed
    behaves like one saved after it, rather than like one with a null in it.
    """
    c = dict(w.chart or {})
    return {
        "dimension": c.get("dimension") or None,
        "period": c.get("period") if c.get("period") in CHART_PERIODS else "month",
        "split": c.get("split") or None,
        "sort": c.get("sort") if c.get("sort") in ("label", "value") else "label",
        "direction": c.get("direction") if c.get("direction") in ("asc", "desc") else "asc",
        "sort_metric": c.get("sort_metric") or None,
        "legend": c.get("legend", True) is not False,
        "value_labels": bool(c.get("value_labels")),
        "show_no_value": c.get("show_no_value", True) is not False,
        # Colours are kept BY ID — "הצבעים יישמרו לפי מזהים" (R06/DASH-22.2)
        # — so renaming a status or a group keeps its colour, and two
        # categories that happen to share a label do not share one.
        "colors": dict(c.get("colors") or {}),
    }


def _dash_person_names(db, ids):
    rows = db.query(User.id, User.name).filter(User.id.in_(list(ids) or [0])).all()
    return {i: n for i, n in rows}


def _period_bucket(d, period):
    """The period a date falls in: (sort key, label key).

    "שבוע שמתחיל בראשון" — Sunday, not Monday. Python's weekday() calls
    Monday 0, so Sunday is 6 and the offset back to the start of the week is
    (weekday + 1) % 7. Getting this wrong moves every weekly bar by a day and
    the chart still looks plausible.
    """
    if period == "day":
        return d.isoformat()
    if period == "week":
        start = d - _dt.timedelta(days=(d.weekday() + 1) % 7)
        return start.isoformat()
    if period == "month":
        return f"{d.year:04d}-{d.month:02d}"
    if period == "quarter":
        return f"{d.year:04d}-Q{(d.month - 1) // 3 + 1}"
    return f"{d.year:04d}"


def _period_label(key, period):
    """A label that can be told apart from its neighbours.

    R07 — "תווית כוללת שנה או תאריך מלא כשנדרש להבחין בין תקופות." A chart
    spanning two years that labels both Marches "מרץ" has two bars nobody can
    tell apart, so the year is always carried.
    """
    if period == "day":
        y, m, dd = key.split("-")
        return f"{dd}/{m}/{y}"
    if period == "week":
        y, m, dd = key.split("-")
        return f"שבוע {dd}/{m}/{y}"
    if period == "month":
        y, m = key.split("-")
        return f"{_HE_MONTHS[int(m) - 1]} {y}"
    return key.replace("-", " ")


_HE_MONTHS = ["ינואר", "פברואר", "מרץ", "אפריל", "מאי", "יוני",
              "יולי", "אוגוסט", "ספטמבר", "אוקטובר", "נובמבר", "דצמבר"]


def _period_next(key, period):
    """The period after this one — how the gaps get filled.

    R07 — "מציגים תקופות ביניים בין הראשונה לאחרונה". A month with no records
    is not a missing row, it is a month in which nothing happened, and a
    chart that simply skips it draws a straight line over a hole.
    """
    if period == "day":
        return (_dt.date.fromisoformat(key) + _dt.timedelta(days=1)).isoformat()
    if period == "week":
        return (_dt.date.fromisoformat(key) + _dt.timedelta(days=7)).isoformat()
    if period == "month":
        y, m = (int(x) for x in key.split("-"))
        return f"{y + (m == 12):04d}-{(m % 12) + 1:02d}"
    if period == "quarter":
        y, q = key.split("-Q")
        y, q = int(y), int(q)
        return f"{y + (q == 4):04d}-Q{(q % 4) + 1}"
    return f"{int(key) + 1:04d}"


def _dash_dim_column(db, board_id, dim, mapping):
    """The column a dimension names, when it names one rather than a kind."""
    if not dim or dim in CHART_DIMS:
        return None
    cid = (mapping.get(str(board_id)) or {}).get(dim) or dim
    return next((c for c in _dash_cols(db, board_id)
                 if str(c.get("id")) == str(cid)), None)


def _dash_column_dim_values(db, task, col, period, names):
    """Which categories this record falls into, for a COLUMN dimension.

    A list, like the person case and for the same reason: a dropdown holds
    the options ticked in it, so one record belongs to each of them and
    carries its whole value into each (R06). The overlap is flagged by the
    caller exactly as it is for people.
    """
    ctype = col.get("type")
    v = (task.custom_fields or {}).get(str(col.get("id")))
    if ctype == "created_at":
        d = task.created_at.date() if task.created_at else None
        if d is None:
            return [(NO_VALUE_KEY, NO_VALUE_LABEL)]
        k = _period_bucket(d, period)
        return [(k, _period_label(k, period))]
    if ctype == "created_by":
        if not task.created_by:
            return [(NO_VALUE_KEY, NO_VALUE_LABEL)]
        nm = names.get(task.created_by) or (
            db.query(User.name).filter(User.id == task.created_by).scalar() or "")
        return [(str(task.created_by), nm)]
    if v in (None, "", [], {}):
        return [(NO_VALUE_KEY, NO_VALUE_LABEL)]
    if ctype == "checkbox":
        return [("1", "מסומן")] if v else [("0", "אינו מסומן")]
    if ctype == "date":
        raw = v.get("from") or v.get("date") if isinstance(v, dict) else v
        d = formula._fdate(raw)
        if d is None:
            return [(NO_VALUE_KEY, NO_VALUE_LABEL)]
        k = _period_bucket(d, period)
        return [(k, _period_label(k, period))]
    if ctype == "people":
        ids = [x.get("id") if isinstance(x, dict) else x for x in v] if isinstance(v, list) else []
        ids = [i for i in ids if isinstance(i, int)]
        if not ids:
            return [(NO_VALUE_KEY, NO_VALUE_LABEL)]
        have = {i: n for i, n in db.query(User.id, User.name).filter(User.id.in_(ids)).all()}
        return [(str(i), have.get(i) or str(i)) for i in ids]
    # status and dropdown — one option, or the several ticked in it
    if isinstance(v, list):
        out = [(x.get("label") if isinstance(x, dict) else x) for x in v]
        out = [str(x) for x in out if x not in (None, "")]
        return [(x, x) for x in out] or [(NO_VALUE_KEY, NO_VALUE_LABEL)]
    label = v.get("label") if isinstance(v, dict) else v
    return [(str(label), str(label))] if label not in (None, "") \
        else [(NO_VALUE_KEY, NO_VALUE_LABEL)]


def _dash_dim_values(db, task, board, kind, mapping, period, names):
    """Which categories this record belongs to — a LIST, not a value.

    People is the reason it is a list. R06 — "ריבוי אנשים משייך את הרשומה
    ואת מלוא ערכה לכל אדם, עם חיווי שרשומה עשויה להופיע ביותר מקטגוריה
    אחת." The full value goes to each of them, deliberately: the question a
    person-grouped chart answers is "how much is on each person's plate", and
    splitting 90 three ways answers a different one. The consequence — that
    the bars add up to more than the total — is a FACT about the data and is
    flagged rather than smoothed away.
    """
    if kind == "group":
        g = db.info.setdefault("_dash_groups", {})
        if task.group_id and task.group_id not in g:
            row = db.query(Group).filter(Group.id == task.group_id).first()
            g[task.group_id] = row.name if row else None
        label = g.get(task.group_id)
        return [(str(task.group_id), label)] if label else [(NO_VALUE_KEY, NO_VALUE_LABEL)]
    if kind == "status":
        if (task.custom_fields or {}).get("status_unset"):
            return [(NO_VALUE_KEY, NO_VALUE_LABEL)]
        key = str(_task_status_key(task))
        entry = next((x for x in _board_statuses(board) if x["key"] == key), None)
        return [(key, (entry or {}).get("label") or key)]
    if kind == "person":
        people = list(task.assignees or [])
        if not people:
            return [(NO_VALUE_KEY, NO_VALUE_LABEL)]
        return [(str(u.id), names.get(u.id) or u.name) for u in people]
    if kind == "board":
        b = db.info.setdefault("_dash_bnames", {})
        if task.board_id not in b:
            b[task.board_id] = (db.query(Board.name)
                                  .filter(Board.id == task.board_id).scalar() or "")
        return [(str(task.board_id), b[task.board_id])]
    if kind not in CHART_DIMS:
        col = _dash_dim_column(db, task.board_id, kind, mapping)
        if col is None:
            return [(NO_VALUE_KEY, NO_VALUE_LABEL)]
        return _dash_column_dim_values(db, task, col, period, names)
    if kind == "date":
        cid = (mapping.get(str(task.board_id)) or {}).get("__date__")
        raw = (task.custom_fields or {}).get(str(cid)) if cid else task.due_date
        if isinstance(raw, dict):
            raw = raw.get("from") or raw.get("date")
        if raw in (None, ""):
            return [(NO_VALUE_KEY, NO_VALUE_LABEL)]
        d = raw.date() if hasattr(raw, "date") else formula._fdate(raw)
        if d is None:
            return [(NO_VALUE_KEY, NO_VALUE_LABEL)]
        k = _period_bucket(d, period)
        return [(k, _period_label(k, period))]
    return [(NO_VALUE_KEY, NO_VALUE_LABEL)]


def _dash_status_colors(db, d, w):
    """The board's own status colours, as the starting point.

    DASH-22.2 — "ברירת המחדל לצבעי סטטוס תילקח מהלוח. שינוי מקומי לא ישנה
    את הלוח." So the board is read, never written: a colour chosen on a
    chart lives in the chart's own `colors` map and the board goes on
    looking the way it looked.
    """
    out = {}
    for s in _widget_sources(d, w):
        b = db.query(Board).filter(Board.id == s["board_id"]).first()
        if b is None:
            continue
        for e in _board_statuses(b):
            out.setdefault(str(e["key"]), e.get("color"))
    return out


# A palette for series that have no colour of their own. The monday values
# the rest of the product uses — nothing is invented here, and nothing is
# purple (invariant 7).
_CHART_PALETTE = ["#0073ea", "#00c875", "#fdab3d", "#e2445c", "#579bfc",
                  "#ffcb00", "#037f4c", "#bb3354", "#00c2b8", "#9badbc"]
# How a series key carries its metric and its split half. Two characters that
# cannot appear in a metric key or a board id, so splitting it back apart is
# exact rather than a guess.
_SER_SEP = "::"
CALC_HE_SRV = {"count": "ספירה", "sum": "סכום", "avg": "ממוצע"}


def _ser_metric(series_key):
    return series_key.split(_SER_SEP)[0]


def _dash_metric_cell(db, d, w, m, t, user_id, today):
    """One record's contribution to one measure, for a chart.

    A count contributes a placeholder and deliberately not a 1: `_dash_reduce`
    counts a count from the NUMBER of entries, so making this a 1 and summing
    would give the same answer today and the wrong one the moment the empty
    policy touched it.
    """
    calc = (m.get("calc") or "count").lower()
    key = str(m.get("field") or "")
    if calc == "count" or not key or key in _DASH_BUILTIN_FIELDS:
        return ("value", 0.0)
    cid = ((w.mapping or {}).get(str(t.board_id)) or {}).get(key)
    col = next((c for c in _dash_cols(db, t.board_id)
                if str(c.get("id")) == str(cid)), None) if cid else None
    if col is None:
        return ("empty", None)
    kind, got = _dash_value(db, t, col, _dash_cols(db, t.board_id), user_id,
                            mirror_agg=(m.get("mirror_agg") or "sum").lower(),
                            today=today)
    return ("empty", None) if kind == "error" else (kind, got)


def _dash_sort_categories(keys, labels, cells, metrics, cfg):
    """Order the categories — by label or by value, ascending or descending.

    R06 — "מיון לפי תווית או ערך, עולה או יורד; במדדים מרובים יש לבחור מדד
    למיון ערך. שוויון לפי תווית ומזהה." The tie-break is not decoration: two
    categories with the same total would otherwise swap places between two
    requests over identical data, and a chart that reorders itself on refresh
    is one nobody trusts.
    """
    rev = cfg["direction"] == "desc"
    if cfg["sort"] == "value":
        want = cfg["sort_metric"] or str(
            (metrics[0] if metrics else {}).get("key") or "m")
        wantm = next((m for m in (metrics or [])
                      if str(m.get("key") or m.get("calc") or "m") == want), None)
        # A count is the NUMBER of cells, not the sum of them: a count cell
        # carries a placeholder (see _dash_metric_cell), so summing it sorts
        # every category to zero and the order silently falls back to label.
        counting = ((wantm or {}).get("calc") or "count").lower() == "count"

        def total(k):
            s = 0.0
            for (sk, ck), vals in cells.items():
                if ck != k or _ser_metric(sk) != want:
                    continue
                s += (len(vals) if counting
                      else sum(v for kind, v in vals if kind == "value" and v is not None))
            return s
        return sorted(keys, key=lambda k: (-total(k) if rev else total(k),
                                           labels.get(k, k), k))
    return sorted(keys, key=lambda k: (labels.get(k, k), k), reverse=rev)


def _dash_chart(db, d, w, user_id, temp=None):
    """A chart\'s categories, series and cells — the whole of DASH-22.

    The shape is one for every chart type, because the five types differ in
    how they are DRAWN and not in what they are made of: a stacked column and
    a line over the same configuration hold the same numbers. DASH-24.2 says
    so for two of them — "מעבר בין אנכי לאופקי ישמור על המקורות, החישוב,
    המסננים, הצבעים והמיון ויציג את אותם ערכים" — and the only way to be sure
    of that is for there to be one computation.

    The population is `_dash_matching`, the same call the numbers widget and
    the drill-down make. That is what makes DASH-23.3 true — "קטגוריה יחידה
    עם אותן הגדרות תציג ערך זהה לווידג\u05f3ט מספרים" — rather than nearly true.
    """
    cfg = _chart_cfg(w)
    ctype = (w.chart or {}).get("type") or "vbar"
    computed_at = datetime.now(timezone.utc)
    base = {"widget_id": w.id, "type": ctype,
            "config_version": d.config_version or 1,
            "computed_at": computed_at,
            "conditions": _dash_conditions(d, w, temp),
            "temporary_filter": bool((temp or {}).get("adv")),
            "can_fix": _dash_access(db, d, user_id) == "owner"}
    if _widget_state(db, d, w, user_id) == "blocked":
        return dict(base, state="blocked", categories=[], series=[])
    dim = cfg["dimension"]
    if not dim:
        return dict(base, state="needs_fix", categories=[], series=[],
                    reason="לא נבחר ממד קיבוץ")
    records, blocked_field = _dash_matching(db, d, w, user_id, temp)
    if blocked_field is not None:
        return dict(base, state="needs_fix", categories=[], series=[],
                    reason="לא ניתן להחיל מסנן — חסר מיפוי לשדה",
                    field=(None if blocked_field == "__bad__" else blocked_field))

    metrics = w.metrics or [{"key": "m", "calc": "count"}]
    split = cfg["split"] if cfg["split"] in CHART_SPLITS else None
    if ctype in ("pie", "donut"):
        # "עוגה ודונאט משתמשות במדד אחד וללא פיצול נוסף" (R06).
        metrics, split = metrics[:1], None
    mapping = w.mapping or {}
    today, _off = _dash_clock(db)
    names = (_dash_person_names(db, {u.id for t in records for u in (t.assignees or [])})
             if dim == "person" or split == "person" else {})

    cells, cat_label, ser_label, counts = {}, {}, {}, {}
    overlap = False
    boards = {}
    for t in records:
        if t.board_id not in boards:
            boards[t.board_id] = db.query(Board).filter(Board.id == t.board_id).first()
        board = boards[t.board_id]
        cats = _dash_dim_values(db, t, board, dim, mapping, cfg["period"], names)
        if len(cats) > 1:
            overlap = True                      # R06 "חיווי חפיפה"
        splits = (_dash_dim_values(db, t, board, split, mapping, cfg["period"], names)
                  if split else [(None, None)])
        if split and len(splits) > 1:
            overlap = True
        for m in metrics:
            mk = str(m.get("key") or m.get("calc") or "m")
            val = _dash_metric_cell(db, d, w, m, t, user_id, today)
            mlabel = m.get("title") or CALC_HE_SRV.get((m.get("calc") or "count"), mk)
            for ck, cl in cats:
                cat_label.setdefault(ck, cl)
                for sk, sl in splits:
                    full = mk if sk is None else mk + _SER_SEP + sk
                    ser_label.setdefault(full, mlabel if sl is None else mlabel + " · " + sl)
                    cells.setdefault((full, ck), []).append(val)
                    counts[(full, ck)] = counts.get((full, ck), 0) + 1

    cat_keys = list(cat_label)
    if not cfg["show_no_value"]:
        cat_keys = [k for k in cat_keys if k != NO_VALUE_KEY]
    if dim == "date":
        # "תאריך תמיד כרונולוגי" (R06), and the intervening periods are filled
        # in so a gap is drawn as a gap rather than skipped (R07).
        real = sorted(k for k in cat_keys if k != NO_VALUE_KEY)
        filled, guard = [], 0
        if real:
            cur, last = real[0], real[-1]
            while cur <= last and guard < 2000:
                filled.append(cur)
                cur = _period_next(cur, cfg["period"])
                guard += 1
        for k in filled:
            cat_label.setdefault(k, _period_label(k, cfg["period"]))
        cat_keys = filled + ([NO_VALUE_KEY] if NO_VALUE_KEY in cat_keys else [])
    else:
        cat_keys = _dash_sort_categories(cat_keys, cat_label, cells, metrics, cfg)

    ser_keys = list(ser_label)
    if len(cat_keys) > CHART_MAX_CATEGORIES:
        return dict(base, state="too_many", categories=[], series=[],
                    limit="categories", found=len(cat_keys), max=CHART_MAX_CATEGORIES,
                    reason="התרשים מפיק " + str(len(cat_keys)) + " קטגוריות, והמגבלה היא "
                           + str(CHART_MAX_CATEGORIES) + " — צמצם בעזרת מסנן או ממד אחר")
    if len(ser_keys) > CHART_MAX_SERIES:
        return dict(base, state="too_many", categories=[], series=[],
                    limit="series", found=len(ser_keys), max=CHART_MAX_SERIES,
                    reason="התרשים מפיק " + str(len(ser_keys)) + " סדרות, והמגבלה היא "
                           + str(CHART_MAX_SERIES) + " — צמצם מדדים או פיצול")

    # The board's own status colours, for the built-in status dimension. A
    # status COLUMN carries its own vocabulary and its own colours, which are
    # a different list — it falls through to the shared palette rather than
    # borrowing the board's, which would put the wrong colour on a label that
    # happens to share a name.
    status_colors = _dash_status_colors(db, d, w) if dim == "status" else {}
    out_cats = []
    for i, ck in enumerate(cat_keys):
        colour = (cfg["colors"].get(ck)
                  or (status_colors.get(ck) if dim == "status" else None)
                  or _CHART_PALETTE[i % len(_CHART_PALETTE)])
        out_cats.append({"key": ck, "label": cat_label.get(ck, ck), "color": colour})
    out_series = []
    for i, sk in enumerate(ser_keys):
        mk = _ser_metric(sk)
        m = next((x for x in metrics
                  if str(x.get("key") or x.get("calc") or "m") == mk), metrics[0])
        fmt = _dash_metric_format(m, m.get("title") or "")
        calc = (m.get("calc") or "count").lower()
        policy = (m.get("empty_policy") or "ignore").lower()
        points = []
        for ck in cat_keys:
            vals = cells.get((sk, ck))
            if vals is None:
                # R07 — "תקופה חסרה היא 0 בספירה ובסכום ופער בממוצע; היא אינה
                # רשומה בעלת ערך ריק." A gap is a null, and DASH-27.3 forbids
                # the line being drawn across one.
                points.append(None if calc == "avg" else 0.0)
                continue
            state, result, _n = _dash_reduce(vals, calc, policy, counts.get((sk, ck), 0))
            points.append(None if state == "no_data" else result)
        out_series.append({
            "key": sk, "label": ser_label.get(sk, sk), "metric": mk, "calc": calc,
            "color": cfg["colors"].get(sk) or _CHART_PALETTE[i % len(_CHART_PALETTE)],
            "unit": m.get("unit"), "points": points, **fmt})
    return dict(base, state=("ok" if out_cats else "no_data"),
                dimension=dim, period=cfg["period"], split=split,
                legend=cfg["legend"], value_labels=cfg["value_labels"],
                overlap=overlap, records=len(records),
                categories=out_cats, series=out_series)


def _dash_narrow_to_cell(db, d, w, records, category, series, user_id):
    """The records behind ONE element of a chart.

    DASH-18.1 — "לחיצה על רכיב תרשים תפתח את הקטגוריה, הסדרה והמדד
    המתאימים, עם אותם מקורות, מסננים וגרסת הגדרות" — and DASH-26.3 says the
    same for a segment of a stack.

    It narrows the population the chart was built from rather than deriving a
    new one, which is the only way the list can be guaranteed to be the rows
    that made that bar. A record in several categories (R06\'s multi-person
    case) appears under each of them, exactly as it was counted.
    """
    if not category:
        return records
    cfg = _chart_cfg(w)
    dim = cfg["dimension"]
    split = cfg["split"] if cfg["split"] in CHART_SPLITS else None
    want_split = None
    if series and _SER_SEP in series:
        want_split = series.split(_SER_SEP, 1)[1]
    mapping = w.mapping or {}
    names = _dash_person_names(
        db, {u.id for t in records for u in (t.assignees or [])})
    boards, out = {}, []
    for t in records:
        if t.board_id not in boards:
            boards[t.board_id] = db.query(Board).filter(Board.id == t.board_id).first()
        b = boards[t.board_id]
        cats = {k for k, _l in _dash_dim_values(db, t, b, dim, mapping,
                                                cfg["period"], names)}
        if category not in cats:
            continue
        if want_split and split:
            sp = {k for k, _l in _dash_dim_values(db, t, b, split, mapping,
                                                  cfg["period"], names)}
            if want_split not in sp:
                continue
        out.append(t)
    return out


# ── ווידג\u05f3ט רשימה ──────────────────────────────────────────────────
# The records themselves, drawn as rows. It measures nothing, so none of the
# numeric machinery applies to it — but everything that decides WHICH records
# does, and it is the same code: the same sources, the same filters, the same
# population, the same per-item permission and the same blocking. A second
# way of choosing records would be a second set of answers to "what is on
# this board", and the two would drift.
LIST_MAX_ROWS = 50
LIST_DEFAULT_ROWS = 10
# What a list may show. Deliberately not "every column": a connect cell is a
# set of ids from other boards and a mirror reads through it, both of which
# have a disclosure story of their own (see _visible_link_ids) that a list
# has no way to tell. They are reachable from the item itself, one click on.
LIST_COLUMN_TYPES = ("text", "long_text", "email", "phone", "number", "rating",
                     "status", "dropdown", "date", "timeline", "checkbox",
                     "people", "formula", "created_at", "created_by", "item_id")


def _dash_list_cfg(w):
    c = dict((w.display or {}))
    try:
        limit = int(c.get("limit") or LIST_DEFAULT_ROWS)
    except (TypeError, ValueError):
        limit = LIST_DEFAULT_ROWS
    cols = c.get("columns") if isinstance(c.get("columns"), dict) else {}
    sort = c.get("sort") if isinstance(c.get("sort"), dict) else {}
    return {"columns": cols,
            "limit": max(1, min(LIST_MAX_ROWS, limit)),
            "sort": {"field": sort.get("field") or "title",
                     "direction": "desc" if sort.get("direction") == "desc" else "asc"}}


def _dash_list_columns(db, d, w):
    """(board_id, column_id) for every column this list is set to show."""
    cfg = _dash_list_cfg(w)
    out = []
    for s in _widget_sources(d, w):
        for cid in (cfg["columns"].get(str(s["board_id"])) or []):
            out.append((s["board_id"], str(cid)))
    return out


def _dash_cell_text(db, t, col, cols, viewer, today):
    """One cell, as the text a row shows — never as markup.

    A list is read, not computed, so a status comes back as its label and a
    date as the day somebody wrote. The one thing it must not do is show a
    value the viewer may not see, and that is settled before this is
    reached: a column they lack is part of the widget\'s required sources, so
    the whole widget is blocked rather than this cell being blanked.
    """
    ctype = (col or {}).get("type")
    cid = str(col.get("id"))
    cf = t.custom_fields or {}
    if ctype == "created_at":
        return t.created_at.isoformat()[:10] if t.created_at else ""
    if ctype == "created_by":
        u = db.query(User.name).filter(User.id == t.created_by).scalar() if t.created_by else None
        return u or ""
    if ctype == "item_id":
        return str(t.item_uid or "")
    if ctype == "formula":
        kind, got = _dash_formula_number(db, t, col, cols, today)
        if kind == "value":
            return got
        # a formula that answers text is still a thing to read in a list,
        # which is exactly where it is NOT a quantity
        try:
            v = formula.evaluate(col.get("formula"), _dash_formula_lookup(db, t, col, cols), today)
            return "" if v is None else v
        except formula.FormulaError:
            return None                      # the row says "לא ניתן לחשב"
    v = cf.get(cid)
    if v in (None, "", [], {}):
        return ""
    if ctype == "people":
        ids = [x.get("id") if isinstance(x, dict) else x for x in v] if isinstance(v, list) else []
        names = {i: n for i, n in db.query(User.id, User.name)
                 .filter(User.id.in_([i for i in ids if isinstance(i, int)] or [0])).all()}
        return ", ".join(names[i] for i in ids if i in names)
    if ctype == "checkbox":
        return "כן" if v else "לא"
    if ctype == "timeline" and isinstance(v, dict):
        a, b = v.get("from") or v.get("start"), v.get("to") or v.get("end")
        return f"{a} – {b}" if a and b else (a or b or "")
    if isinstance(v, dict):
        return v.get("label") or v.get("text") or ""
    if isinstance(v, list):
        return ", ".join(str(x) for x in v if x not in (None, ""))
    return v


def _dash_formula_lookup(db, t, col, cols):
    """The lookup `_dash_formula_number` builds, reused for a text answer."""
    by_title = {}
    for c in cols:
        ttl = (c.get("title") or "").strip()
        if ttl and c.get("id") != col.get("id"):
            by_title.setdefault(ttl, c)
    cf = t.custom_fields or {}

    def lookup(ref):
        c = by_title.get(str(ref).strip())
        if c is None:
            raise formula.FormulaError("אין עמודה בשם " + str(ref))
        v = cf.get(c["id"])
        if c.get("type") == "checkbox":
            return 1 if v else 0
        if c.get("type") == "number":
            return None if v is None or v == "" else formula._fnum(v)
        if isinstance(v, dict):
            return formula._ftext(v.get("label") or v.get("text") or "")
        return v
    return lookup


def _dash_list(db, d, w, user_id, temp=None):
    """A list widget: the records themselves, with the columns it was given.

    Capped at LIST_MAX_ROWS and saying how many there are in total, because
    a list that silently shows the first ten of four hundred is the "חיתוך
    בשקט" R10 forbids — the count beside it is what makes the ten honest.
    """
    cfg = _dash_list_cfg(w)
    computed_at = datetime.now(timezone.utc)
    base = {"widget_id": w.id, "type": "list",
            "config_version": d.config_version or 1,
            "computed_at": computed_at,
            "conditions": _dash_conditions(d, w, temp),
            "temporary_filter": bool((temp or {}).get("adv")),
            "can_fix": _dash_access(db, d, user_id) == "owner"}
    if _widget_state(db, d, w, user_id) == "blocked":
        return dict(base, state="blocked", rows=[], columns=[])
    records, blocked_field = _dash_matching(db, d, w, user_id, temp)
    if blocked_field is not None:
        return dict(base, state="needs_fix", rows=[], columns=[],
                    reason="לא ניתן להחיל מסנן — חסר מיפוי לשדה",
                    field=(None if blocked_field == "__bad__" else blocked_field))

    today, _off = _dash_clock(db)
    wanted = _dash_list_columns(db, d, w)
    # The column list is per board, and a list over several boards shows the
    # union: a row simply has nothing under a column its own board does not
    # have, which is truer than hiding the column for everybody.
    headers, seen = [], set()
    for bid, cid in wanted:
        col = next((c for c in _dash_cols(db, bid) if str(c.get("id")) == cid), None)
        if col is None:
            continue
        key = (col.get("title") or cid)
        if key in seen:
            continue
        seen.add(key)
        headers.append({"key": cid, "label": key, "type": col.get("type")})

    sort = cfg["sort"]
    rev = sort["direction"] == "desc"
    if sort["field"] == "title":
        records = sorted(records, key=lambda t: (t.title or ""), reverse=rev)
    elif sort["field"] == "created_at":
        records = sorted(records, key=lambda t: (t.created_at or datetime.min), reverse=rev)

    names = {b.id: b.name for b in db.query(Board).filter(
        Board.id.in_({t.board_id for t in records} or {0})).all()}
    rows = []
    for t in records[:cfg["limit"]]:
        role = _board_role(db, t.board_id, user_id)
        cols = _dash_cols(db, t.board_id)
        cells = {}
        for h in headers:
            col = next((c for c in cols if (c.get("title") or c.get("id")) == h["label"]), None)
            if col is None:
                cells[h["key"]] = None
                continue
            cells[h["key"]] = _dash_cell_text(db, t, col, cols, user_id, today)
        rows.append({"id": t.id, "title": t.title, "board_id": t.board_id,
                     "board_name": names.get(t.board_id, ""),
                     "kind": "subitem" if t.parent_id else "item",
                     "my_perm": _item_perm(t, user_id, role),
                     "cells": cells})
    return dict(base, state=("ok" if rows else "no_data"),
                columns=headers, rows=rows,
                records=len(records), shown=len(rows),
                limit=cfg["limit"], sort=sort)


def _dash_compute(db, d, w, user_id, temp=None):
    """The compute response for one widget — the contract DASH-01.3 names.

    "תוצאה, זמן חישוב, גרסת הגדרות, יחידה, מספר רשומות וערכים שהשתתפו
    בחישוב, מצב תקין או שגיאה, ומזהי קטגוריה, סדרה ומדד לפתיחת הפירוט."

    A blocked widget carries none of it. Not the result, not the record
    count, not the sources — R01 forbids "מידע שניתן להסיק ממנו כמויות
    וסכומים", and a population size is exactly that.
    """
    computed_at = datetime.now(timezone.utc)
    state = _widget_state(db, d, w, user_id)
    base = {"widget_id": w.id, "config_version": d.config_version or 1,
            "computed_at": computed_at,
            "conditions": _dash_conditions(d, w, temp),
            "temporary_filter": bool((temp or {}).get("adv")),
            # DASH-20.2 — "הקישור לתיקון יוצג למורשה בלבד". Answered here
            # rather than inferred in the browser: a viewer shown a repair
            # link would be sent to a screen that then refuses them, which
            # reads as a broken product rather than as a permission.
            "can_fix": _dash_access(db, d, user_id) == "owner"}
    if state == "blocked":
        return dict(base, state="blocked", metrics=[])
    records, blocked_field = _dash_matching(db, d, w, user_id, temp)
    if blocked_field is not None:
        # DASH-10.3 — a condition that could not be applied stops the
        # measure rather than running without it. The field is named: it is
        # the dashboard's own configuration, not a board's secret, and
        # whoever can fix it needs to know which one.
        return dict(base, state="needs_fix", metrics=[],
                    reason="לא ניתן להחיל מסנן — חסר מיפוי לשדה",
                    field=(None if blocked_field == "__bad__" else blocked_field))
    metrics = w.metrics or []
    if not metrics:
        # A widget with no measure defined yet. Not an error and not a zero:
        # there is nothing to compute, and saying "0" would invent a fact.
        metrics = [{"key": "count", "calc": "count"}]
    out = [_dash_metric(db, d, w, m, records, user_id) for m in metrics]
    if state == "needs_fix" or any(m["state"] == "needs_fix" for m in out):
        overall = "needs_fix"
    elif all(m["state"] == "no_data" for m in out):
        overall = "no_data"
    else:
        overall = "ok"
    return dict(base, state=overall, metrics=out, records=len(records))


@app.post("/api/dashboards/{dash_id}/widgets/{widget_id}/compute")
def compute_widget(dash_id: int, widget_id: int, data: dict = None,
                   user_id: int = Depends(current_user_id)):
    """Work this widget out, now, for this reader.

    POST and not GET because the temporary filter travels with it: "צופה מסנן
    זמנית לאורך הביקור בלבד, ללא השפעה על אחרים" (R05), and a visit's own
    filter is a body rather than a saved setting.
    """
    data = data or {}
    with Session(engine) as db:
        d, _access = _dash_or_404(db, dash_id, user_id)
        w = (db.query(DashboardWidget)
               .filter(DashboardWidget.id == widget_id,
                       DashboardWidget.dashboard_id == d.id).first())
        if w is None:
            raise HTTPException(404, "הווידג׳ט אינו קיים")
        # A visitor's own filter, for this request and no longer. Validated
        # like any other tree — a temporary filter that cannot be parsed is
        # told about rather than dropped — but never written anywhere, so
        # "איפוס יחזיר למסננים השמורים" is simply the next request without it.
        temp = _dash_validate_filters(data.get("temp_filter"))
        if w.type == "list":
            return _json(_dash_list(db, d, w, user_id, temp))
        return _json(_dash_compute(db, d, w, user_id, temp))


@app.post("/api/dashboards/{dash_id}/compute")
def compute_dashboard(dash_id: int, data: dict = None,
                      user_id: int = Depends(current_user_id)):
    """Every widget at once, each answering for itself.

    R09 — "טעינה וכשל נפרדים לכל ווידג׳ט; כשל יחיד לא חוסם אחרים." So a
    widget that cannot be computed comes back with its own state beside the
    ones that could, and never as an error for the whole dashboard.
    """
    with Session(engine) as db:
        d, _access = _dash_or_404(db, dash_id, user_id)
        ws = (db.query(DashboardWidget)
                .filter(DashboardWidget.dashboard_id == d.id)
                .order_by(DashboardWidget.position, DashboardWidget.id).all())
        temp = _dash_validate_filters((data or {}).get("temp_filter"))
        out = []
        for w in ws:
            try:
                # Charts and figures answer through the same session, which is
                # the point of asking for them together: the population is
                # loaded once (see _dash_population) and every widget over the
                # same boards reads it rather than fetching it again.
                out.append(_dash_chart(db, d, w, user_id, temp) if w.type == "chart"
                           else _dash_list(db, d, w, user_id, temp) if w.type == "list"
                           else _dash_compute(db, d, w, user_id, temp))
            except HTTPException:
                raise
            except Exception as e:                 # noqa: BLE001
                # A calculation that threw is a server failure, which R04 separates
                # from every other state: "כשל שרת, שגיאת חישוב או מקור חסום
                # אינם מוצגים כ־0".
                print(f"⚠️  widget {w.id} failed to compute: {e}", flush=True)
                out.append({"widget_id": w.id, "state": "error",
                            "config_version": d.config_version or 1,
                            "metrics": []})
        return _json({"dashboard_id": d.id,
                      "config_version": d.config_version or 1,
                      "widgets": out})


DASH_PAGE_SIZE = 50
DASH_PAGE_MAX = 200


@app.post("/api/dashboards/{dash_id}/widgets/{widget_id}/records")
def widget_records(dash_id: int, widget_id: int, data: dict = None,
                   user_id: int = Depends(current_user_id)):
    """The records behind the measure — the drill-down of R10.

    "פירוט משתמש באותם מקורות, אוכלוסייה, מסננים, מדד והרשאות של הרכיב
    שנלחץ. הרשימה מעומדת אך המדד על כל הרשומות."

    Both halves of that sentence are structural here. The population comes
    from `_dash_matching`, the same call the measure makes, so the two cannot
    drift; and the totals reported beside the page are counted over the WHOLE
    population, never over the slice that was returned. The request carries
    no conditions of its own — only which widget, which measure and which
    page — because a drill-down that could filter independently could show a
    different set from the number that led to it, and that is the one thing
    R10 exists to prevent.
    """
    data = data or {}
    with Session(engine) as db:
        d, _access = _dash_or_404(db, dash_id, user_id)
        w = (db.query(DashboardWidget)
               .filter(DashboardWidget.id == widget_id,
                       DashboardWidget.dashboard_id == d.id).first())
        if w is None:
            raise HTTPException(404, "הווידג׳ט אינו קיים")
        # DASH-04.1 — "לפני חישוב **או פתיחת פירוט**". A blocked source
        # returns an empty block and not an empty page: a page of no rows is
        # itself a statement that the population is empty.
        if _widget_state(db, d, w, user_id) == "blocked":
            return _json({"widget_id": w.id, "state": "blocked", "rows": [],
                          "records": None, "values": None,
                          "config_version": d.config_version or 1})
        temp = _dash_validate_filters(data.get("temp_filter"))
        records, blocked_field = _dash_matching(db, d, w, user_id, temp)
        if blocked_field is not None:
            return _json({"widget_id": w.id, "state": "needs_fix", "rows": [],
                          "records": None, "values": None,
                          "field": (None if blocked_field == "__bad__" else blocked_field),
                          "config_version": d.config_version or 1})
        metrics = w.metrics or [{"key": "count", "calc": "count"}]
        want = str(data.get("metric") or "")
        # A chart element names its series, and the series carries the metric
        # — so clicking a bar opens the measure that bar was drawn from
        # without the caller having to say it twice.
        series = str(data.get("series") or "")
        if not want and series:
            want = _ser_metric(series)
        metric = next((m for m in metrics
                       if str(m.get("key") or "") == want), metrics[0])
        category = data.get("category")
        if category:
            records = _dash_narrow_to_cell(db, d, w, records, str(category),
                                           series, user_id)
        summary = _dash_metric(db, d, w, metric, records, user_id)
        try:
            offset = max(0, int(data.get("offset") or 0))
        except (TypeError, ValueError):
            offset = 0
        try:
            limit = int(data.get("limit") or DASH_PAGE_SIZE)
        except (TypeError, ValueError):
            limit = DASH_PAGE_SIZE
        limit = max(1, min(DASH_PAGE_MAX, limit))
        page = records[offset:offset + limit]
        calc = (metric.get("calc") or "count").lower()
        key = str(metric.get("field") or "")
        mirror_agg = (metric.get("mirror_agg") or "sum").lower()
        policy = (metric.get("empty_policy") or "ignore").lower()
        today, _off = _dash_clock(db)
        names = {b.id: b.name for b in db.query(Board).filter(
            Board.id.in_({t.board_id for t in page} or {0})).all()}
        rows = []
        for t in page:
            role = _board_role(db, t.board_id, user_id)
            entry = {"id": t.id, "title": t.title,
                     "board_id": t.board_id,
                     "board_name": names.get(t.board_id, ""),
                     # DASH-18.2 asks the list to say which kind of record
                     # each row is, because "both" mixes two populations and
                     # a reader cannot tell them apart by name.
                     "kind": "subitem" if t.parent_id else "item",
                     "my_perm": _item_perm(t, user_id, role)}
            if calc != "count" and key and key not in _DASH_BUILTIN_FIELDS:
                cid = ((w.mapping or {}).get(str(t.board_id)) or {}).get(key)
                col = next((c for c in _dash_cols(db, t.board_id)
                            if str(c.get("id")) == str(cid)), None) if cid else None
                if col is None:
                    entry.update(value=None, value_state="error")
                else:
                    kind, got = _dash_value(db, t, col, _dash_cols(db, t.board_id),
                                            user_id, mirror_agg=mirror_agg,
                                            today=today)
                    entry.update(value=(got if kind == "value" else None),
                                 value_state=kind)
                    if kind == "empty":
                        # DASH-14.3 — "בפירוט יופיעו גם רשומות ריקות
                        # ששייכות לאוכלוסייה, עם הסבר אם וכיצד הן משתתפות
                        # בחישוב." The row is here either way; this is the
                        # explanation that belongs beside it.
                        entry["empty_handling"] = (
                            "נספרת כאפס" if policy == "zero" else "לא משתתפת בחישוב")
            rows.append(entry)
        return _json({"widget_id": w.id, "state": summary["state"],
                      "metric": summary["key"], "calc": calc,
                      "category": category or None, "series": series or None,
                      "result": summary["result"], "unit": summary["unit"],
                      # Counted over the whole population and not over the
                      # page — R10's "הרשימה מעומדת אך המדד על כל הרשומות".
                      "records": summary["records"], "values": summary["values"],
                      "empty_policy": policy,
                      "offset": offset, "limit": limit,
                      "has_more": offset + limit < len(records),
                      "config_version": d.config_version or 1,
                      "computed_at": datetime.now(timezone.utc),
                      "rows": rows})


# ── the advanced filter, evaluated here ────────────────────────────────
# The client sends the condition tree as JSON — an AST, groups holding groups —
# and gets back the ids that answer it. It filters locally too, for the
# instant feedback a toolbar needs; this is the authority, and the only place
# that can answer for a board bigger than what the browser was handed.
#
# Two things the client must send, and the reason is the same for both: the
# only clock that can say what "היום" means is the one the person is reading.
#   `today`      — the client's own local date (YYYY-MM-DD)
#   `tz_offset`  — minutes east of UTC, so an instant stored in UTC can be
#                  turned into the day the viewer is having
# Without them the server's own date and UTC are used, which is right for a
# script and wrong for a person — so the report says which was used.
@app.post("/api/boards/{board_id}/items/query")
def query_board_items(board_id: int, data: dict, user_id: int = Depends(current_user_id)):
    with Session(engine) as db:
        b = db.query(Board).filter(Board.id == board_id).first()
        if not b or b.deleted_at:
            raise HTTPException(404, "board not found")
        # the same gate the board's own fetch uses — a filter must never be a
        # way to learn what is on a board you cannot open
        my_role = _board_role(db, board_id, user_id)
        if user_id is not None and my_role is None:
            raise HTTPException(403, "אין לך גישה ללוח זה")
        try:
            tree = filter_ast.parse(data.get("filter"))
        except filter_ast.BadFilter as e:
            # Named, not swallowed: a filter the server refuses and the client
            # keeps showing results for is the two disagreeing in silence.
            raise HTTPException(400, str(e))

        today = str(data.get("today") or "").strip()
        if not filter_ast._ISO_DAY.match(today):
            today = datetime.now(timezone.utc).date().isoformat()
            client_clock = False
        else:
            client_clock = True
        try:
            off = int(data.get("tz_offset") or 0)
        except (TypeError, ValueError):
            off = 0
        off = max(-14 * 60, min(14 * 60, off))

        # What each field can be asked about — built-ins, then the board's own.
        #
        # Two maps, because "the column is gone" and "you may not see it" are
        # different answers and the person deserves the right one. `fields` is
        # what this reader may filter by; `known` is every column the board
        # has, used only to tell the two apart in the report.
        # A column taken off the board is not one to filter by, and the
        # built-ins were added here whatever the board said — so a board whose
        # admin had used "מחק עמודה" on סטטוס went on answering filters about
        # it while the browser drew no such column. "שם הפריט" is exempt: it is
        # the item itself and the board cannot hide it.
        _off = {str(k) for k in ((b.settings or {}).get("col_hidden") or [])}
        base = {k: v for k, v in (("title", "text"), ("status", "status"),
                                  ("priority", "status"), ("assignees", "people"),
                                  ("due", "date"))
                if k == "title" or k not in _off}
        fields, known = dict(base), dict(base)
        known, fields = _filter_columns(b, user_id, my_role, known, fields)

        # A rule naming a column that was deleted comes OUT of the tree rather
        # than being made to answer true — inside an "or" group the two are
        # opposites, and the second quietly shows the whole board. The caller
        # is told which, so it can say so.
        #
        # A rule naming a column this reader may not SEE comes out for the
        # same reason and a different one: running it would answer a question
        # about hidden data with a row set, and a row set is an answer. Which
        # of the two happened is reported separately — "the column was
        # deleted" and "you may not see it" are different facts about the
        # board, and telling somebody the wrong one is its own small lie.
        tree, gone = filter_ast.prune(tree, fields)
        denied = [f for f in gone if f in known]
        dropped = [f for f in gone if f not in known]
        if denied and FILTER_COLUMN_POLICY == "block":
            raise HTTPException(403, "התצוגה מסננת לפי עמודה שאינך מורשה לראות")
        # A SAVED view naming a column the board no longer has does not run at
        # all — "לא תציג תוצאות חלקיות מטעות". Dropping the dead rule and
        # answering anyway is the misleading part: inside an "or" group it
        # shows the whole board with the filter apparently on.
        #
        # Only when the request says which view it came from. A filter somebody
        # is building by hand cannot name a column that is not on the board —
        # the picker offers what exists — so this is about a cut that was saved
        # while the column was still there.
        if dropped and data.get("view_id"):
            raise HTTPException(409, "התצוגה מסננת לפי עמודה שנמחקה מהלוח — יש לתקן אותה")

        # Ordered, and not by chance: pages are cut out of this list, and a
        # list whose order is whatever the database felt like means page two
        # can repeat a row from page one and skip another entirely.
        #
        # The people on each row are loaded WITH the rows, and that is not a
        # micro-optimisation. Every row here is asked for its assignees — the
        # toolbar's people filter reads them, and the shape the condition tree
        # matches against carries them — and the relationship is lazy, so a
        # board of fifteen thousand items asked the database fifteen thousand
        # and eleven times for one keystroke in the search box. That is the
        # whole of why free-text search on a large board took seconds: not the
        # matching, which is a string compare, but the round trip per row.
        rows = (db.query(Task)
                  .options(selectinload(Task.assignees))
                  .filter(Task.board_id == board_id, Task.parent_id.is_(None),
                          Task.is_archived == False, Task.deleted_at.is_(None))
                  .order_by(Task.position, Task.id)
                  .all())
        # and an item this person may not see is not an item this answers for
        #
        # An assigned member's "is this mine" is answered for the whole board
        # in one go (_assign_scope) — per row it is a lazy load each.
        _pc = _assign_scope(db, b, user_id) if my_role in ASSIGNED_ROLES else None
        if user_id is not None:
            rows = [t for t in rows if _item_perm(t, user_id, my_role, _pc) != "none"]

        # "אם עדכון גורם לפריט להפסיק להתאים למסנן, הוא יוסתר לאחר השמירה
        # ותוצג הודעה עם קישור לפריט."
        #
        # Somebody edits a cell and the row they were working on may no longer
        # belong in the cut. Answering that from a PAGE of ids cannot be done:
        # the page holds the first fifty matches, and an item absent from it
        # has either stopped matching or simply sits further down. `ids_only`
        # is no better past its cap, where the honest answer is "truncated".
        #
        # So the question can be asked about named items instead, and then it
        # is exact whatever the board's size: these ids, which of them still
        # match. Everything else about the request is unchanged — the same
        # filter, the same toolbar, the same permissions — because the point
        # is to ask the SAME question about one row.
        only = data.get("only")
        if isinstance(only, list):
            want = {int(x) for x in only if str(x).lstrip("-").isdigit()}
            rows = [t for t in rows if t.id in want]
        # The toolbar's own filters, applied alongside the tree.
        #
        # They have to be here, and the reason is not completeness. On a
        # large board the server's answer IS what the browser shows — the
        # local pass is skipped, because re-filtering a page against the rows
        # this browser happens to hold is the half the server was asked to
        # replace. So a toolbar filter the server does not know about is a
        # filter that silently stops working at exactly the board size where
        # filtering matters most.
        q = str(data.get("q") or "").strip().lower()
        want_people = {int(x) for x in (data.get("people") or []) if str(x).isdigit()}
        want_status = str(data.get("status") or "")
        want_prio = str(data.get("priority") or "")

        # ── what the free-text box actually searches ─────────────────────
        # "רשות" is a column on the board, and somebody typing a municipality
        # into the search box means "the items whose רשות is that one". The box
        # read four things — the title, the description, the item's number and
        # the people on it — so every column the board arranges itself BY was
        # unsearchable, and on a large board, where this answer is the whole of
        # what the screen shows, there was nothing else to fall back on.
        #
        # So the board's own cells are read too. Only columns this reader may
        # SEE: a hidden column that narrowed the board would be answering a
        # question about hidden data with a row set, and a row set is an
        # answer. A mirror is left out — it is a field of a LINKED item,
        # resolved per row per column, and reading every one of them on every
        # keystroke is the cost this endpoint has just stopped paying.
        all_cols = (b.settings or {}).get("columns") or []
        seen_cols = [c for c in all_cols
                     if user_id is None or _col_perm(c, user_id, my_role) != "none"]
        # EVERY column, not a chosen few. The first pass at this left four
        # kinds out and each one was a value somebody could read off the board
        # and not find: a people cell (it stores ids), a date (it stores ISO
        # and shows dd/mm/yyyy), a tick, and a mirror. A column the board
        # draws is a column the search box answers for — that is the whole
        # rule, and the exceptions below are the two that cannot be kept.
        #
        # CONNECT is handled apart rather than skipped: its cell holds ids,
        # and the words are the TITLES at the other end — see
        # _linked_title_hits, which resolves them in three queries for the
        # whole board instead of one per cell.
        #
        # FORMULA is the one column this cannot answer for, and it is said
        # out loud rather than left to be discovered: it is computed and never
        # stored, and the engine that computes it lives in the browser. The
        # browser leaves it out too — a board that crosses the client
        # threshold overnight must not change what it finds.
        search_cols, mirror_cols, status_vocab = [], [], {}
        if q:
            for c in seen_cols:
                cid, ctype = str(c.get("id") or ""), c.get("type")
                if ctype in ("connect", "formula"):
                    continue
                if ctype == "mirror":
                    mirror_cols.append(c)
                    continue
                search_cols.append((cid, ctype))
                if ctype == "status":
                    status_vocab[cid] = {str(o["key"]): o["label"]
                                         for o in _status_vocab(b, cid)[0]}
        # …and the three columns that store nothing of their own: מועד יצירה,
        # יוצר הרשומה and מזהה פריט are read off the item, not out of its
        # cells, so they reach the haystack the way the filter engine gets
        # them — through _derived_cells.
        derived_cols = [(str(c.get("id") or ""), c.get("type")) for c in seen_cols
                        if q and c.get("type") in DERIVED_CELLS]
        # Filled once the sub-items are loaded too — see below. Declared here
        # because _searchable closes over it and runs long after.
        people_names = {}

        def _searchable(t):
            """(substring words, whole words) — everything on this row
            somebody could be typing, and see _searchable_words for why a tick
            is the one that is matched whole."""
            hay = [(t.title or ""), (t.description or ""), str(t.item_uid or "")]
            hay += [u.name or "" for u in t.assignees]
            exact = []
            cf = t.custom_fields or {}
            cells = [(cf.get(cid), ct, status_vocab.get(cid)) for cid, ct in search_cols]
            if derived_cols:
                d = _derived_cells(b, t)
                cells += [(d.get(cid), ct, None) for cid, ct in derived_cols]
            for v, ct, voc in cells:
                sub, whole = _searchable_words(ct, v, people_names, voc)
                hay += sub
                exact += whole
            for col in mirror_cols:
                hay += [c.get("text") or ""
                        for c in (_mirror_cells(db, t, col, user_id, seen_cols) or [])]
            return hay, exact

        def _passes_toolbar(t):
            if want_status and _task_status_key(t) != want_status:
                return False
            if want_prio and _task_priority_key(t) != want_prio:
                return False
            if want_people and not ({u.id for u in t.assignees} & want_people):
                return False
            if q:
                hay, exact = _searchable(t)
                if any(q in h.lower() for h in hay):
                    return True
                if any(q == e.lower() for e in exact):
                    return True
                return t.id in link_hits
            return True

        # ── the hierarchy rules ──────────────────────────────────────────
        # A condition is asked of sub-items as well, and the four combinations
        # have four different answers:
        #
        #   parent matches, a sub matches  → the parent and the matching subs
        #   parent matches, none does      → the parent alone, no subs under it
        #   parent does not, a sub does    → the parent AS CONTEXT, matching subs
        #   neither                        → not shown
        #
        # Two things fall out of that and are easy to get wrong. A parent that
        # matches still shows only the sub-items that match — a cut is a cut
        # all the way down, and showing the rest under a matching parent would
        # answer a different question on every row. And a parent present only
        # because of its children is marked, because it is there to say WHERE
        # they are: unmarked, it reads as a row that answered the filter.
        subs_all = (db.query(Task)
                      .options(selectinload(Task.assignees))
                      .filter(Task.board_id == board_id, Task.parent_id.isnot(None),
                              Task.is_archived == False, Task.deleted_at.is_(None))
                      .order_by(Task.position, Task.id)
                      .all())
        if user_id is not None:
            # the same gate the parents went through — a sub-item somebody may
            # not see cannot pull its parent into the answer either
            subs_all = [t for t in subs_all if _item_perm(t, user_id, my_role, _pc) != "none"]
        if isinstance(only, list):
            subs_all = []          # a question about named rows is about those rows

        # One name per user id, for every people cell on the board at once.
        # A query per cell is the shape this endpoint has just stopped paying
        # for, and a people column on a large board is thousands of them.
        if q and any(ct in ("people", "created_by", "assignees")
                     for _cid, ct in search_cols + derived_cols):
            want = set()
            for t in rows + subs_all:
                for cid, ct in search_cols:
                    if ct in ("people", "created_by", "assignees"):
                        for x in (t.custom_fields or {}).get(cid) or []:
                            if isinstance(x, int):
                                want.add(x)
                if t.created_by is not None:
                    want.add(t.created_by)
            ids = sorted(want)
            for part in [ids[i:i + _PREFETCH_CHUNK]
                         for i in range(0, len(ids), _PREFETCH_CHUNK)]:
                for uid_, nm in db.query(User.id, User.name).filter(User.id.in_(part)):
                    people_names[uid_] = nm or ""

        # A mirror is a field of a LINKED item, so resolving one costs a query
        # per row per column — 750ms and five thousand queries on a board of
        # five thousand, which is why it was left out of the search at first.
        # That was a fact about the naive path and not about the column:
        # warming the links once first brings the same work to 98ms and
        # eighteen queries, which a search can afford. Only when the board
        # actually has one.
        if q and mirror_cols:
            _prefetch_links(db, rows + subs_all, seen_cols, user_id)

        # …and the other half of the search: the items THESE rows point at.
        # Computed here, over the parents and the sub-items together, because
        # it is one pass over the whole board whichever of them asks for it.
        link_hits = _linked_title_hits(db, rows + subs_all, seen_cols, q, user_id) \
            if q else set()

        total = len(rows)

        def _asked(t):
            """Does this row answer the cut — the conditions and the search."""
            item = {
                "id": t.id, "title": t.title,
                "status": _task_status_key(t), "priority": _task_priority_key(t),
                "due_date": t.due_date.isoformat() if t.due_date else None,
                "assignees": [{"id": u.id} for u in t.assignees],
                # …and the columns nobody typed, beside the ones somebody did
                "custom_fields": {**(t.custom_fields or {}), **_derived_cells(b, t)},
            }
            return (_passes_toolbar(t)
                    and filter_ast.match(item, tree, fields, today, off, user_id))

        own = {t.id for t in rows if _asked(t)}
        # matching sub-items, kept in the board's own order under their parent
        kids_hit = {}
        for sub in subs_all:
            if _asked(sub):
                kids_hit.setdefault(sub.parent_id, []).append(sub)
        # a parent appears if it answered, or if one of its children did
        hits = [t for t in rows if t.id in own or t.id in kids_hit]
        # present only to say where the children are — see the rules above
        context_only = {t.id for t in hits if t.id not in own}

        # ── a matching sub-item whose PARENT is not this person's to see ──
        # The permission model allows it: a sub-item carries its own overrides,
        # so somebody can be let into a line of a work plan without being let
        # into the plan. Dropping the parent used to drop the sub-item with
        # it — the row hangs under its parent — so a match they are entitled
        # to simply vanished.
        #
        # Instead the parent comes back as a neutral wrapper: a place to hang
        # the children, carrying no title, no values, no people, no dates.
        # "ולא לחשוף את פרטי האב" is the whole of its content. It is marked
        # both as context and as restricted, because the two mean different
        # things to the screen — one is "this row did not match", the other is
        # "there is nothing here to show you".
        seen_parents = {t.id for t in rows}
        shell_ids = [pid for pid in kids_hit if pid not in seen_parents]
        shells = []
        if shell_ids:
            shells = (db.query(Task)
                        .filter(Task.id.in_(shell_ids), Task.board_id == board_id)
                        .order_by(Task.position, Task.id).all())
        matched = len(hits) + len(shells)

        # ── then sort, over everything that matched ──────────────────────
        # "סינון ומיון חלים על כלל נתוני הלוח המורשים, גם בטעינה מדורגת."
        #
        # Sorting used to be the browser's alone, over the rows it happened to
        # hold. Below the client threshold that is every row and the two are
        # the same thing; past it the server answers with a PAGE, and sorting
        # a page is not sorting the board — it orders fifty rows that were
        # chosen by position and calls the result sorted. Page two then
        # repeats and skips, because each page is ordered against itself.
        #
        # So the order is applied here, after the filter and before the page
        # is cut, which is also the order the spec gives: permissions, then
        # the conditions and the search, then sort, then the hierarchy.
        #
        # The same three keys the toolbar offers and a view stores. Per-COLUMN
        # sorting (the arrows on a header) is still the browser's own and is
        # still wrong past the threshold — it is not part of a saved view's
        # configuration, and giving it the same treatment is its own change.
        prio_rank = {p["key"]: i for i, p in enumerate(_board_priorities(b))}
        _SORTS = {
            # a missing date sorts last, exactly as the browser does it
            "due": lambda t: (t.due_date is None, t.due_date or date.min),
            "priority": lambda t: prio_rank.get(_task_priority_key(t), 998),
            "title": lambda t: (t.title or ""),
        }
        want_sort = str(data.get("sort") or "")
        if want_sort in _SORTS:
            # ── inside the groups, never across them ─────────────────────
            # "סדר הקבוצות נשאר לפי מבנה הלוח. המיון חל בתוך קבוצות ... ואינו
            # מפרק את ההיררכיה."
            #
            # A flat sort reorders the whole board and the groups dissolve:
            # rows from three of them interleave by due date and the board
            # stops being the thing it was arranged into. Groups are
            # structure, not a result — they keep the order the board gives
            # them, and the sort decides who sits where INSIDE each one.
            gpos = {g.id: (g.position or 0, g.id) for g in
                    db.query(Group).filter(Group.board_id == board_id).all()}
            inner = _SORTS[want_sort]
            # a row with no group sorts after the groups, not before them
            hits.sort(key=lambda t: (gpos.get(t.group_id, (10 ** 9, 0)), inner(t),
                                     t.position or 0, t.id))
            # and the same order under each parent, for the same reason: a
            # sort that reordered items but left their children in position
            # order would be two orders on one screen
            for pid in kids_hit:
                kids_hit[pid] = sorted(kids_hit[pid],
                                       key=lambda t: (inner(t), t.position or 0, t.id))

        out = {"matched": matched, "total": total,
               # how many of the rows answered the cut themselves, and how many
               # sub-items did — "3 items" over a list where one of them is
               # only context would be a lie the screen cannot correct
               # Three different numbers, and conflating any two of them
               # misstates the answer: how many top-level items matched, how
               # many sub-items did, and how many rows are on screen only to
               # say where those sub-items are. A context row is not a result.
               # All three count what MATCHED, not what the page happened to
               # load.
               "matched_own": len(own),
               "matched_subs": sum(len(v) for v in kids_hit.values()),
               "matched_context": len(context_only) + len(shells),
               "sort": want_sort if want_sort in _SORTS else "",
               "conditions": filter_ast.count(tree),
               # the rules that could not be run, so the caller can say why
               # the answer is wider than the view promised — and which of
               # the two reasons it was
               "dropped_fields": dropped,
               "denied_fields": denied,
               "column_policy": FILTER_COLUMN_POLICY,
               "client_max": FILTER_CLIENT_MAX,
               # so a caller can see which clock answered "היום"
               "today": today, "tz_offset": off, "client_clock": client_clock}

        # Two ways to answer, and which one is right depends on the board.
        #
        # `ids_only` is the small-board answer: the browser already holds
        # every row and only needs to know which of them survive. It is
        # capped at the same threshold that decides the mode in the first
        # place — past that the browser should not have been asking this way.
        #
        # Otherwise a PAGE of rows, serialised. A board of tens of thousands
        # must never arrive in one response: not because this cannot build
        # it, but because the browser cannot draw it, and the request blocks
        # everything behind it while it tries. Only the page is serialised —
        # the rows that did not make it onto it cost a comparison each and
        # nothing more.
        if isinstance(only, list):
            # the ids asked about that survive, and nothing else: a caller
            # asking about one row must not be handed a page of others
            out["item_ids"] = [t.id for t in hits]
            out["asked"] = sorted(want)
            return out

        if data.get("ids_only"):
            out["item_ids"] = [t.id for t in hits[:FILTER_CLIENT_MAX]]
            out["truncated"] = matched > FILTER_CLIENT_MAX
            return out

        try:
            limit = int(data.get("limit") or QUERY_PAGE)
        except (TypeError, ValueError):
            limit = QUERY_PAGE
        limit = max(1, min(QUERY_PAGE_MAX, limit))
        try:
            offset = max(0, int(data.get("offset") or 0))
        except (TypeError, ValueError):
            offset = 0
        # The wrappers sit at the end of the board's own order, which is where
        # a row with nothing to read belongs: it is scaffolding, not a result.
        ordered = hits + shells
        page = ordered[offset:offset + limit]
        _subs = _prefetch_items(db, page)
        # _prefetch_items has just filled _kids_by with EVERY child of every
        # row on the page. Narrow it to the ones that matched, which is what
        # _serialize_task reads: a parent that answered the cut still shows
        # only the children that did, and one that answered nothing shows none.
        db.info["_kids_by"] = {t.id: kids_hit.get(t.id, []) for t in page}
        _subs = [s for t in page for s in kids_hit.get(t.id, [])]
        _prefetch_links(db, list(page) + _subs, (b.settings or {}).get("columns", []), user_id)
        cols = (b.settings or {}).get("columns", [])
        shell_set = {t.id for t in shells}

        def _row_json(t):
            if t.id in shell_set:
                return _context_shell(t, kids_hit.get(t.id, []), db,
                                      user_id=user_id, board_role=my_role, columns=cols)
            return dict(_serialize_task(t, db, user_id=user_id, board_role=my_role,
                                        columns=cols),
                        context_only=(t.id in context_only), restricted=False)

        out["items"] = [_row_json(t) for t in page]
        # The same override map the board payload carries, for the rows on THIS
        # page — {col_id: {item_id: text}} for a connect column told to show a
        # field of the linked record instead of its title.
        #
        # It has to be here because of where the board payload stopped sending
        # it: above FILTER_CLIENT_MAX the board answers with no tasks, so
        # _board_link_display over an empty list correctly returns {}, and the
        # browser then had nothing to override titles with. A connect column
        # configured to show, say, the linked record's status quietly showed
        # titles instead — the wrong text, with nothing to tell anyone. The
        # browser merges each page's map into what it already holds, so a row
        # is covered from the moment its page arrives.
        #
        # Free, for the same reason it is free on the board: _prefetch_links
        # ran over this page a few lines up and warmed _task_by/_board_by, the
        # two caches _link_display_map reads. It is not an N+1 over the page.
        out["link_display"] = _board_link_display(db, out["items"], cols, user_id)
        out["item_ids"] = [t.id for t in page]
        out["offset"] = offset
        out["limit"] = limit
        out["has_more"] = (offset + len(page)) < matched
        out["next_offset"] = offset + len(page)
        return out


@app.get("/api/boards/{board_id}")
def get_board(board_id: int, user_id: int = Depends(current_user_id)):
    # "It still takes a long time" was reported on one production board (204)
    # after a fix, and nothing on the server could say where the time went:
    # App Service logging is off and this route timed nothing. So every phase
    # below is clocked and sent back as a Server-Timing header, which the
    # browser's own board-open line prints next to its request and render
    # times. The next "it is slow" then arrives with the answer attached —
    # the sweeps, the permission pass, the serialization — instead of a guess.
    _clock = [time.perf_counter()]
    _phases = []

    def _lap(name):
        now = time.perf_counter()
        _phases.append((name, (now - _clock[0]) * 1000))
        _clock[0] = now

    with Session(engine) as db:
        b = db.query(Board).filter(Board.id == board_id).first()
        if not b:
            raise HTTPException(404, "Board not found")
        if b.deleted_at:                     # in the recycle bin — restore it first
            raise HTTPException(404, "הלוח נמצא בסל המחזור")
        # date-based automations have no scheduler — opening the board is when
        # "the due date arrived" is noticed (each rule fires once per item)
        _sweep_due_date_automations(db, board_id, user_id)
        _lap("sweep_due")
        # and the same for the rules on a clock, which come round again rather
        # than firing once (see _sweep_recurring_automations)
        _sweep_recurring_automations(db, board_id, user_id)
        _lap("sweep_recurring")
        # and the rules watching for an item nobody has written on
        _sweep_chat_idle_automations(db, board_id, user_id)
        _lap("sweep_idle")
        my_role = _board_role(db, board_id, user_id)
        if user_id is not None and my_role is None:
            raise HTTPException(403, "אין לך גישה ללוח זה")
        groups = db.query(Group).filter(Group.board_id == b.id).order_by(Group.position).all()
        # ── how many items, and therefore whether any of them travel ─────
        # Above FILTER_CLIENT_MAX the browser does not filter locally: it
        # fetches its rows fifty at a time from /items/query and never looks
        # at `tasks` at all. It was still being sent every one of them —
        # 28.7MB and five seconds on the imported board of 21,187 items,
        # built at full cost and then thrown away on arrival, which is also
        # the freeze somebody sees while a large board "opens".
        #
        # So the count is taken first and decides. It is the number the
        # browser reads to pick its mode (`boardRowCount`), so it has to be
        # the true total and not len(tasks) — a board that answered with no
        # rows and no count would read as empty, and one that counted only
        # what it sent would flip itself back into local filtering over
        # nothing. Counted in SQL: loading the board to measure it is the
        # cost being removed.
        item_count = _board_item_count(db, board_id, user_id)
        # strictly greater, the same comparison filterMode() makes — a board
        # sitting exactly on the threshold filters locally and needs its rows
        paged = item_count > FILTER_CLIENT_MAX
        _lap("item_count")
        # only top-level items as rows; sub-items are nested under their parent
        # position, and then id — because "position" is not unique and never was.
        # Two items can claim one slot (every board that predates the fix in
        # create_task has groups where they do), and ORDER BY position alone
        # leaves the tie to SQLite, which is free to answer differently on
        # consecutive reads. That is rows swapping places on a refresh nobody
        # asked for anything by. The id is arbitrary as a rule and that is the
        # point: it is the same arbitrary answer every time, and it puts the
        # newer of two tied items below the older, which is where it was added.
        tasks = [] if paged else (
            db.query(Task).filter(Task.board_id == b.id, Task.is_archived == False,
                                  Task.parent_id == None).order_by(Task.position, Task.id).all())
        dept_name = db.query(Department.name).filter(Department.id == b.department_id).scalar() or ""
        columns = (b.settings or {}).get("columns", [])
        # a board carrying a "מזהה פריט" column shows an identifier for every
        # item — including ones that predate the column, or arrived from elsewhere
        _lap("items_query")
        if _board_has_item_id_col(b):
            _backfill_item_uids(db, b.id)
        _lap("item_uids")
        # hide items the user has no view permission on — an assigned member's
        # "is it mine" asked once for the board, not lazily per row
        _scope = _assign_scope(db, b, user_id) if my_role in ASSIGNED_ROLES else None
        _hidden = []
        if user_id is not None:
            _kept = [t for t in tasks if _item_perm(t, user_id, my_role, _scope) != "none"]
            if my_role == "assigned_only":
                _ok = {t.id for t in _kept}
                _hidden = [t for t in tasks if t.id not in _ok]
            tasks = _kept
        # one pass for everything an item is about to be asked — its sub-items,
        # assignees and counts (_prefetch_items), then its links (_prefetch_links)
        _subs = _prefetch_items(db, tasks)
        _lap("prefetch_items")
        _prefetch_links(db, list(tasks) + _subs, columns, user_id)
        _lap("prefetch_links")
        tasks_out = [_serialize_task(t, db, user_id=user_id, board_role=my_role, columns=columns) for t in tasks]
        # An assigned_only member named on a SUB-item of an item that is not
        # theirs would otherwise see nothing at all here: the board's rows are
        # its top-level items, and the parent is not theirs to see. The paged
        # fetch already answers this with a context shell (see _context_shell
        # in /items/query) — an empty wrapper holding the sub-items they may
        # read — and the board does the same, at the end like there.
        if _hidden:
            # Only the sub-items this member may see are loaded at all — cut in
            # SQL by the same condition the count uses — and of those, the
            # ones under a parent that was hidden. A visible parent's own
            # sub-items already travel inside it.
            _kids, _hid = {}, {t.id for t in _hidden}
            for sub in (db.query(Task)
                          .filter(Task.board_id == b.id, Task.parent_id.isnot(None),
                                  Task.is_archived == False,                 # noqa: E712
                                  _assigned_only_sql(db, b, user_id))
                          .order_by(Task.position, Task.id).all()):
                if (sub.parent_id in _hid
                        and _item_perm(sub, user_id, my_role, _scope) != "none"):
                    _kids.setdefault(sub.parent_id, []).append(sub)
            tasks_out += [_context_shell(t, _kids[t.id], db, user_id=user_id,
                                         board_role=my_role, columns=columns)
                          for t in _hidden if t.id in _kids]
        _lap("serialize")

        # board owners = members with the board-scoped admin role (creator + any
        # promoted admin). Exposed to every member so anyone can see who manages it.
        # one join, not a query per owner
        owners = [{"id": ou.id, "name": ou.name, "avatar_url": ou.avatar_url}
                  for ou in (db.query(User)
                               .join(BoardMember, BoardMember.user_id == User.id)
                               .filter(BoardMember.board_id == b.id,
                                       BoardMember.role == "admin")
                               .order_by(User.id).all())]

        # built here rather than by FastAPI — see _json_default
        resp = _json({
            "id": b.id, "name": b.name, "description": b.description,
            "board_type": b.board_type.value if hasattr(b.board_type, 'value') else b.board_type,
            "icon": b.icon, "color": b.color,
            "is_archived": b.is_archived,
            "department_name": dept_name,
            "views": _board_views(b),
            "view_only": (b.settings or {}).get("view_only", False),
            "visibility": _board_visibility(b),
            "my_role": my_role,
            # How long the bin keeps a deleted item, carried on the board so
            # the delete dialog can SAY it. It used to be read off whichever
            # bin the reader happened to have opened, and guessed at sixty
            # when neither had been — a promise made by the browser rather
            # than by the server, which is the one thing that sentence must
            # not be. RECYCLE_BIN_DAYS is environment-settable, so a dialog
            # that guessed would promise a window nobody keeps the moment
            # somebody moved it.
            "retention_days": RECYCLE_BIN_DAYS,
            # whether the automations page is offered at all — a board viewer
            # never sees it, and an editor only where the capability is granted
            "can_view_automations": _can_view_automations(db, b, user_id),
            "owners": owners,
            # who may be tagged in a people column — the pickers build from this,
            # so it holds exactly who _can_be_assigned would accept: a member
            # whose account was deactivated is not offered. Anyone already
            # tagged is re-added client-side, so an old tag stays removable.
            #
            # Each carries its board role, because tagging is no longer a yes/no
            # per member: an assigned_only member may be put in the perm column
            # of any item (that is how they are given it) but in no other people
            # column of an item they cannot see. The picker needs the role to
            # say so before the server refuses.
            "members": [{"id": mu.id, "name": mu.name, "avatar_url": mu.avatar_url,
                         "role": mrole}
                        for mu, mrole in (db.query(User, BoardMember.role)
                                     .join(BoardMember, BoardMember.user_id == User.id)
                                     .filter(BoardMember.board_id == b.id,
                                             User.is_active.isnot(False))
                                     .order_by(User.name).all())],
            # Board settings the browser needs to reason with. Only what it
            # asks for — the stored settings JSON also holds the column
            # definitions, which travel above under their own keys. perm_column
            # is the column that decides "assigned" for the assigned roles, as
            # in force: "assignees" when unset or when the column it named is
            # gone (see _board_perm_col).
            "settings": {"perm_column": _board_perm_col(b)},
            # A connect column mid-conversion carries the state of it, so the
            # header can offer "טיפול בחריגות" and say how many are left. Added
            # to a COPY of the definition — b.settings is the stored JSON, and
            # a count written into it would be persisted on the next save.
            "columns": _columns_with_conversions(db, b.id, columns),
            # What a connect cell reads as, where its column was told to show
            # a field of the linked record rather than its title. An OVERRIDE
            # map — {col_id: {item_id: text}} — because the browser already
            # resolves the titles through /api/tasks/lookup, and anything that
            # reads as its own title is simply not in here. Built from what
            # _prefetch_links already loaded, so it costs no query of its own.
            "link_display": _board_link_display(db, tasks_out, columns, user_id),
            # which columns sub-items show (ids, name column first). None = never
            # configured → sub-items mirror the item columns.
            "sub_cols": (b.settings or {}).get("sub_cols"),
            # custom columns that live ONLY on sub-items, never on the parent items
            "sub_only": (b.settings or {}).get("sub_only", []),
            # one map for the whole board — a column's permission is the same on
            # every item (see _serialize_task)
            "col_perms": ({c["id"]: _col_perm(c, user_id, my_role) for c in columns}
                          if user_id is not None else {}),
            "col_widths": (b.settings or {}).get("col_widths", {}),
            # the sub-item table's own widths; a column not named here falls
            # back to its item-table width (see subColgroupHTML)
            "sub_col_widths": (b.settings or {}).get("sub_col_widths", {}),
            "col_labels": (b.settings or {}).get("col_labels", {}),
            "col_hidden": (b.settings or {}).get("col_hidden", []),
            "col_order": (b.settings or {}).get("col_order", []),
            "notifications_enabled": bool((b.settings or {}).get("notifications_enabled", True)),
            # After how many silent days this board draws an item's chat bubble
            # grey instead of blue. A property of the board, answered by the
            # "ללא עדכון בשיחה" rule it has switched on — see
            # _board_chat_stale_days. It travels with the board because the
            # browser needs it before it draws the first row.
            "chat_stale_days": _board_chat_stale_days(db, b.id),
            # Where this board's filtering runs. The browser has to know
            # before it asks anything — it is the number that decides whether
            # to ask at all — so it travels with the board rather than with
            # the first answer.
            "filter_client_max": FILTER_CLIENT_MAX,
            # How many items this board holds for this reader — the same number
            # /items/query answers as `total` for a query with nothing filtered.
            # It is what decides where the filtering runs, and past the
            # threshold it is also the ONLY thing that says the board is not
            # empty: `tasks` is [] up there on purpose, and len(tasks) is no
            # longer an answer to "how big is this board".
            "item_count": item_count,
            "filter_column_policy": FILTER_COLUMN_POLICY,
            "statuses": _board_statuses(b),
            "priorities": _board_priorities(b),
            "groups": [{"id": g.id, "name": g.name, "position": g.position, "color": g.color, "task_status": g.task_status.value if hasattr(g.task_status, 'value') else g.task_status} for g in groups],
            # Empty above the threshold, where the browser pages the rows in
            # from /items/query and never reads this list — see item_count.
            "tasks": tasks_out,
        })
        # everything after serialize — members, owners, link display, column
        # conversions — and the JSON encoding itself, which on a big board is
        # not free either
        _lap("rest")
        resp.headers["Server-Timing"] = ", ".join(
            f"{name};dur={ms:.1f}" for name, ms in _phases)
        total = sum(ms for _, ms in _phases)
        # Printed only when it is worth reading, so a healthy board says
        # nothing. stdout is what the container log keeps, once it is on.
        if total >= 1500:
            # item_count, not len(tasks_out): past the threshold no rows are
            # serialized, and a slow line reading "0 items" would send the next
            # reader of this log looking in the wrong place entirely.
            print(f"[slow board] {board_id}: {item_count} items"
                  f"{' (rows not sent)' if paged else ''}, {total:.0f}ms — "
                  + ", ".join(f"{n} {ms:.0f}" for n, ms in _phases), flush=True)
        return resp

@app.post("/api/boards")
def create_board(data: dict, actor_id: int = Depends(current_user_id)):
    with Session(engine) as db:
        # only a system (workspace) admin may create boards; the creator becomes
        # the board's first admin, so a board is never created without a manager.
        creator = actor_id
        # a new board belongs to the environment it was created in (default: primary workspace)
        env_id = data.get("environment_id")
        if not env_id:
            primary = db.query(Environment).filter(Environment.is_primary == True).first()
            env_id = primary.id if primary else None
        # allowed if the user has the global create-board capability, or manages the
        # target environment (an environment manager runs their own environment)
        if not (_cap(db, creator, "create_board") or _can_manage_env(db, env_id, creator)):
            raise HTTPException(403, "אין לך הרשאה ליצור לוח חדש")
        dept_id = data.get("department_id")
        if not dept_id:
            dept_id = db.query(Department.id).order_by(Department.id).limit(1).scalar()
        folder_id = data.get("folder_id")
        # append the new board at the bottom of its container (env root or folder)
        maxpos = (db.query(func.max(Board.position))
                  .filter(Board.environment_id == env_id, Board.folder_id == folder_id).scalar())
        b = Board(
            name=data.get("name", "לוח חדש"),
            description=data.get("description", ""),
            department_id=dept_id,
            environment_id=env_id,
            folder_id=folder_id,
            position=(maxpos + 1) if maxpos is not None else 0,
            board_type=BoardType.KANBAN,
            icon=data.get("icon", "📋"),
            color=data.get("color", "#0073ea"),
            settings={
                "views": ["table"],  # new boards start with only the main table
                # A new board is private: only the people invited to it can see
                # it. Publishing is a decision its admin makes deliberately from
                # the board menu, never the state a board is born in.
                "visibility": ("public" if data.get("visibility") == "public" else "private"),
                # every new board ships with these auto columns (read-only, from the item's metadata)
                "columns": [
                    {"id": "sys_item_id", "type": "item_id", "title": "מספר מזהה"},
                    {"id": "sys_created_at", "type": "created_at", "title": "מועד יצירה"},
                    # derived from the item's own creator, like "מועד יצירה" above:
                    # nothing to fill in, so it is right on every item on every
                    # board — including boards and items that predate the column
                    {"id": "sys_created_by", "type": "created_by", "title": "יוצר הרשומה"},
                ],
            },
        )
        db.add(b)
        db.flush()
        # default groups: 3 clean stages (no "review"). More can be added in-board.
        g1 = Group(board_id=b.id, name="בתכנון", position=0, color="#579bfc", task_status=TaskStatus.BACKLOG)
        db.add_all([
            g1,
            Group(board_id=b.id, name="בביצוע", position=1, color="#fdab3d", task_status=TaskStatus.IN_PROGRESS),
            Group(board_id=b.id, name="הושלם", position=2, color="#00c875", task_status=TaskStatus.DONE),
        ])
        db.flush()
        # 3 starter items in the first group so the board isn't blank — the creator
        # is recorded as their author and auto-filled into the "יוצר הרשומה" column.
        # Nobody has chosen a status or a priority for them, so both read
        # "טרם הוגדר" until someone does, exactly like an item added by hand.
        for i in range(1, 4):
            cf = {"status_unset": True, "priority_unset": True}
            if creator:
                cf["sys_created_by"] = [creator]
            db.add(Task(board_id=b.id, group_id=g1.id, title=f"פריט {i}",
                        status=TaskStatus.BACKLOG, priority=Priority.MEDIUM, position=i,
                        created_by=creator, custom_fields=cf))
        # creator becomes the board admin; the board is private until they invite others
        db.add(BoardMember(board_id=b.id, user_id=creator, role="admin"))
        # No view tabs. A board starts with the table it has always had and
        # no saved cuts of it; a tab is something somebody added.
        db.commit()
        db.refresh(b)
        return {"id": b.id, "name": b.name, "icon": b.icon, "views": _board_views(b), "my_role": "admin"}

# ── Import a board from a CSV / Excel file ───────────────────────────────
# First row = column headers. First column = the item name; every other column
# becomes a board column whose type is inferred from its values (number / date /
# text). One item is created per data row. Reuses the same board scaffolding as
# create_board (3 default groups, creator becomes admin).

# A number column a sheet wrote for people to read, not for a parser: "₪1,200",
# "1,200 ₪", "35%", a thousands separator that is a no-break space (what Excel
# writes in a Hebrew locale), a minus that is U+2212. Any ONE such cell used to
# make float() fail, and since a column is a number only if every cell is, the
# whole column arrived as text — a budget column nobody could sum or sort.
# The decoration is dropped and the digits kept; what is left must be a plain
# decimal, so "inf", "nan" and "1e5" — all of which float() accepts — stay text.
_IMP_NUM_DECOR = re.compile(r"[₪$€£%]")
_IMP_NUM_PLAIN = re.compile(r"-?(?:\d+\.?\d*|\.\d+)")


def _imp_to_number(v):
    if isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        return v
    s = _IMP_NUM_DECOR.sub("", str(v)).strip()
    s = s.replace(",", "").replace(" ", "").replace(" ", "").replace("−", "-")
    if not s or not _IMP_NUM_PLAIN.fullmatch(s):
        return None
    try:
        f = float(s)
        return int(f) if f.is_integer() else f
    except ValueError:
        return None


def _imp_to_date_iso(v):
    import datetime as _dt
    if isinstance(v, _dt.datetime):
        return v.date().isoformat()
    if isinstance(v, _dt.date):
        return v.isoformat()
    s = str(v).strip()
    if not s:
        return None
    # The sheet's rows are read as text before they are typed, and a real date
    # cell turns into "2024-01-24 00:00:00" on the way — the datetime's own
    # str(). None of the formats below has a time in it, so every date column in
    # a monday Excel export arrived as a text column of those strings. The time
    # is dropped: this is a date column, and monday's date cells carry none.
    s = re.sub(r"[T ]\d{1,2}:\d{2}(?::\d{2}(?:\.\d+)?)?$", "", s)
    for fmt in ("%Y-%m-%d", "%d/%m/%Y", "%d.%m.%Y", "%Y/%m/%d", "%d-%m-%Y", "%m/%d/%Y"):
        try:
            return _dt.datetime.strptime(s, fmt).date().isoformat()
        except ValueError:
            pass
    return None


# A monday Excel export writes a file cell as the file's ADDRESS, several of
# them comma-joined in one cell. As text that is a 2,000-character cell nobody
# can read; as a file column it is what it is — named chips, each opening the
# file in monday. The shape is monday's own asset address, so an ordinary link
# column ("קישור לדף הבית") is not mistaken for an attachment.
# The path is anything but a comma, because monday writes the file's real name
# into the address without escaping it: ".../resources/1476615869/הפרויקטים שלנו .docx"
# has a space in it, and requiring "no whitespace" matched none of her files.
# A comma is allowed in it for the same reason — see _imp_asset_urls, which
# splits a cell only where the next address starts.
_MONDAY_ASSET = re.compile(
    r"^https://[^/\s]+\.monday\.com/(?:protected_static|resources)/.+$|"
    r"^https://files-monday-com\.s3[^/\s]*\.amazonaws\.com/.+$")


def _imp_asset_urls(v):
    """The monday file addresses in one cell, or None if that is not what it is."""
    # Split only where the next address begins. A file's name rides unescaped
    # inside its address — ".../אספקה, התקנה, שיפוץ ואחזקה.docx" — and a split on
    # every comma cut it into pieces that are not addresses, so the whole column
    # read as text and its files never came across.
    parts = [p.strip() for p in re.split(r",\s*(?=https://)", str(v or ""))]
    parts = [p for p in parts if p]
    if not parts or not all(_MONDAY_ASSET.match(p) for p in parts):
        return None
    return parts


def _imp_file_name(url):
    """The file's name out of its address — the last segment, un-escaped."""
    path = urllib.parse.urlparse(url).path
    name = urllib.parse.unquote((path.rsplit("/", 1)[-1] or "").strip())
    return name[:255] or "קובץ"


# A number with a word after it — "3 ימים", "12 מ\"ר", "40 שעות". A monday
# numbers column states its unit, and a sheet that writes the unit into every
# cell turned the whole column into text: one figure nobody could sum, sort or
# filter by range. The word is only read as a unit when it trails the digits,
# is short, holds no digit of its own, and is the SAME word down the whole
# column — "שלב 3" leads with its word and "3 א" / "3 ב" disagree, and both
# stay text. Currency signs are not units here; _imp_to_number already drops
# them.
# The unit has to start with a letter (or the quote of מ"ר / ש"ח): "18+" and
# "7 ?" are a figure with a remark, and read as a unit the remark was painted on
# every row of the column.
_IMP_NUM_UNIT = re.compile(r"(-?[\d.,  ]*\d)\s*((?:[^\W\d_]|[\"'׳״])[^\d/:]{0,5})")


def _imp_number_and_unit(v):
    """(number, unit) for one cell — unit "" when there is none — or None."""
    n = _imp_to_number(v)
    if n is not None:
        return n, ""
    if v is None or isinstance(v, bool):
        return None
    m = _IMP_NUM_UNIT.fullmatch(str(v).strip())
    if not m:
        return None
    n = _imp_to_number(m.group(1))
    return (n, m.group(2).strip()) if n is not None else None


def _imp_number_unit(values):
    """The one unit a column of numbers writes beside its figures, or None.

    None when any cell is not a number, or when the cells disagree about the
    unit — a column that says "ימים" in one row and "שעות" in the next is not
    a quantity of one thing, and is left as the text it is. And None when the
    unit is in fewer than half the cells: one "3 ימים" among plain figures is a
    remark on one row, not the unit of every row.
    """
    units, with_unit, n = set(), 0, 0
    for v in values:
        got = _imp_number_and_unit(v)
        if got is None:
            return None
        n += 1
        if got[1]:
            units.add(got[1])
            with_unit += 1
    return units.pop() if len(units) == 1 and with_unit * 2 >= n else None


def _imp_infer_type(values):
    non_empty = [v for v in values if v is not None and str(v).strip() != ""]
    if not non_empty:
        return "text"
    if all(_imp_asset_urls(v) for v in non_empty):
        return "files"
    if all(_imp_to_number(v) is not None for v in non_empty):
        return "number"
    if all(_imp_to_date_iso(v) is not None for v in non_empty):
        return "date"
    # after the dates, so a day written in words is not a number with a unit
    if _imp_number_unit(non_empty):
        return "number"
    return "text"


# ── a status column, read off the paint ─────────────────────────────────────
# A status cell is a coloured chip and a sheet says so by filling it: monday's
# own export paints every status cell in that label's colour, and this app's
# export writes the same fill. Read as text — which is all a spreadsheet column
# was ever read as here — a status column arrives as free text: the picker
# offers nothing, every cell is grey, and a board migrated in cannot be read at
# a glance the way the board it came from could.
#
# What makes a column a status column is the paint. Repeated words happen in
# plenty of text columns; a column whose cells are FILLED, each word always in
# the same colour, is not something a sheet does by accident. A stray fill or
# two is not one either, so most of the filled cells have to agree — and a
# column of long sentences is prose somebody highlighted, not a vocabulary.
IMPORT_STATUS_MIN_PAINTED = 0.6
IMPORT_STATUS_MAX_LABEL = 40
# The word this app's export writes for a cell nobody has set. It is the ABSENCE
# of a status rather than one of the words the column offers: read back as an
# option it would stand in the picker of a board that never had it, and every
# unset cell would come home holding a value.
IMPORT_STATUS_UNSET = "טרם הוגדר"


def _imp_status_vocab(values, paints):
    """The vocabulary a painted column offers, or None if it is not one.

    `[{"label": …, "color": "#rrggbb" or None}, …]` in the order the sheet
    first uses each word — which is the order the column will offer them in.
    A colour of None is a label the sheet left unpainted; the caller gives it
    one of this app's own, the same way an uncoloured group gets one.
    """
    at = lambda row, i: (row[i] if i < len(row) else None)
    pairs = []
    for i, v in enumerate(values):
        label = "" if v is None else str(v).strip()
        if not label or label == IMPORT_STATUS_UNSET:
            continue
        pairs.append((label, at(paints, i)))
    if not pairs:
        return None
    painted = [(v, c) for v, c in pairs if c]
    if len(painted) < IMPORT_STATUS_MIN_PAINTED * len(pairs):
        return None
    labels = []
    for v, _ in pairs:
        if v not in labels:
            labels.append(v)
    if len(labels) > STATUS_COL_MAX or any(len(v) > IMPORT_STATUS_MAX_LABEL for v in labels):
        return None
    # One colour per word: the one most of its cells wear. A sheet where the
    # same word is painted two ways has been edited by hand, and the colour it
    # mostly is, is the colour it is.
    tally = {}
    for v, c in painted:
        worn = tally.setdefault(v, {})
        worn[c] = worn.get(c, 0) + 1
    return [{"label": v,
             "color": (max(tally[v].items(), key=lambda kv: kv[1])[0] if v in tally else None)}
            for v in labels]


def _imp_status_cell(opts, val):
    """One status cell, pointing at the option the column offers for that word.

    Written as the bare word the sheet rendered it matches nothing in the
    column's vocabulary and the board shows "טרם הוגדר" over data that is
    plainly there — the same reason the monday import resolves its cells.
    """
    label = "" if val is None else str(val).strip()
    if not label or label == IMPORT_STATUS_UNSET:
        return None
    o = (opts or {}).get(label)
    return ({"id": o["id"], "label": o["label"], "color": o["color"]} if o
            else {"label": label[:IMPORT_STATUS_MAX_LABEL], "color": "#c4c4c4"})


def _imp_subitem_names(text):
    """The sub-item names one sub-items cell holds, in the file's own order.

    monday renders that column as the sub-items' names joined by ", " and
    escapes nothing, so the comma is the only split there is — a sub-item whose
    own name holds one arrives as two. That is the file's limit rather than a
    choice here, and the report says what to re-export to get the sub-items
    themselves instead of their names. Same rule as the JSON import's
    import_monday._subitem_names, and the same ceiling.
    """
    out = []
    for part in str(text or "").split(","):
        name = part.strip()
        if name:
            out.append(name)
        if len(out) >= import_monday.SUBITEM_NAMES_MAX:
            break
    return out


def _imp_coerce(v, ctype):
    if v is None:
        return None
    if ctype == "number":
        # the unit, where the cell wrote one, is the column's — see _imp_number_unit
        got = _imp_number_and_unit(v)
        return got[0] if got else None
    if ctype == "date":
        return _imp_to_date_iso(v)
    if ctype == "files":
        urls = _imp_asset_urls(v) or []
        return [{"name": _imp_file_name(u), "url": u} for u in urls] or None
    s = str(v).strip()
    return s or None


# The grey band this app's export writes over a sub-item block, naming the
# columns those sub-items have. It is a header, not an item.
IMPORT_SUBHEAD_FILL = "FFEDEFF5"


def _imp_cell_paint(cell, fills_only=False):
    """The colour a sheet painted a cell with, as #rrggbb — or None.

    A group's row is coloured in every file that has groups at all: monday
    fills it, and this app's own export writes the colour on the text. Either
    is the group's colour, and reading it is what lets a board come back the
    colour it left.

    A status cell is painted too, and only ever filled — the chip IS the fill,
    in monday's export and in this app's own. `fills_only` is for reading those:
    text in a colour is how one file writes a group's name and is not a status
    anywhere, and a sheet whose body text happens to be navy would otherwise
    arrive as a board of navy statuses.

    White and black are not read as colours: they are what a sheet looks like
    when nothing was painted, and a group headed "ללא צבע" white-on-white is
    worse than one wearing a default.
    """
    def hexof(c):
        rgb = getattr(c, "rgb", None)
        # openpyxl answers a theme or indexed colour with no usable rgb at all,
        # and the themed palette is not in the file to resolve it against.
        if not isinstance(rgb, str) or len(rgb) != 8:
            return None
        if rgb[:2] == "00":              # fully transparent: nothing was painted
            return None
        h = "#" + rgb[2:].lower()
        return None if h in ("#ffffff", "#000000") else (h if _valid_hex(h) else None)

    try:
        fill = getattr(cell, "fill", None)
        if fill is not None and getattr(fill, "patternType", None) == "solid":
            c = hexof(fill.fgColor)
            # the grey sub-item band is this app's own furniture, not a colour
            # anybody chose for a group
            if c and c != "#" + IMPORT_SUBHEAD_FILL[2:].lower():
                return c
        if fills_only:
            return None
        font = getattr(cell, "font", None)
        if font is not None and font.color is not None:
            return hexof(font.color)
    except (AttributeError, TypeError, ValueError):
        pass
    return None


def _imp_parse_tabular(raw, filename, with_shape=False):
    """Rows (each a list of cell values) from CSV or XLSX bytes.

    With `with_shape`, each row is paired with what the sheet says it is:
    `(level, is_band, paint, values, paints)`. A board exported from here
    indents the first cell by two per level — a group at 0, an item at 1, a
    sub-item at 2 — and paints the sub-item column band grey. Both survive a
    read-back (the outline levels do not, in the streaming reader), so they are
    what the hierarchy is read from. A file with no indentation reads as level 0
    throughout, which is what a flat CSV is.

    `paint` is the colour the sheet gave the row's first cell, which on a group
    row is the group's own colour — the thing a board is recognised by before
    any of it is read. `paints` is the same question asked of every cell in the
    row, as fills only: a status cell is a coloured chip, and the fill is where
    a sheet says which colour. A CSV carries no colour, and says None to both.
    """
    name = (filename or "").lower()
    if name.endswith((".xlsx", ".xlsm")):
        import io as _io
        from openpyxl import load_workbook
        wb = load_workbook(_io.BytesIO(raw), data_only=True, read_only=True)
        ws = wb.active
        if not with_shape:
            rows = [list(r) for r in ws.iter_rows(values_only=True)]
            wb.close()
            return rows
        shaped = []
        for cells in ws.iter_rows():
            first = cells[0] if cells else None
            indent = 0
            band = False
            try:
                indent = int((first.alignment.indent or 0) if first is not None else 0)
                fill = getattr(first, "fill", None)
                band = bool(fill is not None and getattr(fill, "fgColor", None) is not None
                            and str(fill.fgColor.rgb or "").upper() == IMPORT_SUBHEAD_FILL)
            except (AttributeError, TypeError, ValueError):
                pass
            paint = _imp_cell_paint(first) if first is not None else None
            shaped.append((indent // 2, band, paint, [c.value for c in cells],
                           [_imp_cell_paint(c, fills_only=True) for c in cells]))
        wb.close()
        return shaped
    # CSV / TSV / plain text
    import csv as _csv, io as _io
    text = None
    for enc in ("utf-8-sig", "utf-8", "cp1255", "iso-8859-8"):
        try:
            text = raw.decode(enc)
            break
        except UnicodeDecodeError:
            continue
    if text is None:
        text = raw.decode("utf-8", errors="replace")
    sample = text[:4096]
    delim = ","
    if sample.count(";") > sample.count(","):
        delim = ";"
    elif sample.count("\t") > max(sample.count(","), sample.count(";")):
        delim = "\t"
    rows = [list(r) for r in _csv.reader(_io.StringIO(text), delimiter=delim)]
    # a CSV carries no indentation, so every row is flat — a parent column is the
    # only way such a file can name a hierarchy
    return [(0, False, None, r, [None] * len(r)) for r in rows] if with_shape else rows


def _imp_formula_text(raw, filename, shaped):
    """Fill the cells a spreadsheet left uncalculated with the formula itself.

    Excel stores two things for a formula cell: the formula, and the value it
    last worked out. A file written by a program — or one never opened since the
    formula was typed — carries the formula and no value, and read for values
    those cells come back empty. A whole column of them then arrives as a column
    nobody ever filled, which is the opposite of what the file says.

    So where there is no value, the formula is what the file says about that
    cell, and it comes across as text — "=B2*2", verbatim, in a text column.
    Nothing is computed here: a spreadsheet's formula is over cell addresses
    (B2), and the addresses are gone the moment the rows become items.

    Returns (shaped, how many cells were filled this way).
    """
    if not (filename or "").lower().endswith((".xlsx", ".xlsm")):
        return shaped, 0                     # a CSV holds text, formulas included
    import io as _io
    import zipfile
    try:
        # Reading the workbook a second time is not free, so first ask the file
        # whether it has any formulas at all: the sheet's XML carries an <f>
        # element per formula cell, and the board is the first sheet.
        with zipfile.ZipFile(_io.BytesIO(raw)) as z:
            sheets = sorted(n for n in z.namelist() if n.startswith("xl/worksheets/sheet"))
            if not sheets or b"<f" not in z.read(sheets[0]):
                return shaped, 0
    except Exception:                        # noqa: BLE001 — not a readable zip; the caller reports
        return shaped, 0
    from openpyxl import load_workbook
    try:
        wb = load_workbook(_io.BytesIO(raw), data_only=False, read_only=True)
    except Exception:                        # noqa: BLE001
        return shaped, 0
    try:
        src = [list(r) for r in wb.active.iter_rows(values_only=True)]
    finally:
        wb.close()
    filled = 0
    for i, row in enumerate(shaped):
        vals = row[3]
        if i >= len(src):
            break
        for j, v in enumerate(vals):
            if v is not None and str(v).strip() != "":
                continue
            f = src[i][j] if j < len(src[i]) else None
            if isinstance(f, str) and f.startswith("="):
                vals[j] = f
                filled += 1
    return shaped, filled


def _imp_conversation_sheet(raw, filename):
    """The rows of the workbook's conversation sheet, when it has one.

    A board exported from here writes its items on one sheet and its
    conversation on another; reading only the first sheet back meant every
    exported board lost its conversation on the way home. The sheet is found by
    name and, failing that, by its headers — a file someone rebuilt by hand does
    not have to guess at our sheet name.
    """
    if not (filename or "").lower().endswith((".xlsx", ".xlsm")):
        return []                                # a CSV holds one sheet, the items
    import io as _io
    from openpyxl import load_workbook
    try:
        wb = load_workbook(_io.BytesIO(raw), data_only=True, read_only=True)
    except Exception:                            # noqa: BLE001 — the caller reports it
        return []
    try:
        want = {"פריט", "תוכן"}
        best = None
        for ws in wb.worksheets:
            if ws is wb.worksheets[0]:
                continue                         # the first sheet is the board itself
            rows = [list(r) for r in ws.iter_rows(values_only=True)]
            if not rows:
                continue
            head = {str(c).strip() for c in rows[0] if c is not None}
            if ws.title.strip() in ("שיחות", "שיחה") or want <= head:
                best = rows
                break
        return best or []
    finally:
        wb.close()


def _imp_files_sheet(raw, filename):
    """The rows of the workbook's file sheet, when it has one.

    A file cell holds the file's name, because that is what a grid can show. The
    address it is served at does not fit in the grid at all, so a board exported
    from here writes it on a sheet of its own — the same answer the conversation
    got. Read back, the files come home as files; ignored, they come home as
    names with nothing behind them.
    """
    if not (filename or "").lower().endswith((".xlsx", ".xlsm")):
        return []
    import io as _io
    from openpyxl import load_workbook
    try:
        wb = load_workbook(_io.BytesIO(raw), data_only=True, read_only=True)
    except Exception:                            # noqa: BLE001 — the caller reports it
        return []
    try:
        want = {"פריט", "שם הקובץ"}
        for ws in wb.worksheets:
            if ws is wb.worksheets[0]:
                continue                         # the first sheet is the board itself
            rows = [list(r) for r in ws.iter_rows(values_only=True)]
            if not rows:
                continue
            head = {str(c).strip() for c in rows[0] if c is not None}
            if ws.title.strip() == "קבצים" or want <= head:
                return rows
        return []
    finally:
        wb.close()


def _imp_attach_files(db, rows, tasks, board, files, max_cols):
    """Hang an imported file sheet on the items and columns it names.

    Matched by name — the item's title and the column's title — because the ids
    in the file belong to the board it came from. A column the sheet names that
    came in as text IS that file column: the grid could only carry its names, so
    the names are replaced by the files themselves.
    """
    out = {"attached": 0, "unmatched_items": [], "unmatched_cols": []}
    if not rows:
        return out
    head = [str(c).strip() if c is not None else "" for c in rows[0]]
    idx = {h: i for i, h in enumerate(head)}
    if not all(h in idx for h in ("פריט", "שם הקובץ")):
        return out
    cell = lambda r, h: (str(r[idx[h]]).strip()
                         if h in idx and idx[h] < len(r) and r[idx[h]] is not None else "")

    by_title = {}
    for t in tasks:
        by_title.setdefault((t.title or "").strip(), t)
    settings = dict(board.settings or {})
    cols = [dict(c) for c in (settings.get("columns") or [])]
    by_col = {(c.get("title") or "").strip(): c for c in cols if c["id"].startswith("col_")}
    custom = [c for c in cols if c["id"].startswith("col_")]

    # item -> column -> [entries], gathered first so one cell is written once
    wanted, missing_items, missing_cols = {}, set(), set()
    for r in rows[1:]:
        title, cname = cell(r, "פריט"), cell(r, "עמודה")
        name, url = cell(r, "שם הקובץ"), cell(r, "כתובת")
        if not (name or url):
            continue
        t = by_title.get(title)
        if t is None:
            missing_items.add(title or "—")
            continue
        col = by_col.get(cname)
        if col is None:
            if len(custom) >= max_cols - 1:
                missing_cols.add(cname or "—")
                continue
            col = {"id": "col_" + uuid.uuid4().hex[:8], "type": "files", "title": cname or "קבצים",
                   "options": None, "formula": None, "connect": None, "copy_mode": None,
                   "perms": {}}
            cols.append(col)
            custom.append(col)
            by_col[cname] = col
        col["type"] = "files"           # a file column, whatever the grid made of it
        wanted.setdefault(t.id, {}).setdefault(col["id"], []).append({"name": name, "url": url})

    if not wanted and not missing_items and not missing_cols:
        return out
    settings["columns"] = cols
    board.settings = settings
    tasks_by_id = {t.id: t for t in tasks}
    for tid, per_col in wanted.items():
        t = tasks_by_id[tid]
        cf = dict(t.custom_fields or {})
        for cid, entries in per_col.items():
            got = _import_attachments(db, entries, files["budget"], files["stats"])
            cf[cid] = got
            out["attached"] += len(got)
        t.custom_fields = cf
    out["unmatched_items"] = sorted(missing_items)[:20]
    out["unmatched_cols"] = sorted(missing_cols)[:20]
    return out


def _imp_attach_conversation(db, rows, tasks, actor_id, budget):
    """Write an imported conversation onto the items it names.

    Rows are matched to items by name, which is the only handle a file and a
    freshly created board share — the ids in the file belong to the board it
    came from. A row naming an item that is not here is counted and reported
    rather than being attached to something arbitrary.

    Threading survives the trip: the file gives every message an id and names
    the one it answers, so roots are written first and replies are hung off
    whatever those ids became here.
    """
    if not rows:
        return {"messages": 0, "replies": 0, "unmatched_items": [], "unmatched_people": []}
    head = [str(c).strip() if c is not None else "" for c in rows[0]]
    idx = {h: i for i, h in enumerate(head)}
    need = ("פריט", "תוכן")
    if not all(h in idx for h in need):
        return {"messages": 0, "replies": 0, "unmatched_items": [], "unmatched_people": []}
    cell = lambda r, h: (str(r[idx[h]]).strip()
                         if h in idx and idx[h] < len(r) and r[idx[h]] is not None else "")

    by_title = {}
    for t in tasks:
        by_title.setdefault((t.title or "").strip(), t)
    names = {}
    for u in db.query(User).all():
        if u.name:
            names.setdefault(u.name.strip().lower(), u.id)
        if u.email:
            names.setdefault(u.email.strip().lower(), u.id)

    def when_of(r):
        v = r[idx["נכתב"]] if "נכתב" in idx and idx["נכתב"] < len(r) else None
        if isinstance(v, datetime):
            return v.replace(tzinfo=None)
        try:
            return datetime.fromisoformat(str(v).replace("Z", "+00:00")).replace(tzinfo=None)
        except (TypeError, ValueError):
            return None

    made = {"messages": 0, "replies": 0}
    missing_items, missing_people, id_map = set(), set(), {}
    # roots first: a reply can only be hung off a message that already exists
    for pas in (0, 1):
        for r in rows[1:]:
            if budget[0] <= 0:
                break
            parent_src = cell(r, "בתגובה להודעה")
            if bool(parent_src) != bool(pas):
                continue
            title = cell(r, "פריט")
            task = by_title.get(title)
            if task is None:
                if title:
                    missing_items.add(title)
                continue
            body = cell(r, "תוכן")
            files = [{"name": n.strip(), "url": ""} for n in cell(r, "קבצים").split(",") if n.strip()]
            if not body and not files:
                continue
            author = cell(r, "מאת")
            uid = names.get(author.lower()) if author else None
            if author and not uid:
                missing_people.add(author)
            parent_id = id_map.get(parent_src) if parent_src else None
            if parent_src and parent_id is None:
                continue                          # its message is not in this file
            c = Comment(task_id=task.id, user_id=uid, parent_id=parent_id,
                        content=body[:20000], attachments=files[:20],
                        mentions=[], likes=[], seen_by=[],
                        created_at=when_of(r) or datetime.now(timezone.utc).replace(tzinfo=None),
                        origin={"source": "xlsx", "author": author[:120],
                                "external_id": cell(r, "מזהה הודעה")[:40],
                                "matched": bool(uid)})
            db.add(c)
            db.flush()
            src_id = cell(r, "מזהה הודעה")
            if src_id:
                id_map[src_id] = c.id
            budget[0] -= 1
            made["replies" if parent_id else "messages"] += 1
    return {**made, "unmatched_items": sorted(missing_items)[:20],
            "unmatched_people": sorted(missing_people)[:20]}


# How many rows one import may bring in. It was 2,000, with nothing written
# down about why, and a real migration walked straight into it: a monday board
# of 2,069 items imported as 2,069 minus the 69 that happened to come last in
# the file — a whole group short by 69 rows, discovered by counting them in
# monday a day later. The number was never about what this app can hold; the
# upload ceiling (IMPORT_MAX_UPLOAD_MB) is the real guard on how big a file can
# be, and it refuses rather than trims. So this is set where no board anyone
# migrates here will reach it, and is tunable for the one that does.
IMPORT_MAX_ROWS = int(os.getenv("IMPORT_MAX_ROWS", "20000"))
# How many columns a board may be imported with. 40 was below what a real
# monday board carries — a 64-column board lost five columns that had data in
# them purely to the ceiling, which is the one kind of loss a migration cannot
# afford. 80 is the width this app's own export already writes at
# (XLSX_MAX_COLS), so a board that can be imported can also be exported whole.
IMPORT_MAX_COLS = 80
# Messages one import may bring in, across every item on the board. A board's
# conversation can be far longer than the board itself, so it gets a ceiling of
# its own — and what it cuts is named in the report rather than just missing.
IMPORT_MAX_MESSAGES = 10000
# ── the files an import brings with it ───────────────────────────────
# monday's export carries a pre-signed link per attachment. Those links work for
# about an hour and then the file is behind monday's auth forever, so the only
# moment the bytes can be brought across is the import itself. What arrives
# without them is a list of file NAMES — enough to see that an item had a spec
# attached, and useless for opening it.
#
# Fetched under a budget, because a board's attachments can dwarf the board:
# past either ceiling the rest keep their names and the report says how many.
#
# Both ceilings are the WHOLE import's, not one file's — IMPORT_MAX_FILE_MB is
# the megabytes an import may bring across in total, and the per-file limit is
# IMPORT_MAX_ONE_FILE_MB below, which is a different thing entirely.
#
# They were 600 files and 150MB, and that is small enough to cut a real board in
# half without anyone noticing. "ניהול ביקורים" (1495412381) carries 972
# attachments weighing 982MB — 918MB of it one column of site photographs — and
# the budget ran out 86 files in, at item 112 of 592. Every attachment after
# that point arrived as a name with nothing behind it, which on a board whose
# groups run newest-first means every registration form and every schedule older
# than June 2026 was missing. The board imported, reported, and looked finished.
# A ceiling that low only ever gets found by someone opening an old row.
#
# They can be this high now because the bytes no longer pile up in memory: they
# are fetched a window at a time (_ImportFileWindow) and written to the database
# a window at a time (_import_attachments), so what an import holds at once is
# IMPORT_FILE_WINDOW_MB and not everything it has brought so far.
IMPORT_MAX_FILES = int(os.getenv("IMPORT_MAX_FILES", "2000"))
IMPORT_MAX_FILE_MB = int(os.getenv("IMPORT_MAX_FILE_MB", "1200"))
IMPORT_FILE_TIMEOUT = 20            # seconds per file
# How many megabytes of attachments an import holds in memory at once — the
# fetch runs this far ahead of the walk, and the rows written behind it are
# flushed and let go at the same mark. It is a memory ceiling and nothing else:
# raising it makes an import no more complete, only hungrier.
IMPORT_FILE_WINDOW_MB = int(os.getenv("IMPORT_FILE_WINDOW_MB", "96"))
# The biggest single attachment an import will bring across. It was
# MAX_UPLOAD_BYTES — the ceiling on what a person may upload through the UI —
# and an import is not a person uploading. It is a board that already exists
# somewhere else, and a file that lives in monday today does not become smaller
# because this app's own form would have refused it. On ניהול ביקורים that rule
# dropped 22 attachments on the floor, one of them a registration form. Still a
# limit, so a runaway link is not read without end; only one sized for a
# migration rather than for a person picking a file.
IMPORT_MAX_ONE_FILE_MB = int(os.getenv("IMPORT_MAX_ONE_FILE_MB", "50"))
# How many attachments are fetched at once. The files are an import's only
# outbound calls and they do not depend on each other, so the wait is the one
# thing worth overlapping. Eight is modest on purpose: the other side is
# monday's S3, and an import is not the only thing this server is doing.
#
# Eight was that, and eight is also three minutes of wall clock for a board
# carrying a gigabyte — long enough that a gateway in front of this app gives up
# on the request before the import is finished, which to the person waiting is
# indistinguishable from a crash. Sixteen brings the same board in two. The
# memory that number used to cost is now the window's, not the pool's.
IMPORT_FILE_WORKERS = int(os.getenv("IMPORT_FILE_WORKERS", "16"))
# The upload ceiling for an import. It was 8MB, and a 320-item board exported
# from monday rejected at 11.7MB — of which 8MB was the indentation Postman adds
# when a response is saved from its pretty view. The content was 3.66MB. A limit
# that turns on how a file was saved rather than on what is in it is a limit that
# rejects the right board for the wrong reason, so there is room for a board
# several times that size, pretty-printed.
IMPORT_MAX_UPLOAD_MB = int(os.getenv("IMPORT_MAX_UPLOAD_MB", "32"))

# Only monday's own asset hosts. The URLs come out of a file the user supplied,
# and fetching whatever it names would let an import point this server at an
# address inside the network it runs in.
def _import_host_allowed(host):
    host = (host or "").lower()
    return (host == "monday.com" or host.endswith(".monday.com")
            or (host.startswith("files-monday-com.s3.") and host.endswith(".amazonaws.com"))
            or host == "files-monday-com.s3.amazonaws.com")


class _NoRedirects(urllib.request.HTTPRedirectHandler):
    """A pre-signed asset link does not redirect. Refusing to follow one closes
    the hole where an allowed host bounces the fetch somewhere it should not go."""

    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


_IMPORT_OPENER = urllib.request.build_opener(_NoRedirects)


# Consecutive failures after which the import stops trying. When a file's links
# have expired, every link in that file has expired — and discovering that 300
# times over cost three minutes of an import that had nothing else to do.
IMPORT_FILE_FAIL_STREAK = 5


def _stored_file_token(url):
    """The token in one of this app's own file addresses, or None.

    `/api/files/<32 hex>` is where an uploaded file is served from, so a file
    cell in a board exported from here names a blob this database already holds.
    """
    m = re.fullmatch(r"(?:https?://[^/]+)?/api/files/([0-9a-f]{8,64})", (url or "").strip())
    return m.group(1) if m else None


def _signed_url_expired(url, now=None):
    """Has this pre-signed link already lapsed, going by the link itself?

    monday's asset URLs are S3 signatures carrying the moment they were minted
    and how long they last (`X-Amz-Date` + `X-Amz-Expires`, an hour). Reading it
    is free and exact, which beats spending a round trip per file to be told 403.
    """
    try:
        q = urllib.parse.parse_qs(urllib.parse.urlparse(url or "").query)
        minted = (q.get("X-Amz-Date") or [""])[0]
        window = int((q.get("X-Amz-Expires") or ["0"])[0])
        if not minted or window <= 0:
            return False                       # not a signed link — let the fetch decide
        t = datetime.strptime(minted, "%Y%m%dT%H%M%SZ").replace(tzinfo=timezone.utc)
        return (now or datetime.now(timezone.utc)) > t + timedelta(seconds=window)
    except (ValueError, TypeError, OverflowError):
        return False


def _fetch_import_file(url):
    """(bytes, content_type) for one attachment, or None if it cannot be had.

    Never raises: an expired link, a redirect, a host we do not fetch from and a
    file over the per-file ceiling all mean the same thing to the caller — this
    one keeps its name only.
    """
    try:
        parts = urllib.parse.urlparse(url or "")
        if parts.scheme != "https" or not _import_host_allowed(parts.hostname):
            return None
        req = urllib.request.Request(url, headers={"User-Agent": "CODE-CAL-MISSIONS/import"})
        with _IMPORT_OPENER.open(req, timeout=IMPORT_FILE_TIMEOUT) as resp:
            ctype = (resp.headers.get("Content-Type") or "").split(";")[0].strip().lower()
            # A monday link that needs a session does not answer 401 — it answers
            # 200 with the login page. Stored, that is a docx-shaped file holding
            # monday's HTML, which is worse than the name on its own: it opens,
            # and it is not the file.
            if ctype == "text/html":
                return None
            ceiling = IMPORT_MAX_ONE_FILE_MB * 1024 * 1024
            data = resp.read(ceiling + 1)
            if not data or len(data) > ceiling:
                return None
            return data, ctype
    except Exception:                              # noqa: BLE001 — see the docstring
        return None


def _import_fetchable(url):
    """Whether this address is one the import would spend a round trip on.

    The same questions _import_attachments asks before fetching, in the same
    order — kept here so the prefetch warms exactly the set the import would
    have fetched itself, and nothing besides.
    """
    if not url or _stored_file_token(url):
        return False
    parts = urllib.parse.urlparse(url)
    if parts.path.startswith("/protected_static/") or not _import_host_allowed(parts.hostname):
        return False
    return not _signed_url_expired(url)


class _ImportFileWindow:
    """An import's attachments, fetched ahead of the walk a window at a time.

    One at a time, in the order the items are read, is a round trip per file
    with nothing else happening: a fresh monday export of 320 items carried 307
    live S3 links, and 307 round trips end to end is minutes of a request that
    spends them waiting. The bytes do not depend on each other, so they are
    fetched together and the walk finds each file already in hand.

    All of them together is the other failure, and it is the one that set the
    ceiling so low. A board of 972 attachments weighing 982MB would have held
    those 982MB in memory before a single item was written — so the budget was
    150MB, and the board came across with two thirds of its files reduced to
    names. Neither the fetch nor the import needs everything at once: the walk
    reads the attachments in exactly the order this queue holds them.

    So the queue is drawn from in windows. Asking for a url fetches everything
    up to it and a window's worth beyond, and a url handed over is let go — what
    is in memory is the window, whatever the import's total comes to. It answers
    `url in cache` and `cache[url]` so the caller cannot tell the difference
    from the dict this used to be: a value of None still means the fetch failed,
    which is what the caller does with a failed fetch anyway.
    """

    # Files asked for in one go — four times the pool's width, so every worker
    # has something queued behind it and no window is one slow file long.
    CHUNK = 32

    def __init__(self, urls, budget, workers=None):
        seen, self.queue = set(), []
        for u in urls:
            if u and u not in seen and _import_fetchable(u):
                seen.add(u)
                self.queue.append(u)
        # Past the file ceiling nothing is fetched, so nothing is queued either:
        # a prefetch that pulled more than the import may keep would spend
        # exactly the time this exists to save.
        self.queue = self.queue[:max(0, budget[0])]
        self.at = {u: i for i, u in enumerate(self.queue)}
        self.next = 0
        self.have = {}
        self.held = 0
        self.window = IMPORT_FILE_WINDOW_MB * 1024 * 1024
        self.workers = max(1, workers or IMPORT_FILE_WORKERS)
        self.left = [budget[1]]
        self.streak = [0]

    def __contains__(self, url):
        if url in self.have:
            return True
        i = self.at.get(url)
        # Behind the queue means it was fetched and handed over already — the
        # same file in a second cell. Rare, and one round trip of its own is a
        # better answer than keeping every file to the end of the import.
        if i is None or i < self.next:
            return False
        self._fill(i)
        return url in self.have

    def __getitem__(self, url):
        got = self.have.pop(url)
        if got:
            self.held -= len(got[0])
        return got

    def _fill(self, target):
        """Fetch up to the file asked for, and a window's worth past it."""
        while self.next < len(self.queue) and self.left[0] > 0 and (
                self.next <= target or self.held < self.window):
            batch = self.queue[self.next:self.next + self.CHUNK]
            self.next += len(batch)
            self._fetch(batch)

    def _fetch(self, batch):
        lock = threading.Lock()

        def one(u):
            with lock:
                # the run-of-failures guard, honoured here too: if the first
                # handful cannot be had the rest cannot either, and the point of
                # that rule is not to spend a timeout per file proving it. Up to
                # one pool's worth are already in flight when the run trips —
                # but in flight together, so it costs one timeout rather than
                # one each.
                if self.left[0] <= 0 or self.streak[0] >= IMPORT_FILE_FAIL_STREAK:
                    return u, None
            got = _fetch_import_file(u)
            with lock:
                if got:
                    self.streak[0] = 0
                    self.left[0] -= len(got[0])
                else:
                    self.streak[0] += 1
            return u, got

        n = max(1, min(self.workers, len(batch)))
        with concurrent.futures.ThreadPoolExecutor(
                max_workers=n, thread_name_prefix="import-file") as pool:
            for u, got in pool.map(one, batch):
                self.have[u] = got
                if got:
                    self.held += len(got[0])


def _prefetch_import_files(urls, budget, workers=None):
    """The attachments of one import, ready to be read in the file's own order.

    An empty dict when there is nothing to fetch, so a board with no files costs
    no object and no pool.
    """
    win = _ImportFileWindow(urls, budget, workers)
    return win if win.queue else {}


def _attachment_urls(parsed, columns):
    """Every address this import might fetch, in the order the file states them.

    The cells of the file columns and the assets hanging off the conversation —
    on the items and on their sub-items alike, which is where half of them were.
    """
    keys = [c["key"] for c in columns if c["type"] == "files"]
    out = []
    def msgs(src):
        for up in src.get("updates") or []:
            for m in [up] + (up.get("replies") or []):
                out.extend((a or {}).get("url") or "" for a in (m.get("assets") or []))
    for row in parsed["items"]:
        for src in [row] + (row.get("subitems") or []):
            for k in keys:
                for f in src["values"].get(k) or []:
                    out.append((f or {}).get("url") or "")
            msgs(src)
    return out


def _import_attachments(db, files, budget, stats, cache=None):
    """Bring a list of [{name,url}] across, and return it pointing here.

    `budget` is [files_left, bytes_left], shared by the whole import. An entry
    whose bytes could not be fetched keeps its name and its original link, so
    nothing is lost that was there before — it simply is not openable.
    """
    out = []
    for f in files or []:
        name = _safe_filename(f.get("name"), "קובץ")
        url = f.get("url") or ""
        # An attachment that could not be fetched keeps its name and the address
        # it had, and now says why. The two kinds of leftover are not the same
        # thing and must not look the same: a /protected_static/ link opens the
        # file in monday, where the user IS signed in, while an expired signature
        # can never open again, for anyone. Handed over as a plain link, that one
        # opens S3's XML complaint — "Request has expired" — which reads as a
        # broken app rather than as a file that did not come across.
        def keep(why, dead=True):
            one = {"name": name[:255], "url": url, "why": why}
            if dead:
                one["dead"] = True
            out.append(one)
            stats[why] = stats.get(why, 0) + 1
        if not url:
            out.append({"name": name[:255], "url": ""})
            continue
        # ── the file is already stored here ───────────────────────────────
        # A board exported from here and imported back names its files by the
        # address they are served at. The bytes never left, so nothing is
        # fetched and nothing is copied — the cell points at the same blob.
        token = _stored_file_token(url)
        if token:
            if db.query(UploadedFile.id).filter(UploadedFile.token == token).first():
                out.append({"name": name[:255], "url": url})
                stats["reused"] = stats.get("reused", 0) + 1
            else:
                out.append({"name": name[:255], "url": "", "why": "gone", "dead": True})
                stats["gone"] = stats.get("gone", 0) + 1
            continue
        # ── a link this server cannot fetch ───────────────────────────────
        # monday's /protected_static/ address is the file behind a LOGIN, and the
        # login is the user's, not this server's: unauthenticated it answers 200
        # with monday's sign-in page. It is what a monday Excel export writes for
        # every attachment, so the name and the link are kept — a chip that opens
        # the file in monday, where the user is signed in — and no round trip is
        # spent being told so. Anything on a host this server does not fetch from
        # is the same answer.
        parts = urllib.parse.urlparse(url)
        if (parts.path.startswith("/protected_static/")
                or not _import_host_allowed(parts.hostname)):
            keep("linked", dead=False)      # this one still opens, in monday
            continue
        # the two questions that can be answered without a round trip
        if _signed_url_expired(url):
            keep("expired")
            continue
        if stats.get("streak", 0) >= IMPORT_FILE_FAIL_STREAK:
            keep("failed")
            continue
        if budget[0] <= 0 or budget[1] <= 0:
            # The ceiling, and the ceiling is not a failure. Counted as one it
            # read in the report as "קבצים לא נענו" — links that were blocked or
            # files no longer there, nothing anybody here could do — when what
            # actually happened was that the import stopped, on purpose, at a
            # number in this file. On ניהול ביקורים that sentence stood over 878
            # attachments that monday was serving perfectly well. The two call
            # for opposite things, so they are counted apart.
            keep("over_budget")
            continue
        if cache is not None and url in cache:
            got = cache[url]      # already in hand — see _prefetch_import_files
        else:
            got = _fetch_import_file(url)
        if got is None:
            stats["streak"] = stats.get("streak", 0) + 1
            keep("failed")
            continue
        stats["streak"] = 0
        data, ctype = got
        if len(data) > budget[1]:
            keep("over_budget")
            continue
        token = uuid.uuid4().hex
        media_type, _ = _safe_media_type(ctype)
        row = UploadedFile(token=token, name=name[:255], content_type=media_type,
                           data=data, size=len(data))
        db.add(row)
        # Written out once a window's worth has gathered, rather than at the
        # end. A session holds what has been added to it until the commit, so an
        # import carrying a gigabyte of attachments held that gigabyte twice —
        # once as the bytes it fetched and once as the rows waiting to go out —
        # and that, not the files themselves, is what the 150MB ceiling was
        # really protecting. Flushed, the INSERT is inside this same transaction
        # and a failure still rolls the whole import back; detached, the bytes
        # can be let go.
        pending = stats.setdefault("pending", [])
        pending.append(row)
        stats["pending_bytes"] = stats.get("pending_bytes", 0) + len(data)
        if stats["pending_bytes"] >= IMPORT_FILE_WINDOW_MB * 1024 * 1024:
            db.flush()
            for done in pending:
                db.expunge(done)
            pending.clear()
            stats["pending_bytes"] = 0
        budget[0] -= 1
        budget[1] -= len(data)
        stats["imported"] = stats.get("imported", 0) + 1
        stats["bytes"] = stats.get("bytes", 0) + len(data)
        out.append({"name": name[:255], "url": f"/api/files/{token}"})
    return out


# Column headings that mean "the item this row belongs under". A CSV cannot
# indent, so naming the parent is the only way such a file can say it.
# The three columns the system issues on its own — the item's identifier, when
# it was created and by whom. An imported board gets them like any other board,
# but AFTER the columns that came out of the file: nobody typed them, nobody
# asked for them, and in front of the board they read as data that came from
# somewhere. A function, because each import needs its own dicts to mutate.
def IMPORT_SYSTEM_COLS():
    return [{"id": "sys_item_id", "type": "item_id", "title": "מספר מזהה"},
            {"id": "sys_created_at", "type": "created_at", "title": "מועד יצירה"},
            {"id": "sys_created_by", "type": "created_by", "title": "יוצר הרשומה"}]


IMPORT_PARENT_HEADERS = {"פריט אב", "תת פריט של", "תת־פריט של", "תת-פריט של",
                         "שייך לפריט", "parent", "parent item", "sub-item of",
                         "subitem of", "sub item of"}


# Column headings that mean "the group this row belongs to". A flat sheet — a
# CSV, or one built by hand — cannot indent and has no group rows, so a column
# naming the group is the only way such a file can say how the board is divided.
IMPORT_GROUP_HEADERS = {"קבוצה", "שם הקבוצה", "קבוצת", "קיבוץ", "group",
                        "group name", "group title", "board group"}

# What monday calls the column it writes its sub-items' names into. It is not a
# column of the board — the sub-items come in as themselves, under their items —
# so it is the same names a second time, comma-joined, as text.
IMPORT_SUBITEMS_HEADERS = {"subitems", "sub-items", "sub items", "subtasks",
                           "תתי פריטים", "תתי־פריטים", "תתי-פריטים",
                           "תת פריטים", "תתי משימות"}


def _imp_monday_layout(shaped):
    """monday's own Excel/CSV export, read as the divided board it describes.

    monday does not write one table. It writes the board's name on a line of its
    own and then, for every group, that group's name on a line of its own
    followed by a fresh copy of the header row:

        ניהול תוכן אתר החברה           ← the board
        עליה לאוויר - יוני             ← a group
        Name | Subitems | מטפל | …     ← the header
        דף הבית | … | …                ← an item
        Subitems | Name | מטפל | …     ← the sub-item header (a "band")
             | הפרויקטים שלנו | …      ← a sub-item
        באגים                          ← the next group
        Name | Subitems | מטפל | …     ← the header, again

    Read as one flat table from row 0 — which is what happened until now — the
    board's NAME becomes the header row: every column arrives titled "עמודה 3",
    the real header and each group name arrive as items, the sub-items arrive as
    nameless items, and the whole board lands in one invented group. Nothing
    about the file is unclear; it states its division on every one of those
    lines.

    Returns `(title, header, body, summaries)`, the body in the same `(level,
    is_band, paint, values)` shape a board exported from here is already read in — a
    group at 0, an item at 1, a sub-item at 2 — so everything downstream of here
    is unchanged. A sheet that is not this layout returns None and is read
    exactly as before: the first row its header, every row under it an item.
    """
    def txt(vals):
        return [("" if c is None else str(c).strip()) for c in vals]

    rows = [txt(row[3]) for row in shaped]
    if len(rows) < 3:
        return None
    filled = [sum(1 for c in r if c) for r in rows]
    # a line carrying one cell, and that cell the first: a name, not a row
    lone = [f == 1 and bool(r and r[0]) for r, f in zip(rows, filled)]
    head = next((i for i, f in enumerate(filled) if f >= 3), None)
    # the header sits under the board's name, and under the first group's name
    # when there is one. Anything else — a header on row 0, a preamble longer
    # than that — is not this layout.
    if head is None or head not in (1, 2) or not all(lone[:head]):
        return None
    if head + 1 >= len(rows):
        return None
    header = rows[head]
    labels = [c for c in header if c]
    name_lbl = header[0]
    sub_lbl = header[1] if len(header) > 1 else ""

    def is_header(r):
        return [c for c in r if c] == labels

    def is_band(r):
        # the sub-item header monday writes: its own column's title first, the
        # item-name column's title second, and the sub-item columns after them
        return bool(sub_lbl) and len(r) > 1 and r[0] == sub_lbl and r[1] == name_lbl

    body, in_band, i, summaries = [], False, head + 1, 0
    if head == 2:
        # the group this header is for
        body.append((0, False, shaped[1][2], shaped[1][3], shaped[1][4]))
    while i < len(shaped):
        r, vals, paint, paints = rows[i], shaped[i][3], shaped[i][2], shaped[i][4]
        # A name on a line of its own, with the header repeated beneath it, is
        # how monday says "a new group starts here". The header-beneath is what
        # tells it apart from an item nobody filled anything in for.
        if lone[i] and i + 1 < len(rows) and is_header(rows[i + 1]):
            body.append((0, False, paint, vals, paints))
            in_band, i = False, i + 2                # the repeat is not a row of the board
            continue
        if is_header(r):
            i += 1
            continue
        if is_band(r):
            body.append((2, True, None, vals, paints))
            in_band, i = True, i + 1
            continue
        if in_band and not r[0]:
            # a sub-item: its name is in the second cell
            body.append((2, False, None, vals, paints))
            i += 1
            continue
        if not r[0] and not (len(r) > 1 and r[1]):
            # monday closes each group with a summary line — no name anywhere, and
            # in the date column the group's rolled-up range ("2024-05-05 to
            # 2024-05-30"). Imported, that is a "פריט 38" holding one date that
            # belongs to nobody; it was four of the forty-one items her real file
            # "had". A row with a name in the second cell is a sub-item whose
            # band went unread, and it is kept — counted as one of these, it
            # would be a row of the board dropped without a word.
            summaries += 1
            i += 1
            continue
        in_band = False
        body.append((1, False, None, vals, paints))
        i += 1
    return rows[0][0], shaped[head][3], body, summaries


# Colours handed to imported status/dropdown options. Same list the status
# picker offers, so an imported column looks like one made here by hand.
IMPORT_PALETTE = [
    "#1AC877", "#FBAA47", "#DB2D4C", "#565BDC", "#5A9CF9", "#9C51DB", "#E30073",
    "#53CCC5", "#FD6C42", "#9DD335", "#276FDC", "#FD5AC3", "#117FB3", "#7E5348",
    "#B93255", "#FECA29", "#6ACDFD", "#784DCF", "#0F7F4D", "#9BADBC",
]


def _import_comment(db, task, msg, by_token, parent_id=None, files=None, flush=True):
    """One imported message, written onto the item it belongs to.

    The author is matched to an account by e-mail first and by name second — the
    same order the people columns use, for the same reason. An author with no
    account here keeps their name through `origin` instead of being replaced by
    whoever ran the import: a conversation is a record of who said what, and an
    import that rewrites that is worse than one that drops it.
    """
    uid = (by_token.get((msg.get("email") or "").lower())
           or by_token.get((msg.get("author") or "").lower()))
    when = None
    raw = (msg.get("created_at") or "").strip()
    if raw:
        try:
            when = datetime.fromisoformat(raw.replace("Z", "+00:00")).replace(tzinfo=None)
        except ValueError:
            when = None
    atts = [{"name": a.get("name", ""), "url": a.get("url", "")}
            for a in (msg.get("assets") or [])][:20]
    if files is not None:
        # the bytes, while monday's links still work — see _import_attachments
        atts = _import_attachments(db, atts, files["budget"], files["stats"],
                                   files.get("cache"))
    c = Comment(task_id=task.id, user_id=uid, parent_id=parent_id,
                content=(msg.get("body") or "")[:20000],
                attachments=atts,
                mentions=[], likes=[], seen_by=[],
                created_at=when or datetime.now(timezone.utc).replace(tzinfo=None),
                origin={"source": "monday", "author": (msg.get("author") or "")[:120],
                        "external_id": (msg.get("external_id") or "")[:40],
                        "matched": bool(uid)})
    db.add(c)
    # Flushed only when the row's own id is about to be needed — a message whose
    # replies hang off it. A reply is nobody's parent, and flushing it on its own
    # made every single imported message a round trip of its own; left pending,
    # they go out together with whatever flush comes next.
    if flush:
        db.flush()
    return c


def _import_conversation(db, task, updates, by_token, budget, files=None):
    """An item's whole conversation, replies kept under the message they answer.

    `budget` is a one-element list — the import's remaining message allowance,
    shared across every item so a single board cannot write an unbounded number
    of rows. Returns how many messages were written.
    """
    made = 0
    for up in updates or []:
        if budget[0] <= 0:
            break
        root = _import_comment(db, task, up, by_token, files=files)
        budget[0] -= 1
        made += 1
        for rep in up.get("replies") or []:
            if budget[0] <= 0:
                break
            _import_comment(db, task, rep, by_token, parent_id=root.id, files=files,
                            flush=False)
            budget[0] -= 1
            made += 1
    return made


def _import_monday_board(raw, filename, name, environment_id, folder_id, actor_id):
    """Build a board out of a monday.com API response.

    The column budget is the one the tabular importer already works to: the item
    name plus IMPORT_MAX_COLS - 1 custom columns. Nothing raises it. When the
    file holds more than fits, the fullest columns win and the rest come back in
    the report, named — so the drop is a decision the user can see rather than a
    silence they discover weeks later.
    """
    try:
        parsed = import_monday.parse(raw, IMPORT_MAX_COLS - 1)
    except import_monday.NotMondayJson as e:
        raise HTTPException(400, f"הקובץ אינו תשובת API של מאנדיי ({e})")
    except (ValueError, TypeError):
        raise HTTPException(400, "לא ניתן לקרוא את הקובץ — ודא שהוא JSON תקין")
    # A board with no rows is not an empty file: monday answers a board whose
    # structure is built and whose rows are not with `items_page: {items: []}`
    # beside its columns and groups, and that is worth importing as it stands —
    # the columns, the groups and the log arrive, and the first row is typed
    # here instead of there. A file that never carried an items page at all —
    # the history response on its own — is refused by the parser before this.
    if len(parsed["items"]) > IMPORT_MAX_ROWS:
        # A migration is not a sample. Past the ceiling the rows used to be cut
        # here — the first IMPORT_MAX_ROWS in file order — and the loss was
        # written into the report, where it sat under a long list of other notes
        # and was read by nobody: the board that lost 69 of 2,069 rows this way
        # looked finished, and the gap surfaced a day later when someone counted
        # the group in monday. A board that is quietly 3% short is worse than an
        # import that did not happen, because only one of the two gets noticed.
        #
        # So it is refused, with both numbers and the knob that moves them.
        raise HTTPException(413,
            f"בקובץ {len(parsed['items'])} פריטים, ותקרת הייבוא היא {IMPORT_MAX_ROWS}. "
            "הייבוא נעצר כדי שלא ייווצר לוח חסר בשקט — פצל את הייצוא לכמה לוחות, "
            "או הרם את התקרה במשתנה הסביבה IMPORT_MAX_ROWS והרץ שוב")

    with Session(engine) as db:
        env_id = environment_id
        if not env_id:
            primary = db.query(Environment).filter(Environment.is_primary == True).first()
            env_id = primary.id if primary else None
        if not (_cap(db, actor_id, "create_board") or _can_manage_env(db, env_id, actor_id)):
            raise HTTPException(403, "אין לך הרשאה ליצור לוח חדש")

        # ── people: monday gives a display name, and an e-mail when the export
        # carries one; we need an account. E-mail is tried first — it is the half
        # that survives someone changing their display name, and two people can
        # share a name. Anyone with no account here is named in the report rather
        # than being dropped on the floor in silence.
        people_wanted = set()
        for r in parsed["items"]:
            for src in [r] + r["subitems"]:
                for c in parsed["columns"]:
                    if c["type"] == "people":
                        people_wanted.update(src["values"].get(c["key"]) or [])
                # whoever wrote the item's conversation is a person to look for
                # as much as whoever was assigned to it
                for up in src.get("updates") or []:
                    for msg in [up] + (up.get("replies") or []):
                        people_wanted.update(t for t in (msg.get("email"), msg.get("author")) if t)
        by_token = {}
        if people_wanted:
            low = [t.lower() for t in people_wanted]
            for u in db.query(User).filter(or_(func.lower(User.email).in_(low),
                                               func.lower(User.name).in_(low))).all():
                if u.email:
                    by_token.setdefault(u.email.lower(), u.id)
                if u.name:
                    by_token.setdefault(u.name.lower(), u.id)
        unmatched = sorted(t for t in people_wanted if t.lower() not in by_token)

        # ── the columns ──────────────────────────────────────────────────────
        col_ids, custom_cols, sub_used = {}, [], set()
        status_opts = {}   # column key -> {label: the option its cells point at}
        for c in parsed["columns"]:
            cid = "col_" + uuid.uuid4().hex[:8]
            col_ids[c["key"]] = cid
            col = {"id": cid, "type": c["type"], "title": c["title"][:60], "options": None,
                   "formula": c.get("formula"), "connect": None, "copy_mode": None, "perms": {}}
            if c["type"] == "status":
                # through the same normaliser a column edited by hand goes
                # through, so every label gets the stable id a cell points at —
                # renaming the option later then carries its cells with it.
                #
                # Each label in the colour the file gave it. A status is read as
                # its colour before it is read as a word — "הושלם" green, "תקוע"
                # red — and the palette below is cycled by POSITION, so a
                # vocabulary coloured by it arrives with those two swapped as
                # often as not. It is the fallback for a label the file says no
                # colour for, and nothing more; see import_monday.status_colors.
                paint = c.get("option_colors") or {}
                col["options"] = _status_col_options(
                    [{"label": str(o)[:40],
                      "color": paint.get(o) or IMPORT_PALETTE[j % len(IMPORT_PALETTE)]}
                     for j, o in enumerate(c.get("options") or [])])
                status_opts[c["key"]] = {o["label"]: o for o in (col["options"] or [])}
            elif c["type"] == "dropdown":
                col["options"] = [str(o)[:40] for o in (c.get("options") or [])]
            elif c["type"] == "number" and c.get("unit"):
                # the unit monday shows beside the figures — see import_monday.number_unit
                col["number"] = _number_col_cfg({"unit": c["unit"]})
            custom_cols.append(col)
        # Columns that exist on monday's sub-item board and nowhere on the parent
        # one. They are board columns here, shown on the sub-item rows and never
        # on the item — which is the structure the file describes. Without this
        # they stood on every item as well, empty forever.
        sub_only_ids = [col_ids[c["key"]] for c in parsed["columns"] if c.get("sub_only")]

        settings = {
            "views": ["table"],
            # the board's own columns in the board's own order, and the three the
            # system issues after them — see the note in _import_board_file
            "columns": custom_cols + IMPORT_SYSTEM_COLS(),
            # The board's four built-in columns — אחראים, סטטוס, עדיפות,
            # תאריך יעד — are not in the file and nothing in this import fills
            # them. Left showing, they are four columns of "טרם הוגדר" standing
            # in front of the board that was actually imported, and they follow
            # it into every export of it.
            # Hidden, not removed: a board admin turns any of them back on the
            # moment there is something to put in it.
            "col_hidden": ["assignees", "status", "priority", "due"],
            # and the sub-item board's own columns stay on the sub-items
            "sub_only": sub_only_ids,
        }
        base = os.path.splitext(os.path.basename(filename or ""))[0]
        board_name = (name or "").strip() or parsed["board_name"] or base or "לוח מיובא"
        name_from = _board_name_from(name, parsed["board_name"], base)
        maxpos = (db.query(func.max(Board.position))
                  .filter(Board.environment_id == env_id, Board.folder_id == folder_id).scalar())
        dept_id = db.query(Department.id).order_by(Department.id).limit(1).scalar()
        b = Board(name=board_name[:200], description="", department_id=dept_id,
                  environment_id=env_id, folder_id=folder_id,
                  position=(maxpos + 1) if maxpos is not None else 0,
                  board_type=BoardType.KANBAN, icon="\U0001F4CB", color="#0073ea",
                  settings=settings)
        db.add(b)
        db.flush()
        # ── groups: the board's own, when the export carries them ────────────
        # Without `group { id title }` in the query monday says nothing about how
        # the board was divided, and inventing three named stages would be a
        # claim about the file that the file does not make. Everything goes into
        # one group, and that group is left unnamed — a name would be a heading
        # over a division that does not exist. It is renamed or split the moment
        # there is something true to call it.
        #
        # A group's colour is monday's where the file carries it. The header
        # colour is how a board is read before a single name is: a "דחוף" that
        # was red on monday arriving green here is the board saying something
        # it never said. Only a file that did not state one falls back to this
        # app's palette.
        gmap, groups = {}, []
        for i, g in enumerate(parsed["groups"]):
            grp = Group(board_id=b.id, name=g["title"][:200], position=i,
                        color=g.get("color") or IMPORT_PALETTE[i % len(IMPORT_PALETTE)],
                        task_status=TaskStatus.BACKLOG)
            db.add(grp)
            groups.append(grp)
            gmap[g["id"]] = grp
        if not groups:
            grp = Group(board_id=b.id, name="", position=0, color="#579bfc",
                        task_status=TaskStatus.BACKLOG)
            db.add(grp)
            groups.append(grp)
        db.flush()
        g1 = groups[0]

        def cells(values, track_sub=False):
            cf = {"status_unset": True, "priority_unset": True}
            for c in parsed["columns"]:
                v = values.get(c["key"])
                if v is None or v == "" or v == []:
                    continue
                if c["type"] == "status":
                    # A status cell references an option; it does not hold a
                    # word. Written as the bare label monday rendered, it
                    # matches nothing in the column's vocabulary and the board
                    # shows "טרם הוגדר" over data that is in fact there.
                    # The label and colour ride along as the fallback the rest
                    # of the system already uses for an option since removed —
                    # which is also where a label past the column's own ceiling
                    # lands, shown in grey rather than swallowed.
                    o = status_opts.get(c["key"], {}).get(str(v))
                    v = ({"id": o["id"], "label": o["label"], "color": o["color"]} if o
                         else {"label": str(v)[:40], "color": "#c4c4c4"})
                elif c["type"] == "files":
                    # a name is enough to see that an item had a spec attached,
                    # and useless for opening it — so the bytes come too
                    v = _import_attachments(db, v, files["budget"], files["stats"],
                                            files.get("cache"))
                elif c["type"] == "people":
                    # A name with no account here is kept AS the name.
                    #
                    # A monday people cell carries monday's own person id
                    # ({"personsAndTeams":[{"id":11397425}]}) and the export
                    # carries no e-mail to resolve it against, so a display name
                    # character-for-character is the only key there is. On her
                    # board that matched almost nobody — 31 people, one of them
                    # "Deleted member" on 41 items, whom monday itself can no
                    # longer name — and every cell that failed to match was
                    # dropped whole: two columns, 306 and 135 items, arrived
                    # empty over data that is plainly there in monday.
                    #
                    # So the name rides along beside the real ids, as a string.
                    # It is not an assignment and cannot become one by accident:
                    # nothing is notified, nothing is tagged, and the report
                    # still names everyone who did not match. What it is, is the
                    # board saying who was on the item — which is the whole
                    # reason to migrate one.
                    out, seen = [], set()
                    for tok in v:
                        name = str(tok).strip()
                        if not name:
                            continue
                        key = by_token.get(name.lower()) or name
                        if key in seen:
                            continue
                        seen.add(key)
                        out.append(key)
                    if not out:
                        continue
                    v = out
                cf[col_ids[c["key"]]] = v
                if track_sub:
                    sub_used.add(col_ids[c["key"]])
            return cf

        made = subs_made = talked = 0
        # the conversation's own ceiling, shared across the whole import
        budget = [IMPORT_MAX_MESSAGES]
        # and the attachments': [files left, bytes left]
        files = {"budget": [IMPORT_MAX_FILES, IMPORT_MAX_FILE_MB * 1024 * 1024],
                 "stats": {}}
        # The attachments, fetched together before the walk begins. Nothing below
        # changes: _import_attachments asks the same questions in the same order
        # and gets the same answers — it just does not wait for them one by one.
        files["cache"] = _prefetch_import_files(
            _attachment_urls(parsed, parsed["columns"]), files["budget"])
        # Identifiers for every row this import writes, minted in one go. Asked
        # per row, each one cost a SELECT ("is this taken on this board?") and
        # the UPDATE that followed the insert — 782 round trips for a board whose
        # every row is being written in this same transaction, and whose answer
        # to that question could only ever be "no": it was created a moment ago
        # and holds nothing.
        uids = iter(_mint_item_uids(len(parsed["items"])
                                    + sum(len(r["subitems"]) for r in parsed["items"])))
        gpos = {}
        # monday's own item id → the task it became. The board's history names
        # items by that id and by nothing else, so this is the only moment the
        # two can be put together.
        by_monday_id = {}
        for row in parsed["items"]:
            grp = gmap.get(row.get("group")) or g1
            pos = gpos[grp.id] = gpos.get(grp.id, -1) + 1
            t = Task(board_id=b.id, group_id=grp.id, title=row["name"][:500],
                     status=TaskStatus.BACKLOG, priority=Priority.MEDIUM, position=pos,
                     created_by=actor_id, custom_fields=cells(row["values"]),
                     item_uid=next(uids), item_uid_board=b.id)
            db.add(t)
            db.flush()
            if row.get("id"):
                by_monday_id[str(row["id"])] = t
            made += 1
            talked += _import_conversation(db, t, row.get("updates"), by_token, budget, files)
            for spos, sub in enumerate(row["subitems"]):
                stask = Task(board_id=b.id, group_id=grp.id, parent_id=t.id,
                             title=sub["name"][:500], status=TaskStatus.BACKLOG,
                             priority=Priority.MEDIUM, position=spos,
                             created_by=actor_id,
                             custom_fields=cells(sub["values"], track_sub=True),
                             item_uid=next(uids), item_uid_board=b.id)
                db.add(stask)
                db.flush()
                subs_made += 1
                talked += _import_conversation(db, stask, sub.get("updates"), by_token,
                                                   budget, files)

        # ── the board's history ──────────────────────────────────────────────
        # Written as the same AuditLog rows the log already reads, so it shows
        # up in both places at once: the item's own לוגים tab and the board-level
        # log. There is one log here, not two.
        #
        # `origin` marks every row as monday's, which is what stops it offering
        # an undo — reverting a change made in monday a year ago would write
        # that value onto the item now, from a button that looks like every
        # other undo. It also keeps the author's name, for the people the
        # account has no match for; the audit has nowhere else to put a person.
        logged, log_unmatched = 0, 0
        for row in parsed.get("activity") or []:
            t = by_monday_id.get(str(row.get("item") or ""))
            if t is None:
                log_unmatched += 1
                continue
            uid = (by_token.get((row.get("email") or "").lower())
                   or by_token.get((row.get("author") or "").lower()))
            field = row.get("field")
            if field == "column":
                cid = col_ids.get(row.get("column") or "")
                if not cid:
                    # the column did not make the trip (its own budget, or a type
                    # with nothing to carry) — so neither can its history
                    log_unmatched += 1
                    continue
                field = "col:" + cid
            when = None
            if row.get("at"):
                try:
                    when = datetime.fromisoformat(str(row["at"]).replace("Z", "+00:00"))
                    when = when.replace(tzinfo=None)
                except ValueError:
                    when = None
            # values go in the shape the log's own reader expects of a column —
            # JSON — so "ריק" stays empty rather than arriving as the word null
            enc = lambda v: json.dumps(v, ensure_ascii=False) if v not in (None, "") else None
            db.add(AuditLog(
                entity_type="task", entity_id=t.id, action=row.get("action") or "update",
                field_name=field, old_value=enc(row.get("old")), new_value=enc(row.get("new")),
                changed_by=uid,
                created_at=when or datetime.now(timezone.utc).replace(tzinfo=None),
                origin={"source": "monday", "event": (row.get("event") or "")[:40],
                        "author": (row.get("author") or "")[:120], "matched": bool(uid)}))
            logged += 1

        if sub_used or sub_only_ids:
            # Sub-items show only the columns they actually carry, in the order
            # monday's sub-item board puts them — the sub-item-only ones
            # included, at their own place. They used to be left out of this
            # list and appended by the board after the shared ones, which
            # reshuffled any sub-item board that interleaves the two; the board
            # now places a sub-item-only column wherever sub_cols names it.
            # A column the sub-item order does not mention (a file whose
            # sub-items were never surveyed) keeps board order, behind them.
            s2 = dict(b.settings)
            wanted = set(sub_used) | set(sub_only_ids)
            ordered = [col_ids[k] for k in (parsed.get("sub_order") or [])
                       if col_ids.get(k) in wanted]
            ordered += [c["id"] for c in custom_cols
                        if c["id"] in wanted and c["id"] not in ordered]
            s2["sub_cols"] = ["item"] + ordered
            b.settings = s2
        db.add(BoardMember(board_id=b.id, user_id=actor_id, role="admin"))
        db.commit()
        db.refresh(b)

        wanted = parsed["report"].get("updates") or 0
        return {"id": b.id, "name": b.name, "icon": b.icon,
                "items": made, "subitems": subs_made, "columns": len(custom_cols),
                "messages": talked,
                "files": files["stats"].get("imported", 0),
                "report": {**parsed["report"],
                           # the colour each group actually ended up with, beside
                           # the names in `group_names`. The report shows the
                           # groups as the chips they are on the board, which is
                           # the one way "the colours came across" can be checked
                           # at a glance instead of taken on trust.
                           "group_hex": [g.color for g in groups][:40],
                           # the board's name, and which of the three places it
                           # came from — see _board_name_from
                           "board_name": board_name[:200],
                           "board_name_from": name_from,
                           "messages_imported": talked,
                           "files_imported": files["stats"].get("imported", 0),
                           "files_bytes": files["stats"].get("bytes", 0),
                           # a link that had already expired, or a host we do not
                           # fetch from: the name is kept, the file is not here
                           "files_unreachable": files["stats"].get("failed", 0),
                           # a link whose own signature says it lapsed before the
                           # import ran — the one failure worth naming separately,
                           # because the fix is "export and import in one go"
                           "files_expired": files["stats"].get("expired", 0),
                           "files_over_budget": files["stats"].get("over_budget", 0),
                           # a conversation cut by the import's own ceiling, as
                           # opposed to one the file never carried
                           "messages_dropped": max(0, wanted - talked),
                           "people_matched": len(set(by_token.values())),
                           "people_unmatched": unmatched}}


@app.post("/api/boards/import")
async def import_board(file: UploadFile = File(...), name: Optional[str] = Form(None),
                       environment_id: Optional[int] = Form(None),
                       folder_id: Optional[int] = Form(None),
                       actor_id: int = Depends(current_user_id)):
    raw = await file.read()
    filename = file.filename
    if len(raw) > IMPORT_MAX_UPLOAD_MB * 1024 * 1024:
        # The size is said, because "too big" over a file the user believes is
        # small is not something they can act on — and so is the reason it is
        # usually bigger than it looks: a monday response saved from Postman's
        # pretty view is about three times the JSON it holds, all of it
        # indentation, and saving the raw body is the whole fix.
        raise HTTPException(413,
            f"הקובץ גדול מדי — {len(raw) / 1048576:.1f}MB, והמקסימום הוא "
            f"{IMPORT_MAX_UPLOAD_MB}MB. אם שמרת את התשובה מהתצוגה המיופה של פוסטמן, "
            "ההזחה היא כ-70% מהקובץ: שמור את ה-body הגולמי (Raw) ונסה שוב")
    # A monday export is JSON, and the JSON of a long board is mostly the same
    # column ids and type names written out again on every one of its rows. The
    # 21,187-item board that prompted this came out at 78.5MB and gzips to
    # 4.0MB — twenty times smaller for a file that says exactly the same thing.
    #
    # It matters because the wait people describe as "the import is slow" is not
    # the import: writing all 21,187 items and their 9,950 history rows takes 13
    # seconds, measured. The rest of it is 78MB climbing a home upload link to
    # Azure, and that is the half a smaller file actually fixes.
    #
    # Unpacked under the SAME ceiling rather than before it: a few compressed
    # megabytes can name a file no machine can hold, so the limit is on what the
    # import reads, not on what arrived. Reading cap+1 is how that is noticed
    # without materialising the bomb first.
    if raw[:2] == b"\x1f\x8b":
        cap = IMPORT_MAX_UPLOAD_MB * 1024 * 1024
        try:
            with gzip.GzipFile(fileobj=io.BytesIO(raw)) as _gz:
                raw = _gz.read(cap + 1)
        except (OSError, EOFError):
            raise HTTPException(400,
                "הקובץ הדחוס פגום ולא ניתן לפרוס אותו — שמור אותו שוב ונסה שנית")
        if len(raw) > cap:
            raise HTTPException(413,
                f"הקובץ הדחוס נפרס ליותר מ-{IMPORT_MAX_UPLOAD_MB}MB, וזו התקרה")
        # so the ".json" the reader dispatches on is not hidden behind ".gz"
        if (filename or "").lower().endswith(".gz"):
            filename = filename[:-3]
    # Reading a workbook and writing a few hundred rows is seconds of CPU and of
    # blocking database calls. Run on the event loop, that is not just this one
    # request being slow: every other request in the app waits behind it — the
    # board someone else is opening, the avatars, the live event stream — which
    # is what makes an import feel like the whole system froze. Off the loop, the
    # import takes exactly as long and nothing else notices.
    return await run_in_threadpool(_import_board_file, raw, filename, name,
                                   environment_id, folder_id, actor_id)


def _import_board_file(raw, filename, name, environment_id, folder_id, actor_id):
    # A monday.com API response is JSON, not a table, and carries the column
    # types a CSV export would have flattened to text. It gets its own reader.
    if (filename or "").lower().endswith(".json") or import_monday.looks_like_monday(raw):
        return _import_monday_board(raw, filename, name, environment_id, folder_id, actor_id)
    try:
        shaped = _imp_parse_tabular(raw, filename, with_shape=True)
    except Exception:
        raise HTTPException(400, "לא ניתן לקרוא את הקובץ — ודא שהוא CSV או Excel תקין")
    # Before anything is dropped, so the rows still line up with the sheet's own.
    shaped, formula_cells = _imp_formula_text(raw, filename, shaped)
    # drop fully-empty rows
    shaped = [row for row in shaped
              if any(c is not None and str(c).strip() != "" for c in row[3])]
    if not shaped:
        raise HTTPException(400, "הקובץ ריק")
    rows = [row[3] for row in shaped]
    ncols = min(max(len(r) for r in rows), IMPORT_MAX_COLS)
    if ncols < 1:
        raise HTTPException(400, "לא נמצאו עמודות בקובץ")
    # A board exported from monday states its name and its group division on
    # lines of their own above the header; read from row 0 those lines become the
    # header and two items. Read that layout as what it is, and fall back to
    # "row 0 is the header" for every other sheet.
    md = _imp_monday_layout(shaped)
    if md:
        sheet_title, header, all_body, summary_rows = md[0], md[1], md[2], md[3]
    else:
        sheet_title, header, all_body, summary_rows = None, rows[0], shaped[1:], 0
    body = all_body[:IMPORT_MAX_ROWS]
    # A sheet past the ceiling was cut here without a word, which is the one
    # thing an import must not do: a board short by its last 400 rows looks
    # exactly like a board that has 2,000.
    rows_dropped = len(all_body) - len(body)

    def _cell(r, i):
        return (str(r[i]).strip() if i < len(r) and r[i] is not None else "")

    labels = [(_cell(header, i) or f"עמודה {i + 1}") for i in range(ncols)]

    # ── what the file says about sub-items ───────────────────────────────
    # Two ways a sheet can say "this belongs under that", read in this order:
    # the indentation a board exported from here writes — where the structure IS
    # the sheet — and failing that a column naming the parent by its title, which
    # is how a CSV or a hand-made sheet says the same thing.
    hier = any(lvl >= 1 for lvl, *_ in body)
    parent_at = next((i for i in range(1, ncols)
                      if labels[i].strip().lower() in IMPORT_PARENT_HEADERS), None)
    # and the same for the group: a sheet with a "קבוצה" column is dividing its
    # board by it, the way an exported one divides by its group rows.
    group_at = next((i for i in range(1, ncols)
                     if labels[i].strip().lower() in IMPORT_GROUP_HEADERS), None)

    # ── read the sheet into groups, items and sub-items ──────────────────
    # `band` is the grey header this app writes over a sub-item block, naming the
    # columns those sub-items have. It is a header, not an item, and its labels
    # are what a sub-item's cells are read against.
    #
    # `group_paint` is the colour each group row was painted — monday fills that
    # row with the group's colour and this app's own export writes it on the
    # text, so it is the source board saying what colour the group is. Kept by
    # name, which is how every step after this one refers to a group.
    # `plan` carries each row's paints beside its values: a status cell is a
    # coloured chip, and the fill is the sheet saying which colour — see
    # _imp_status_vocab.
    plan, band_vals, sub_labels, group_paint = [], None, [], {}
    for lvl, is_band, paint, r, cpaint in body:
        vals = [_cell(r, i) for i in range(ncols)]
        paints = [(cpaint[i] if i < len(cpaint) else None) for i in range(ncols)]
        if hier and lvl == 0:
            plan.append(("group", vals, paints))
            if paint and vals[0]:
                group_paint.setdefault(vals[0], paint)
            continue
        if hier and lvl >= 2:
            if is_band or (band_vals is not None and vals[1:] == band_vals[1:]):
                band_vals = vals
                sub_labels = [v or f"עמודה {i + 1}" for i, v in enumerate(vals)]
                continue
            plan.append(("sub", vals, paints))
            continue
        plan.append(("item", vals, paints))
    item_rows = [v for kind, v, _ in plan if kind == "item"]
    item_paints = [p for kind, _, p in plan if kind == "item"]
    sub_rows = [v for kind, v, _ in plan if kind == "sub"]
    sub_paints = [p for kind, _, p in plan if kind == "sub"]
    # monday writes its sub-items twice: once as their own rows under the band,
    # and once comma-joined into a column of the item ("Subitems"). Kept, that
    # column is the same names a second time as text, standing beside the
    # sub-items it names. The band says which column it is — its own title is
    # the band's first cell.
    # The band names it — its own title is the band's first cell — and for a board
    # whose sub-items were not exported there is no band, so monday's own name
    # for the column stands in. Only ever inside monday's layout: a column
    # someone here called "תתי משימות" by hand is a column of their board.
    sub_col_at = None
    if md:
        _st = _cell(band_vals or [], 0)
        def _is_sub_col(i):
            return (labels[i] == _st if _st
                    else labels[i].strip().lower() in IMPORT_SUBITEMS_HEADERS)
        sub_col_at = next((i for i in range(1, ncols) if _is_sub_col(i)), None)
    if not item_rows:
        raise HTTPException(400, "לא נמצאו פריטים בקובץ")

    # ── the columns ──────────────────────────────────────────────────────
    # An item column is typed from what the items put in it. A column only the
    # sub-items have is typed from the sub-items, and one they share with the
    # items keeps the item column — sub-items on a board show a subset of its
    # columns, never a parallel set of their own.
    # A column with nothing under it on any row is not a column of this board —
    # the same rule the monday import follows. It is created neither when the
    # sheet gives it no heading (a column that is not there at all) nor when it
    # has a heading and no values: an empty column standing in front of the
    # board that was actually imported is a column nobody asked for. Named in
    # the report either way, so "where is it?" has an answer.
    def _has_values(i):
        return any((str(r[i]).strip() if i < len(r) and r[i] is not None else "")
                   for r in item_rows)

    def _blank_col(i):
        return not _cell(header, i) and not _has_values(i)

    empty_cols = [labels[i] for i in range(1, ncols)
                  if i not in (parent_at, group_at, sub_col_at)
                  and _cell(header, i) and not _has_values(i)]
    data_at = [i for i in range(1, ncols)
               if i not in (parent_at, group_at, sub_col_at) and _has_values(i)]
    # What a column holds, and — for the ones that would otherwise be text — the
    # vocabulary its paint says it is. A status column read as text loses both
    # the words the picker offers and the colour each one is read by, which on a
    # board exported from here is the whole of what its status columns were.
    def _typed(i, body_rows, body_paints):
        cells = [(r[i] if i < len(r) else None) for r in body_rows]
        ctype = _imp_infer_type(cells)
        if ctype == "number":
            # a number column that wrote its unit into every cell keeps the unit
            # as the column's own, the way one made here shows it
            return ctype, _imp_number_unit(
                [v for v in cells if v is not None and str(v).strip() != ""])
        if ctype != "text":
            return ctype, None
        vocab = _imp_status_vocab([_cell(r, i) for r in body_rows],
                                  [(p[i] if i < len(p) else None) for p in body_paints])
        return ("status", vocab) if vocab else ("text", None)

    col_typed = [_typed(i, item_rows, item_paints) for i in data_at]
    col_ids = ["col_" + uuid.uuid4().hex[:8] for _ in data_at]
    by_label = {labels[i]: (cid, i) for i, cid in zip(data_at, col_ids)}
    # column id → {label: the option its cells point at}, so a cell can be
    # written as the option it references rather than as a loose word
    status_opts = {}

    def _status_col(cid, vocab):
        """A status column's options: each word in the colour the sheet painted
        it, and this app's palette only where the sheet painted none."""
        opts = _status_col_options(
            [{"label": o["label"],
              "color": o["color"] or IMPORT_PALETTE[j % len(IMPORT_PALETTE)]}
             for j, o in enumerate(vocab)])
        status_opts[cid] = {o["label"]: o for o in (opts or [])}
        return opts

    def _new_col(cid, ctype, extra, title):
        col = {"id": cid, "type": ctype, "title": title,
               "options": _status_col(cid, extra) if ctype == "status" else None,
               "formula": None, "connect": None, "copy_mode": None, "perms": {}}
        if ctype == "number" and extra:
            col["number"] = _number_col_cfg({"unit": extra})
        return col

    custom_cols = [_new_col(cid, ctype, extra, labels[i])
                   for cid, (ctype, extra), i in zip(col_ids, col_typed, data_at)]
    # how much of the statuses' colour came out of the sheet rather than out of
    # the palette — the same question the report already answers for the groups
    status_options = sum(len(c["options"] or []) for c in custom_cols if c["type"] == "status")
    status_colored = sum(1 for ctype, vocab in col_typed if ctype == "status"
                         for o in vocab if o["color"])
    type_of = {c["id"]: c["type"] for c in custom_cols}
    # a sub-item column maps to the board column of the same name, or becomes one
    sub_map = []          # (index in the sub row, column id)
    sub_col_ids = []
    # A band column the items have no column for exists only on the sub-items —
    # which is exactly what the export says by naming it in the band and not in
    # the item header. Created as an ordinary board column it stood on every
    # item as well, empty forever, and the structure the board gave its
    # sub-items did not survive the trip.
    sub_only_ids = []
    for i in range(2, len(sub_labels)):
        # a band cell with nothing written in it names no column; invented, it
        # arrives as an "עמודה 21" the sub-items show and nobody can fill
        if not _cell(band_vals or [], i):
            continue
        room = len(custom_cols) < IMPORT_MAX_COLS - 1
        if not room and sub_labels[i] not in by_label:
            continue
        hit = by_label.get(sub_labels[i])
        ctype, extra = _typed(i, sub_rows, sub_paints)
        # A title is what joins a sub-item column to an item column, and a title
        # is not a type. monday's sub-item board is a board of its own: its
        # "כמות" can be a numbers column while the parent's "כמות" is text.
        # Joined anyway, the sub-items' figures were written into the item's
        # text column — a number column that "arrived as text" — or, the other
        # way round, the sub-items' words were coerced into a number column and
        # dropped. So the join holds only when the sub-items' own cells read as
        # the same type; otherwise they get a column of their own, as the monday
        # JSON import already does (it matches on title AND type). A status
        # column the sub-items left unpainted still joins: the word is the same
        # word, and _imp_status_cell writes it either way.
        # Two number columns with different units are not one column either:
        # joined, the sub-items' "4 שעות" was shown as "4 ימים".
        def _unit_of(cid):
            c = next((c for c in custom_cols if c["id"] == cid), None) or {}
            return (c.get("number") or {}).get("unit") or ""
        if (hit and room and any(_cell(r, i) for r in sub_rows)
                and (ctype != type_of.get(hit[0])
                     or (ctype == "number" and (extra or "") != _unit_of(hit[0])))
                and not (type_of.get(hit[0]) == "status" and ctype == "text")):
            hit = None
        if hit:
            cid = hit[0]
        else:
            cid = "col_" + uuid.uuid4().hex[:8]
            custom_cols.append(_new_col(cid, ctype, extra, sub_labels[i]))
            type_of[cid] = ctype
            if ctype == "status":
                status_options += len(custom_cols[-1]["options"] or [])
                status_colored += sum(1 for o in extra if o["color"])
            by_label.setdefault(sub_labels[i], (cid, None))
            sub_only_ids.append(cid)
        sub_map.append((i, cid))
        # Every sub-item column, shared or not, in the order the band lists
        # them. The sub-item-only ones used to be left out of this list and
        # appended by the board after the shared ones, so a sub-item board whose
        # columns interleave the two came back reshuffled: "Owner, Status,
        # תאריך" in monday read "Status, תאריך, Owner" here. The board now
        # places a sub-item-only column wherever sub_cols names it.
        if cid not in sub_col_ids:
            sub_col_ids.append(cid)
    # A column named in the header, empty on every item and filled by the
    # sub-items is now a column of this board — so it is no longer one of the
    # ones the report says were left out for being empty.
    _made = {c["title"] for c in custom_cols}
    empty_cols = [t for t in empty_cols if t not in _made]

    with Session(engine) as db:
        creator = actor_id
        env_id = environment_id
        if not env_id:
            primary = db.query(Environment).filter(Environment.is_primary == True).first()
            env_id = primary.id if primary else None
        if not (_cap(db, creator, "create_board") or _can_manage_env(db, env_id, creator)):
            raise HTTPException(403, "אין לך הרשאה ליצור לוח חדש")
        dept_id = db.query(Department.id).order_by(Department.id).limit(1).scalar()
        maxpos = (db.query(func.max(Board.position))
                  .filter(Board.environment_id == env_id, Board.folder_id == folder_id).scalar())
        base = os.path.splitext(os.path.basename(filename or ""))[0]
        # An exported board names itself on its first line; the file it was saved
        # as carries whatever the browser called it ("Spotical_1786443119").
        board_name = (name or "").strip() or (sheet_title or "").strip() or base or "לוח מיובא"
        name_from = _board_name_from(name, sheet_title, base)
        settings = {
            "views": ["table"],
            # The file's columns first, in the file's own order, and the three
            # the system issues on its own after them. Put first — which is
            # where a board created by hand starts with them — they sit between
            # the item's name and the first column of the board that was
            # actually imported, so the migrated board reads three columns of
            # metadata before it reads anything anybody wrote. It is the same
            # judgement the export already makes (see EXPORT_AUTO_COLS).
            "columns": custom_cols + IMPORT_SYSTEM_COLS(),
            "col_labels": {"item": labels[0]},   # name the item column after the first header
            # The board's four built-in columns — אחראים, סטטוס, עדיפות,
            # תאריך יעד — are not in the file and nothing in this import fills
            # them. Left showing, they are four columns of "טרם הוגדר" standing
            # in front of the board that was actually imported, and they follow
            # it into every export of it.
            # Hidden, not removed: a board admin turns any of them back on the
            # moment there is something to put in it.
            "col_hidden": ["assignees", "status", "priority", "due"],
        }
        if sub_col_ids or sub_only_ids:
            # sub-items show the columns the file gave them, in the band's own
            # order — sub-item-only ones included, see sub_col_ids above
            settings["sub_cols"] = ["item"] + sub_col_ids
            settings["sub_only"] = sub_only_ids
        b = Board(name=board_name, description="", department_id=dept_id, environment_id=env_id,
                  folder_id=folder_id, position=(maxpos + 1) if maxpos is not None else 0,
                  board_type=BoardType.KANBAN, icon="\U0001F4CB", color="#0073ea", settings=settings)
        db.add(b)
        db.flush()

        # ── groups: the file's own where it has them ─────────────────────
        # A sheet that names its groups is describing a board someone already
        # divided; inventing בתכנון/בביצוע/הושלם over it would file every item
        # under a heading the file never claimed. A flat sheet has no such
        # division, and the three stages are the board it is being turned into.
        #
        # Three ways a file names the division, in the order they are trusted:
        # the group rows an exported board writes between its items, a column
        # naming each row's group — the only way a CSV can say it — and, failing
        # both, nothing, which is the one case that gets the default stages.
        named = [_cell(v, 0) for kind, v, _ in plan if kind == "group" and _cell(v, 0)]
        col_groups = []
        if not named and group_at is not None:
            for kind, vals, _ in plan:
                if kind != "item":
                    continue
                g = _cell(vals, group_at)
                if g and g not in col_groups:
                    col_groups.append(g)
        # an item whose group cell is empty belongs to no group the file named,
        # and filing it under the first one would be a quiet misplacement
        col_blank = bool(col_groups) and any(
            not _cell(v, group_at) for kind, v, _ in plan if kind == "item")
        from_file = named or col_groups
        groups = []
        if from_file:
            # The colour the sheet gave the group, where it gave one. A board
            # exported with its groups coloured comes back coloured; a sheet
            # that says nothing about colour gets this app's palette, which is a
            # default rather than a claim about the file.
            for i, gname in enumerate(list(from_file) + (["ללא קבוצה"] if col_blank else [])):
                groups.append(Group(board_id=b.id, name=gname[:200], position=i,
                                    color=(group_paint.get(gname)
                                           or IMPORT_PALETTE[i % len(IMPORT_PALETTE)]),
                                    task_status=TaskStatus.BACKLOG))
        else:
            groups = [Group(board_id=b.id, name="בתכנון", position=0, color="#579bfc",
                            task_status=TaskStatus.BACKLOG),
                      Group(board_id=b.id, name="בביצוע", position=1, color="#fdab3d",
                            task_status=TaskStatus.IN_PROGRESS),
                      Group(board_id=b.id, name="הושלם", position=2, color="#00c875",
                            task_status=TaskStatus.DONE)]
        db.add_all(groups)
        db.flush()
        by_group = {g.name: g for g in groups} if col_groups else {}

        # The same budget the monday import runs under, shared by every file in
        # this one: the cells that hold addresses, and the file sheet.
        files = {"budget": [IMPORT_MAX_FILES, IMPORT_MAX_FILE_MB * 1024 * 1024],
                 "stats": {}}

        def cells_of(vals, pairs):
            cf = {"status_unset": True, "priority_unset": True}
            for i, cid in pairs:
                col = next((c for c in custom_cols if c["id"] == cid), None)
                val = _imp_coerce(vals[i] if i < len(vals) else None, col["type"] if col else "text")
                if col and col["type"] == "status":
                    # the option the column offers for that word, not the word
                    val = _imp_status_cell(status_opts.get(cid), val)
                elif col and col["type"] == "files" and val:
                    # a name is enough to see that an item had a spec attached,
                    # and useless for opening it — so the bytes come too, where
                    # they can be had at all
                    val = _import_attachments(db, val, files["budget"], files["stats"])
                if val is not None and val != "":
                    cf[cid] = val
            return cf

        item_pairs = list(zip(data_at, col_ids))
        pos, subs_made, made_tasks = 0, 0, []
        # item id → the sub-item names its sub-items column holds, for the items
        # whose sub-items are in the file as NAMES and not as rows of their own.
        # Emptied the moment a sub-item row turns up under the item — a row says
        # everything a name does and more. See _imp_subitem_names.
        named_subs, pending_named = 0, {}
        by_title, parent_of = {}, {}
        grp = groups[0]
        gi, gpos, last_item = -1, {}, None
        for kind, vals, _paints in plan:
            if kind == "group":
                gi += 1
                if gi < len(groups):
                    grp = groups[gi]
                last_item = None
                continue
            if kind == "sub":
                # the band's first column is the sub-item's own name
                title = _cell(vals, 1) or f"תת־פריט {subs_made + 1}"
                if last_item is None:
                    continue                      # a sub-item with nothing above it
                pending_named.pop(last_item.id, None)
                t = Task(board_id=b.id, group_id=last_item.group_id, parent_id=last_item.id,
                         title=title[:500], status=TaskStatus.BACKLOG, priority=Priority.MEDIUM,
                         position=subs_made, created_by=creator,
                         custom_fields=cells_of(vals, sub_map))
                db.add(t)
                db.flush()
                _ensure_item_uid(db, t)
                _audit(db, t.id, "create", field="subitem", old=None, new=t.title, user_id=creator)
                made_tasks.append(t)
                subs_made += 1
                continue
            title = _cell(vals, 0) or f"פריט {pos + 1}"
            if by_group:
                # the row names its own group, so the row decides — not its place
                # in the file, which for a flat sheet says nothing
                grp = by_group.get(_cell(vals, group_at)) or groups[-1]
            p = gpos[grp.id] = gpos.get(grp.id, -1) + 1
            t = Task(board_id=b.id, group_id=grp.id, title=title[:500], status=TaskStatus.BACKLOG,
                     priority=Priority.MEDIUM, position=p, created_by=creator,
                     custom_fields=cells_of(vals, item_pairs))
            db.add(t)
            db.flush()
            _ensure_item_uid(db, t)
            _audit(db, t.id, "create", field="item", old=None, new=t.title, user_id=creator)
            made_tasks.append(t)
            by_title.setdefault(t.title, t)
            if parent_at is not None:
                pname = _cell(vals, parent_at)
                if pname:
                    parent_of[t.id] = pname
            # Only for a row that names ITSELF. A row with an empty first cell
            # and a name in its second is a sub-item whose band went unread (see
            # the summary-line rule in _imp_monday_layout) — that second cell is
            # its own name, not a list of sub-items under it, and read as one it
            # became a sub-item of a nameless item.
            if sub_col_at is not None and _cell(vals, 0):
                names = _imp_subitem_names(_cell(vals, sub_col_at))
                if names:
                    pending_named[t.id] = (t, names)
            last_item = t
            pos += 1

        # ── sub-items the file names and does not spell out ──────────────
        # monday writes its sub-items twice: as rows of their own under a band,
        # and as their names joined by commas in the item's sub-items column.
        # A file exported without the rows — monday's CSV export, an Excel one
        # whose sub-items were not expanded — still carries that column, and it
        # is the file saying those sub-items exist. Read as nothing, the board
        # arrived without them while the report said that column "became the
        # sub-items": the loss named as the feature.
        #
        # So the names become sub-items. They carry a name and nothing else —
        # the file holds nothing else about them — and the report says exactly
        # that, beside what to re-export to bring the rest.
        for t, names in pending_named.values():
            for name in names:
                sub = Task(board_id=b.id, group_id=t.group_id, parent_id=t.id,
                           title=name[:500], status=TaskStatus.BACKLOG,
                           priority=Priority.MEDIUM, position=subs_made, created_by=creator,
                           custom_fields={"status_unset": True, "priority_unset": True})
                db.add(sub)
                db.flush()
                _ensure_item_uid(db, sub)
                _audit(db, sub.id, "create", field="subitem", old=None, new=sub.title,
                       user_id=creator)
                made_tasks.append(sub)
                subs_made += 1
                named_subs += 1
        db.flush()

        # ── a parent named by column ─────────────────────────────────────
        # Resolved after every row is in, because a file may name a parent that
        # appears below the row pointing at it. A name that matches nothing is
        # left as a top-level item and reported — guessing at the nearest title
        # would file someone's item under the wrong parent silently.
        orphans = []
        for t in made_tasks:
            pname = parent_of.get(t.id)
            if not pname:
                continue
            parent = by_title.get(pname)
            if parent is None or parent.id == t.id:
                orphans.append(pname)
                continue
            t.parent_id = parent.id
            t.group_id = parent.group_id
            pos -= 1
            subs_made += 1
        db.flush()

        # the conversation sheet, when the workbook carries one
        talk = _imp_attach_conversation(db, _imp_conversation_sheet(raw, filename),
                                        made_tasks, creator, [IMPORT_MAX_MESSAGES])
        # and the file sheet, which is where the addresses of the attachments are
        attached = _imp_attach_files(db, _imp_files_sheet(raw, filename), made_tasks, b,
                                     files, IMPORT_MAX_COLS)
        db.add(BoardMember(board_id=b.id, user_id=creator, role="admin"))
        db.commit()
        db.refresh(b)
        st_files = files["stats"]
        return {"id": b.id, "name": b.name, "icon": b.icon, "items": pos,
                "subitems": subs_made, "columns": len(custom_cols),
                "messages": talk["messages"] + talk["replies"],
                "files": st_files.get("imported", 0) + st_files.get("reused", 0),
                "report": {"messages_imported": talk["messages"] + talk["replies"],
                           # the files: brought across, already here, or a named
                           # link to somewhere this server cannot fetch from
                           "files_imported": st_files.get("imported", 0),
                           "files_bytes": st_files.get("bytes", 0),
                           "files_reused": st_files.get("reused", 0),
                           "files_linked": st_files.get("linked", 0),
                           "files_unreachable": st_files.get("failed", 0),
                           "files_expired": st_files.get("expired", 0),
                           "files_over_budget": st_files.get("over_budget", 0),
                           "files_gone": st_files.get("gone", 0),
                           "files_items_unmatched": attached["unmatched_items"],
                           "replies_imported": talk["replies"],
                           "conversation_items_unmatched": talk["unmatched_items"],
                           "people_unmatched": talk["unmatched_people"],
                           # the division that came out of the FILE — a board
                           # that got the three default stages instead says so
                           # with a 0 here and "default" below, rather than
                           # reporting three groups nobody asked for
                           "groups": len(from_file),
                           "group_names": [g.name for g in groups][:40],
                           # the colour each one ended up with, and how many of
                           # those the sheet itself painted — see group_paint
                           "group_hex": [g.color for g in groups][:40],
                           "group_colors": sum(1 for g in groups if g.name in group_paint),
                           # and the statuses: the columns the sheet's paint
                           # said were status columns, how many words they
                           # offer, and how many of those came out of the file
                           # wearing their own colour rather than the palette
                           "status_cols": sum(1 for c in custom_cols if c["type"] == "status"),
                           "status_options": status_options,
                           "status_colors": status_colored,
                           # and where it came from, because "3 קבוצות" over an
                           # undivided board reads exactly like a division
                           "board_name": board_name[:200],
                           "board_name_from": name_from,
                           "groups_from": ("sheet" if named else
                                           "column" if col_groups else "default"),
                           "groups_column": labels[group_at] if (col_groups and group_at is not None) else "",
                           # the line monday writes under each group, holding
                           # that group's rolled-up dates and no name
                           "summary_rows": summary_rows,
                           # cells the spreadsheet never worked out, which came
                           # across as the formula itself rather than as empty
                           "formula_cells_as_text": formula_cells,
                           # a heading in the file with nothing under it: named,
                           # not created — see _has_values above
                           "columns_empty": empty_cols,
                           "rows_dropped": rows_dropped,
                           # how the file said what belongs under what
                           "hierarchy": ("band" if (md and sub_rows)
                                         else "indent" if (hier and sub_rows)
                                         else "parent_column" if (parent_at is not None and subs_made)
                                         else ""),
                           # the columns that were the sub-items themselves
                           "as_subitems": ([labels[sub_col_at]] if sub_col_at is not None else []),
                           # Of the sub-items on the board, the ones built from
                           # a name in that column and nothing else, because the
                           # file carried no row for them. They are here, and
                           # they carry no columns: said apart from the count,
                           # so it is not read as sub-items that came whole.
                           "subitems_named": named_subs,
                           # and the ones the sub-items have and the items do
                           # not — named, because that is where somebody will
                           # look for them on the item row and not find them
                           "columns_sub": [c["title"] for c in custom_cols
                                           if c["id"] in set(sub_only_ids)],
                           "parents_unmatched": sorted(set(orphans))[:20]}}


@app.patch("/api/boards/{board_id}")
def update_board(board_id: int, data: dict, actor_id: int = Depends(current_user_id)):
    with Session(engine) as db:
        b = db.query(Board).filter(Board.id == board_id).first()
        if not b or b.deleted_at:
            raise HTTPException(404, "board not found")
        # Every key below used to be checked on its own, and the ones that are
        # not admin-only — the name, icon, colour, views, view_only — were not
        # checked at all: a user who was never invited to the board, refused a
        # GET on it with 403, could still rename it with a PATCH (found by the
        # penetration test of 2026-11). Changing a board starts with being
        # someone who may change it; the admin-only keys then narrow further.
        _require_board_edit(db, board_id, actor_id)
        if data.get("name") is not None:
            b.name = data["name"]
        if data.get("icon") is not None:
            b.icon = data["icon"]
        if data.get("color") is not None:
            b.color = data["color"]
        if data.get("views") is not None:
            views = ["table"] + [v for v in data["views"] if v in ALL_VIEWS and v != "table"]
            s = dict(b.settings or {})
            s["views"] = views
            b.settings = s
        if "timezone" in data:
            # the board's dates are read in a place, and this is where it says
            # which one. Board admins only: it moves when every date rule fires.
            if _board_role(db, board_id, actor_id) != "admin":
                raise HTTPException(403, "רק מנהל הלוח יכול לשנות את אזור הזמן")
            tzn = str(data["timezone"] or "").strip()
            if tzn and not _zone(tzn):
                raise HTTPException(400, "אזור זמן לא מוכר — נדרש שם IANA, למשל Asia/Jerusalem")
            s = dict(b.settings or {})
            if tzn:
                s["timezone"] = tzn
            else:
                s.pop("timezone", None)            # back to the organisation's
            b.settings = s
        if "view_only" in data:
            s = dict(b.settings or {})
            s["view_only"] = bool(data["view_only"])
            b.settings = s
        if "visibility" in data:
            # Board admins only. Publishing a board hands it to everyone in the
            # environment at once, which is not something an editor should be
            # able to do on their own.
            if _board_role(db, board_id, actor_id) != "admin":
                raise HTTPException(403, "רק מנהל הלוח יכול לשנות את חשיפת הלוח")
            v = data["visibility"]
            if v not in BOARD_VISIBILITY:
                raise HTTPException(400, "ערך חשיפה לא תקין")
            s = dict(b.settings or {})
            s["visibility"] = v
            b.settings = s
        if "perm_column" in data:
            # Which column says who an item is assigned to, for the
            # assigned_editor / assigned_only members. Board admins only: moving
            # it re-decides, at once, which items every such member may see and
            # edit. Only the built-in circles or one of this board's own people
            # columns — anything else would be a perm column nobody can ever
            # be put in, and is refused rather than stored and ignored.
            if _board_role(db, board_id, actor_id) != "admin":
                raise HTTPException(403, "רק מנהל הלוח יכול לקבוע את עמודת ההרשאות")
            pc = data["perm_column"]
            if not isinstance(pc, str) or (pc != "assignees" and not any(
                    c.get("id") == pc and c.get("type") == "people"
                    for c in (b.settings or {}).get("columns", []) or [])):
                raise HTTPException(400, "עמודת ההרשאות חייבת להיות עמודת אנשים בלוח")
            s = dict(b.settings or {})
            s["perm_column"] = pc
            b.settings = s
        # `form` used to be a key in here — one form per board, four flags
        # per field, rebuilt from the live columns on every open. A form is a
        # view of the board now, with a row of its own and endpoints of its
        # own; see the Form View section. The key is migrated away at startup
        # by _migrate_board_forms and is not accepted here any more.
        if data.get("col_widths") is not None:
            # only a board admin may set column widths (drag-to-resize)
            if _board_role(db, board_id, actor_id) != "admin":
                raise HTTPException(403, "רק מנהל הלוח יכול לשנות רוחב עמודות")
            widths = {}
            for k, v in (data["col_widths"] or {}).items():
                try:
                    widths[str(k)] = max(60, min(600, int(v)))
                except (TypeError, ValueError):
                    continue
            s = dict(b.settings or {})
            s["col_widths"] = widths
            b.settings = s
        if data.get("sub_col_widths") is not None:
            # The sub-item table is its own, narrower table, set in from the
            # parent row. It used to borrow the item table's widths, so a
            # status column widened for the items widened every sub-item panel
            # with it, and the sub-item name was fixed at 260px for everybody.
            # Its widths are kept apart, under the same rule and the same
            # clamp: a board admin drags them, everybody sees them.
            if _board_role(db, board_id, actor_id) != "admin":
                raise HTTPException(403, "רק מנהל הלוח יכול לשנות רוחב עמודות")
            sub_widths = {}
            for k, v in (data["sub_col_widths"] or {}).items():
                try:
                    sub_widths[str(k)] = max(60, min(600, int(v)))
                except (TypeError, ValueError):
                    continue
            s = dict(b.settings or {})
            s["sub_col_widths"] = sub_widths
            b.settings = s
        if data.get("col_labels") is not None:
            # rename a built-in column header (e.g. "פריט") — board admin
            if _board_role(db, board_id, actor_id) != "admin":
                raise HTTPException(403, "רק מנהל הלוח יכול לשנות שם עמודה")
            builtin = {"item", "assignees", "status", "priority", "due"}
            labels = {}
            for k, v in (data["col_labels"] or {}).items():
                if k in builtin:
                    lv = str(v or "").strip()[:40]
                    if lv:
                        labels[str(k)] = lv
            s = dict(b.settings or {})
            s["col_labels"] = labels
            b.settings = s
        if data.get("col_hidden") is not None:
            # hide built-in columns (the "פריט" name column can never be hidden) — board admin
            if _board_role(db, board_id, actor_id) != "admin":
                raise HTTPException(403, "רק מנהל הלוח יכול להסתיר עמודות")
            hidden = [str(k) for k in (data["col_hidden"] or [])
                      if str(k) in HIDEABLE_BUILTIN_COLS]
            s = dict(b.settings or {})
            was = [str(k) for k in (s.get("col_hidden") or [])]
            s["col_hidden"] = list(dict.fromkeys(hidden))  # de-dup, preserve order
            b.settings = s
            # Logged like a deletion, because that is the word the board uses:
            # the "..." menu on a built-in header offers "מחק עמודה" and this
            # is what it calls. A built-in column is a column of the item and
            # cannot really be dropped, so the row says "הוסרה מהלוח" rather
            # than "נמחקה" — and the way back is logged too, or the log reads
            # as four deletions and no restorations.
            _he = {"assignees": "אחראים", "status": "סטטוס",
                   "priority": "עדיפות", "due": "תאריך יעד"}
            _name = lambda k: (s.get("col_labels") or {}).get(k) or _he.get(k, k)
            for k in s["col_hidden"]:
                if k not in was:
                    _log_board(db, board_id, "delete", field="builtin_column",
                               old=_name(k), actor=actor_id)
            for k in was:
                if k not in s["col_hidden"]:
                    _log_board(db, board_id, "restore", field="builtin_column",
                               old=_name(k), actor=actor_id)
        if data.get("col_order") is not None:
            # persisted display order of columns (built-in keys + custom ids) — board admin
            if _board_role(db, board_id, actor_id) != "admin":
                raise HTTPException(403, "רק מנהל הלוח יכול לשנות סדר עמודות")
            order = [str(k) for k in (data["col_order"] or []) if isinstance(k, (str, int))]
            s = dict(b.settings or {})
            s["col_order"] = list(dict.fromkeys(order))  # de-dup, preserve first occurrence
            b.settings = s
        if "notifications_enabled" in data:
            # board admin toggles all notifications for this board on/off
            if _board_role(db, board_id, actor_id) != "admin":
                raise HTTPException(403, "רק מנהל הלוח יכול לשנות התראות ללוח")
            s = dict(b.settings or {})
            s["notifications_enabled"] = bool(data["notifications_enabled"])
            b.settings = s
        if data.get("statuses") is not None:
            # only a board admin may rename/recolor/reorder/add statuses
            if _board_role(db, board_id, actor_id) != "admin":
                raise HTTPException(403, "רק מנהל הלוח יכול לערוך סטטוסים")
            out, seen = [], set()
            for it in data["statuses"]:
                e = _norm_board_status(it, seen)
                if e:
                    out.append(e)
                if len(out) >= BOARD_STATUS_MAX:
                    break
            if not out:
                raise HTTPException(400, "חובה סטטוס אחד לפחות")
            # A rename keeps the key, so only a key that is GONE is a deletion —
            # which is the whole of "שינוי שם רכיב — המשך לפי מזהה קבוע".
            was = {x["key"]: x.get("label") or x["key"] for x in _board_statuses(b)}
            gone = [k for k in was if k not in {x["key"] for x in out}]
            # Refused before anything is written, and before the dependents are
            # suspended below: a save that does not happen must not leave a
            # stopped automation behind it — see _status_in_use_409.
            if gone:
                _used = _board_status_usage(db, b)
                _busy = [{"key": k, "label": was[k], "items": _used[k]}
                         for k in gone if _used.get(k)]
                if _busy:
                    _status_in_use_409(_busy)
            for key in gone:
                _suspend_dependents(db, b, "status", key, actor_id, was[key])
            s = dict(b.settings or {})
            s["statuses"] = out
            b.settings = s
        if data.get("priorities") is not None:
            # the priority column is a status column, so it is edited under the
            # same rule: only a board admin may rename/recolor/reorder/add
            if _board_role(db, board_id, actor_id) != "admin":
                raise HTTPException(403, "רק מנהל הלוח יכול לערוך עדיפויות")
            out, seen = [], set()
            for it in data["priorities"]:
                e = _norm_board_priority(it, seen)
                if e:
                    out.append(e)
                if len(out) >= BOARD_PRIORITY_MAX:
                    break
            if not out:
                raise HTTPException(400, "חובה עדיפות אחת לפחות")
            s = dict(b.settings or {})
            s["priorities"] = out
            b.settings = s
        if data.get("columns") is not None:
            # only a board admin may add/edit/remove columns and their options
            if _board_role(db, board_id, actor_id) != "admin":
                raise HTTPException(403, "רק מנהל הלוח יכול לערוך עמודות")
            # full replacement of the custom-column definitions
            # "long_text" and "phone" are new here and were half-present
            # everywhere else already: filter_ast.KINDS and the automation
            # matrix have known about long_text since before a column could be
            # one, and the monday importer was flattening both of them into
            # plain text for want of anywhere to put them. The form view needs
            # them as FIELDS — a question's type is its column's type, so a
            # form cannot ask for a paragraph or a phone number unless the
            # board can hold one.
            allowed = {"timeline", "text", "long_text", "phone", "email", "number", "date",
                       "rating", "status", "people", "dropdown", "files", "accounts",
                       "checkbox", "formula",
                       "connect", "created_at", "created_by", "item_id", "mirror"}
            old_cols = {c.get("id"): c for c in (b.settings or {}).get("columns", [])}
            # where each one sat, so a restore can put it back in its place
            _old_at = {c.get("id"): i
                       for i, c in enumerate((b.settings or {}).get("columns", []))}
            is_ws_admin = _ws_role(db, actor_id) == "admin"
            cols = []
            for c in data["columns"]:
                if not isinstance(c, dict) or c.get("type") not in allowed:
                    continue
                cid = c.get("id") or ("col_" + uuid.uuid4().hex[:8])
                if c["type"] == "connect":
                    # A board admin owns their own board's columns, this one
                    # included. What used to be a blanket workspace-admin gate
                    # is now two narrower rules, because the thing that actually
                    # needs guarding is not the column — it is where the column
                    # REACHES.
                    prev = old_cols.get(cid)
                    changed = (not prev) or prev.get("type") != "connect" or prev.get("connect") != c.get("connect")
                    if changed and not is_ws_admin:
                        _cfg = c.get("connect") or {}
                        _targets = [int(x) for x in (_cfg.get("board_ids") or [])
                                    if str(x).lstrip("-").isdigit()]
                        # Naming a target is not a way to reach a board you were
                        # never given: the picker, the report and the mirror all
                        # read through this list.
                        _seen = _visible_board_ids(db, actor_id)
                        _unseen = [t for t in _targets if t not in _seen]
                        if _unseen:
                            raise HTTPException(
                                403, "אפשר לבחור רק לוחות יעד שיש לך גישה אליהם")
                        # A two-way column CREATES a column on the target board.
                        # Writing into someone else's board takes rights on that
                        # board — said plainly rather than downgrading the column
                        # to one-way behind the admin's back.
                        if _cfg.get("two_way"):
                            _no_admin = [t for t in _targets
                                         if _board_role(db, t, actor_id) != "admin"]
                            if _no_admin:
                                _names = ", ".join(
                                    (db.query(Board.name).filter(Board.id == t).scalar() or str(t))
                                    for t in _no_admin)
                                raise HTTPException(
                                    403, f"קשר דו־כיווני יוצר עמודה בלוח היעד — נדרשת הרשאת "
                                         f"מנהל לוח גם ב: {_names}")
                # a status column carries its own {label,color} vocabulary;
                # every other type keeps its options untouched
                opts = (_status_col_options(c.get("options"))
                        if c["type"] == "status" else c.get("options"))
                cols.append({
                    "id": cid,
                    "type": c["type"],
                    "title": c.get("title") or c["type"],
                    "options": opts,
                    "formula": c.get("formula"),
                    "connect": c.get("connect") if c["type"] == "connect" else None,
                    # which connect column to read through, and which field of
                    # the linked item to show
                    "mirror_of": c.get("mirror_of") if c["type"] == "mirror" else None,
                    # "מזהה פריט": what a click on the cell copies — the number
                    # itself ("id", the default) or a link to the item ("url")
                    "copy_mode": (c.get("copy_mode") if c.get("copy_mode") in ("id", "url") else "id")
                                 if c["type"] == "item_id" else None,
                    # "מספר": the unit shown beside the figure and whether the
                    # thousands are grouped — how it is read, not what is stored.
                    # A formula carries the same, for the results that are
                    # numbers; it was dropped here, so a formula column could
                    # never keep a ₪ or a separator however often it was saved.
                    "number": _number_col_cfg(c.get("number"))
                              if c["type"] in ("number", "formula") else None,
                    # "רשימה": the options retired from new selection — still
                    # real words on the cells that carry them, just no longer
                    # offered. Kept only where they still name an option of
                    # THIS column, because a stale entry here would be a word
                    # the column neither offers nor has, and nothing could
                    # ever clear it from the editor.
                    "inactive_options": _dropdown_inactive(opts, c.get("inactive_options"))
                                        if c["type"] == "dropdown" else None,
                    "perms": c.get("perms") or {},
                })
            _conn_n = sum(1 for c in cols if c.get("type") == "connect")
            _conn_was = sum(1 for c in old_cols.values() if c.get("type") == "connect")
            # An over-budget board that already exists stays editable — the
            # limit blocks growth, it does not freeze the column list.
            if _conn_n > _max_connect_cols() and _conn_n > _conn_was:
                raise HTTPException(
                    400, f"מותרות עד {_max_connect_cols()} עמודות קישור בלוח אחד")
            # A two-way column needs its counterpart to exist before it is saved:
            # the map of WHERE the reverse link shows lives on the column itself,
            # and the configuration screen reads it back to tell the admin.
            for c in cols:
                if _is_two_way(c):
                    c["connect"] = {**_connect_cfg(c),
                                    "mirror": _ensure_mirrors(db, board_id, c)}
            # A connect column that is going away takes its relationships with
            # it: the rows are keyed by (item, column), so leaving them would
            # keep the link readable from the mirror on the other board after
            # this side has no column to show it in.
            _drop_links_for_columns(db, [cid for cid, c in old_cols.items()
                                         if c.get("type") == "connect"
                                         and cid not in {x["id"] for x in cols}])
            # "מחיקת שדה — השהיה והודעה", and "שינוי סוג שדה — בדיקת תאימות;
            # השהיה אם אינו תואם". A rename is neither: the id carries on and
            # the sentence simply shows the new name.
            now_by_id = {x["id"]: x for x in cols}
            # ── a status option items wear cannot be dropped either ──
            # The same rule as the board's own statuses, one level down: a
            # status COLUMN's vocabulary is an agreement too, and a cell
            # pointing at an option the column no longer offers is the same
            # unreadable disagreement. Only columns that SURVIVE this save are
            # asked: removing the whole column is a different act, with its own
            # warning, its own recycle bin and its own way back.
            _busy_opts = []
            _rows = None
            for cid, prev in old_cols.items():
                nxt = now_by_id.get(cid)
                if (not nxt or prev.get("type") != "status"
                        or nxt.get("type") != "status"):
                    continue
                kept = {str(o["id"])
                        for o in (_status_col_options(nxt.get("options")) or [])}
                dropped = [o for o in (_status_col_options(prev.get("options")) or [])
                           if str(o["id"]) not in kept]
                if not dropped:
                    continue
                if _rows is None:
                    _rows = _status_usage_rows(db, b)
                used = _status_col_usage(db, b, prev, _rows)
                for o in dropped:
                    if used.get(str(o["id"])):
                        _busy_opts.append({"col_id": cid,
                                      "column": prev.get("title") or cid,
                                      "key": o["id"], "label": o["label"],
                                      "items": used[str(o["id"])]})
            if _busy_opts:
                _status_in_use_409(_busy_opts)
            # ── nor a dropdown option an item still has ticked ──
            # The same disagreement in a list: a cell holding a word its
            # column no longer offers is drawn from the cache, absent from the
            # picker and unaskable in the filter. A dropdown option has no id
            # — the word IS the option — so it is matched by text, and an
            # option the admin no longer wants offered has a way out that
            # costs nobody their data: inactive_options. Same scope as the
            # status rule above: only columns that survive the save, and the
            # whole column going away is its own act.
            _busy_dd = []
            for cid, prev in old_cols.items():
                nxt = now_by_id.get(cid)
                if (not nxt or prev.get("type") != "dropdown"
                        or nxt.get("type") != "dropdown"):
                    continue
                kept = {str(o) for o in (nxt.get("options") or [])}
                dropped = []
                for o in (prev.get("options") or []):
                    if str(o) not in kept and str(o) not in dropped:
                        dropped.append(str(o))
                if not dropped:
                    continue
                if _rows is None:
                    _rows = _status_usage_rows(db, b)
                used = _dropdown_col_usage(cid, _rows)
                for o in dropped:
                    if used.get(o):
                        _busy_dd.append({"col_id": cid,
                                         "column": prev.get("title") or cid,
                                         "label": o, "items": used[o]})
            if _busy_dd:
                raise HTTPException(409, {
                    "message": "לא ניתן למחוק אפשרות שיש בה שימוש — הסר אותה תחילה "
                               "מהפריטים או העבר אותה למצב לא פעיל",
                    "options": _busy_dd})
            # ── what this change does to the board's forms ──
            # Gone, or changed into a type the old questions cannot mean.
            # Both are a change to a form somebody published, so both need
            # saying out loud BEFORE the write and agreeing to in the
            # request. A client that has not shown the warning cannot
            # accidentally sail past it: the refusal carries the impact, and
            # the only way through is to name the columns back.
            _gone = [cid for cid in old_cols if cid not in now_by_id]
            _retyped = {cid: (now_by_id[cid].get("type") or "")
                        for cid, prev in old_cols.items()
                        if cid in now_by_id
                        and not _column_types_compatible(prev.get("type"),
                                                         now_by_id[cid].get("type"))}
            _at_risk = _gone + list(_retyped)
            _uses = _form_column_uses(db, board_id, _at_risk)
            if _uses:
                agreed = {str(x) for x in (data.get("confirm_columns") or [])}
                unagreed = [cid for cid in _uses if cid not in agreed]
                if unagreed:
                    raise HTTPException(409, {
                        "message": "השדות האלה נמצאים בשימוש בטפסים — "
                                   "אישור מפורש נדרש לפני המחיקה",
                        "columns": [{
                            "col_id": cid,
                            "title": (old_cols.get(cid) or {}).get("title") or cid,
                            "removed": cid in _gone,
                            "new_type": _retyped.get(cid),
                            "forms": _uses[cid],
                        } for cid in unagreed]})
            for cid, prev in old_cols.items():
                nxt = now_by_id.get(cid)
                title = prev.get("title") or cid
                if nxt is None:
                    _suspend_dependents(db, b, "column", cid, actor_id, title)
                    # The column itself is about to stop existing, so this row
                    # is the only place its name survives. Written here and not
                    # beside `_gone` above, because above is still in front of
                    # the forms gate: a change refused with a 409 must not
                    # leave a line saying it happened.
                    _row = _log_board(db, board_id, "delete", field="column",
                                      old=title, actor=actor_id)
                    _bin_a_column(db, b, prev, _row.id, actor_id, _old_at.get(cid))
                    # the column is gone, so the conversion that was waiting
                    # on it has nowhere left to put an answer — see
                    # _close_conversions_for_columns
                    _close_conversions_for_columns(db, board_id, [cid], actor_id)
                elif not _column_types_compatible(prev.get("type"), nxt.get("type")):
                    _suspend_dependents(db, b, "column", cid, actor_id,
                                        f"{title} (שונתה מ{prev.get('type')} ל{nxt.get('type')})")
            # And the ones that were not there before. The loop above walks
            # old_cols, so it can only ever see a column that already existed:
            # a deletion left a line and the addition that preceded it left
            # none, and the log read as a board that only ever lost columns.
            # Written after the forms gate for the same reason the deletions
            # are — a change refused with a 409 must not leave a line saying
            # it happened.
            for c in cols:
                cid = str(c.get("id") or "")
                if cid and cid not in old_cols:
                    _log_board(db, board_id, "create", field="column",
                               new=c.get("title") or cid, actor=actor_id)
            # The questions bound to a column that is gone stay, and stop
            # being live — see _form_column_gone. The ones whose column
            # changed type lose the settings that type can no longer carry.
            if _gone:
                _form_column_gone(db, board_id, _gone, actor_id)
            if _retyped:
                _form_settings_resweep(db, board_id, _retyped)
            s = dict(b.settings or {})
            s["columns"] = cols
            # a deleted column can't linger in the sub-item-only set
            if s.get("sub_only"):
                live = {str(c.get("id")) for c in cols if c.get("id")}
                s["sub_only"] = [i for i in s["sub_only"] if str(i) in live]
            b.settings = s
            # adding the column issues an identifier to every item already on the
            # board (and to its sub-items)
            if any(c.get("type") == "item_id" for c in cols):
                for t in db.query(Task).filter(Task.board_id == board_id).all():
                    _ensure_item_uid(db, t)
        if data.get("sub_cols") is not None:
            # Sub-items have their own column structure: identical for every
            # sub-item on the board, but not necessarily the item's columns.
            # Stored as ids picked from the board's column pool (built-in keys +
            # custom column ids); the name column is always present and first.
            if _board_role(db, board_id, actor_id) != "admin":
                raise HTTPException(403, "רק מנהל הלוח יכול להגדיר את עמודות תת-הפריט")
            s = dict(b.settings or {})
            pool = {"assignees", "status", "priority", "due"}
            pool |= {str(c.get("id")) for c in s.get("columns", []) if c.get("id")}
            picked = [str(k) for k in (data["sub_cols"] or []) if str(k) in pool]
            s["sub_cols"] = ["item"] + list(dict.fromkeys(picked))
            b.settings = s
        if data.get("sub_only") is not None:
            # Sub-item-only columns: custom columns that exist on sub-item rows
            # but never on the parent items. Stored as a list of custom column
            # ids; only ids that are real columns on this board are kept.
            if _board_role(db, board_id, actor_id) != "admin":
                raise HTTPException(403, "רק מנהל הלוח יכול להגדיר עמודות תת-פריט")
            s = dict(b.settings or {})
            live = {str(c.get("id")) for c in s.get("columns", []) if c.get("id")}
            s["sub_only"] = [str(k) for k in (data["sub_only"] or []) if str(k) in live]
            b.settings = s
        db.commit()
        # columns, statuses, the board's own settings — everyone on it is looking
        # at a board that just changed shape
        bus.publish("board.changed", board_id=board_id, actor_id=actor_id)
        db.refresh(b)
        # statuses and priorities come back because the server mints the key for
        # a newly added one — the client cannot know it otherwise
        return {"id": b.id, "name": b.name, "icon": b.icon, "color": b.color,
                "views": _board_views(b), "columns": (b.settings or {}).get("columns", []),
                "statuses": _board_statuses(b), "priorities": _board_priorities(b)}

# ── Recycle bin (סל מחזור) ──────────────────────────────────────────
# A deleted board is not destroyed: it keeps its groups, items, comments and
# memberships and only stops being listed. After RECYCLE_BIN_DAYS it is purged
# for good. Restoring simply clears the deletion stamp.
RECYCLE_BIN_DAYS = int(os.getenv("RECYCLE_BIN_DAYS", "60"))   # "חודשיים"


def _hard_delete_board(db, board_id: int):
    """Destroy a board and everything under it. Irreversible — only ever called
    for a board already in the recycle bin (expired, or purged on request)."""
    b = db.query(Board).filter(Board.id == board_id).first()
    if not b:
        return False
    tasks = db.query(Task).filter(Task.board_id == board_id).all()
    task_ids = [t.id for t in tasks]
    if task_ids:
        db.query(Comment).filter(Comment.task_id.in_(task_ids)).delete(synchronize_session=False)
        # The history goes with the items, the way _hard_delete_task has always
        # taken it. Left behind it does not merely sit there: ids are reissued,
        # so a destroyed board's log reattaches to whatever item is created into
        # that id next — and an imported board showed one row of a stranger's
        # history, dated three weeks before the item existed, under "יצר/ה את
        # הפריט" with another board's item name in it.
        db.query(AuditLog).filter(AuditLog.entity_type == "task",
                                  AuditLog.entity_id.in_(task_ids)).delete(synchronize_session=False)
        # links reach across boards, so the far end is on a board that survives
        _drop_links_for_tasks(db, task_ids)
    # and the board's own rows, for exactly the reason above: a board id is
    # reissued too, and a column deletion left behind would surface in the log
    # of whatever board is created into that id next.
    db.query(AuditLog).filter(AuditLog.entity_type == "board",
                              AuditLog.entity_id == board_id).delete(synchronize_session=False)
    for t in tasks:          # clear assignee links via the ORM relationship
        t.assignees = []
    db.flush()
    # ...and everything else that names this board, found rather than listed
    _delete_rows_pointing_at_board(db, board_id, task_ids)
    db.delete(b)
    return True


def _delete_rows_pointing_at_board(db, board_id, task_ids):
    """Empty every table that points at this board, children before parents.

    A sweep over the schema rather than a list of tables, because the list was
    the bug. Twenty-two tables carry a board id and this deleted three of them
    — tasks, groups, members — so on Postgres, where the foreign keys are
    real, purging a board raised ForeignKeyViolation on board_views and the
    recycle bin answered 500 to everybody who opened it. Restoring a board
    went the same way: _purge_expired_boards runs first there too, so one
    board past its retention window took the whole bin down with it. SQLite
    does not enforce foreign keys unless it is asked to, which is why every
    test here passed and only QA ever showed it.

    `sorted_tables` is the dependency order SQLAlchemy already works out for
    create_all; reversed, it is the order it is safe to delete in — a table is
    emptied before the table it points at.

    Three ways a row can belong to this board, and only the first names it:
    the board itself, one of its items (a comment, a permit), or one of its
    forms (a file somebody uploaded into one). The ones that name nothing are
    exactly the ones a list of tables would go on missing.
    """
    form_ids = [i for (i,) in db.query(FormView.id)
                .filter(FormView.board_id == board_id).all()]
    for table in reversed(Board.metadata.sorted_tables):
        if table.name == "boards":
            continue
        where = [table.c[name] == board_id
                 for name in ("board_id", "target_board_id") if name in table.c]
        if task_ids and "task_id" in table.c:
            where.append(table.c.task_id.in_(task_ids))
        if form_ids and "form_view_id" in table.c:
            where.append(table.c.form_view_id.in_(form_ids))
        if where:
            db.execute(table.delete().where(or_(*where)))
    # the ORM still holds the rows just deleted underneath it; expiring them
    # here is what keeps db.delete(b) from flushing a stale task back out
    db.expire_all()
    db.flush()


def _sweep_stray_audit(db):
    """Log rows that describe an item that is not there, or is not theirs.

    Two kinds, and the second is why this exists rather than being left as
    harmless clutter:

      · rows pointing at an item that no longer exists — every board destroyed
        before the delete above took the history with it left all of them;
      · rows DATED BEFORE the item they point at was created. An id is reissued
        once the row that held it is gone, so those are a deleted item's history
        wearing a living item's id. A freshly imported board showed one such row
        on an item — "created item 'פריט 742'", three weeks before that item
        existed, from a board deleted weeks earlier.

    Imported history is the one thing that legitimately predates its item: a
    monday change from 2024 is written onto an item created today, and it is
    skipped here by the `origin` that marks it.

    Returns (orphans, misattributed).
    """
    stray = db.query(AuditLog.id).filter(
        AuditLog.entity_type == "task",
        ~db.query(Task.id).filter(Task.id == AuditLog.entity_id).exists()).all()
    orphan_ids = [i for (i,) in stray]
    wrong = db.query(AuditLog.id).join(Task, Task.id == AuditLog.entity_id).filter(
        AuditLog.entity_type == "task", AuditLog.origin.is_(None),
        Task.created_at != None, AuditLog.created_at != None,          # noqa: E711
        AuditLog.created_at < Task.created_at).all()
    wrong_ids = [i for (i,) in wrong]
    for ids in (orphan_ids, wrong_ids):
        for i in range(0, len(ids), 500):                 # SQLite caps the IN list
            db.query(AuditLog).filter(AuditLog.id.in_(ids[i:i + 500])).delete(
                synchronize_session=False)
    if orphan_ids or wrong_ids:
        db.commit()
    return len(orphan_ids), len(wrong_ids)


def _purge_expired_boards(db):
    """Hard-delete boards whose retention window has passed. Cheap enough to run
    whenever the bin is read, so no scheduler is needed."""
    cutoff = datetime.now(timezone.utc).replace(tzinfo=None) - timedelta(days=RECYCLE_BIN_DAYS)
    expired = [b.id for b in db.query(Board).filter(
        Board.deleted_at != None, Board.deleted_at < cutoff).all()]   # noqa: E711
    for bid in expired:
        _hard_delete_board(db, bid)
    if expired:
        db.commit()
    return expired


def _purge_unclaimed_form_uploads(db):
    """Files uploaded for a form that was never sent.

    A respondent uploads before they submit, so between those two moments the
    file belongs to nothing. Most of the time the submission follows and
    claims it; sometimes the tab is closed, and what is left is bytes in a
    table with no record pointing at them and nobody who can reach them —
    the form's own endpoint hands back a token and never a way to read one.

    Only form uploads, and only unclaimed ones: an ordinary attachment
    carries no form id and is never touched by this. Swept where the board
    bin is swept, for the same reason — cheap enough that no scheduler has to
    exist for it.
    """
    cutoff = (datetime.now(timezone.utc).replace(tzinfo=None)
              - timedelta(hours=FORM_UPLOAD_TTL_HOURS))
    rows = (db.query(UploadedFile)
              .filter(UploadedFile.form_view_id.isnot(None),
                      UploadedFile.claimed_at.is_(None),
                      UploadedFile.created_at < cutoff).all())
    for r in rows:
        db.delete(r)
    if rows:
        db.commit()
    return len(rows)


# One sweep at boot, so expired boards are cleared even if nobody opens the bin.
with Session(engine) as _bin_db:
    try:
        _expired = _purge_expired_boards(_bin_db)
        if _expired:
            print(f"🗑️  purged {len(_expired)} board(s) past the {RECYCLE_BIN_DAYS}-day window", flush=True)
    except Exception as _e:
        print(f"⚠️  recycle-bin purge skipped: {_e}", flush=True)
    try:
        _dropped = _purge_unclaimed_form_uploads(_bin_db)
        if _dropped:
            print(f"🗑️  dropped {_dropped} unsent form upload(s) past "
                  f"{FORM_UPLOAD_TTL_HOURS}h", flush=True)
    except Exception as _e:                            # noqa: BLE001
        print(f"⚠️  form upload sweep skipped: {_e}", flush=True)


def _can_delete_board(db, b, user_id):
    """A board admin, a manager of the board's environment, or a system admin."""
    if user_id is None:
        return True                        # auth disabled → no per-user gate
    return (_board_role(db, b.id, user_id) == "admin"
            or _can_manage_env(db, b.environment_id, user_id))


def _trash_board_json(db, b):
    days_left = RECYCLE_BIN_DAYS - (datetime.now(timezone.utc).replace(tzinfo=None) - b.deleted_at).days
    return {
        "id": b.id, "name": b.name, "icon": b.icon, "color": b.color,
        "description": b.description,
        "environment_id": b.environment_id,
        "environment_name": db.query(Environment.name).filter(
            Environment.id == b.environment_id).scalar() or "",
        "deleted_at": b.deleted_at.isoformat() if b.deleted_at else None,
        "deleted_by": b.deleted_by,
        "deleted_by_name": (db.query(User.name).filter(User.id == b.deleted_by).scalar() or "")
                           if b.deleted_by else "",
        "task_count": db.query(Task).filter(
            Task.board_id == b.id, Task.parent_id == None).count(),   # noqa: E711
        "days_left": max(0, days_left),
        "retention_days": RECYCLE_BIN_DAYS,
    }


@app.get("/api/boards/{board_id}/status-usage")
def board_status_usage(board_id: int, actor_id: int = Depends(current_user_id)):
    """How many items wear each status — the board's own vocabulary, and every
    status column's.

    What the editor needs in order to say "4 פריטים" beside a status and put
    its bin out of reach BEFORE anybody presses it. The refusal on save is the
    authority and this is not a second one; it exists so that the screen stops
    being a place where an action that cannot succeed still looks available.

    Open to anyone on the board, not just its admins: the counts are the board
    reading itself back, and every one of them is already on screen as rows.
    """
    with Session(engine) as db:
        b, _role = _board_role_or_403(db, board_id, actor_id)
        rows = _status_usage_rows(db, b)
        cols = [c for c in ((b.settings or {}).get("columns") or [])
                if c.get("type") == "status" and c.get("id")]
        return {"statuses": _board_status_usage(db, b, rows),
                "columns": {str(c["id"]): _status_col_usage(db, b, c, rows)
                            for c in cols}}


# ── a renamed status option, carried into the cells that already wear it ──
#
# Renaming an option in the column editor rewrites the VOCABULARY, and the
# cells go on holding the word they were written with: the grid stores the
# label (and a form answer or a monday import stores the whole option), so an
# option renamed from "אושר" to "אושר סופית" leaves every item that already
# carried it reading the old word. The browser used to fix that itself —
# _csMigrate, one PATCH per cell over the rows it holds.
#
# Which is fine until the board is big. Above FILTER_CLIENT_MAX the browser
# holds a page of fifty rows out of tens of thousands, so that loop renamed
# whatever happened to be on screen and left everything else carrying the old
# label — a migration that looks like it ran. The frontend now refuses rather
# than do a fraction of the job quietly, and this is where the job actually
# gets done: one pass over the column for the whole board, whatever its size.
#
# Nothing about a RULE is touched, and that is on purpose. An automation
# stores the option's id, the id survives a rename, and _status_cell_key reads
# a cell back to its id — so the rules were never the thing that broke. Only
# the text a person reads was.
@app.post("/api/boards/{board_id}/columns/{col_id}/status-rename")
def column_status_rename(board_id: int, col_id: str, data: dict,
                         actor_id: int = Depends(current_user_id)):
    """Carry a status option's new name into every cell on the board wearing it.

    Called right after the column itself has been saved, so the column already
    offers the NEW words — each rename names the option by its new label and
    says which old word it used to be. The colour is read off the column and
    not off the request: the column is the one authority on what an option
    looks like, and a colour sent alongside is one more thing that can
    disagree with it.

    Permission is the rule the column editor already answers to — a board
    admin, the same gate PATCH /api/boards/{id} puts in front of `columns`.
    Editing the words and carrying them into the cells are one act; they must
    not be able to come apart because one of them asked for less.
    """
    with Session(engine) as db:
        b = db.query(Board).filter(Board.id == board_id).first()
        if not b or b.deleted_at:
            raise HTTPException(404, "board not found")
        if _board_role(db, board_id, actor_id) != "admin":
            raise HTTPException(403, "רק מנהל הלוח יכול לערוך עמודות")
        col = _find_col(db, board_id, col_id)
        if not col:
            raise HTTPException(404, "column not found")
        if (col.get("type") or "") != "status":
            raise HTTPException(400, "העמודה אינה עמודת סטטוס")
        opts = _status_col_options(col.get("options")) or []
        by_label = {o["label"]: o for o in opts}

        # ── what was asked, checked whole before a single cell is written ──
        # A rename half-applied is worse than one refused: the board would
        # then hold two spellings of the same option with no screen able to
        # say which items got which.
        wanted, seen_old = [], set()
        for r in (data.get("renames") or []):
            if not isinstance(r, dict):
                continue
            old = str(r.get("from") or "").strip()
            new = str(r.get("to") or "").strip()
            if not old or not new or old == new or old in seen_old:
                continue
            o = by_label.get(new)
            if not o:
                # The column does not offer that word. Almost always the save
                # of the column itself did not land, and renaming cells to a
                # label no option carries would put the board in exactly the
                # state this endpoint exists to prevent.
                raise HTTPException(
                    400, f"הסטטוס \"{new}\" אינו קיים בעמודה — שמור את העמודה תחילה")
            # The old word still belonging to a DIFFERENT option is the one
            # case where a cell holding only a label cannot be resolved: it is
            # unknowable whether it means the option that was renamed away
            # from the word or the one that now answers to it. Said out loud
            # rather than guessed, because guessing moves items between
            # statuses and nobody would ever see it happen.
            clash = by_label.get(old)
            if clash is not None and clash["id"] != o["id"]:
                raise HTTPException(
                    400, f"\"{old}\" הוא כעת שמו של סטטוס אחר בעמודה — "
                         f"לא ניתן לדעת לאיזה מהם שייכים התאים")
            seen_old.add(old)
            wanted.append((old, o))
        if not wanted:
            raise HTTPException(400, "לא נמסרו שינויי שם")

        by_old = {old: o for old, o in wanted}
        by_id = {o["id"]: o for _old, o in wanted}

        # ── the cells ──
        # Read and rewritten in Python rather than as one SQL UPDATE over the
        # JSON blob, because a cell is written two ways in this product and
        # both are in the data: the grid stores the label, a form answer and
        # the monday import store the whole option. A text substitution inside
        # the blob would have to know the difference, and would happily rewrite
        # a word that belonged to some other column of the same item.
        #
        # Archived items and the ones in the recycle bin are included. They
        # come back — an unarchive, a board restored from the bin — and they
        # must not come back wearing a word the column has not offered for
        # months, which is the same unreadable disagreement that makes
        # dropping a status-in-use a 409.
        cid = str(col_id)
        rows = (db.query(Task)
                  .options(load_only(Task.custom_fields))
                  .filter(Task.board_id == b.id)
                  .execution_options(include_deleted=True)
                  .all())
        hit = {o["id"]: 0 for _old, o in wanted}
        for t in rows:
            cf = t.custom_fields or {}
            v = cf.get(cid)
            if v in (None, "", []):
                continue
            # By id first and by the old label only then: the id is the stable
            # name of the option and the label is what the rename is changing.
            if isinstance(v, dict):
                o = by_id.get(str(v.get("id") or "")) or by_old.get(str(v.get("label") or ""))
            else:
                o = by_old.get(str(v))
            if o is None:
                continue
            want = {"id": o["id"], "label": o["label"], "color": o.get("color")}
            if v == want:
                continue                 # already carries it — nothing to write
            # The whole option and not just the new label, which is what
            # _apply_status_col writes: a cell that carries its id is matched
            # by id the NEXT time somebody renames it, and never by text.
            nf = dict(cf)
            nf[cid] = want
            # JSON columns are replaced, never mutated in place — SQLAlchemy
            # does not watch inside one and an in-place edit commits nothing.
            t.custom_fields = nf
            hit[o["id"]] += 1

        total = sum(hit.values())
        title = col.get("title") or cid
        # One line for the whole rename and not one per item: the board log is
        # read as a history of decisions, and twenty thousand rows saying the
        # same thing would bury every other decision made that day.
        if total:
            _log_board(db, board_id, "update", field="column", old=title,
                       new=f"{title} — " + ", ".join(
                           f"\"{old}\" שונה ל\"{o['label']}\"" for old, o in wanted)
                           + f" ({total} תאים)",
                       actor=actor_id)
        db.commit()
        return {"col_id": cid, "title": title,
                "items": total, "scanned": len(rows),
                "renamed": [{"from": old, "to": o["label"], "id": o["id"],
                             "items": hit[o["id"]]} for old, o in wanted]}


# ── a dropdown ("רשימה") column: what each option is worn by, and a rename ──
#
# A dropdown option is a bare word with no id behind it, so every place that
# remembers one remembers the TEXT: the cells, a rule's "העמודה היא X", a saved
# view's filter. That is why the rename below is one endpoint that edits the
# column itself as well as the cells, where status splits the two: a status
# option keeps its id across a rename and the column PATCH can go first, while
# a dropdown option renamed in the PATCH alone would look, to the delete-guard
# there, exactly like an option in use being deleted — and would be refused.

@app.get("/api/boards/{board_id}/columns/{col_id}/dropdown-usage")
def column_dropdown_usage(board_id: int, col_id: str,
                          actor_id: int = Depends(current_user_id)):
    """How many items carry each option of one dropdown column.

    What the editor needs to put a delete out of reach BEFORE anybody presses
    it and to offer "העבר למצב לא פעיל" instead — the 409 on save stays the
    authority. Open to anyone on the board, like status-usage: the counts are
    the board reading back rows every member can already see.
    """
    with Session(engine) as db:
        b, role = _board_role_or_403(db, board_id, actor_id)
        col = _find_col(db, board_id, col_id)
        # A column this reader's override hides ("none") is one the grid,
        # the filter and the export never show them — see _unseen_col_ids.
        # Its words and their counts are the column's content, so the answer
        # is the same 404 as a column that does not exist: a 403 would tell
        # them it is there. No actor (auth off) sees every column, as in
        # _unseen_col_ids.
        if not col or (actor_id is not None
                       and _col_perm(col, actor_id, role) == "none"):
            raise HTTPException(404, "column not found")
        if (col.get("type") or "") != "dropdown":
            raise HTTPException(400, "העמודה אינה עמודת רשימה")
        return {"col_id": str(col_id),
                "usage": _dropdown_col_usage(col_id, _status_usage_rows(db, b))}


def _dropdown_swap(v, old, new):
    """A cell value (or a filter/condition value) with `old` replaced by `new`
    — deduplicated, order kept — and whether anything changed. Always a NEW
    object: these live in JSON columns, and SQLAlchemy does not see an edit
    made inside one."""
    if isinstance(v, list):
        hit, out = False, []
        for x in v:
            lbl = x.get("label") if isinstance(x, dict) else x
            if lbl is not None and str(lbl) == old:
                hit, x = True, new
            key = x.get("label") if isinstance(x, dict) else x
            if any((y.get("label") if isinstance(y, dict) else y) == key for y in out):
                continue
            out.append(x)
        return (out, True) if hit else (v, False)
    # A lone value is compared as text, as list members are above: an imported
    # cell can hold the number 3 for the option "3", and leaving it behind
    # would keep a word the column no longer offers. bool is an int to Python
    # and is never an option, so it is kept out on purpose.
    if (isinstance(v, (str, int, float)) and not isinstance(v, bool)
            and str(v) == old):
        return new, True
    return v, False


def _dropdown_rename_tree(node, cid, old, new, depth=0):
    """A saved filter tree with every rule on this column that names `old`
    asking for `new` instead. (tree, changed) — the tree rebuilt, never
    mutated, and only the rules on THIS column touched: the same word may be
    an option of another column on the board, and that one was not renamed."""
    if not isinstance(node, dict) or depth > filter_ast.MAX_DEPTH:
        return node, False
    if node.get("type") == "group" or "rules" in node:
        hit, kids = False, []
        for kid in (node.get("rules") or []):
            k, h = _dropdown_rename_tree(kid, cid, old, new, depth + 1)
            kids.append(k)
            hit = hit or h
        return ({**node, "rules": kids}, True) if hit else (node, False)
    if str(node.get("field") or "") != cid:
        return node, False
    # Two spellings of the same rule reach here: filter_ast's own wire shape
    # holds the word under `value`, but the tab strip saves what newRule()
    # builds — {field, op, v, v2} — and parse() reads either. Reading only
    # `value` left every view saved from the real browser untouched by a
    # rename. Written back under the key it came from, so the view keeps the
    # shape its own client expects.
    key = "value" if "value" in node else "v"
    val, hit = _dropdown_swap(node.get(key), old, new)
    return ({**node, key: val}, True) if hit else (node, False)


def _dropdown_rename_conds(conds, cid, old, new):
    """A rule's conditions with "העמודה היא/אינה «old»" on this column now
    naming `new`. A side that is a column REFERENCE (a dict) is left alone —
    it names a column, not a word."""
    hit, out = False, []
    for c in (conds if isinstance(conds, list) else []):
        spec = c.get("value") if isinstance(c, dict) else None
        if (isinstance(c, dict) and c.get("kind") in recipes.COLUMN_CONDITIONS
                and isinstance(spec, dict) and str(spec.get("col") or "") == cid):
            val, h = _dropdown_swap(spec.get("value"), old, new)
            if h:
                c = {**c, "value": {**spec, "value": val}}
                hit = True
        out.append(c)
    return out, hit


def _dropdown_rename_text(v, old, new):
    """A set_column value naming `old`, now naming `new`. Only a value that IS
    the word: _coerce_cell strips the text and then demands it be one of the
    column's options, so anything else — a token, a sentence — either is not
    this word or resolves at run time and is not ours to rewrite."""
    if isinstance(v, str) and v.strip() == old:
        return new, True
    return v, False


def _dropdown_rename_cfg(recipe_id, cfg, cid, old, new):
    """A rule's config with every mention of `old` on this column moved to
    `new`: its conditions, and its set_column actions that write into it.

    The actions as well as the conditions, because set_column will write into
    a dropdown — FIELD_MATRIX marks the type as no action target, but nothing
    enforces that: the column is not in AUTOMATION_UNWATCHABLE_COLUMNS or
    DERIVED_CELLS, and _coerce_cell reads it as a status-kind column and
    accepts any of its options. Left alone, "כאשר …, עדכן את «סוג» ל«old»"
    would be refused on every firing from the rename on ("אינו ערך מוכר
    בעמודה"), which is the rule going quietly dead the conditions part of
    this exists to prevent. The rule's own action keeps its blanks as
    a_column/a_text (only the set_column recipes declare a_column with a
    text); an added one as {"key": "set_column", "values": {column, text}}.
    (cfg, changed) — a new dict, never the stored one edited in place."""
    cfg = cfg if isinstance(cfg, dict) else {}
    out, hit = dict(cfg), False
    conds, h = _dropdown_rename_conds(cfg.get(recipes.CONDITION_KEY), cid, old, new)
    if h:
        out[recipes.CONDITION_KEY], hit = conds, True
    if ((recipes.recipe(recipe_id) or {}).get("action") == "set_column"
            and str(cfg.get("a_column") or "") == cid):
        val, h = _dropdown_rename_text(cfg.get("a_text"), old, new)
        if h:
            out["a_text"], hit = val, True
    extras = cfg.get(recipes.ACTIONS_KEY)
    if isinstance(extras, list):
        acts, ahit = [], False
        for x in extras:
            vals = x.get("values") if isinstance(x, dict) else None
            if (isinstance(vals, dict) and x.get("key") == "set_column"
                    and str(vals.get("column") or "") == cid):
                val, h = _dropdown_rename_text(vals.get("text"), old, new)
                if h:
                    x = {**x, "values": {**vals, "text": val}}
                    ahit = True
            acts.append(x)
        if ahit:
            out[recipes.ACTIONS_KEY], hit = acts, True
    return (out, True) if hit else (cfg, False)


@app.post("/api/boards/{board_id}/columns/{col_id}/dropdown-rename")
def column_dropdown_rename(board_id: int, col_id: str, data: dict,
                           actor_id: int = Depends(current_user_id)):
    """Rename one option of a dropdown column, and carry the new word into
    everything that remembers the old one — in a single transaction.

    Everything is: the column's options (in place, same position) and its
    inactive list; every cell of the column on the board, archived and binned
    items included, because they come back and must not come back wearing a
    word the column stopped offering; the board's automations whose
    conditions ask "העמודה היא «old»" on this column, which would otherwise
    go quietly false for ever; and the board's saved views whose filter asks
    for the old word, which would otherwise go quietly empty.

    Same gate as the column PATCH — a board admin. Editing the word and
    carrying it must not be able to come apart because one asked for less.
    """
    with Session(engine) as db:
        b = db.query(Board).filter(Board.id == board_id).first()
        if not b or b.deleted_at:
            raise HTTPException(404, "board not found")
        if _board_role(db, board_id, actor_id) != "admin":
            raise HTTPException(403, "רק מנהל הלוח יכול לערוך עמודות")
        cols = list((b.settings or {}).get("columns") or [])
        at = next((i for i, c in enumerate(cols)
                   if isinstance(c, dict) and str(c.get("id")) == str(col_id)), None)
        if at is None:
            raise HTTPException(404, "column not found")
        col = cols[at]
        if (col.get("type") or "") != "dropdown":
            raise HTTPException(400, "העמודה אינה עמודת רשימה")

        # ── what was asked, checked whole before anything is written ──
        old_in = str(data.get("from") or "").strip()
        new = str(data.get("to") or "").strip()
        if not old_in or not new:
            raise HTTPException(400, "חובה שם קודם ושם חדש")
        # Refused rather than cut: a truncated word is a rename to something
        # the admin never typed, and they would find out from the grid.
        if len(new) > 200:
            raise HTTPException(400, "שם האפשרות ארוך מדי — עד 200 תווים")
        opts = list(col.get("options") or [])
        # Matched exactly first, then ignoring the edges — an option saved
        # with a stray space is still the option the admin is pointing at.
        # The cells are rewritten by the word AS STORED, which is what they hold.
        idx = next((i for i, o in enumerate(opts) if str(o) == old_in), None)
        if idx is None:
            idx = next((i for i, o in enumerate(opts) if str(o).strip() == old_in), None)
        if idx is None:
            raise HTTPException(400, f"האפשרות \"{old_in}\" אינה קיימת בעמודה")
        old = str(opts[idx])
        if new == old:
            raise HTTPException(400, "השם החדש זהה לשם הקודם")
        # Case-insensitively, because "Urgent" and "urgent" side by side are
        # one option spelt twice to the person reading them. A rename that
        # only changes the case of the option itself is not a clash.
        fold = new.casefold()
        if any(i != idx and str(o).strip().casefold() == fold
               for i, o in enumerate(opts)):
            raise HTTPException(400, f"האפשרות \"{new}\" כבר קיימת בעמודה")

        # ── the column ──
        opts[idx] = new
        inactive = col.get("inactive_options")
        if isinstance(inactive, list):
            inactive = _dropdown_inactive(
                opts, [new if str(x) == old else x for x in inactive])
        new_col = {**col, "options": opts, "inactive_options": inactive}
        cols[at] = new_col
        s = dict(b.settings or {})
        s["columns"] = cols
        b.settings = s

        # ── the cells ──
        cid = str(col_id)
        rows = (db.query(Task)
                  .options(load_only(Task.custom_fields))
                  .filter(Task.board_id == b.id)
                  .execution_options(include_deleted=True)
                  .all())
        total = 0
        for t in rows:
            cf = t.custom_fields or {}
            if cf.get(cid) in (None, "", []):
                continue
            val, hit = _dropdown_swap(cf.get(cid), old, new)
            if not hit:
                continue
            nf = dict(cf)
            nf[cid] = val
            t.custom_fields = nf
            total += 1

        # ── the rules that ask about the word ──
        # Rewritten in the live configuration and not parked as a draft the
        # way an edit to an active rule is: the rule means exactly what it
        # meant a moment ago, and a draft would leave the running version
        # asking for a word no cell can hold any more. A version is recorded
        # so "who changed this rule" still has an answer. A pending draft is
        # carried too, or publishing it later would bring the old word back.
        for a in db.query(Automation).filter(Automation.board_id == b.id).all():
            cfg = a.config or {}
            new_cfg, hit = _dropdown_rename_cfg(a.recipe_id, cfg, cid, old, new)
            if a.draft_version:
                dv = (db.query(AutomationVersion)
                        .filter(AutomationVersion.automation_id == a.id,
                                AutomationVersion.version == a.draft_version).first())
                snap = (dv.snapshot or {}) if dv is not None else {}
                dcfg = snap.get("config") if isinstance(snap.get("config"), dict) else None
                if dcfg is not None:
                    # the draft's own recipe: a draft can change what the
                    # rule does, and its a_text is only a set_column value
                    # if the draft is still a set_column rule
                    ndcfg, dhit = _dropdown_rename_cfg(
                        snap.get("recipe_id") or a.recipe_id, dcfg, cid, old, new)
                    if dhit:
                        dv.snapshot = {**snap, "config": ndcfg}
            if not hit:
                continue
            before = _snapshot_automation(a)
            a.config = new_cfg
            a.updated_by = actor_id
            a.updated_at = datetime.now(timezone.utc).replace(tzinfo=None)
            _record_automation_version(
                db, b, a, actor_id, before=before,
                note=f"האפשרות \"{old}\" בעמודה \"{col.get('title') or cid}\" שונתה ל\"{new}\"")

        # ── the saved views that filter on the word ──
        # Binned views too, for the reason binned items are: they come back.
        for v in db.query(SavedView).filter(SavedView.board_id == b.id).all():
            f = v.filters or {}
            if not isinstance(f, dict) or not f.get("adv"):
                continue
            tree, hit = _dropdown_rename_tree(f.get("adv"), cid, old, new)
            if not hit:
                continue
            v.filters = {**f, "adv": tree}
            # the shared configuration moved, and a client holding the view
            # must be able to tell — see SavedView.config_version
            v.config_version = (v.config_version or 1) + 1

        title = col.get("title") or cid
        # One line for the whole rename, as with status: the log is a history
        # of decisions, not of the rows a decision touched.
        _log_board(db, board_id, "update", field="column", old=title,
                   new=f"{title} — \"{old}\" שונה ל\"{new}\" ({total} תאים)",
                   actor=actor_id)
        db.commit()
        return {"col_id": cid, "column": new_col, "items": total,
                "from": old, "to": new}


@app.delete("/api/boards/{board_id}")
def delete_board(board_id: int, user_id: int = Depends(current_user_id)):
    """Move a board to the recycle bin. Nothing under it is destroyed — groups,
    items, comments and memberships are kept so a restore is lossless. Only a
    board admin or an environment manager may delete it."""
    with Session(engine) as db:
        b = db.query(Board).filter(Board.id == board_id).first()
        if not b:
            raise HTTPException(404, "board not found")
        if not _can_delete_board(db, b, user_id):
            raise HTTPException(403, "רק מנהל הלוח או מנהל הסביבה יכול למחוק אותו")
        if b.deleted_at:
            return {"status": "deleted", "id": board_id, "days_left": RECYCLE_BIN_DAYS}
        # "מחיקת לוח — ביטול אוטומציות והפעלות; השהיית אוטומציות תלויות בלוחות
        # אחרים". Three separate things, in this order, while the board is still
        # readable: afterwards there is no board to work any of them out from.
        _stopped = _retire_board_automations(db, b, user_id)
        _elsewhere = _suspend_dependents(db, b, "board", b.id, user_id, b.name)
        b.deleted_at = datetime.now(timezone.utc).replace(tzinfo=None)
        b.deleted_by = user_id
        db.commit()
        if _stopped or _elsewhere:
            return {"status": "deleted", "id": board_id,
                    "restorable_until_days": RECYCLE_BIN_DAYS,
                    "automations_stopped": _stopped,
                    "automations_suspended_elsewhere": _elsewhere}
        return {"status": "deleted", "id": board_id,
                "restorable_until_days": RECYCLE_BIN_DAYS}


# ── the board's own recycle bin: items ───────────────────────────────
def _deleted_tasks_q(db):
    """Tasks the bin cares about. The global hook hides deleted rows from every
    query, so the bin has to say explicitly that it wants them."""
    return db.query(Task).execution_options(include_deleted=True)


def _purge_expired_tasks(db, board_id=None):
    """Hard-delete items whose retention window has passed. Run when a bin is
    read, so no scheduler is needed — the same approach the board bin uses."""
    cutoff = datetime.now(timezone.utc).replace(tzinfo=None) - timedelta(days=RECYCLE_BIN_DAYS)
    q = _deleted_tasks_q(db).filter(Task.deleted_at != None, Task.deleted_at < cutoff)  # noqa: E711
    if board_id is not None:
        q = q.filter(Task.board_id == board_id)
    gone = [t.id for t in q.all()]
    for tid in gone:
        _hard_delete_task(db, tid)
    if gone:
        db.commit()
    return gone


def _hard_delete_task(db, task_id):
    """Remove an item for good, with everything hanging off it."""
    for sub in _deleted_tasks_q(db).filter(Task.parent_id == task_id).all():
        _hard_delete_task(db, sub.id)
    db.query(Comment).filter(Comment.task_id == task_id).delete(synchronize_session=False)
    db.query(AuditLog).filter(AuditLog.entity_type == "task",
                              AuditLog.entity_id == task_id).delete(synchronize_session=False)
    _drop_links_for_tasks(db, [task_id])
    t = _deleted_tasks_q(db).filter(Task.id == task_id).first()
    if t:
        t.assignees = []
        db.delete(t)


def _trash_task_json(db, t, users):
    days_left = RECYCLE_BIN_DAYS - (datetime.now(timezone.utc).replace(tzinfo=None) - t.deleted_at).days
    subs = _deleted_tasks_q(db).filter(Task.parent_id == t.id).count()
    return {"id": t.id, "title": t.title, "group_id": t.group_id,
            "deleted_at": t.deleted_at, "deleted_by": t.deleted_by,
            "deleted_by_name": users.get(t.deleted_by, "—"),
            "sub_count": subs,
            "days_left": max(0, days_left), "retention_days": RECYCLE_BIN_DAYS}


@app.get("/api/boards/{board_id}/trash")
def board_trash(board_id: int, actor_id: int = Depends(current_user_id)):
    """Items deleted from this board, newest first.

    Only top-level items are listed: a sub-item is deleted with its parent and
    restored with it, so listing both would offer a restore that does nothing.
    """
    with Session(engine) as db:
        b = db.query(Board).filter(Board.id == board_id).first()
        if not b or b.deleted_at:
            raise HTTPException(404, "board not found")
        if _board_role(db, board_id, actor_id) is None:
            raise HTTPException(403, "אין לך גישה ללוח זה")
        _purge_expired_tasks(db, board_id)
        users = {u.id: u.name for u in db.query(User).all()}
        rows = (_deleted_tasks_q(db)
                .filter(Task.board_id == board_id, Task.deleted_at != None,  # noqa: E711
                        Task.parent_id == None)                              # noqa: E711
                .order_by(Task.deleted_at.desc()).all())
        # filtered, not refused: an assigned_only member's bin is their own
        # items in it, the same cut their board is
        _vis = _assigned_only_ids(db, board_id, actor_id)
        if _vis is not None:
            rows = [t for t in rows if t.id in _vis]
        return {"items": [_trash_task_json(db, t, users) for t in rows],
                "retention_days": RECYCLE_BIN_DAYS}


@app.post("/api/tasks/{task_id}/restore")
def restore_task(task_id: int, data: dict = None, actor_id: int = Depends(current_user_id)):
    with Session(engine) as db:
        t = _deleted_tasks_q(db).filter(Task.id == task_id).first()
        if not t or not t.deleted_at:
            raise HTTPException(404, "item not in the recycle bin")
        _require_board_edit(db, t.board_id, actor_id)
        # the group it lived in may itself be gone; put it back where it can be seen
        g = db.query(Group).filter(Group.id == t.group_id, Group.board_id == t.board_id).first()
        if not g:
            g = db.query(Group).filter(Group.board_id == t.board_id).order_by(Group.position).first()
            t.group_id = g.id if g else None
        for sub in _deleted_tasks_q(db).filter(Task.parent_id == task_id).all():
            sub.deleted_at = None
            sub.deleted_by = None
        t.deleted_at = None
        t.deleted_by = None
        _audit(db, task_id, "restore", field="item", old=None, new=t.title, user_id=actor_id)
        _bid = t.board_id
        db.commit()
        bus.publish("task.created", board_id=_bid, task_id=task_id, actor_id=actor_id)
        return {"status": "restored", "id": task_id}


@app.delete("/api/boards/{board_id}/trash/{task_id}")
def purge_task(board_id: int, task_id: int, actor_id: int = Depends(current_user_id)):
    """Permanent. Board admins only — nothing brings this back."""
    with Session(engine) as db:
        t = _deleted_tasks_q(db).filter(Task.id == task_id, Task.board_id == board_id).first()
        if not t or not t.deleted_at:
            raise HTTPException(404, "item not in the recycle bin")
        if not _is_board_admin(db, board_id, actor_id):
            raise HTTPException(403, "רק מנהל הלוח יכול למחוק לצמיתות")
        _hard_delete_task(db, task_id)
        db.commit()
        return {"status": "purged", "id": task_id}


@app.get("/api/boards/{board_id}/trash/{task_id}")
def view_trashed_task(board_id: int, task_id: int, actor_id: int = Depends(current_user_id)):
    """Read a deleted item without restoring it — the bin's "צפייה"."""
    with Session(engine) as db:
        if _board_role(db, board_id, actor_id) is None:
            raise HTTPException(403, "אין לך גישה ללוח זה")
        t = _deleted_tasks_q(db).filter(Task.id == task_id, Task.board_id == board_id).first()
        if not t or not t.deleted_at:
            raise HTTPException(404, "item not in the recycle bin")
        _vis = _assigned_only_ids(db, board_id, actor_id)
        if _vis is not None and t.id not in _vis:
            raise HTTPException(403, "אין לך גישה לפריט זה")
        users = {u.id: u.name for u in db.query(User).all()}
        subs = _deleted_tasks_q(db).filter(Task.parent_id == task_id).order_by(Task.position).all()
        comments = db.query(Comment).filter(Comment.task_id == task_id).count()
        return {"id": t.id, "title": t.title, "description": t.description,
                "status": t.status.value if hasattr(t.status, "value") else t.status,
                "priority": t.priority.value if hasattr(t.priority, "value") else t.priority,
                "due_date": t.due_date,
                "custom_fields": t.custom_fields or {},
                "assignees": [{"id": u.id, "name": u.name, "avatar_url": u.avatar_url}
                              for u in (t.assignees or [])],
                "deleted_at": t.deleted_at, "deleted_by_name": users.get(t.deleted_by, "—"),
                "comment_count": comments,
                "subs": [{"id": x.id, "title": x.title} for x in subs]}


@app.get("/api/trash/boards")
def list_trash_boards(user_id: int = Depends(current_user_id)):
    """Boards currently in the recycle bin that this user may act on."""
    with Session(engine) as db:
        _purge_expired_boards(db)
        rows = db.query(Board).filter(Board.deleted_at != None).order_by(   # noqa: E711
            Board.deleted_at.desc()).all()
        rows = [b for b in rows if _can_delete_board(db, b, user_id)]
        return {"boards": [_trash_board_json(db, b) for b in rows],
                "retention_days": RECYCLE_BIN_DAYS}


@app.post("/api/trash/boards/{board_id}/restore")
def restore_board(board_id: int, user_id: int = Depends(current_user_id)):
    """Bring a board back out of the recycle bin, with all of its content."""
    with Session(engine) as db:
        _purge_expired_boards(db)
        b = db.query(Board).filter(Board.id == board_id).first()
        if not b:
            raise HTTPException(404, "הלוח לא נמצא — ייתכן שנמחק לצמיתות")
        if not b.deleted_at:
            raise HTTPException(400, "הלוח אינו בסל המחזור")
        if not _can_delete_board(db, b, user_id):
            raise HTTPException(403, "רק מנהל הלוח או מנהל הסביבה יכול לשחזר אותו")
        # the board's environment may itself have been removed meanwhile — fall
        # back to the primary workspace so a restored board is never orphaned
        if b.environment_id and not db.query(Environment).filter(
                Environment.id == b.environment_id).first():
            primary = db.query(Environment).filter(Environment.is_primary == True).first()  # noqa: E712
            b.environment_id = primary.id if primary else None
            b.folder_id = None
        elif b.folder_id and not db.query(Folder).filter(Folder.id == b.folder_id).first():
            b.folder_id = None
        b.deleted_at = None
        b.deleted_by = None
        db.commit()
        return {"status": "restored", "id": b.id, "name": b.name,
                "environment_id": b.environment_id}


@app.delete("/api/trash/boards/{board_id}")
def purge_board(board_id: int, user_id: int = Depends(current_user_id)):
    """Empty a single board out of the recycle bin — destroys it for good."""
    with Session(engine) as db:
        b = db.query(Board).filter(Board.id == board_id).first()
        if not b:
            raise HTTPException(404, "board not found")
        if not b.deleted_at:
            raise HTTPException(400, "הלוח אינו בסל המחזור")
        if not _can_delete_board(db, b, user_id):
            raise HTTPException(403, "רק מנהל הלוח או מנהל הסביבה יכול למחוק אותו")
        _hard_delete_board(db, board_id)
        db.commit()
        return {"status": "purged", "id": board_id}

# ── Board membership & per-board permissions ────────────────────────
# The two "assigned" roles sit beside the classic three rather than between
# them: at board level both act as a viewer (see _BROLE_ORDER and _board_caps),
# and what they add is per item — edit what you are assigned to, and for
# assigned_only, see nothing else. Which column decides "assigned" is the
# board's perm column; see _board_perm_col.
BOARD_ROLES = ("admin", "editor", "viewer", "assigned_editor", "assigned_only")
BROLE_HE = {"admin": "מנהל לוח", "editor": "עורך", "viewer": "צופה",
            "assigned_editor": "עריכת רשומות משויכות",
            "assigned_only": "גישה לרשומות משויכות בלבד"}


def _notify(db, user_id, type, title, body="", board_id=None, task_id=None):
    """Create an in-app notification for a recipient (best-effort, no-op on bad input)."""
    if not user_id:
        return
    db.add(Notification(user_id=user_id, type=type, title=title, body=body,
                        board_id=board_id, task_id=task_id))

def _board_notify_on(board):
    """Whether the board emits notifications (board admin can switch it off wholesale)."""
    return bool((board.settings or {}).get("notifications_enabled", True)) if board else True


# ── Outgoing mail ───────────────────────────────────────────────────
# One way out of the app (_send_email) and two providers behind it. Which one
# sends is configuration, never a call site's business: MAIL_PROVIDER names it
# outright, and with nothing named the choice is simply whichever key is set —
# SendGrid first, since an environment holding a SendGrid key was given one on
# purpose. Neither key set is not an error: the message is logged and dropped,
# so an invite still goes through on a machine where mail was never configured.
MAIL_ENDPOINTS = {"sendgrid": "https://api.sendgrid.com/v3/mail/send",
                  "resend": "https://api.resend.com/emails"}


def _mail_provider():
    """Which provider sends, and with what key. ('', None) when mail is off."""
    named = (os.environ.get("MAIL_PROVIDER") or "").strip().lower()
    keys = {"sendgrid": os.environ.get("SENDGRID_API_KEY"),
            "resend": os.environ.get("RESEND_API_KEY")}
    if named in keys:
        # an explicitly named provider is never silently swapped for the other:
        # a missing key is a misconfiguration to see in the log, not to route
        # around, or a test send goes out through a provider nobody chose
        return (named, keys[named]) if keys[named] else ("", None)
    for name in ("sendgrid", "resend"):
        if keys[name]:
            return name, keys[name]
    return "", None


def _mail_from():
    """The From address, as (name, email).

    INVITE_FROM_EMAIL takes either form — "CityOS <no-reply@x.gov.il>" or the
    bare address. The default belongs to Resend's shared sandbox domain, which
    only Resend will accept; SendGrid refuses any sender it has not verified,
    so there it is better to send nothing and say why than to let every message
    come back 403 from a default nobody chose.
    """
    import email.utils
    name, addr = email.utils.parseaddr(
        os.environ.get("INVITE_FROM_EMAIL", "CityOS <onboarding@resend.dev>"))
    return name, addr


def _send_email(to_email, subject, html):
    """Send one transactional email. Returns True only if a provider took it.

    Every caller stays out of the provider question — see _mail_provider.
    """
    provider, api_key = _mail_provider()
    if not provider or not to_email:
        print(f"[email] skipped (no mail provider configured) → {to_email}: {subject}")
        return False
    from_name, from_addr = _mail_from()
    if provider == "sendgrid" and from_addr.endswith("@resend.dev"):
        print("[email] skipped (SENDGRID_API_KEY is set but INVITE_FROM_EMAIL is "
              "still Resend's sandbox sender — set a verified SendGrid sender) "
              f"→ {to_email}: {subject}")
        return False
    # development mode: until a domain is verified with the provider, real
    # recipients are blocked. Redirect every message to a single verified inbox
    # so invites can be tested end-to-end, keeping the original recipient
    # visible in the email.
    redirect = os.environ.get("EMAIL_DEV_REDIRECT")
    actual_to = to_email
    if redirect:
        actual_to = redirect
        subject = f"[פיתוח · נועד ל-{to_email}] {subject}"
        html = (f"<div dir='rtl' style='background:#fff3cd;border:1px solid #ffe08a;"
                f"border-radius:8px;padding:10px 12px;margin-bottom:14px;font-size:12.5px;"
                f"font-family:Arial'>⚙️ מצב פיתוח — הנמען המקורי של ההזמנה הוא "
                f"<b>{to_email}</b>. מייל זה הופנה אליך לצורכי בדיקה.</div>") + html
    if provider == "sendgrid":
        body = {"personalizations": [{"to": [{"email": actual_to}]}],
                "from": ({"email": from_addr, "name": from_name} if from_name
                         else {"email": from_addr}),
                "subject": subject,
                "content": [{"type": "text/html", "value": html}]}
        # sandbox_mode validates the whole request — sender identity included —
        # and delivers nothing. It is how a deploy can prove mail is wired up
        # without a message reaching anybody.
        if (os.environ.get("SENDGRID_SANDBOX") or "").strip() not in ("", "0", "false"):
            body["mail_settings"] = {"sandbox_mode": {"enable": True}}
    else:
        from_hdr = f"{from_name} <{from_addr}>" if from_name else from_addr
        body = {"from": from_hdr, "to": [actual_to], "subject": subject, "html": html}
    return _post_mail(provider, api_key, body, actual_to, subject)


def _post_mail(provider, api_key, body, actual_to, subject):
    """The one HTTP call. Split out so a test can exercise the payload alone."""
    import urllib.request, urllib.error, json as _json
    req = urllib.request.Request(MAIL_ENDPOINTS[provider],
                                 data=_json.dumps(body).encode("utf-8"),
                                 headers={"Authorization": f"Bearer {api_key}",
                                          "Content-Type": "application/json",
                                          "User-Agent": "CityOS/1.0"})
    try:
        with urllib.request.urlopen(req, timeout=10) as r:
            r.read()
        # "sent" must mean a message somebody can receive. A sandbox send is
        # accepted by the provider and then thrown away, so logging it the same
        # way reads as a delivery that never happened — and the log is the only
        # place anyone can see which of the two it was.
        if ((body.get("mail_settings") or {}).get("sandbox_mode") or {}).get("enable"):
            print(f"[email] validated by {provider}, NOT delivered "
                  f"(SENDGRID_SANDBOX is on) → {actual_to}: {subject}")
        else:
            print(f"[email] sent via {provider} → {actual_to}: {subject}")
        return True
    except urllib.error.HTTPError as e:
        # The refusal itself is the useful part — "does not match a verified
        # Sender Identity" is the answer to nearly every mail that never
        # arrives — so the body is logged, not just the status. It carries no
        # credential; the key only ever goes out in the request header.
        detail = ""
        try:
            detail = (e.read() or b"")[:400].decode("utf-8", "replace")
        except Exception:
            pass
        print(f"[email] {provider} refused ({e.code}) → {actual_to}: {detail}")
        return False
    except Exception as e:
        print(f"[email] send failed via {provider} → {actual_to}: {e}")
        return False


def _app_base_url(request: Request = None):
    """The origin the links in outgoing mail must point at.

    Mail hardcoded the Vercel demo host, and nothing in either pipeline sets
    APP_BASE_URL — so an invitation sent from QA or from production linked to a
    different deployment altogether, one whose database is re-seeded per cold
    start. The board named in the mail does not exist there, so "כניסה ללוח"
    could only ever land somebody on an empty demo of somebody else's city.

    In order: the explicit setting; the origin SSO is already configured with
    (the production pipeline writes it from the Web App's own hostnames, so it
    is by definition a host the invitee can sign in on); the host this very
    request arrived on; and only then the old constant.
    """
    explicit = os.environ.get("APP_BASE_URL", "").strip()
    if explicit:
        return explicit.rstrip("/")
    first = os.environ.get("ENTRA_REDIRECT_URI", "").split(",")[0].strip()
    if first:
        origin = first.rsplit("/auth/callback", 1)[0] if "/auth/callback" in first else first
        if origin.strip():
            return origin.rstrip("/")
    if request is not None:
        host = (request.headers.get("x-forwarded-host")
                or request.headers.get("host")
                or request.url.netloc or "")
        host = host.split(",")[0].strip()
        if host:
            proto = (request.headers.get("x-forwarded-proto")
                     or request.url.scheme or "https")
            return f"{proto.split(',')[0].strip() or 'https'}://{host}"
    return "https://code-cal-missions.vercel.app"


