# ── Visualization Engine ─────────────────────────────────────────────

@app.get("/api/viz/board-insights")
def board_insights(user_id: int = Depends(current_user_id)):
    """Generate visualization data and insights for boards the user may see."""
    with Session(engine) as db:
        visible = _visible_board_ids(db, user_id)
        boards = db.query(Board).filter(
            Board.is_archived == False, Board.deleted_at == None, Board.id.in_(visible)
        ).all() if visible else []
        insights = []
        _ao_boards = _assigned_only_boards(db, user_id)
        for b in boards:
            tasks = db.query(Task).filter(Task.board_id == b.id).all()
            # Filtered, not refused: on a board where this person is
            # assigned_only, the insight is about their own items — a status
            # breakdown of the rest is a description of items they cannot see
            if b.id in _ao_boards:
                _vis = _assigned_only_ids(db, b.id, user_id)
                tasks = [t for t in tasks if t.id in _vis]
            if not tasks:
                continue
            
            # Status distribution
            status_dist = {}
            priority_dist = {}
            overdue = 0
            now = datetime.now(timezone.utc).replace(tzinfo=None)
            dept_name = db.query(Department.name).filter(Department.id == b.department_id).scalar() or ""
            
            for t in tasks:
                s = t.status.value if hasattr(t.status, 'value') else t.status
                p = t.priority.value if hasattr(t.priority, 'value') else t.priority
                status_dist[s] = status_dist.get(s, 0) + 1
                priority_dist[p] = priority_dist.get(p, 0) + 1
                due = t.due_date
                if due and hasattr(due, 'tzinfo') and due.tzinfo:
                    due = due.replace(tzinfo=None)
                if due and due < now and s not in ("done", "cancelled"):
                    overdue += 1
            
            insights.append({
                "board_id": b.id,
                "board_name": b.name,
                "icon": b.icon,
                "department": dept_name,
                "total_tasks": len(tasks),
                "status_distribution": status_dist,
                "priority_distribution": priority_dist,
                "overdue_count": overdue,
                "completion_rate": round(status_dist.get("done", 0) / max(len(tasks), 1) * 100, 1),
            })
        
        return {"boards": insights, "total": len(insights)}

@app.get("/api/viz/timeline")
def viz_timeline(days: int = 30, user_id: int = Depends(current_user_id)):
    """Task timeline data for Gantt-like visualization.

    Counted over the boards the caller may see, and on a board where they are
    assigned_only over their own items there. It counted every item in the
    system for anyone who asked — a daily count is a small disclosure, but it
    is one, and it was the only reader here that did not ask who was reading."""
    with Session(engine) as db:
        from datetime import timedelta
        cutoff = datetime.now(timezone.utc).replace(tzinfo=None) - timedelta(days=days)
        visible = _visible_board_ids(db, user_id)
        tasks = db.query(Task).filter(
            Task.created_at >= cutoff, Task.board_id.in_(visible or [0])
        ).order_by(Task.created_at).all()
        _vis = {bid: _assigned_only_ids(db, bid, user_id)
                for bid in _assigned_only_boards(db, user_id) if bid in visible}
        if _vis:
            tasks = [t for t in tasks if t.board_id not in _vis or t.id in _vis[t.board_id]]
        
        # Group by day
        daily = {}
        for t in tasks:
            day = t.created_at.strftime("%Y-%m-%d") if t.created_at else "unknown"
            if day not in daily:
                daily[day] = 0
            daily[day] += 1
        
        return {"timeline": [{"date": d, "count": c} for d, c in sorted(daily.items())]}

# ── Obsidian-like Graph ─────────────────────────────────────────────

@app.get("/api/graph/context")
def graph_context():
    """Generate a knowledge graph of all tasks, boards, and their connections."""
    with Session(engine) as db:
        boards = db.query(Board).filter(Board.is_archived == False, Board.deleted_at == None).all()
        tasks = db.query(Task).filter(Task.is_archived == False).all()
        users = db.query(User).all()
        
        nodes = []
        edges = []
        
        # Board nodes
        for b in boards:
            nodes.append({
                "id": f"board_{b.id}", "label": b.name, "type": "board",
                "icon": b.icon, "color": b.color
            })
        
        # Task nodes
        for t in tasks:
            nodes.append({
                "id": f"task_{t.id}", "label": t.title[:30], "type": "task",
                "status": t.status.value if hasattr(t.status, 'value') else t.status,
                "priority": t.priority.value if hasattr(t.priority, 'value') else t.priority,
            })
            edges.append({
                "source": f"task_{t.id}", "target": f"board_{t.board_id}",
                "type": "belongs_to"
            })
        
        # User nodes
        for u in users:
            nodes.append({
                "id": f"user_{u.id}", "label": u.name, "type": "user",
                "role": u.role
            })
        
        # Assignee edges
        for t in tasks:
            if t.assignees:
                for a in t.assignees:
                    edges.append({
                        "source": f"user_{a.id}", "target": f"task_{t.id}",
                        "type": "assigned_to"
                    })
        
        return {"nodes": nodes, "edges": edges}

